-- AP&E glossary — Machine B batch 1 — PASTE FILE 5 of 6
-- Paste this whole file into the Supabase SQL editor and Run. Order between files does not matter.
-- Idempotent: safe to re-run. Backup already exists (glossary_backup_mb_batch1_20260721).
BEGIN;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"aa7894aa-ec6f-4fcc-a507-b6db3bc54d69": {"definition": "A short amplitude ramp applied at the start (fade-in) or end (fade-out) of a sample, gradually raising or lowering level to prevent clicks or pops caused by an abrupt start or stop away from zero.", "plain_english": "A sample fade is a quick volume ramp at the start or end of a sound. It eases the level up or down so you don't hear a click when the clip begins or stops.", "purpose_function": "It removes clicks and pops from starting or ending a waveform away from zero, making edits and loop points sound smooth.", "practical_application": "A technician adds a few milliseconds of fade to trimmed sample edges or loop points to stop clicks during playback.", "category": "Sample Editing", "related_terms": ["Sample editing", "Zero crossing", "Sample looping", "Crossfade", "Envelope"], "common_mistakes": ["Making fades too long and softening the attack of a sound.", "Skipping fades on edits, leaving audible clicks.", "Confusing a short edit fade with a volume envelope on the whole note."], "scenario_contexts": ["Adding a short fade-out to stop a click at a sample's end.", "Smoothing a loop point with a crossfade.", "Cleaning up edited drum hits."]}, "27c442b0-7934-404c-bbc0-be41a0576ecd": {"definition": "Repeating a defined section of a sample seamlessly so a sound can sustain longer than the original recording, using matched loop points and often a crossfade to hide the seam.", "plain_english": "Sample looping repeats part of a sound over and over so it can hold as long as you need. Good loop points make the repeat sound seamless, with no bump.", "purpose_function": "It lets a short recording sustain indefinitely, so held notes on a sampled instrument do not run out of audio.", "practical_application": "A technician sets loop start and end points in the steady part of a sustained note and crossfades them so a held key sounds continuous.", "category": "Sample Editing", "related_terms": ["Sample fade", "Crossfade", "Zero crossing", "Sample playback engine", "Sustain"], "common_mistakes": ["Placing loop points at mismatched levels, causing a click each cycle.", "Looping across a section where the tone changes, creating a noticeable pulse.", "Setting loop points off zero crossings without a crossfade."], "scenario_contexts": ["Looping the sustain of a sampled string so held notes last.", "Creating a seamless ambient loop.", "Extending a short recorded note for a keyboard instrument."]}, "7f70ea1c-c245-4ce1-89b5-8c34dab8b16c": {"definition": "An amplitude adjustment that scales a sample's gain so its peak (peak normalization) or measured loudness (loudness normalization) reaches a chosen target level, without altering its dynamics or tone.", "plain_english": "Sample normalization raises or lowers a clip's volume to hit a set level. It finds the loudest peak, then scales the whole clip so that peak sits at your target.", "purpose_function": "It brings samples to a consistent reference level so they sit together predictably and make use of the available headroom.", "practical_application": "A technician peak-normalizes captured one-shots to a set level, such as -1 dBFS, so a drum kit's hits are balanced before mixing.", "category": "Sample Editing", "related_terms": ["Sample editing", "Gain staging", "Peak level", "Headroom", "Loudness"], "common_mistakes": ["Thinking normalization is the same as compression; it does not change dynamics.", "Normalizing to 0 dBFS and leaving no headroom for later processing.", "Normalizing noisy samples, which raises the noise floor along with the signal."], "scenario_contexts": ["Leveling a set of recorded drum hits to a common peak.", "Bringing a quiet sample up before mapping.", "Preparing one-shots to a consistent reference level."]}, "e7f925a9-b3ac-4951-b410-36242c953201": {"definition": "The hardware or software component of a sampler that reproduces stored samples, handling voice allocation, sample-rate conversion and pitch shifting, envelopes, filtering, and mixing to turn triggered notes into audio output.", "plain_english": "The sample playback engine is the part of a sampler that actually makes the sound. When you press a key, it picks the right clip, shifts its pitch, and plays it back.", "purpose_function": "It converts note triggers into audio by selecting, pitching, shaping, and mixing samples in real time, letting one recording play across many notes.", "practical_application": "A technician watches the engine's voice limit and streaming settings when loading big instruments so notes do not cut off during dense passages.", "category": "Playback & Memory", "related_terms": ["Sample cache", "Sample looping", "Voice allocation", "Pitch shifting", "Polyphony"], "common_mistakes": ["Exceeding the engine's voice count, causing notes to cut off.", "Blaming the samples for artifacts actually caused by pitch-shifting far from the root note.", "Ignoring the engine's interpolation quality setting that trades CPU for sound."], "scenario_contexts": ["Loading a multi-gigabyte instrument and setting voice limits.", "Diagnosing dropped notes during dense passages.", "Choosing interpolation quality to balance CPU load and sound."]}, "5e5a8e75-43bd-4082-a78b-9bd8977ae47f": {"definition": "The technique of loading a short initial portion of each sample into RAM ahead of playback so a note sounds instantly when triggered, while the remainder of the sample streams from disk. It removes the start-of-note gaps or clicks that occur when audio must be fetched from storage only after the note begins.", "plain_english": "A sampler loads just the start of each sound into fast memory before you play. That way the note begins right away, and the rest is read from the drive as it plays. It is like a video that buffers its first second so it can start at once.", "purpose_function": "It guarantees clean, low-latency note starts in disk-streaming instruments by keeping the crucial attack already in memory, while sparing the RAM that holding every full sample would cost.", "practical_application": "When loading a large orchestral or drum library, a technician sets the preload buffer size in the sampler's options so notes trigger cleanly without running the computer out of memory.", "category": "Sample playback", "related_terms": ["Sample streaming", "Sample purge", "Sample triggering", "Sample replay", "Preload buffer"], "common_mistakes": ["Setting the preload buffer too small, which starves streaming voices and causes clicks or dropouts on fast passages", "Assuming preload holds the whole sample in RAM and so badly misjudging how much memory a large library needs"], "scenario_contexts": ["Loading a multi-gigabyte string library on a laptop and tuning preload size to balance memory use against clean note starts", "Troubleshooting attack clicks in a live keyboard rig by increasing the sampler's preload buffer"]}, "de0f623d-396f-40bb-aa5e-882704d150ac": {"definition": "A memory-management operation in disk-streaming samplers that unloads from RAM any samples not currently in use, keeping only those actually triggered by the loaded part or performance. It frees memory so very large instruments can be used without loading every mapped zone.", "plain_english": "Purging tells the sampler to drop any sounds you are not using out of memory. It keeps only the notes your part actually plays. It is like closing apps you never open to free up space on a phone.", "purpose_function": "It reclaims RAM in big sample libraries by discarding unused zones, letting a computer run instruments far larger than its physical memory would otherwise allow.", "practical_application": "After recording a MIDI part, an engineer runs 'purge unused samples' so the project keeps only the handful of notes played, cutting memory load before mixing.", "category": "Sample playback", "related_terms": ["Sample preload", "Sample streaming", "Sample triggering", "Sample replay"], "common_mistakes": ["Purging unused samples, then editing the MIDI to play new notes, which sound silent until the samples are reloaded", "Confusing purge (unload from RAM) with deleting the sample files from disk"], "scenario_contexts": ["Freeing memory mid-session in a template that has hundreds of loaded instruments", "Reducing an orchestral template's RAM footprint before bouncing on an older machine"]}, "da690ce8-8810-44e5-b3af-e2bf7c26c993": {"definition": "The playback of stored digital audio samples, in which recorded sound is read from memory or disk and reproduced, typically triggered and pitched from a keyboard or sequencer. Sample-replay instruments (romplers) sound only from fixed recordings rather than generating tones from scratch.", "plain_english": "Sample replay just means playing back sounds that were already recorded and stored. A key press calls up the recording and plays it at the pitch you want. It is like a jukebox that plays a saved clip instead of a live band.", "purpose_function": "It lets an instrument reproduce real recorded sounds on demand, giving realistic tones without having to build them from scratch by synthesis.", "practical_application": "A player uses a sample-replay sound module to lay down realistic piano or drum parts by triggering its stored recordings from a MIDI keyboard.", "category": "Sample playback", "related_terms": ["Sample triggering", "Sample-based oscillator", "Sample root note", "Sample streaming"], "common_mistakes": ["Assuming a sample-replay instrument can invent wholly new timbres like a synthesizer, when it only replays stored recordings", "Expecting extreme transposition of a replayed sample to stay natural, ignoring the speed and formant artifacts it creates"], "scenario_contexts": ["Programming a backing track with a rompler that replays multisampled instruments", "Using a hardware sound module for live sample replay of orchestral hits"]}, "f78e6e16-46e0-4a9c-8654-ba1bf5689fbb": {"definition": "The pitch (key) at which a sample plays back at its original recorded speed and frequency, serving as the reference from which the sampler transposes the sample up or down across the keymap. It is also called the original pitch, unity pitch, or root key.", "plain_english": "The root note is the key that plays a sample at its true, recorded pitch. Play a higher or lower key and the sampler speeds the sound up or slows it down from there. It is the 'home' note the sound was recorded at.", "purpose_function": "It tells the sampler the sample's true pitch so it can work out the correct transposition for every other key, keeping a mapped instrument in tune across the keyboard.", "practical_application": "When mapping a new recording, a technician sets the root note to the pitch that was actually played so the sample tracks the keyboard correctly.", "category": "Sample mapping", "related_terms": ["Sample replay", "Sample triggering", "Sample-based oscillator", "Multisample", "Key zone"], "common_mistakes": ["Leaving the root note at a default value so the whole instrument plays sharp or flat", "Confusing the root note (original pitch) with the lowest key of the sample's assigned range"], "scenario_contexts": ["Building a multisample keymap and assigning each recording its correct root note", "Fixing an out-of-tune sampled patch by correcting a wrong root note"]}, "976dea6b-22af-4ed9-81ea-51be85e75882": {"definition": "The process of dividing a sample, usually a rhythmic loop, into smaller segments at transient or beat points, with each slice assigned to its own trigger such as a MIDI note or pad. This frees the loop to be re-sequenced, quantized, or played at a new tempo without changing its pitch.", "plain_english": "Slicing chops a loop into separate hits, like putting each drum beat on its own pad. Then you can rearrange them or change the speed without the pitch going wrong. It is like cutting a song into pieces you can shuffle around.", "purpose_function": "It releases a recorded loop from its fixed tempo and order, letting a producer change speed, rearrange hits, and quantize timing while keeping the original pitch.", "practical_application": "A producer slices a breakbeat across pads, then re-triggers the slices to build a new drum pattern that locks to the project tempo.", "category": "Sampling technique", "related_terms": ["Sample trimming", "Sample triggering", "Sample replay", "Transient", "Time stretching"], "common_mistakes": ["Placing slice markers off the transients so hits start late or include the tail of the previous beat", "Slicing too finely and creating audible clicks at each segment boundary"], "scenario_contexts": ["Converting a drum loop into a sliced, tempo-flexible kit inside an MPC or DAW sampler", "Repitching and reordering a vocal chop from its sliced segments"]}, "6436ebd3-c563-435d-af59-d2232273824b": {"definition": "A playback method, also called direct-from-disk streaming, that reads sample audio continuously from a storage drive during playback instead of loading whole samples into RAM, with only a short preload buffer held in memory. It lets instruments be far larger than the available RAM.", "plain_english": "Streaming plays a sound straight off the drive as it goes, instead of loading the whole thing into memory first. Only a tiny start is kept in memory. It is like streaming a movie online rather than downloading all of it first.", "purpose_function": "It allows huge sample libraries to play on ordinary computers by trading RAM use for continuous disk reads, keeping memory demand low even for enormous instruments.", "practical_application": "An engineer stores a large sample library on a fast SSD so the sampler can stream dozens of multi-gigabyte instruments at once without exhausting RAM.", "category": "Sample playback", "related_terms": ["Sample preload", "Sample purge", "Preload buffer", "Sample replay", "Disk streaming"], "common_mistakes": ["Streaming a big library from a slow or heavily fragmented hard drive, causing dropouts and voice starvation", "Assuming streaming removes all RAM use, when a preload buffer per voice still consumes memory"], "scenario_contexts": ["Running a large orchestral template by streaming from an SSD instead of loading everything into RAM", "Diagnosing playback stutters traced to disk streaming bandwidth limits"]}, "e71599df-efcc-43f0-a385-20fc2a1e8e2c": {"definition": "The act of starting playback of a sample in response to an event such as a MIDI note-on, pad strike, sequencer step, or detected audio transient. The trigger determines when a sample begins, and often which sample and velocity layer plays.", "plain_english": "Triggering is whatever starts a sample playing. A key press, a pad hit, or a drum signal tells it to sound. It is like pressing play on one clip at the exact moment you want it.", "purpose_function": "It links a performance or control event to sample playback, deciding the instant a stored sound plays and, through velocity, how loud it is or which layer is chosen.", "practical_application": "A drummer triggers sampled sounds live by striking pads on an electronic kit, each hit firing the mapped sample at the played velocity.", "category": "Sample playback", "related_terms": ["Sample replay", "Sample root note", "Sample-based oscillator", "Sample slicing", "Velocity layer"], "common_mistakes": ["Double-triggering a sample from a noisy drum trigger, producing flams or machine-gun repeats", "Ignoring velocity so every triggered hit plays the same layer and sounds unnatural"], "scenario_contexts": ["Setting trigger thresholds on an electronic drum module to avoid false hits", "Triggering sampled one-shots from a sequencer during a live set"]}, "4d45d6ae-e420-4ab7-9f33-1ec4075c23a4": {"definition": "Editing a sample by moving its start and end points to remove unwanted silence or audio at the beginning and end, tightening the usable region without altering the audio between them. It sets where playback begins and stops.", "plain_english": "Trimming cuts the dead space or extra sound off the start and end of a sample. What is left is just the part you want to play. It is like cropping the empty edges off a photo.", "purpose_function": "It removes leading silence and unwanted tails so samples trigger tightly on time and loop or map cleanly.", "practical_application": "After recording a one-shot, a technician trims the silence before the attack so the sound fires the instant the pad is hit.", "category": "Sample editing", "related_terms": ["Sample slicing", "Sample root note", "Sample triggering", "Zero crossing", "One-shot"], "common_mistakes": ["Trimming into the attack transient and cutting off the punch of the sound", "Trimming at a point that is not a zero crossing, so the start or end produces an audible click"], "scenario_contexts": ["Cleaning up recorded one-shots by trimming silence before assigning them to pads", "Tightening a sampled vocal phrase by trimming the breath before the first word"]}, "e568762b-375e-4c11-a4da-d54e529e94f9": {"definition": "A synthesizer sound source that generates its output by reading back a stored digital sample, such as a recorded waveform or single-cycle wave, rather than computing a waveform mathematically. It is the core of sample-based (S+S) synthesis, where sampled sources feed conventional filters, envelopes, and amplifiers.", "plain_english": "This is a synth sound source that plays a recorded sound instead of a made-up wave. That recording is then shaped by the synth's filters and envelopes. It is like starting from a real sound clip and bending it with the synth's controls.", "purpose_function": "It provides realistic or complex starting tones from recordings, which the rest of the synth then filters and shapes, combining sampled realism with synth-style control.", "practical_application": "A sound designer picks a sampled waveform as the oscillator in a workstation synth, then applies filter and envelope moves to craft a new patch.", "category": "Sample synthesis", "related_terms": ["Sample replay", "Sample root note", "Sample triggering", "Wavetable", "Rompler"], "common_mistakes": ["Confusing a sample-based oscillator with a full sampler, when it is one voice element inside a synth engine", "Expecting a short looped sample oscillator to hold long sustains without an audible loop point"], "scenario_contexts": ["Programming a rompler-style patch built on sampled oscillators fed into resonant filters", "Layering a sample-based oscillator with a virtual-analog one for a hybrid tone"]}, "7fbfcde3-57ed-49d8-9d52-60c9c459c359": {"definition": "A slice marker is a point placed within a sampled audio file that marks where the sample is divided into separate, independently playable segments. Markers are typically set at transient onsets in a loop so each hit or note becomes its own slice.", "plain_english": "A slice marker is a cut point you drop into a sound clip. It splits a loop into small pieces, so each drum hit can be played on its own.", "purpose_function": "It defines the boundary of each slice so a sampler can chop a continuous recording into separately triggerable pieces, allowing tempo changes and rearrangement without pitch shifting.", "practical_application": "A producer loads a drum loop into a slicing sampler, places slice markers on each transient, and maps the slices across MIDI notes or pads to rebuild or re-time the groove.", "category": "Sampling", "related_terms": ["Slice trigger", "Transient detection", "Sample slicing", "Loop point", "Warp marker"], "common_mistakes": ["Placing markers slightly after the transient, which clips off the attack of each hit.", "Confusing slice markers with loop points; a marker divides audio while a loop point sets a repeating region.", "Setting too many markers so quiet noise between hits becomes its own useless slice."], "scenario_contexts": ["Chopping a breakbeat into individual drum hits to reprogram a new pattern.", "Slicing a vocal phrase so each word can be retriggered from a pad.", "Preparing a loop for tempo-flexible playback in a live set."]}, "eb50c53c-2e12-4b2f-9070-ae9066aed6e4": {"definition": "A slice trigger is the event—usually a MIDI note or pad hit—that plays back one individual slice of a sliced sample. Each slice is assigned to its own trigger so the slices can be played in any order or rhythm.", "plain_english": "A slice trigger is the note or pad that fires one piece of a chopped-up sound. Press it and that single slice plays. This lets you replay the pieces in any order you like.", "purpose_function": "It lets each slice of a sliced loop play independently, so a performer can rearrange, re-time, or remix the original recording in real time.", "practical_application": "After slicing a loop, a producer plays the slice triggers from a pad controller to build a new beat or to lock the loop to the project tempo.", "category": "Sampling", "related_terms": ["Slice marker", "Sample slicing", "MIDI note", "Pad controller", "One-shot"], "common_mistakes": ["Assuming slices always land on the intended pads; slices often need manual remapping after slicing.", "Letting a slice ring too long so it bleeds into the next trigger.", "Forgetting to set slice playback to one-shot, so held notes loop unexpectedly."], "scenario_contexts": ["Finger-drumming a sliced breakbeat on sampler pads.", "Retriggering vocal chops during a live performance.", "Programming slice triggers in a piano roll to reorder a melody."]}, "0c0ebfc1-9ad8-4223-9880-d4fd0094fb9b": {"definition": "Soft synchronization (soft sync) is a form of oscillator synchronization in which a master oscillator only partially resets a slave oscillator—commonly restarting it only under certain phase conditions rather than on every master cycle—producing a gentler harmonic change than hard sync.", "plain_english": "Soft sync links two sound oscillators, but only nudges the second one now and then instead of forcing a full restart each time. The result is a softer, less harsh tone than hard sync.", "purpose_function": "It loosely locks two oscillators to create richer, moving harmonics while keeping a smoother, less aggressive sound than hard sync.", "practical_application": "A sound designer selects soft sync on a synth's oscillator to add subtle harmonic movement to a pad or lead without the sharp bite of hard sync.", "category": "Synthesis", "related_terms": ["Oscillator sync", "Hard synchronization", "Oscillator", "Sub-oscillator", "Waveform"], "common_mistakes": ["Expecting the dramatic tearing sound of hard sync; soft sync is deliberately subtler.", "Confusing oscillator soft sync with clock or tempo synchronization.", "Assuming every synth implements soft sync identically; the behavior varies by instrument."], "scenario_contexts": ["Adding gentle harmonic motion to an analog-style pad.", "Designing a lead that is warmer than a hard-sync patch.", "Comparing soft and hard sync while shaping a bass sound."]}, "8237e1d8-c860-45e0-a294-e913bed86db9": {"definition": "A software synthesizer (soft synth) is a synthesizer implemented entirely in software that generates or shapes sound through digital signal processing on a computer's CPU, running as a plug-in inside a DAW or as a standalone application rather than as dedicated hardware.", "plain_english": "A software synthesizer is a synth that lives inside your computer as a program. It makes sounds with code instead of physical circuits. You play it with a MIDI keyboard through your music software.", "purpose_function": "It provides the sound-generating power of a hardware synth in software form, giving flexible, recallable, and often lower-cost instruments that integrate directly with a DAW.", "practical_application": "A producer loads a soft synth as a plug-in in their DAW, plays it from a MIDI controller, and saves every setting with the project for instant recall.", "category": "Synthesis", "related_terms": ["Virtual instrument", "Plug-in", "MIDI controller", "DAW", "Sampler"], "common_mistakes": ["Blaming the synth for latency that is actually caused by buffer or audio-interface settings.", "Overloading the CPU by running many voices or instances without freezing tracks.", "Assuming a soft synth needs no MIDI setup; it still requires a controller or programmed notes."], "scenario_contexts": ["Building a track using only in-the-box virtual instruments.", "Recreating a classic hardware synth sound with an emulation plug-in.", "Layering several soft synths for a bigger pad."]}, "0ca1f3a4-14d1-4262-b4a2-61541e244324": {"definition": "A spiccato sample is a recording of a bowed string instrument played spiccato—a short, bouncing, off-the-string bow stroke—captured as a distinct articulation within a sample library so the crisp, detached attack can be reproduced by a sampler.", "plain_english": "A spiccato sample is a recording of a string player using a bouncing bow stroke. Each note is short and springy. Sample libraries include it so you can play that lively bounce from a keyboard.", "purpose_function": "It supplies the spiccato articulation to a virtual string instrument, letting composers write fast, light, detached passages that sound like a real bouncing bow.", "practical_application": "A composer selects the spiccato articulation, often via a keyswitch, in a string library to play rapid, rhythmic detached lines in a film cue.", "category": "Articulation", "related_terms": ["Staccato sample", "Sustain sample", "String library", "Keyswitch", "Round-robin"], "common_mistakes": ["Confusing spiccato with staccato; spiccato is a bouncing bow stroke, staccato is a general short detached note.", "Using spiccato for slow, sustained lines where it sounds unnatural.", "Ignoring round-robin so repeated notes sound identically machine-gunned."], "scenario_contexts": ["Writing a fast, playful string ostinato in an action cue.", "Keyswitching to spiccato for a light, bouncy passage.", "Layering spiccato with pizzicato for extra rhythmic bite."]}, "4929d669-d1d2-43bb-bbe9-fbaaee96e3c0": {"definition": "A staccato sample is a recording of a single note played staccato—short and clearly detached from the notes around it—captured as a separate articulation in a sample library to reproduce crisp, punctuated playing.", "plain_english": "A staccato sample is a recording of one short, clipped note. The note stops quickly instead of ringing on. Libraries include it so your parts can sound sharp and punchy.", "purpose_function": "It gives a virtual instrument a short, detached articulation, letting players write rhythmic, punctuated lines that a sustained sample could not convincingly produce.", "practical_application": "A composer keyswitches to the staccato articulation to play tight rhythmic chords or fast repeated notes in an orchestral mock-up.", "category": "Articulation", "related_terms": ["Spiccato sample", "Sustain sample", "String library", "Keyswitch", "Round-robin"], "common_mistakes": ["Assuming all staccato samples share one length; libraries often provide short and long staccato variants.", "Overlapping staccato notes so the detached character is lost.", "Forgetting round-robin, causing repeated notes to sound mechanically identical."], "scenario_contexts": ["Programming a punchy brass rhythm figure.", "Playing fast repeated string notes in a mock-up.", "Switching between sustain and staccato with keyswitches during a phrase."]}, "527e36f9-40f8-49c9-b31d-5f434233f438": {"definition": "A string library is a sample-based virtual instrument containing recordings of orchestral string instruments—typically violins, violas, cellos, and double basses—captured across multiple articulations, dynamics, and often microphone positions for playback from a sampler.", "plain_english": "A string library is a collection of recorded orchestral string sounds. It holds violins, violas, cellos, and basses. You play these real recordings from a keyboard to write string music on a computer.", "purpose_function": "It lets composers produce realistic orchestral string parts without hiring live players, providing multiple articulations and dynamics that can be triggered from a MIDI keyboard.", "practical_application": "A composer loads a string library into a sampler, chooses articulations with keyswitches, and shapes dynamics with a controller to build a mock-up of an orchestral cue.", "category": "Sample Library", "related_terms": ["Spiccato sample", "Staccato sample", "Sustain sample", "Keyswitch", "Sampler"], "common_mistakes": ["Leaving every section at full dynamics, producing a flat, unrealistic sound.", "Ignoring articulation and legato scripting, so lines sound disconnected.", "Loading all microphone positions at once and needlessly overloading RAM and CPU."], "scenario_contexts": ["Scoring a film cue with layered string sections.", "Building a realistic legato melody for a demo.", "Mixing close and hall mic positions to place the strings in a space."]}, "ab601a70-6e47-4404-b9d9-a582a81d4442": {"definition": "A sub-oscillator is a secondary oscillator in a synthesizer that produces a tone one or two octaves below the main oscillator's pitch, usually as a simple square or sine wave, added to reinforce the low end of a sound.", "plain_english": "A sub-oscillator is an extra tone generator that plays one or two octaves lower than the main sound. It adds deep low end and weight. Think of it as a built-in bass booster for a synth patch.", "purpose_function": "It thickens and deepens a sound by adding low-frequency energy beneath the main oscillator, giving basses and leads extra body and power.", "practical_application": "A sound designer raises the sub-oscillator level on a bass patch to add weight for large systems, watching a meter to avoid overloading the low end.", "category": "Synthesis", "related_terms": ["Oscillator", "Soft synchronization", "Waveform", "Low-pass filter", "Detuning"], "common_mistakes": ["Adding too much sub level, muddying the mix and eating headroom.", "Assuming the sub adds a new pitch; it tracks the main oscillator one or two octaves down.", "Forgetting that small speakers cannot reproduce the sub, so it is only felt on larger systems."], "scenario_contexts": ["Reinforcing a bass patch for a dance track.", "Adding weight to a lead so it carries a mix.", "Filling the low end of a sound before mastering."]}, "aabe1963-8ac7-4946-8c5d-a1f3241704e1": {"definition": "A sustain sample is a recording of a note held at a steady level, capturing the sustained body of an instrument's tone rather than a short attack, used in sample libraries to produce long, continuous notes.", "plain_english": "A sustain sample is a recording of a note that is held out long. It captures the steady, ringing part of the sound. Libraries use it so you can play long, smooth notes.", "purpose_function": "It provides the long, held articulation of a sampled instrument, letting players write pads, legato lines, and sustained chords that short samples cannot cover.", "practical_application": "A composer uses the sustain articulation for long melodic lines and swells, shaping volume with an expression controller for realistic phrasing.", "category": "Articulation", "related_terms": ["Staccato sample", "Spiccato sample", "String library", "Keyswitch", "Loop point"], "common_mistakes": ["Bad loop points inside the sustained portion, causing an audible click or bump on long notes.", "Leaving dynamics static, so held notes sound lifeless and synthetic.", "Using a sustain sample for fast passages where a short articulation would fit better."], "scenario_contexts": ["Holding long string chords under a melody.", "Playing a slow, expressive legato line.", "Building an evolving pad from sustained notes."]}, "84cd5fc6-028e-4be1-a014-a7d42647c69b": {"definition": "The onset (attack) portion of a note reproduced by a tape-replay instrument or tape sample: the initial rise of the sound as playback of the recorded tape begins. On instruments such as the Mellotron, a spring returns each tape strip to its start between keystrokes so the recorded instrument's natural attack transient plays back from the beginning of every note.", "plain_english": "The very start of a sound as the tape begins to play. On a tape keyboard, each key rewinds its own tape, so you always hear the true beginning of the note, like a short clip that starts from the first frame every time.", "purpose_function": "An accurate attack lets a tape-based sampler sound like the real instrument it recorded, because the opening transient carries much of an instrument's character.", "practical_application": "A player depends on the tape returning to its start between notes; a tired spring or slipping tape gives late or weak note starts, which a technician spots by listening for soft or delayed attacks.", "category": "Note articulation", "related_terms": ["Tape release", "Tape playback", "Tape frame", "Tape head", "Envelope"], "common_mistakes": ["Assuming the attack can be shaped with an amplitude envelope like a modern sampler, when on a tape instrument the attack is fixed by the original recording.", "Confusing tape attack (the note's onset) with tape saturation softening the transients of a signal being recorded."], "scenario_contexts": ["A keyboardist re-triggering a Mellotron flute line where each note must start cleanly from the tape's beginning.", "A technician tracing weak or delayed note starts to a fatigued tape-return spring."]}, "8e394eb6-7b44-4bd2-aa91-0b85ec88c75e": {"definition": "Rapid, short-term variations in tape speed, typically above about 6 Hz, caused by transport imperfections such as an eccentric capstan, worn pinch roller, dirty guides, or uneven tape tension. Flutter modulates the pitch and timbre of the reproduced signal, adding a warbling or rough quality; slower speed variations below that range are called wow.", "plain_english": "A fast wobble in the tape's speed that makes the pitch shake. It is like a trembling singing voice, but here it is caused by the tape not moving at a perfectly steady speed.", "purpose_function": "Flutter is an unwanted artifact, not a feature; measuring and minimizing it is how engineers judge the mechanical quality and health of a tape transport.", "practical_application": "A technician measures wow and flutter with a steady test tone and a meter, then cleans or replaces the capstan, pinch roller, or bearings when the reading exceeds spec.", "category": "Tape artifacts", "related_terms": ["Wow", "Tape motor noise", "Capstan", "Tape playback", "Tape head"], "common_mistakes": ["Confusing flutter (fast speed changes) with wow (slow speed changes).", "Blaming the tape for flutter when a dirty or worn capstan or pinch roller is usually the real cause."], "scenario_contexts": ["Restoring an old tape machine and hearing a warbling pitch on sustained notes.", "Evaluating a vintage tape sampler or Mellotron for pitch instability during playback."]}, "3d1a6363-341c-4a1a-ac8a-077640ea7b2b": {"definition": "On a tape-replay keyboard such as the Mellotron, the removable assembly that holds the bank of individual tape strips (one per key) together with their guides and return springs. Sliding or swapping the frame changes which recorded sounds the instrument plays.", "plain_english": "The tray inside a tape keyboard that holds all the little tapes, one for each key. Swapping the tray gives the instrument a whole new set of sounds, a bit like changing a cartridge.", "purpose_function": "The frame organizes and aligns every tape strip over its playback head, and because it is removable it lets a player change the instrument's entire voice set.", "practical_application": "A technician removes and reinstalls the tape frame to swap sound banks, and adjusts tape alignment and spring tension within it during servicing.", "category": "Instrument mechanics", "related_terms": ["Tape head", "Tape playback", "Tape attack", "Tape release", "Tape splice"], "common_mistakes": ["Thinking a tape keyboard plays endless loops, when most frames hold finite strips that must spring back to their start.", "Forcing or misaligning the strips when reinstalling the frame, which causes dropouts and uneven levels."], "scenario_contexts": ["Swapping a Mellotron's tape frame to change from strings to choir sounds.", "Servicing a tape-replay instrument to realign strips and check spring returns inside the frame."]}, "728475ef-6765-4c31-b34a-964c9c3a7df5": {"definition": "An electromagnetic transducer that transfers signal between a machine's audio electronics and the magnetic tape. A recorder typically has separate heads for erase, record, and playback (reproduce); each is a small gapped magnetic core with a coil that either magnetizes the passing tape or senses the tape's magnetic field.", "plain_english": "The small magnetic part that reads or writes sound on the tape as it slides past. It works a bit like the needle on a record player, but it uses magnetism instead of a groove.", "purpose_function": "Heads are the link between electrical audio and the magnetic pattern on the tape; without them a machine cannot record, erase, or play back sound.", "practical_application": "A technician cleans and demagnetizes the heads regularly and checks head alignment (azimuth) with a test tape to keep the high frequencies and stereo image correct.", "category": "Tape mechanics", "related_terms": ["Tape playback", "Tape hiss", "Azimuth", "Bias", "Tape frame"], "common_mistakes": ["Skipping regular head cleaning and demagnetizing, letting oxide build-up dull the highs and raise the noise.", "Confusing the record, playback, and erase heads, or mistaking a misaligned playback-head azimuth for a fault in the tape."], "scenario_contexts": ["Aligning azimuth on a tape deck with a test tape before a transfer session.", "Tracing lost high frequencies to a dirty or worn playback head."]}, "a0aa02d4-e082-4152-ae33-eb2c23c8b75d": {"definition": "The steady broadband high-frequency noise inherent to magnetic tape, produced by the random size and distribution of the magnetic particles in the tape coating. It sets the noise floor of an analog tape recording and is most audible during quiet passages.", "plain_english": "The soft, steady 'shhh' you hear from tape, especially in quiet parts. It comes from the tiny magnetic specks on the tape not being perfectly even.", "purpose_function": "Hiss defines the noise floor, and therefore the usable dynamic range, of a tape system; understanding it drives choices about recording level and noise reduction.", "practical_application": "Engineers record at healthy levels and may use noise reduction such as Dolby to keep hiss below the music, and roll off unused high frequencies to tame it during a transfer.", "category": "Tape noise", "related_terms": ["Signal-to-noise ratio", "Noise reduction", "Tape motor noise", "Tape playback", "Bias"], "common_mistakes": ["Recording at too low a level to feel safe, which pushes the music down into the hiss and worsens the signal-to-noise ratio.", "Treating hiss as a fault to repair rather than as an inherent property of the medium."], "scenario_contexts": ["Setting record levels so a quiet vocal stays well above the tape's noise floor.", "Cleaning up hiss when digitizing an old cassette or reel."]}, "c4615e7e-cfe6-400d-a6d5-01bee849858b": {"definition": "Unwanted low-frequency rumble and mechanical or electrical noise introduced by a tape machine's motors and transport, including the capstan and reel motors, bearings, and drive components. It couples into the audio as rumble or hum and can also modulate speed, contributing to wow and flutter.", "plain_english": "The low rumble or hum a tape machine's motors add to the sound. It is like the background drone of a fridge in the room, coming from the spinning parts.", "purpose_function": "Recognizing motor noise helps a technician separate transport faults from tape or electronic problems and keep the recording's low end clean.", "practical_application": "A technician isolates rumble by servicing bearings and motors, checking mounts and belts, and confirming the noise follows transport speed rather than the recorded signal.", "category": "Tape noise", "related_terms": ["Tape flutter", "Tape hiss", "Capstan", "Rumble", "Tape playback"], "common_mistakes": ["Mistaking motor rumble for a low-frequency fault in the recording or the monitors.", "Ignoring worn bearings or dry motors, which raises both rumble and flutter over time."], "scenario_contexts": ["Chasing a low rumble on a transfer and finding a worn capstan bearing.", "Servicing an old reel machine whose reel motors add hum during fast winding."]}, "7b4ef5bc-6648-43f0-b321-f59757137790": {"definition": "The reproduction of a recorded signal from magnetic tape, in which the moving tape's magnetic pattern induces a voltage in the playback (reproduce) head that is then equalized and amplified back to audio. On tape-replay instruments, playback is triggered per note by a key advancing its tape past the head.", "plain_english": "Playing back sound that was stored on tape. The magnetic pattern on the moving tape is turned back into an electrical signal by the head, then made loud enough to hear.", "purpose_function": "Playback is how recorded audio is heard again; on samplers and tape keyboards it is the core mechanism that turns stored recordings into a playable instrument.", "practical_application": "A technician verifies playback level and frequency response with a calibration tape, and on a tape instrument checks that each key reliably starts and stops its tape.", "category": "Sample playback", "related_terms": ["Tape head", "Tape attack", "Tape release", "Tape frame", "Equalization"], "common_mistakes": ["Confusing playback (reproduce) equalization with tone controls, when playback EQ actually corrects the head's natural response.", "Assuming a playback problem is in the tape when the head or its alignment is at fault."], "scenario_contexts": ["Transferring a reel to digital and confirming flat playback with a calibration tape.", "Testing a Mellotron so every key plays its recorded note back cleanly."]}, "76e32a96-bc77-4344-bbf5-a4ee6bc2ccf9": {"definition": "The release (ending) stage of a note on a tape-replay instrument: what happens to the sound when a key is let go. On instruments such as the Mellotron, releasing the key lifts the tape from the playback head and a spring returns the strip to its start, so the note ends and resets for the next press.", "plain_english": "What happens to a tape keyboard's note when you let go of the key. The tape stops playing and springs back to its start, so the sound ends and the key is ready to play again.", "purpose_function": "Reliable release and reset let each key be replayed accurately and in time; it is the counterpart to the attack in a tape instrument's note cycle.", "practical_application": "A technician checks the return spring and tape freedom so notes end cleanly and reset fully; a sticky return causes hanging notes or a shortened next attack.", "category": "Note articulation", "related_terms": ["Tape attack", "Tape playback", "Tape frame", "Tape head", "Envelope"], "common_mistakes": ["Expecting an adjustable release tail like a synth, when on a tape instrument the note simply stops as the tape lifts.", "Overlooking a weak return spring, which leaves the tape short of its start and shortens the next note."], "scenario_contexts": ["Diagnosing hanging or shortened notes on a Mellotron traced to sticky tape returns.", "Setting up a tape-replay keyboard so keys reset fully between fast repeated notes."]}, "c80cd925-aac5-4d87-ac02-a01da6ae940f": {"definition": "A join between two pieces of magnetic tape, made by cutting the tape (usually on a 45-degree diagonal in a splicing block) and butting the ends together with special splicing tape. Splicing is the basic method of physically editing analog tape and of forming tape loops.", "plain_english": "A spot where two pieces of tape are cut and joined. Editors cut the tape at an angle and stick the ends with special splicing tape, like cutting and taping film, to rearrange or loop the sound.", "purpose_function": "Splicing is how analog editing is done: removing mistakes, rearranging sections, and building loops, all by physically cutting and rejoining the tape.", "practical_application": "A technician cuts on the diagonal in a splicing block, joins the ends with proper splicing tape (never ordinary adhesive tape), and angles the cut so the edit is inaudible.", "category": "Tape editing", "related_terms": ["Tape loop", "Tape head", "Tape playback", "Leader tape", "Splicing block"], "common_mistakes": ["Using ordinary sticky tape or the wrong adhesive, which oozes, gums up the heads, and fails over time.", "Splicing straight across instead of on a diagonal, which leaves an audible click at the join."], "scenario_contexts": ["Editing a reel-to-reel master by cutting out a bad take and splicing the good sections together.", "Making a tape loop by splicing the end of a section back to its beginning."]}, "e6dbf388-35ba-4e53-8736-0047ce4aa75b": {"definition": "A length of pre-recorded magnetic tape that stores a single note or sound in a tape-replay keyboard such as the Mellotron; each key draws its own tape strip across a playback head to sound the recorded tone.", "plain_english": "A tape strip is a short piece of recording tape that holds one note. On a Mellotron, each key plays its own strip, like a row of tiny tape players.", "purpose_function": "It holds the real recorded sound of an instrument so a keyboard can replay actual tones per key; it was the storage medium that made the Mellotron an early sample-playback instrument.", "practical_application": "A technician cleans, aligns, and replaces worn tape strips on a Mellotron and checks that each strip returns fully to its start position after the key is released.", "category": "Tape sampling", "related_terms": ["Vintage Mellotron sound", "Tape wow", "Sample playback", "Multisampling", "Wow and flutter"], "common_mistakes": ["Thinking a tape strip loops forever; classic Mellotron strips play for only about eight seconds before the note must be released and reset.", "Assuming keys share one tape; on a Mellotron every key has its own dedicated strip.", "Handling old strips roughly, since aged tape becomes brittle and stretches easily."], "scenario_contexts": ["Restoring a vintage Mellotron and replacing brittle or stretched tape strips.", "Explaining how early sample-playback keyboards stored sound before digital memory.", "Recreating the Mellotron effect in software by mapping short samples to each key."]}, "ac45eae1-63c9-48fd-a268-a06fe59ca689": {"definition": "Tape wow is a slow, cyclic variation in reproduced pitch, typically below about 6 Hz, caused by uneven tape transport speed; it is the low-rate component of wow and flutter.", "plain_english": "Tape wow is a slow wobble in pitch that happens when tape does not move at a steady speed. The sound drifts a little sharp and flat, like a record player slowing down and speeding up.", "purpose_function": "As a fault it reveals speed-stability problems in a tape machine; as an effect it is deliberately emulated to give digital audio a warm, vintage, slightly unstable character.", "practical_application": "A technician measures wow and flutter to a standard when servicing a tape deck, and a producer may add modeled tape wow to make sampled or synthesized sounds feel analog.", "category": "Tape artifacts", "related_terms": ["Wow and flutter", "Tape strip", "Vintage Mellotron sound", "Pitch modulation", "Flutter"], "common_mistakes": ["Confusing wow with flutter; wow is slow pitch drift while flutter is fast.", "Blaming wow on the recording when it comes from uneven tape transport speed.", "Thinking all wow is a defect; some producers add tape wow on purpose for a vintage feel."], "scenario_contexts": ["Adding subtle tape wow with a plugin to make a clean synth pad feel vintage.", "Diagnosing a worn pinch roller or motor causing unwanted wow on a tape machine.", "Teaching the difference between wow and flutter in an audio class."]}, "51c9bf7a-b352-42ea-9a82-a15766705a84": {"definition": "Time-stretch sampling is digital processing that changes the duration of a sampled sound without altering its pitch, usually by resynthesizing or repositioning short overlapping segments of the audio.", "plain_english": "Time-stretch sampling makes a sound longer or shorter without changing its pitch. It is like slowing down speech so you can still understand the words, just at a new speed.", "purpose_function": "It lets a sample fit a new tempo or length while keeping its original pitch, decoupling time from pitch so loops and phrases can be matched to a project.", "practical_application": "In a DAW a technician warps or stretches a loop to lock it to the session tempo, choosing an algorithm suited to drums, vocals, or complex material.", "category": "Sample editing", "related_terms": ["Pitch shifting", "Transient slicing", "Warp markers", "Granular synthesis", "Resampling"], "common_mistakes": ["Expecting extreme stretching to stay clean; large ratios add smearing or metallic artifacts.", "Confusing time-stretching with pitch shifting; stretching changes length, not pitch.", "Forgetting to pick the right transient or complexity mode for the material."], "scenario_contexts": ["Fitting a vocal sample to a new song tempo without changing its pitch.", "Slowing a drum break for a remix while keeping the same key.", "Lining up a loop to the project tempo in a DAW using warp or stretch."]}, "ec9cf625-593e-4a10-bbfc-2200323a3cc0": {"definition": "Transient slicing is the automatic or manual segmentation of an audio sample at its transients, cutting it into individual hits or events that can be triggered, reordered, or re-timed independently.", "plain_english": "Transient slicing cuts a sound into small pieces at each hit or beat. A drum loop can be split into single hits, so you can move or replay them one at a time.", "purpose_function": "It breaks a continuous loop into playable pieces so the rhythm can follow tempo changes or be rearranged without relying on pitch-changing time-stretch.", "practical_application": "A producer slices a drum loop into separate hits, maps them across a sampler or pads, and rebuilds or re-times the groove.", "category": "Sample editing", "related_terms": ["Beat slicing", "Time-stretch sampling", "Transient detection", "Sample chopping", "Warp markers"], "common_mistakes": ["Setting the sensitivity too high so quiet noises create false slices.", "Confusing slicing with time-stretching; slicing cuts the audio into parts.", "Slicing just after the start of a hit and losing the attack."], "scenario_contexts": ["Chopping a drum loop into single hits to rearrange the groove.", "Preparing a loop so it follows tempo changes by triggering slices.", "Extracting a single snare hit from a recorded break."]}, "949e5dc8-e134-47c4-993c-a790f96a02c4": {"definition": "A tremolo sample is a recorded sample that captures an instrument played with tremolo — rapid repetition of a note or fast amplitude or bowing modulation — supplied as a distinct articulation within a sampled instrument.", "plain_english": "A tremolo sample is a recording of an instrument played with a fast, shaky, repeating sound. Sample libraries include it so a keyboard can play that trembling effect.", "purpose_function": "It provides a realistic trembling articulation in sample libraries so a player can call up authentic tremolo instead of faking it with a modulated volume envelope.", "practical_application": "A composer selects a string or mandolin tremolo articulation, often through a keyswitch, to add tension or shimmer in a mock-up or score.", "category": "Sample articulation", "related_terms": ["Articulation", "Multisampling", "Sample library", "Vibrato", "Amplitude modulation"], "common_mistakes": ["Confusing tremolo, a change in volume or repetition, with vibrato, a change in pitch.", "Looping a tremolo sample poorly so the pulse becomes uneven.", "Assuming one tremolo speed fits every tempo; the rate may clash with the song."], "scenario_contexts": ["Loading a string tremolo articulation in an orchestral library for a tense scene.", "Layering a tremolo sample under a pad for a shimmering texture.", "Switching from a sustain to a tremolo articulation with a keyswitch."]}, "1cd63e6a-a58c-4116-9367-016edb9c2467": {"definition": "Unison detuning is the slight pitch offsetting of two or more voices or oscillators sounding the same note, producing beating between the near-identical pitches and a thicker, wider timbre.", "plain_english": "Unison detuning plays several copies of the same note slightly out of tune with each other. The tiny differences make the sound fuller and wider, like many singers on one note.", "purpose_function": "It fattens and widens a sound by creating gentle beating between near-identical pitches, a core technique behind rich leads, pads, and supersaw tones.", "practical_application": "A sound designer sets a synth to unison mode and dials in a small detune amount to thicken a lead, watching polyphony use since each stacked voice adds load.", "category": "Synthesis technique", "related_terms": ["Detune", "Voice allocation", "Chorus effect", "Oscillator", "Supersaw"], "common_mistakes": ["Adding too much detune so the note sounds out of tune instead of full.", "Forgetting that detuned unison voices use more polyphony and processing power.", "Confusing unison detune with a chorus effect, though they can sound similar."], "scenario_contexts": ["Thickening a lead synth by stacking detuned unison voices.", "Programming a wide supersaw for an electronic track.", "Adding gentle detune to a sampled pad so it sounds less static."]}, "645816be-f82a-4e9c-b5b5-3d99972ecc80": {"definition": "The vintage Mellotron sound is the characteristic timbre of the Mellotron tape-replay keyboard: recorded instrument samples on tape reproduced with noticeable pitch instability, limited note length, tape noise, and a warm, wavering, lo-fi character.", "plain_english": "The vintage Mellotron sound is the wobbly, breathy tone of an old tape keyboard. Its notes waver in pitch and sound a bit worn, which many people find warm and haunting.", "purpose_function": "It denotes a recognizable retro texture — flutes, strings, choirs — prized for its imperfect, haunting quality and often emulated to evoke 1960s and 1970s recordings.", "practical_application": "A producer picks a real or software Mellotron for a period-authentic string or choir part and often keeps its pitch drift and tape noise for character.", "category": "Tape sampling", "related_terms": ["Tape strip", "Tape wow", "Sample playback", "Multisampling", "Wow and flutter"], "common_mistakes": ["Thinking the Mellotron is a synthesizer; it plays back real recorded tape samples.", "Expecting long sustained notes; original tape strips run out after a few seconds.", "Assuming the wobble is a fault; the pitch drift is part of the classic sound."], "scenario_contexts": ["Adding a Mellotron flute or strings part to a retro-style song.", "Choosing a software Mellotron for an authentic 1960s to 1970s texture.", "Restoring an original Mellotron for a studio session."]}, "790ea4f2-1669-4ede-b600-39ceda1c9352": {"definition": "Voice allocation is the process by which a polyphonic synthesizer or sampler assigns incoming notes to its finite number of available voices, including how it reuses or steals voices when the voice limit is reached.", "plain_english": "Voice allocation decides which notes a synth or sampler will play when only so many can sound at once. It is like having a set number of seats and choosing who sits down.", "purpose_function": "It manages limited polyphony so the most important notes keep sounding, deciding which voice plays a new note and which older note is cut when voices run out.", "practical_application": "A player configures voice-stealing or note-priority behavior so that held chords and sustained notes are not cut abruptly during busy passages.", "category": "Voice management", "related_terms": ["Polyphony", "Voice stealing", "Note priority", "Unison detuning", "Multitimbral"], "common_mistakes": ["Confusing a voice with a patch; a voice is one sounding note, not one instrument.", "Not expecting voice stealing when you exceed the polyphony limit.", "Assuming more voices are always free; each active voice uses processing power."], "scenario_contexts": ["Setting how a synth steals voices when a player holds many notes.", "Choosing note-priority rules on a monophonic synth.", "Managing polyphony on a sampler to avoid cut-off notes in a busy part."]}, "b6974f94-e833-4ab9-8faf-1a70570a0fca": {"definition": "Waveform folding, or wavefolding, is a nonlinear synthesis technique that reflects the portions of a waveform exceeding a threshold back toward the center, adding harmonics and reshaping the timbre rather than simply clipping the peaks.", "plain_english": "Waveform folding bends the loud peaks of a wave back on themselves. This folding adds bright, buzzy overtones and turns a plain tone into a richer one.", "purpose_function": "It enriches a simple waveform with new overtones, creating bright, complex, often evolving tones that are central to West Coast and modular synthesis.", "practical_application": "A synthesist feeds a sine or triangle wave into a wavefolder and modulates the fold amount with an envelope or LFO to generate moving, harmonically rich sounds.", "category": "Synthesis technique", "related_terms": ["Wavetable synthesis", "Waveshaping", "Frequency modulation", "Additive synthesis", "Distortion"], "common_mistakes": ["Confusing folding with clipping; clipping flattens peaks while folding turns them back.", "Pushing the fold amount so high the tone becomes harsh and unstable.", "Expecting only a subtle change; folding can strongly alter the timbre."], "scenario_contexts": ["Using a wavefolder to add bright harmonics to a plain sine or triangle wave.", "Modulating fold amount with an envelope for evolving timbres.", "Designing aggressive West Coast style synth tones."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"7b4398d8-e0bb-4620-80c2-9d3a8714df3a": {"definition": "A synthesis technique that produces a continuous, gradual transition between two or more source waveforms by interpolating between their shapes over time, so the timbre changes smoothly from one waveform to another.", "plain_english": "It slowly blends one sound wave into another, the way one photo can fade into a different photo. As it blends, the tone changes little by little.", "purpose_function": "It exists to create evolving, moving timbres from a small set of stored waveforms, giving a synth sound life and change without switching abruptly between fixed tones.", "practical_application": "A technician modulates a morph or wavetable-position control with an envelope or LFO to make a pad or lead slowly shift from a dull, soft tone to a bright, harmonically rich one.", "category": "Synthesis", "related_terms": ["Wavetable oscillator", "Waveform shaping", "Interpolation", "Timbre", "LFO"], "common_mistakes": ["Confusing morphing with a simple volume crossfade of two separate oscillators; true morphing interpolates the waveform shape itself, not just the loudness of two sounds.", "Assuming morphing always sounds smooth, when large differences between source waveforms can produce audible stepping or harsh artifacts.", "Thinking morphing and wavetable-position sweeps are unrelated, when sweeping through a wavetable is one common way morphing is implemented."], "scenario_contexts": ["Automating a slow timbral sweep on a pad so it evolves from a soft, sine-like tone to a bright, edgy one.", "Using an LFO or envelope to morph an oscillator's shape and add movement to a lead sound.", "Designing evolving textures in a soft synth such as Serum or Massive by moving through morphing waveforms."]}, "f5acbd98-9719-4e5b-a39e-b193b5a1c056": {"definition": "A synthesis technique, also called waveshaping, in which a signal is passed through a nonlinear transfer function that reshapes its waveform and adds new harmonics, changing the timbre in a controlled, level-dependent way.", "plain_english": "It bends a sound wave into a new shape to give it a richer, buzzier tone. Think of it like reshaping clay to change how it looks.", "purpose_function": "It exists to add harmonics and character to a simple tone, letting a plain waveform become a complex, brighter, or more saturated sound without extra oscillators.", "practical_application": "A technician routes a clean synth tone through a waveshaper or saturation stage to add warmth, grit, or harmonic edge, adjusting drive to control how much new harmonic content appears.", "category": "Synthesis", "related_terms": ["Wavetable oscillator", "Waveform morphing", "Harmonic distortion", "Transfer function", "Timbre"], "common_mistakes": ["Confusing waveshaping with filtering; a filter removes harmonics, while waveshaping adds new ones through a nonlinear transfer function.", "Driving the shaper too hard and creating harsh aliasing, especially at high pitches when no oversampling is used.", "Assuming waveshaping only means heavy distortion, when gentle shaping can add subtle warmth and low-level harmonics."], "scenario_contexts": ["Adding harmonic richness and grit to a synth bass by routing it through a waveshaper.", "Using a soft-clipping waveshaper to emulate analog saturation on a track.", "Building complex timbres from a simple sine wave by shaping it with a nonlinear curve."]}, "12a86bbe-6f2c-43eb-a8d6-bc1b894fdcda": {"definition": "An oscillator that generates sound by repeatedly reading through a stored table of single-cycle waveforms, looping the table at a rate set by the desired pitch, and often sweeping across successive waveforms to change timbre over time.", "plain_english": "It makes sound by playing through a list of stored wave shapes, one after another. Sweeping through the list slowly changes the tone, like flipping the pages of a flip book.", "purpose_function": "It exists to produce a wide range of rich, evolving digital timbres efficiently, using stored waveforms instead of computing complex tones in real time.", "practical_application": "A technician selects a wavetable and modulates its position with an envelope or LFO to make a lead, bass, or pad move through different tones as a note plays.", "category": "Synthesis", "related_terms": ["Waveform morphing", "Waveform shaping", "Single-cycle waveform", "Oscillator", "Wavetable synthesis"], "common_mistakes": ["Thinking a wavetable holds a full recording, when each slot usually stores just one single-cycle waveform.", "Sweeping the table position too fast and getting clicks or aliasing instead of smooth movement.", "Confusing wavetable synthesis with sample playback; a wavetable oscillator loops short cycles at pitch rather than playing a whole recorded sample."], "scenario_contexts": ["Creating an evolving lead by modulating the wavetable position with an envelope.", "Programming a bright, digital pad in a synth such as Serum, Massive, or a Waldorf instrument.", "Layering two detuned wavetable oscillators for a fat, moving sound."]}, "56de5cab-cf23-4f1e-aed5-86dfc5ef801b": {"definition": "In a sampler, the assignment of samples to defined ranges of the keyboard (key zones) and playing dynamics (velocity zones) so that the correct sample plays for a given note and playing dynamic (how hard the key is struck).", "plain_english": "It tells a sampler which recorded sound to play for each key and how hard you press. So low keys, high keys, and soft or loud hits can each trigger their own sample.", "purpose_function": "It exists so one instrument can cover a full keyboard and dynamic range with many samples, keeping each sample near its natural pitch and loudness instead of stretching one sound over everything.", "practical_application": "A technician building a sampled instrument drags samples onto key and velocity ranges, sets each sample's root key, and checks that zones cover the whole keyboard with no gaps or unwanted overlaps.", "category": "Sample mapping", "related_terms": ["Key mapping", "Velocity layer", "Sample", "Multisampling", "Root key"], "common_mistakes": ["Leaving gaps between key zones so some notes trigger no sample and play silence.", "Overlapping velocity zones by mistake so two samples sound at once at certain velocities.", "Forgetting to set a sample's root key, so its zone plays back at the wrong pitch."], "scenario_contexts": ["Building a multisampled piano by mapping each recorded note across a small range of keys.", "Setting up velocity zones so soft hits trigger a quiet sample and hard hits trigger a bright, loud one.", "Mapping a drum kit so each key or pad triggers a different drum sample."]}, "c551a5bf-9d0f-49a3-ba60-d3b720b25545": {"definition": "Grains generated at irregular, stochastically spaced points in time rather than at a fixed periodic rate, so they scatter into a texture with no perceptible pulse.", "plain_english": "These are tiny sound bits played at random, uneven moments instead of on a steady beat. They fall like scattered raindrops rather than the tick of a clock.", "purpose_function": "Scattering grains randomly in time avoids the buzzy pitched tone of a steady grain rate and instead builds smooth, evolving clouds of sound.", "practical_application": "A technician picks a random or asynchronous timing mode in a granular synth or effect to turn a sample into a lush, non-rhythmic pad or ambient wash.", "category": "Granular Synthesis", "related_terms": ["Audio grain", "Grain cloud", "Cloud synthesis", "Grain buffer", "Buffer position"], "common_mistakes": ["Assuming the grains still line up with the beat, when their timing is deliberately random and has no steady pulse.", "Confusing random timing with pitch; scattering grains in time changes the texture, not the note.", "Setting grain density too low, which leaves audible gaps instead of a smooth cloud."], "scenario_contexts": ["Building an evolving ambient pad from a short vocal sample.", "Creating a wind-like texture from a field recording.", "Smoothing a time-stretched sample so no rhythmic buzz appears."]}, "5c71caa8-9154-4706-9460-15fbfe0d69ff": {"definition": "A very short segment of sound, typically well under 100 ms and often 10-30 ms, shaped by a smooth amplitude envelope, used as the basic building block of granular synthesis.", "plain_english": "A grain is a tiny slice of sound only a few thousandths of a second long. Granular synths stack many of these little slices to build bigger sounds, like bricks making a wall.", "purpose_function": "The grain is the smallest unit a granular system works with, so combining many of them lets you rebuild, stretch, or reshape a sound from its smallest parts.", "practical_application": "When granulating a sample, a technician sets each grain's length and envelope to control how smooth or choppy the resulting texture sounds.", "category": "Granular Synthesis", "related_terms": ["Asynchronous grains", "Grain cloud", "Grain buffer", "Cloud synthesis", "Buffer position"], "common_mistakes": ["Making grains too short, which adds clicks or a buzzy tone instead of clean sound.", "Skipping the grain envelope, so hard edges cause a click at each grain.", "Thinking a grain is a whole note when it is only a tiny fragment of sound."], "scenario_contexts": ["Time-stretching a vocal without changing its pitch.", "Freezing a single moment of a sample into a sustained tone.", "Designing a granular pad from a short instrument sample."]}, "59d5a878-c51c-49f7-9877-a77f5756699f": {"definition": "The size of a memory buffer holding audio, given as a duration or a number of samples, which sets how much recorded sound is available for playback, looping, or granular processing.", "plain_english": "Buffer length is how much sound the computer holds in memory to work with, measured in seconds or samples. A longer buffer stores more audio, like a bigger notepad holds more notes.", "purpose_function": "It defines the window of stored audio the system can read grains or loops from, so too short limits the material while too long uses more memory.", "practical_application": "A technician sets buffer length to match the sample they want to granulate or loop, making sure the whole phrase fits in memory.", "category": "Granular Synthesis", "related_terms": ["Grain buffer", "Buffer position", "Buffer loop", "Buffer scan", "Audio grain"], "common_mistakes": ["Setting the buffer too short, so the sample is cut off before it finishes.", "Confusing buffer length with grain length; one holds the source, the other is a tiny slice.", "Using a needlessly long buffer that wastes memory."], "scenario_contexts": ["Loading a four-second vocal phrase into a granular sampler.", "Recording live audio into a buffer for real-time granulation.", "Sizing loop memory in a hardware sampler before capturing a phrase."]}, "451cda98-58c1-42aa-8e48-70fdeb35cdf3": {"definition": "Continuous, repeating playback of the audio stored in a buffer, cycling from the end back to a start point so the buffered material sounds without pause.", "plain_english": "A buffer loop plays the stored sound over and over, jumping back to the start each time it reaches the end. It is like setting a song to repeat.", "purpose_function": "Looping a buffer lets a short recording sustain without end, giving a steady stream of source material for pads, drones, or grains.", "practical_application": "A technician loops a captured phrase in a sampler so grains or playback keep drawing from it while other controls are adjusted.", "category": "Granular Synthesis", "related_terms": ["Buffer length", "Buffer position", "Buffer scan", "Grain buffer", "Cloud synthesis"], "common_mistakes": ["Placing loop points away from zero crossings, which causes a click on every cycle.", "Confusing a buffer loop with a grain; the loop repeats the whole stored audio, not a tiny slice.", "Looping a phrase whose start and end do not match, leaving an audible seam."], "scenario_contexts": ["Holding a sustained drone from a short recorded note.", "Keeping a live-recorded phrase cycling for real-time granulation.", "Building a rhythmic loop from a captured bar of audio."]}, "8930d53c-84aa-4eab-b7ac-6e42dd503622": {"definition": "The read location within an audio buffer from which playback or a grain is taken, usually expressed as a time offset or a normalized value between the buffer's start and end.", "plain_english": "Buffer position is the exact spot in the stored sound the playhead reads from right now. Moving it is like sliding your finger to a different point on a tape.", "purpose_function": "It selects which part of the stored audio you hear or granulate, letting you focus on any single moment of the sample.", "practical_application": "A technician moves the buffer position to scrub to a specific vowel or transient in a sample and generate grains from that exact spot.", "category": "Granular Synthesis", "related_terms": ["Buffer scan", "Buffer length", "Grain buffer", "Audio grain", "Buffer loop"], "common_mistakes": ["Confusing buffer position with pitch; position picks where to read, not what note plays.", "Jumping the position abruptly, which can click if grains are not enveloped.", "Assuming position is fixed, when in granular engines it can be moved continuously."], "scenario_contexts": ["Freezing on one moment of a pad by holding the position still.", "Slowly moving through a sample to reveal its inner detail.", "Targeting a single drum hit inside a longer loop."]}, "2a0dfaca-abd6-48ef-8b95-383f1f0117d6": {"definition": "The act of moving the read position through an audio buffer over time, sweeping across the stored sound to select changing source material for playback or grains.", "plain_english": "Buffer scan means slowly sliding the read point across the stored sound. It is like dragging a magnifying glass along a strip of tape to hear each part in turn.", "purpose_function": "Scanning lets a technician explore or perform through a sample, turning a static recording into an evolving, playable sound source.", "practical_application": "A technician automates or hand-moves the scan control to sweep grains through a sample, morphing the texture as the read point travels.", "category": "Granular Synthesis", "related_terms": ["Buffer position", "Buffer length", "Grain buffer", "Buffer loop", "Grain cloud"], "common_mistakes": ["Scanning too fast, which turns the smooth sweep into a pitched buzz.", "Confusing scan with playback speed; scanning moves the read point, not grain pitch.", "Forgetting grain envelopes, so a fast scan adds clicks."], "scenario_contexts": ["Sweeping through a vocal to morph between vowels.", "Performing a granular pad live by scanning a loaded sample.", "Automating a slow scan across a texture for an evolving soundscape."]}, "6e7282c6-474d-493b-bced-cec1370d125f": {"definition": "A granular technique that builds sound from dense masses of grains, called clouds, whose overall statistics such as density, duration, pitch spread, and position are controlled rather than each grain individually.", "plain_english": "Cloud synthesis makes sound from a thick swarm of tiny grains, shaped as a group instead of one at a time. It is like sculpting a cloud of mist rather than placing each droplet.", "purpose_function": "Treating grains as a cloud lets a technician sculpt rich, evolving textures by setting overall rules for how thousands of grains behave.", "practical_application": "A technician dials in grain density, spread, and duration to grow a shimmering cloud from a simple sample instead of programming each grain.", "category": "Granular Synthesis", "related_terms": ["Grain cloud", "Asynchronous grains", "Audio grain", "Grain buffer", "Buffer scan"], "common_mistakes": ["Setting density too low, so the cloud thins into separate audible grains.", "Expecting note-by-note control, when cloud synthesis is shaped by statistics rather than single grains.", "Overlapping too many loud grains, which overloads and distorts the output."], "scenario_contexts": ["Creating an evolving ambient wash from one recorded note.", "Turning a short sample into a dense granular texture.", "Designing an atmospheric sound bed for film or game audio."]}, "5ff2422e-c7d8-4901-8abc-c2bd66aa850b": {"definition": "The block of memory that stores the audio a granular engine reads grains from; each grain is a short excerpt copied from a position within this buffer.", "plain_english": "The grain buffer is the pocket of memory that holds the sound a granular synth chops into grains. Think of it as the loaf of bread the synth keeps slicing pieces from.", "purpose_function": "It supplies the source audio for granulation, holding the recorded or loaded sample so grains can be drawn from any point in it.", "practical_application": "A technician loads a sample or records live audio into the grain buffer, then sets position and size to pull grains from it.", "category": "Granular Synthesis", "related_terms": ["Audio grain", "Buffer position", "Buffer length", "Buffer scan", "Grain cloud"], "common_mistakes": ["Confusing the grain buffer with a single grain, when the buffer holds all the source audio.", "Overwriting the buffer while grains still read from it, causing glitches.", "Loading audio at the wrong sample rate, which shifts the buffer's pitch and length."], "scenario_contexts": ["Loading a vocal sample into a granular plugin before granulating.", "Recording live input into the buffer for real-time granular effects.", "Swapping the buffer's contents to change the granular sound source."]}, "e29a6aca-e1fa-48ae-879a-c913bbffac8d": {"definition": "A dense collection of overlapping grains distributed across time and frequency, heard as a single evolving texture rather than as separate sonic particles.", "plain_english": "A grain cloud is a thick swarm of tiny sound grains heard as one shifting texture. Like a cloud of gnats looks like one shape from far away, the grains blur into a single sound.", "purpose_function": "Grouping grains into a cloud creates smooth, complex textures whose density and spread can be shaped as a whole.", "practical_application": "A technician raises grain density and spread to grow a grain cloud from a sample, producing an atmospheric pad or wash.", "category": "Granular Synthesis", "related_terms": ["Cloud synthesis", "Asynchronous grains", "Audio grain", "Grain buffer", "Buffer scan"], "common_mistakes": ["Setting density too low, so the cloud breaks into audible separate grains.", "Confusing a grain cloud with a single grain, when the cloud is made of many overlapping ones.", "Piling up too many grains, which can overload the output and distort."], "scenario_contexts": ["Building an ambient texture from a short recorded sound.", "Thickening a thin sample into a lush pad.", "Creating an evolving background wash for a film scene."]}, "f4e0c346-0ed1-4e0c-a44c-95b794cb1317": {"definition": "In granular synthesis, grain density is the number of sound grains generated per unit of time, usually expressed in grains per second. Higher density packs more overlapping grains together for thick, continuous textures, while lower density produces sparse, pointillistic sounds.", "plain_english": "Granular tools chop a sound into tiny slices called grains and play lots of them. Grain density is how many grains you hear each second. More grains make a thick, smooth wash; fewer grains sound like scattered dots.", "purpose_function": "It controls how sparse or thick a granular texture is, so the sound can range from a few separate points to a dense, continuous cloud.", "practical_application": "A producer raises grain density to turn a short sample into a lush ambient pad, or lowers it for a stuttering, rhythmic effect.", "category": "Granular Synthesis", "related_terms": ["Grain duration", "Grain overlap", "Grain envelope", "Grain position", "Granular synthesis"], "common_mistakes": ["Confusing density with grain duration — density is how many grains play per second, not how long each grain lasts", "Pushing density very high without watching levels, which lets grains stack up and clip the output"], "scenario_contexts": ["Building an evolving ambient pad from a one-shot vocal sample", "Creating a granular drone for a film score", "Designing a sparse, pointillistic percussion texture"]}, "ea4d42fa-87f7-4328-8059-2fe918031e19": {"definition": "Grain duration is the length of each individual grain in granular synthesis, typically ranging from about 1 to 100 milliseconds. Very short grains blur the source into buzzy or pitched textures, while longer grains preserve more of the original sample's recognizable character.", "plain_english": "A grain is a tiny slice of a sound. Grain duration is how long each slice lasts, often just a few thousandths of a second. Very short grains sound rough and buzzy; longer grains sound more like the real sample.", "purpose_function": "It shapes the timbre and clarity of a granular sound, trading recognizable source material for smoother or grittier textures.", "practical_application": "An engineer shortens grain duration to smear a sample into a pad, or lengthens it to keep words or notes recognizable.", "category": "Granular Synthesis", "related_terms": ["Grain density", "Grain envelope", "Grain overlap", "Grain position", "Granular synthesis"], "common_mistakes": ["Setting grains extremely short and still expecting the source to stay recognizable", "Confusing grain duration (the length of one grain) with grain density (how many grains play per second)"], "scenario_contexts": ["Turning a spoken-word clip into a smooth textured drone", "Dialing in a metallic, buzzy grain sound for sound design", "Keeping a melody audible while time-stretching with grains"]}, "b72dea3e-dbcd-4fb0-a82b-a9041dbf013f": {"definition": "A grain envelope is the amplitude shape, or window, applied to each grain so it fades in and out smoothly. It prevents clicks at the grain's edges and strongly affects the smoothness and timbre of the texture; common shapes include Gaussian, Hann, and trapezoidal windows.", "plain_english": "Each grain gets a volume shape that fades it in and out. This is the grain envelope. Without it, the sudden start and stop of every grain would make clicks and pops.", "purpose_function": "It smooths the start and end of every grain to avoid clicks, and its shape controls how soft or sharp the texture sounds.", "practical_application": "A sound designer picks a smooth bell-shaped envelope for pads, or a sharper one for percussive, gritty grains.", "category": "Granular Synthesis", "related_terms": ["Grain duration", "Grain density", "Grain overlap", "Envelope", "Granular synthesis"], "common_mistakes": ["Assuming grains can play with no envelope — without a fade, the hard edges click", "Confusing the per-grain envelope with the overall amplitude envelope of the whole sound"], "scenario_contexts": ["Removing clicks from a granular pad by choosing a smoother window", "Shaping percussive grains with a sharper attack for rhythmic textures", "Comparing Gaussian and Hann windows to change how smooth a cloud sounds"]}, "55ccad41-a136-48b0-9baa-52f75f0d69f7": {"definition": "Grain freeze is a granular technique that holds playback at a fixed point in the source sample and keeps generating grains from that spot, sustaining a single moment of the sound indefinitely. This turns a brief slice of audio into a steady drone or pad.", "plain_english": "Grain freeze locks onto one spot in a sound and keeps making grains from that same spot. This stretches a single moment out, like holding one frame of a video. A short sound becomes a long, steady pad.", "purpose_function": "It lets a fleeting moment of a sample be held as a continuous tone, which is useful for pads, drones, and ambient beds.", "practical_application": "A producer freezes on a sustained vowel in a vocal to create an evolving background pad under a track.", "category": "Granular Synthesis", "related_terms": ["Grain position", "Grain density", "Grain jitter", "Grain duration", "Granular synthesis"], "common_mistakes": ["Expecting a frozen grain cloud to sound perfectly static — a little movement or jitter is usually needed to avoid a robotic, looping tone", "Freezing on a silent or very quiet part of the sample and getting almost no output"], "scenario_contexts": ["Sustaining a single chord from a sample into an ambient drone", "Holding a reverb tail to build an evolving pad", "Freezing one moment of a field recording for a film soundscape"]}, "1aab5be7-4717-4413-8ba1-264d813d3901": {"definition": "Grain jitter is deliberate random variation applied to grain parameters such as start position, timing, pitch, or pan. Small amounts break up mechanical repetition and add natural movement, while larger amounts create chaotic, noisy textures.", "plain_english": "Jitter adds a little randomness to the grains. Instead of every grain being exactly the same, each one shifts slightly. A small amount makes the sound feel alive; a lot makes it messy and noisy.", "purpose_function": "It adds controlled randomness so grains do not repeat identically, making textures sound more natural and less robotic.", "practical_application": "An engineer adds a touch of position and pitch jitter to a frozen grain cloud so it stops sounding like a static loop.", "category": "Granular Synthesis", "related_terms": ["Grain position", "Grain pitch", "Grain pan", "Grain freeze", "Granular synthesis"], "common_mistakes": ["Adding too much jitter and turning a musical texture into noise", "Assuming jitter changes pitch only — it can also randomize position, timing, and pan"], "scenario_contexts": ["Humanizing a static granular pad so it feels less mechanical", "Spreading grains randomly for a wide stereo cloud", "Creating a chaotic, evolving sound-design texture"]}, "12ecafb8-4f40-42d5-b666-59c5dfcd6be8": {"definition": "Grain overlap is the extent to which successive grains coincide in time, set by the relationship between grain duration and the spacing between grain onsets. Higher overlap fills the gaps between grains for smoother, denser textures, while low or no overlap leaves audible gaps or rhythmic separation.", "plain_english": "Grains can start before the last one has finished, so they overlap. Grain overlap is how much they pile on top of each other. Lots of overlap makes a smooth, gapless sound; little overlap leaves gaps you can hear.", "purpose_function": "It controls whether grains blend into a continuous sound or stay separate, shaping the smoothness and density of the texture.", "practical_application": "A producer increases overlap to remove gaps and smooth a time-stretched sample into a seamless texture.", "category": "Granular Synthesis", "related_terms": ["Grain density", "Grain duration", "Grain envelope", "Grain position", "Granular synthesis"], "common_mistakes": ["Confusing overlap with density — overlap is how much grains share time, density is how many play per second", "Using very high overlap without watching levels, which lets grains build up and clip"], "scenario_contexts": ["Smoothing a time-stretch so no gaps are heard", "Dialing back overlap for a stuttering, rhythmic effect", "Building a dense, continuous cloud from a single sample"]}, "1ea520e5-9a3c-484b-bc05-dc63181a8a69": {"definition": "Grain pan is the stereo placement assigned to individual grains, often spread or randomized across the stereo field. Distributing grains to different pan positions widens the sound into an enveloping stereo cloud rather than a single point.", "plain_english": "Grain pan sets where each grain sits from left to right. When grains are spread out or placed randomly, the sound feels wide and surrounds you. When they all sit in the center, it sounds narrow.", "purpose_function": "It spreads grains across the stereo image to create width and a sense of space in a granular texture.", "practical_application": "A sound designer randomizes grain pan to turn a mono sample into a wide, immersive stereo pad.", "category": "Granular Synthesis", "related_terms": ["Grain jitter", "Grain density", "Grain position", "Grain pitch", "Stereo width"], "common_mistakes": ["Spreading grains very wide without checking mono compatibility, which can cause phase problems when the mix is summed to mono", "Assuming heavy random panning always sounds good — it can make the stereo image feel unstable"], "scenario_contexts": ["Widening a mono vocal into a stereo granular cloud", "Creating an immersive ambient bed for a mix", "Moving grains dynamically across the field for motion in a patch"]}, "226695e2-47dc-4f46-9ebf-d3492409354b": {"definition": "Grain pitch is the playback pitch of individual grains, set independently of how the playhead moves through the sample. Adjusting it transposes the source without changing its length, and randomizing it across grains produces shimmering or chord-like clouds.", "plain_english": "Grain pitch is how high or low each grain plays. You can raise or lower it without making the sample faster or slower. Spreading the pitch across many grains can create a shimmering, chord-like sound.", "purpose_function": "It lets grains be transposed separately from position, so pitch can change without altering timing or length.", "practical_application": "A producer shifts grain pitch up an octave for a sparkling texture, or randomizes it to build a chord from a single note.", "category": "Granular Synthesis", "related_terms": ["Grain position", "Grain jitter", "Grain density", "Pitch shifting", "Granular synthesis"], "common_mistakes": ["Confusing grain pitch with grain position — pitch is how high grains sound, position is where in the sample they come from", "Expecting a pitch change to also change length, as it would with simple tape-style speed changes"], "scenario_contexts": ["Transposing a sample without the usual time-stretch artifacts", "Building shimmering octave-up textures", "Randomizing pitch to form chord clouds from one note"]}, "b7b32a06-3ccb-4ba1-919f-21b7dcbf637c": {"definition": "Grain position is the location within the source sample from which grains are read, effectively the playhead point for granular playback. Moving it scans through the sample, while holding it fixed sustains one moment as a texture.", "plain_english": "Grain position is the spot in the sample where grains are taken from. Move it and you scan through the sound; hold it still and you stay on one moment. It is like choosing where to set the needle on a record.", "purpose_function": "It selects and scans the point in the sample used for grains, controlling which part of the source is heard and how it evolves.", "practical_application": "An engineer slowly sweeps grain position across a sample to morph smoothly from one sound into another.", "category": "Granular Synthesis", "related_terms": ["Grain freeze", "Grain jitter", "Grain density", "Grain pitch", "Granular synthesis"], "common_mistakes": ["Confusing grain position with grain pitch — position is where in the sample, pitch is how high it plays", "Sweeping position too quickly and losing the smooth, sustained texture"], "scenario_contexts": ["Scanning through a vocal sample to morph between vowels", "Holding position to freeze a moment into a pad", "Automating slow position sweeps for evolving soundscapes"]}, "86f788a9-d99b-4019-a0d6-b620859d058e": {"definition": "In granular synthesis, the deliberate introduction of random variation into grain parameters such as start position, size, pitch, amplitude, and pan, so that successive grains differ instead of repeating identically. It replaces mechanical regularity with a more natural, evolving texture.", "plain_english": "Granular synthesis builds sound from tiny slices called grains. Grain randomization changes each slice a little at random, so the sound feels alive instead of buzzy and robotic. It is like tossing confetti instead of stacking it in a neat line.", "purpose_function": "It exists to avoid the static, buzzy tone that comes from playing identical grains in a fixed pattern, adding movement and organic variation to a granular texture.", "practical_application": "A technician dials in small amounts of position and pitch randomization on a granular plugin to turn a short looping sample into an evolving pad or ambience.", "category": "Granular synthesis", "related_terms": ["Grain spray", "Grain spread", "Grain size", "Grain synchronization", "Grain transposition"], "common_mistakes": ["Adding so much randomization that pitch and timing become unstable and the sound loses its intended character", "Assuming randomization alone makes a good texture, when grain size and grain shape matter just as much", "Confusing randomizing grain parameters with simply lowering the grain rate"], "scenario_contexts": ["Turning a short vocal sample into a shifting ambient pad", "Designing evolving sci-fi textures for film sound", "Loosening up a stiff, mechanical granular loop"]}, "8c0a6db5-917d-4a95-9615-fef13c373e5d": {"definition": "The number of grains generated per unit of time in granular synthesis, usually stated in grains per second; it sets how densely grains are packed and strongly affects perceived texture and pitch. Higher rates fuse grains into continuous tones, while lower rates yield distinct, separated events.", "plain_english": "Granular synthesis makes sound from tiny slices called grains. Grain rate is how many of those slices play each second. A high rate blurs them into a smooth tone, while a low rate lets you hear each little tick.", "purpose_function": "It controls the density of the grain stream, letting a sound range from a smooth continuous texture to a sparse, rhythmic stutter.", "practical_application": "A technician raises the grain rate to fuse grains into a solid pad, or lowers it to create a granular stutter or click texture.", "category": "Granular synthesis", "related_terms": ["Grain spacing", "Grain size", "Grain synchronization", "Grain randomization", "Grain shape"], "common_mistakes": ["Confusing grain rate with grain size; rate is how often grains play, size is how long each one lasts", "Setting the rate very low and expecting a smooth, continuous tone", "Not realizing that very high synchronous rates can introduce an audible pitch"], "scenario_contexts": ["Building a dense granular pad from a single note", "Creating a rhythmic stutter effect from a drum loop", "Tuning texture density in a sound-design patch"]}, "c8e40bfb-f9ca-4692-b1ed-f2c1ef935484": {"definition": "The amplitude envelope applied to each individual grain, controlling how it fades in and out over its short duration; common shapes include Gaussian, Hann (raised-cosine), triangular, and trapezoidal. The envelope smooths grain edges to prevent clicks and shapes the grain's tonal character.", "plain_english": "Each grain is a tiny slice of sound, and grain shape is the fade put on its start and end. A smooth, rounded fade stops clicks, while a sharper shape sounds more percussive. It is like the fade-in and fade-out on a very short clip.", "purpose_function": "It exists to prevent clicks at grain boundaries and to control the smoothness and tone of the resulting texture.", "practical_application": "A technician chooses a smooth Gaussian-style shape for pads and a sharper shape for percussive or gritty granular textures.", "category": "Granular synthesis", "related_terms": ["Grain size", "Grain rate", "Grain randomization", "Grain spacing", "Grain synchronization"], "common_mistakes": ["Using a hard-edged grain shape and then wondering where the clicking comes from", "Thinking grain shape changes pitch rather than smoothness and tone", "Ignoring how a very short grain combined with a wide fade leaves little usable sustain"], "scenario_contexts": ["Removing clicks from a granular pad", "Making a granular texture more percussive", "Shaping the tone of a time-stretched sample"]}, "e3bd256e-3499-4bcc-844a-11f8298c0a9a": {"definition": "The duration of a single grain in granular synthesis, typically ranging from roughly 1 to 100 milliseconds; it determines whether individual grains are heard as separate events or fuse into a continuous tone. Very short grains sound like clicks or noise, while longer grains preserve more of the source sound's character.", "plain_english": "A grain is a tiny slice of sound, and grain size is how long each slice lasts, usually just a few thousandths of a second. Short grains sound like clicks or noise, while longer grains keep more of the original sound. It is like choosing how thick to cut each slice.", "purpose_function": "It sets the basic character of the texture, trading off between recognizable source material with longer grains and abstract, cloud-like tone with shorter grains.", "practical_application": "A technician shortens grain size to smear a sample into a smooth cloud, or lengthens it to keep the sample recognizable while time-stretching.", "category": "Granular synthesis", "related_terms": ["Grain rate", "Grain shape", "Grain spacing", "Grain randomization", "Grain transposition"], "common_mistakes": ["Confusing grain size, the length of each grain, with grain rate, how many play per second", "Setting grains extremely short and expecting the source to stay recognizable", "Forgetting that very short grains emphasize noise and lose low-frequency content"], "scenario_contexts": ["Time-stretching a vocal without changing its pitch", "Turning a sustained note into a shimmering cloud", "Designing textured drones from a field recording"]}, "4d906325-7d92-4c8e-9685-9077dfce472c": {"definition": "The time interval between the onsets of successive grains in granular synthesis; it is the inverse of grain rate and, together with grain size, determines whether grains overlap, abut, or leave gaps. Regular spacing yields synchronous streams, while varied spacing yields scattered, asynchronous textures.", "plain_english": "Grain spacing is the gap in time between one grain starting and the next. Small gaps pack grains tightly into a smooth sound, while big gaps leave space so you hear separate ticks. It is like how close together beads sit on a string.", "purpose_function": "It controls how tightly grains are packed in time, shaping density, overlap, and the rhythmic feel of a granular texture.", "practical_application": "A technician tightens grain spacing so grains overlap into a solid pad, or widens it to open gaps for a sparse, rhythmic effect.", "category": "Granular synthesis", "related_terms": ["Grain rate", "Grain size", "Grain synchronization", "Grain randomization", "Grain shape"], "common_mistakes": ["Confusing spacing with grain size; spacing is the gap between grains, size is each grain's length", "Assuming grains always overlap, when wide spacing leaves audible gaps", "Overlooking that spacing and rate describe the same thing from opposite directions"], "scenario_contexts": ["Creating overlapping grains for a seamless pad", "Opening gaps for a sputtering granular rhythm", "Balancing density in a sound-design patch"]}, "778ac4c7-43e6-47ec-886b-a6c987fd90a1": {"definition": "A control in many granular instruments that randomizes the read position, and sometimes the timing, of grains within the source sample, scattering their start points instead of reading strictly in order. Small amounts add subtle motion, while larger amounts smear the sample into a diffuse cloud.", "plain_english": "Grain spray scatters where each grain is picked from inside the sample, instead of reading it in a straight line. A little spray adds gentle movement, and a lot turns the sample into a blurry cloud. It is like spraying droplets instead of pouring a steady stream.", "purpose_function": "It exists to add randomness and motion to a granular texture by jittering grain positions, reducing mechanical repetition.", "practical_application": "A technician adds a little spray to keep a held granular note from sounding static, or a lot to blur a sample into ambience.", "category": "Granular synthesis", "related_terms": ["Grain randomization", "Grain spread", "Grain size", "Grain rate", "Grain spacing"], "common_mistakes": ["Confusing spray, random read position, with spread, the stereo placement of grains", "Using extreme spray and losing all sense of the original sample", "Assuming spray changes pitch, when it mainly changes where grains are read"], "scenario_contexts": ["Adding subtle motion to a sustained granular pad", "Blurring a loop into an ambient wash", "Preventing a frozen sample from sounding static"]}, "bf33fb65-7aa2-4926-9c13-80f3e2973152": {"definition": "A control that distributes grains across the stereo field, typically by randomizing each grain's pan position, so that a granular texture widens from a narrow point source into a broad stereo image. Larger settings place successive grains further apart across the left-right panorama.", "plain_english": "Grain spread places grains at different points from left to right across the stereo picture. A wide spread makes the sound big and surrounding, while none keeps it in the center. It is like scattering grains across the room instead of stacking them in one spot.", "purpose_function": "It exists to widen and add spatial depth to a granular texture by placing individual grains at different stereo positions.", "practical_application": "A technician increases grain spread to turn a mono sample into a wide, immersive stereo pad.", "category": "Granular synthesis", "related_terms": ["Grain spray", "Grain randomization", "Grain size", "Grain rate", "Grain synchronization"], "common_mistakes": ["Confusing spread, stereo placement, with spray, the random read position in the sample", "Setting extreme spread and creating mono-compatibility or phase problems", "Expecting spread to add movement in time rather than across the stereo field"], "scenario_contexts": ["Widening a mono sample into a stereo pad", "Creating an immersive ambient bed", "Adding spaciousness to a granular texture"]}, "0ad487f9-f308-43ef-9dca-4bd1ad5a6eef": {"definition": "In granular synthesis, the temporal alignment of grain emission, meaning whether grains are output at regular, evenly-timed intervals (synchronous granular synthesis) or at irregular, randomized intervals (asynchronous granular synthesis). Synchronous streams tend to produce pitched, tonal results, while asynchronous streams produce cloud-like textures.", "plain_english": "Grain synchronization is about whether grains play on a steady, even beat or at random times. Even timing gives a clear, pitched tone, while random timing makes a cloudy texture. It is like a steady drip versus scattered raindrops.", "purpose_function": "It determines the basic character of a granular stream, letting a sound be tonal and regular or diffuse and cloud-like.", "practical_application": "A technician uses synchronous grains to build a pitched pad, and switches to asynchronous timing for evolving clouds and atmospheres.", "category": "Granular synthesis", "related_terms": ["Grain spacing", "Grain rate", "Grain randomization", "Grain size", "Grain shape"], "common_mistakes": ["Assuming randomized, asynchronous grains will still hold a clear pitch", "Confusing grain synchronization with locking grains to the song tempo", "Overlooking that steady synchronous timing can add an unwanted pitched buzz"], "scenario_contexts": ["Building a pitched pad from evenly-timed grains", "Creating cloud textures with randomized timing", "Choosing between tonal and atmospheric granular results"]}, "daf78046-d8c5-4c91-acb8-a625aace233d": {"definition": "The pitch-shifting of grains by altering their internal playback rate independently of the grain stream's timing, so a sample can be moved up or down in pitch without changing its duration or read speed. It is the mechanism behind granular pitch-shifting and harmony effects.", "plain_english": "Grain transposition changes the pitch of each grain without changing how fast the sound moves through the sample. That means you can raise or lower the pitch while the timing stays the same. It is like speeding up a tiny slice to make it higher without rushing the whole song.", "purpose_function": "It exists to decouple pitch from time, allowing pitch-shifting, transposition, and layered harmonies within a granular texture.", "practical_application": "A technician transposes grains to shift a sample up an octave, or layers several transpositions to build granular harmonies.", "category": "Granular synthesis", "related_terms": ["Grain size", "Grain rate", "Grain randomization", "Grain shape", "Grain spacing"], "common_mistakes": ["Confusing grain transposition, which is pitch, with grain rate, which is density in time", "Expecting large transpositions to sound natural, when extreme shifts add artifacts", "Forgetting that grain size affects how clean a transposition sounds"], "scenario_contexts": ["Pitch-shifting a sample without changing its length", "Building granular harmonies from one source", "Transposing a texture to fit a song's key"]}, "aa53222e-6e59-4bbb-89bf-a7cf23d020c4": {"definition": "The continuous audio signal produced when a granular processor emits a sequence, or stream, of short sonic grains one after another. In synchronous granular synthesis the grains follow at a regular rate, and their combined result forms a stream whose pitch and texture depend on grain rate, grain duration, and grain content.", "plain_english": "A granular tool cuts sound into tiny pieces called grains and plays them in a row. The steady flow of grains coming out is the grain-stream output. Think of a string of beads, where each bead is a very short piece of sound.", "purpose_function": "It is the usable result of a granular process, the flowing signal that carries the reshaped pitch, texture, and timing built from many tiny grains. Without a stream the separate grains would not add up to a musical sound.", "practical_application": "A producer routes the grain-stream output of a granular instrument into the mix, then shapes it with grain rate and density controls to get anything from a smooth pad to a stuttering texture.", "category": "Granular Synthesis", "related_terms": ["Particle synthesis", "Granular time stretching", "Microsound", "Granular pitch shifting", "Live granular processing"], "common_mistakes": ["Confusing the grain-stream output with a single grain; the output is the whole ongoing flow, not one snippet.", "Setting the grain rate so low that the stream becomes a series of separate clicks instead of a continuous tone.", "Assuming the output pitch always equals the source pitch, when grain rate and spacing can shift the perceived pitch."], "scenario_contexts": ["Building an evolving ambient pad by streaming grains from a short vocal sample.", "Feeding a grain-stream output into a reverb to create a shimmering, sustained texture.", "Turning a static field recording into a pitched drone with a steady synchronous grain stream."]}, "4de6b8d0-df71-4a31-ac00-0891db6a6e58": {"definition": "A delay effect in which the incoming signal is broken into short grains that are individually delayed, and often repitched, reversed, or scattered, before being fed back, producing echoes made of granular fragments rather than exact copies of the input.", "plain_english": "A normal delay repeats your sound as clear echoes. A granular delay first cuts the sound into tiny grains, then echoes those, so the repeats can shimmer, blur, or change pitch. It is like an echo made of confetti instead of a clean copy.", "purpose_function": "It extends the delay idea into textural, evolving repeats that add motion and space beyond a plain echo. This lets an engineer build lush tails and clouds from a simple sound.", "practical_application": "An engineer places a granular delay on a synth or vocal to turn simple echoes into a clouded, drifting tail, adjusting grain size and feedback to control how smeared the repeats become.", "category": "Granular Synthesis", "related_terms": ["Granular reverb", "Granular pitch shifting", "Grain-stream output", "Live granular processing", "Microsound"], "common_mistakes": ["Expecting clean, rhythmic echoes, when granular delays smear and randomize the repeats by design.", "Pushing feedback too high, which can build into a runaway, unpredictable grain cloud.", "Setting grain size very small and then wondering why the repeats lose the original sound's character."], "scenario_contexts": ["Adding drifting, pitch-shifted echoes to a synth lead for an ambient section.", "Turning a spoken word phrase into a blurred, cloud-like tail for a transition.", "Creating rising, reversed echo swells before a drop in electronic music."]}, "cd3473b6-806a-40d4-b024-d392a44c57fd": {"definition": "A pitch-shifting method that slices audio into short grains and plays them back at a changed rate or spacing so the pitch moves while the overall duration is preserved. Overlapping grains are crossfaded to smooth the joins between them.", "plain_english": "This raises or lowers the pitch of a sound without making it faster or slower. It works by chopping the sound into tiny grains and repacking them. It is like saying the same sentence in a higher voice but at the same speaking speed.", "purpose_function": "It lets a technician change pitch on its own, separate from time, which is needed for tuning, harmonizing, or transposing recorded audio. This independence is the whole reason the grain method is used.", "practical_application": "A producer uses granular pitch shifting to move a sampled note up or down to fit a new key, or to stack shifted copies of a sound into a chord, watching for artifacts on large shifts.", "category": "Granular Synthesis", "related_terms": ["Granular time stretching", "Grain-stream output", "Granular delay", "Microsound", "Particle synthesis"], "common_mistakes": ["Shifting by large amounts and expecting no artifacts, when big shifts add graininess and a metallic tone.", "Confusing pitch shifting with time stretching, though here the duration stays fixed while pitch moves.", "Ignoring formant changes, which can make voices sound unnatural or chipmunk-like."], "scenario_contexts": ["Retuning a flat sampled vocal note to match the rest of a take.", "Building a harmony by layering pitch-shifted copies of one sound.", "Dropping a drum loop down an octave for a heavier feel without slowing it."]}, "5c783e16-2277-4d63-b10a-8d5ae024a346": {"definition": "A reverberation effect that builds its tail by spawning dense clouds of short grains from the input signal and scattering them in time, pitch, and stereo position to create a diffuse, evolving space rather than modeling a real room.", "plain_english": "Normal reverb copies the way sound bounces around a room. Granular reverb instead makes its tail from clouds of tiny grains, so the space can shimmer and slowly change. It is like a mist of sound rather than a plain echo of a hall.", "purpose_function": "It gives a lush, evolving sense of space and texture that a standard room reverb cannot, which is useful for ambient and cinematic sound design. The grain scattering creates the smooth, blurred tail.", "practical_application": "A sound designer sends a pad or vocal into a granular reverb to create a slowly blooming, shimmering wash, tuning grain size and density to control how thick and smeared the tail feels.", "category": "Granular Synthesis", "related_terms": ["Granular delay", "Grain-stream output", "Granular pitch shifting", "Live granular processing", "Microsound"], "common_mistakes": ["Treating it as a realistic room reverb, when it makes an artificial, evolving cloud instead.", "Using very short grains and losing the smoothness that a longer grain gives the tail.", "Overusing it on a busy mix, where the dense grain cloud can quickly muddy everything."], "scenario_contexts": ["Creating a shimmering ambient wash behind a slow synth pad.", "Adding a huge, blooming tail to a single piano note for a film cue.", "Turning a short vocal into a drifting cloud of sound for a texture bed."]}, "235ad55a-9f4f-4144-8d07-34bb2d4a92b7": {"definition": "A time-stretching technique that divides audio into short grains and repeats or re-spaces them to change the overall duration while keeping the pitch constant. Grain overlap and crossfading hide the joins so the result stays smooth.", "plain_english": "This makes a sound longer or shorter without changing its pitch. It works by cutting the sound into tiny grains, then spacing them out or repeating them. It is like stretching a row of beads by adding gaps, not by making each bead bigger.", "purpose_function": "It lets a technician change the length or tempo of audio without the pitch going up or down, which is key for matching tempos and fitting sounds to a timeline. This time and pitch independence is the main point.", "practical_application": "An engineer stretches a vocal or drum loop to fit a project's tempo, adjusting grain size to trade off between a smooth sound and audible graininess at extreme settings.", "category": "Granular Synthesis", "related_terms": ["Granular pitch shifting", "Grain-stream output", "Microlooping", "Microsound", "Particle synthesis"], "common_mistakes": ["Stretching by extreme amounts and expecting no artifacts, when large stretches add a grainy, watery tone.", "Confusing it with pitch shifting, though here duration changes while pitch stays fixed.", "Leaving grain size wrong for the material, which can smear transients on drums or add flutter to vocals."], "scenario_contexts": ["Slowing a sampled loop to fit a slower song without lowering its pitch.", "Stretching a short sound into a long pad for an ambient bed.", "Matching a borrowed vocal take to a new project tempo."]}, "f0632803-8027-4ac9-903b-89372f64e7d6": {"definition": "Granular synthesis or granular effects applied in real time to an incoming live audio signal, capturing short buffers of the input and re-granulating them on the fly. Barry Truax pioneered real-time granular systems for this kind of live work.", "plain_english": "This takes sound coming in right now, like a live mic or instrument, and chops it into grains as it plays. The reshaped, grainy result comes out with almost no delay. It is like a blender working on the sound the moment it arrives.", "purpose_function": "It brings granular textures and time and pitch effects into live performance and real-time interaction, rather than only offline editing. This lets performers reshape their own sound as they play.", "practical_application": "A performer routes a live instrument into a granular processor and, in real time, freezes, stretches, or clouds the incoming sound, using controllers to steer grain rate and density on stage.", "category": "Granular Synthesis", "related_terms": ["Grain-stream output", "Granular delay", "Granular reverb", "Microsound", "Particle synthesis"], "common_mistakes": ["Ignoring input buffer length, which sets how much delay and material the live grains have to work with.", "Overloading the CPU with too many grains, causing dropouts during a live set.", "Forgetting gain staging, so a hot live input clips before it even reaches the granular stage."], "scenario_contexts": ["Freezing and stretching a held guitar note live to build an evolving drone.", "Granulating a live vocal on stage to create a shifting cloud behind the singer.", "Reprocessing an acoustic instrument in real time during an improvised electronic set."]}, "a59572f1-ecae-44f0-9587-c9c7a53e17ef": {"definition": "Looping a very short segment of audio, often only a few milliseconds to a few tens of milliseconds, so that rapid repetition produces a sustained, pitched tone or buzzing texture rather than an audible repeating phrase. The loop length sets the perceived pitch.", "plain_english": "This loops a tiny slice of sound over and over, so fast that you no longer hear it repeat. Instead the fast repeats blend into a steady buzzing note. It is like flipping one drawing so quickly that it turns into motion.", "purpose_function": "It turns a short fragment of a sample into a sustained pitched tone or drone, giving new sounds from tiny pieces of existing audio. Because the loop rate sets the pitch, it can also be played like an instrument.", "practical_application": "A producer sets a very short loop inside a sample and shrinks it until the repeats fuse into a pitched buzz, then moves the loop point through the file to sweep the timbre.", "category": "Granular Synthesis", "related_terms": ["Microsound", "Grain-stream output", "Granular time stretching", "Particle synthesis", "Granular pitch shifting"], "common_mistakes": ["Expecting a normal rhythmic loop, when a loop this short fuses into a single pitched tone.", "Overlooking that the loop length controls the pitch, so changing length retunes the sound.", "Leaving clicks at the loop point, which add harsh buzz unless the ends are crossfaded."], "scenario_contexts": ["Freezing a tiny slice of a vocal into a sustained, pitched vowel tone.", "Sweeping a short loop across a drum hit to pull out a pitched drone.", "Building glitch textures by shrinking a loop until it becomes a buzzing note."]}, "61dd1b48-8ad4-4412-97cf-c0318d81f7f4": {"definition": "Sound events on very short time scales, roughly one millisecond to about one-tenth of a second, sitting between the single-sample level and the level of a musical note. The term also names the family of techniques, such as granular and particle synthesis, that compose sound from these brief particles.", "plain_english": "Microsound means sound bits that last only a tiny moment, from about one thousandth of a second up to a tenth of a second. These pieces are longer than one sample but shorter than a played note. The word also covers the tools that build sound from such tiny pieces.", "purpose_function": "It gives a name to the time scale where grains and particles live, so composers and engineers can work with sound below the note level. Thinking at this scale is what makes granular and particle methods possible.", "practical_application": "A sound designer works at the microsound level when shaping grain size and density in a granular tool, choosing durations short enough to blend into texture yet long enough to carry pitch.", "category": "Granular Synthesis", "related_terms": ["Particle synthesis", "Grain-stream output", "Granular time stretching", "Microlooping", "Live granular processing"], "common_mistakes": ["Treating microsound as one specific effect, when it names a whole time scale and family of methods.", "Assuming grains are single samples, though microsound events are longer than the sample level.", "Overlooking that grain duration in this range strongly shapes the perceived pitch and texture."], "scenario_contexts": ["Discussing grain size settings that fall in the millisecond range on a granular synth.", "Designing evolving textures from clouds of very short sound events.", "Studying how sound behaves between the sample and note time scales."]}, "b03dc6a3-1f8a-4488-8d64-91945d88f53d": {"definition": "An umbrella term for synthesis techniques that build sound from large numbers of brief acoustic particles or grains, including granular, pulsar, glisson, and trainlet synthesis, rather than from continuous waveforms. Each method differs in how it shapes and schedules its particles.", "plain_english": "Particle synthesis builds sound from thousands of tiny sound bits, called grains or particles. Instead of one smooth wave, you get a swarm of short pieces played together. It is like making a picture out of many small dots.", "purpose_function": "It gives a common name to all the ways of making sound from tiny particles, letting engineers create rich, evolving textures that smooth waveforms cannot. Granular synthesis is the best known member of this family.", "practical_application": "A sound designer reaches for a particle synthesis tool to build swarming, cloud-like textures, choosing the specific method, such as granular or pulsar, to fit the sound they want.", "category": "Granular Synthesis", "related_terms": ["Microsound", "Grain-stream output", "Granular time stretching", "Granular pitch shifting", "Live granular processing"], "common_mistakes": ["Treating particle synthesis and granular synthesis as identical, when granular is only one type of it.", "Expecting a single smooth waveform, since the sound is built from many separate particles.", "Ignoring particle density, which strongly controls whether the result is sparse and clicky or thick and smooth."], "scenario_contexts": ["Choosing between granular and pulsar methods to design an evolving pad.", "Building a dense, swarming texture from many overlapping sound particles.", "Explaining how granular synthesis fits within the wider family of particle methods."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"47c99f0e-0e6b-4c90-b881-fcdac1e54a0a": {"definition": "A spectral-processing technique that captures the frequency-domain content of a single analysis frame from an FFT/phase-vocoder analysis of a sound and repeats it during resynthesis, sustaining that one timbral moment for any length while its magnitude and phase spectrum stay fixed, producing a static drone or pad.", "plain_english": "It grabs one tiny slice of a sound and holds it in place. The tone stays the same, but time seems to stop. A short note can turn into a long, steady hum.", "purpose_function": "It extends a short or decaying sound into a continuous sustained texture; it exists so producers and sound designers can build drones, pads and ambiences from material that would otherwise fade away quickly.", "practical_application": "A technician sets a freeze point on a held vowel, synth chord or cymbal wash in a spectral plugin or editor and captures it to make an evolving background pad or to sustain a tail under a transition.", "category": "Spectral processing", "related_terms": ["Phase vocoder", "FFT", "Time freeze", "Granular synthesis", "Time stretching", "Spectral editing"], "common_mistakes": ["Freezing on a noisy transient, which gives a harsh or metallic drone instead of a smooth tone", "Expecting a freeze to keep evolving on its own — the held spectrum is static unless you modulate it", "Confusing a spectral freeze with looping a slice of audio; a freeze holds a reconstructed spectrum, not a repeated time segment"], "scenario_contexts": ["Turning a sustained vocal note into an ambient pad in a DAW", "Holding a reverb tail or cymbal wash under a scene change in film sound design", "Creating a tension drone from a single instrument hit"]}, "541a4ecc-825b-4af5-bc37-ae7edddbc74f": {"definition": "In granular synthesis, grains — very short fragments of sound, typically a few to a few hundred milliseconds long — whose emission rate or spacing is locked to the host tempo or musical clock, so grain onsets fall on note values such as 1/8 or 1/16 rather than at a free-running rate set in hertz.", "plain_english": "Granular tools chop a sound into tiny pieces called grains. Here the grains play in time with the beat. So the little bursts land right on the groove instead of at random.", "purpose_function": "Locking grain timing to tempo keeps granular textures rhythmically in step with the track; it exists so stuttered, chopped or clouded grain effects groove with the music instead of drifting against the beat.", "practical_application": "A producer switches a granular sampler's grain rate or density parameter from hertz to a note division, so a stutter or grain cloud stays in time whenever the sample is triggered in the project.", "category": "Granular synthesis", "related_terms": ["Granular synthesis", "Grain", "Grain size", "Grain density", "Tempo sync", "Beat slicing"], "common_mistakes": ["Assuming grain rate is always set in hertz — in a DAW it can be switched to musical note values", "Setting grain size longer than the note spacing, so grains overlap and smear away the rhythm", "Confusing tempo-synced grains with simple beat slicing; grains are far shorter and are re-emitted, not just cut and rearranged"], "scenario_contexts": ["Making a tempo-locked stutter or glitch fill from a vocal in a DAW", "Building a rhythmic granular pad that pulses in time with a track", "Designing an in-time hi-hat or texture pattern from a single sampled sound"]}, "00918395-996b-460d-8097-6c2a6aa4a8d2": {"definition": "A sample-manipulation technique that suspends the forward progress of playback at a chosen point so the sound sustains indefinitely at that instant; it is commonly realised either by spectral (phase-vocoder) freezing of one analysis frame or by granular looping of a very short window around the freeze point.", "plain_english": "This holds a sound still at one moment so it plays on and on. It is like pressing pause, but the sound keeps ringing. A quick sound becomes a long, steady tone.", "purpose_function": "It turns a moment of a sound into a sustained tone or texture; it exists so technicians can hold, suspend or fill space with audio to build tension or make pads from short source material.", "practical_application": "A technician sets a freeze point in a granular or spectral processor and engages it live or in a DAW to sustain a chord, note or ambience for as long as needed under a scene or transition.", "category": "Time manipulation", "related_terms": ["Spectral freeze", "Phase vocoder", "Granular synthesis", "Time stretching", "Tempo-synchronized grains", "Looping"], "common_mistakes": ["Thinking a time freeze slows the sound down — it holds one instant rather than stretching the whole timeline", "Freezing on a transient or plosive, which produces an unnatural or buzzy held tone", "Expecting the frozen tone to change on its own; it stays static unless you add modulation or movement"], "scenario_contexts": ["Sustaining a synth chord under a build-up in a DAW", "Holding an ambience or drone live during a pause in a performance", "Freezing a single word or note in sound design to stretch a dramatic moment"]}, "1828644c-20e9-4cf9-bb5d-fbf1fa4516f9": {"definition": "A curated collection of pre-recorded drum and percussion sounds, supplied as individual samples and/or assembled kits, that a producer loads into a sampler, drum machine, or DAW instrument to program beats.", "plain_english": "A drum library is a big folder of ready-made drum sounds like kicks, snares, and hi-hats. You pick sounds from it to build your own beats, the way you pick blocks from a bin.", "purpose_function": "It gives producers a ready, consistent supply of high-quality drum sounds so they can build rhythms without setting up mics and recording a live kit.", "practical_application": "A technician browses the library, drags chosen hits into a sampler or drum rack, and maps them to pads or MIDI notes to program a groove.", "category": "Sample Sources", "related_terms": ["One-shot sample", "Sample library", "Drum kit", "Drum rack", "Sampler", "Loop"], "common_mistakes": ["Assuming every library sound is mix-ready and skipping level, tuning, and EQ matching between hits from different sources.", "Loading huge multi-gigabyte libraries entirely into RAM instead of streaming, then running out of memory mid-session.", "Ignoring the license terms and using paid or royalty-restricted library sounds in commercial releases without clearance."], "scenario_contexts": ["Building a hip-hop beat by pulling a kick, snare, and hat from a downloaded drum library into a drum rack.", "Layering a library snare under a live-recorded snare to reinforce the backbeat.", "Auditioning several library kits to find one that fits the genre and tempo of a track."]}, "625f757b-a294-40e8-ba15-20c2b908e3c3": {"definition": "A single self-contained audio sample that plays once from start to finish each time it is triggered rather than looping, typically an individual drum hit such as a kick, snare, clap, or cymbal.", "plain_english": "A one-shot is a short sound that plays one time each time you hit the pad or key. It is like a doorbell: press it once and it rings once, then stops.", "purpose_function": "It lets a producer trigger a discrete drum hit on demand, so each note in a programmed pattern sounds as a clean, repeatable event.", "practical_application": "A technician assigns a one-shot kick and snare to sampler pads or MIDI notes, then sequences them step by step to build a drum pattern.", "category": "Sample Sources", "related_terms": ["Drum library", "Loop", "Sampler", "Trigger", "Velocity", "Drum rack"], "common_mistakes": ["Confusing a one-shot with a loop and expecting it to repeat on its own when it only plays once per trigger.", "Leaving the sampler in a mode that cuts the sample off early, so decay-heavy hits like cymbals get chopped.", "Retriggering the same one-shot rapidly on one voice and causing clicks instead of using multiple voices or a choke group."], "scenario_contexts": ["Programming a kick-and-snare pattern from individual one-shot hits on a step sequencer.", "Mapping one-shots across a pad grid on a controller for finger-drumming a beat.", "Replacing a weak recorded snare by triggering a one-shot from the drum track's transients."]}, "ea57d82c-92c2-4c25-b611-f03ef3a20bce": {"definition": "The use of artificial-intelligence models to generate or reshape a musical arrangement — deciding how instruments, parts, harmonies, and sections are combined and ordered — from an input such as a melody, chord chart, or text prompt.", "plain_english": "AI arrangement means letting a computer program decide how a song's parts fit together. You give it a tune or some chords, and it adds instruments, harmony, and structure. It is like a helper that turns a plain idea into a fuller song.", "purpose_function": "It speeds up the arranging stage of production, letting a user turn a basic musical idea into a fuller, multi-part piece without scoring every part by hand.", "practical_application": "A producer feeds a melody line into an AI arrangement tool to get backing chords, bass, and drums as a starting sketch, then edits the result in a DAW.", "category": "AI music generation", "related_terms": ["AI-assisted composition", "AI beat-making", "AI sound effects generator", "MIDI", "DAW"], "common_mistakes": ["Treating the AI output as a finished, release-ready track instead of a rough draft to edit", "Assuming the arrangement is automatically original or free of copyright concerns", "Confusing arrangement (organising existing parts) with composing new material from nothing"], "scenario_contexts": ["Turning a hummed melody into a backing track for a demo", "Generating a fuller arrangement of a simple piano sketch", "Creating quick variations of a song section for a client to choose from"]}, "22cbdef1-f048-4a8a-b2de-4d46c5ba2fad": {"definition": "The generation of rhythmic drum and percussion patterns using AI models, which produce or suggest grooves, drum-hit sequences, and rhythmic variations from a prompt, style tag, or seed pattern.", "plain_english": "AI beat-making is using a smart program to create drum patterns for you. You pick a style, and it lays down a groove with kicks, snares, and hats. Think of it as a drum machine that comes up with the pattern on its own.", "purpose_function": "It exists to quickly produce rhythm tracks and groove ideas, giving producers a fast starting point instead of programming every drum hit manually.", "practical_application": "A beat-maker asks the tool for a hip-hop groove at a set tempo, then swaps sounds and tweaks the pattern in their DAW or drum sampler.", "category": "AI music generation", "related_terms": ["AI arrangement", "AI-assisted composition", "MIDI", "Sequencer", "DAW"], "common_mistakes": ["Assuming the generated groove needs no editing to fit the song", "Believing AI-made beats are always cleared for commercial release", "Confusing pattern generation with full song production"], "scenario_contexts": ["Sketching a drum groove for a new track", "Generating rhythm variations to fill out a song section", "Making a quick beat under a vocal idea before a session"]}, "0216d237-698e-40d0-a0b5-831958fd9596": {"definition": "A system that uses AI — often a text-to-audio model — to synthesize sound effects such as footsteps, explosions, or ambience from a text description or other conditioning input, rather than recording or sampling them.", "plain_english": "An AI sound effects generator makes sound effects from a text prompt. You type something like \"heavy rain on a tin roof,\" and it creates that sound. It is like an artist who can draw any picture you describe, but for sound.", "purpose_function": "It lets creators get a needed sound from a text idea, saving time over searching sample libraries or recording the effect in the field.", "practical_application": "A game or video sound designer types a description to draft an effect, then cleans or layers it before dropping it into the project.", "category": "AI music generation", "related_terms": ["AudioLDM", "Audio-domain generation", "AI arrangement", "Sound design", "Sample library"], "common_mistakes": ["Expecting broadcast- or film-master quality straight from the prompt", "Assuming generated effects always sync perfectly to picture without editing", "Overlooking licensing or usage terms of the generation tool"], "scenario_contexts": ["Drafting a whoosh or impact for a video edit", "Generating room ambience for a scene", "Prototyping creature or machine sounds from a text idea"]}, "7c716815-e615-48ee-a448-8257ce72458b": {"definition": "The practice of composing music with the aid of AI tools that suggest, generate, or complete musical material — melodies, harmonies, or full pieces — while a human keeps creative direction and makes the final decisions.", "plain_english": "AI-assisted composition means writing music with help from a smart program. The AI offers melodies or chords, and you pick and shape them. The computer is like a co-writer, not the boss.", "purpose_function": "It exists to help composers work faster and get past creative blocks by offering musical ideas the human can accept, reject, or refine.", "practical_application": "A composer generates a few melody or chord options for a cue, then chooses one and finishes the piece by hand in a notation editor or DAW.", "category": "AI music generation", "related_terms": ["AI arrangement", "AI beat-making", "AI sound effects generator", "MIDI", "DAW"], "common_mistakes": ["Assuming the AI does all the creative work with no human input needed", "Treating raw suggestions as finished music", "Ignoring authorship and copyright questions around AI-generated ideas"], "scenario_contexts": ["Generating melody options for a film cue", "Getting chord ideas to break a writing block", "Sketching a song idea before a co-writing session"]}, "b2e69598-c087-49b7-bdbc-eb402b397c48": {"definition": "AIVA (Artificial Intelligence Virtual Artist) is a commercial AI music-composition system, created by AIVA Technologies in 2016, that uses deep-learning models trained on a corpus of existing scores to generate original instrumental compositions across many styles; it was the first AI composer registered with a music-rights society (SACEM).", "plain_english": "AIVA is an app that writes original music for you. You pick a style and length, and it makes a piece you can download and edit.", "purpose_function": "It lets users generate music quickly without composing from scratch, serving creators who need scores for video, games, or media on a budget or deadline.", "practical_application": "A content creator picks a mood, style, and duration in AIVA, generates a cue, then exports stems or MIDI to fine-tune the arrangement in a DAW.", "category": "AI music generation", "related_terms": ["AI-assisted composition", "AI arrangement", "Suno", "Udio", "Symbolic music generation"], "common_mistakes": ["Assuming AIVA's output is automatically cleared for any commercial use without checking the license tier", "Treating generated cues as final rather than editing stems or MIDI to fit picture", "Expecting fully original creativity rather than patterns learned from training data"], "scenario_contexts": ["Generating a cinematic cue for a video project", "Producing a first-draft game soundtrack to iterate on", "Exporting MIDI from AIVA to rearrange in a DAW"]}, "d28bfa24-4851-4de0-b361-8acb5844eaa9": {"definition": "The process of converting a continuous audio waveform into a sequence of discrete symbols (tokens), typically using a neural audio codec, so that audio can be modeled and generated by token-based, language-model-style systems.", "plain_english": "Audio tokenization turns sound into a list of small code numbers. Each number stands for a tiny chunk of the audio. This lets AI handle sound the same way it handles words in a sentence.", "purpose_function": "It compresses audio into a compact, discrete form so that sequence models built for tokens can learn from and generate audio efficiently.", "practical_application": "A technician meets audio tokens when using neural codecs like EnCodec or SoundStream to feed audio into models such as AudioLM or a text-to-music system.", "category": "Generative audio models", "related_terms": ["Autoregressive model", "Audio-domain generation", "AudioLDM", "Quantization", "Sample rate"], "common_mistakes": ["Confusing audio tokens with MIDI notes — tokens are learned codec codes, not musical notes", "Assuming tokenization is perfectly lossless", "Thinking one token equals one audio sample"], "scenario_contexts": ["Preparing audio to train an audio language model", "Compressing sound through a neural codec", "Building a text-to-music generation pipeline"]}, "c3dc20ab-ee65-4b5f-a2f0-74fc03a664af": {"definition": "Generative approaches that produce sound directly as an audio waveform, or a spectral or latent audio representation of it, as opposed to symbolic-domain generation that outputs notation such as MIDI or a score.", "plain_english": "Audio-domain generation means the AI makes the actual sound itself, wave and all. It does not just write notes for a player to perform. Think of it as painting the finished photo instead of writing sheet music.", "purpose_function": "It exists to produce ready-to-hear audio that includes timbre and performance detail, capturing sounds that written notation cannot fully describe.", "practical_application": "A technician picks audio-domain tools like WaveNet or AudioLDM when they need finished sound, and symbolic tools when they need editable MIDI instead.", "category": "Generative audio models", "related_terms": ["AudioLDM", "Autoregressive model", "Audio tokenization", "MIDI", "Waveform"], "common_mistakes": ["Confusing audio-domain output with editable MIDI — a waveform is not note data", "Expecting note-by-note editing of generated audio", "Assuming it always sounds better than symbolic methods"], "scenario_contexts": ["Generating a realistic sound effect from text", "Producing sung vocals rather than a written score", "Creating background ambience as finished audio"]}, "eb8e9571-1647-451e-a86c-f0abf551682d": {"definition": "A text-to-audio generation model that produces audio — sound effects, ambience, and music — from text prompts using a latent diffusion model that operates on a compressed audio latent space guided by CLAP text-audio embeddings.", "plain_english": "AudioLDM is an AI model that makes sounds from text. You type a description, and it builds the audio step by step out of noise. It works a bit like image AI, but the thing it makes is a sound.", "purpose_function": "It exists to generate varied audio from text efficiently by working in a small compressed latent space instead of on raw waveform samples.", "practical_application": "A sound designer uses AudioLDM to draft sound effects or ambience from a written prompt rather than digging through sample libraries.", "category": "Generative audio models", "related_terms": ["Audio-domain generation", "AI sound effects generator", "Audio tokenization", "Autoregressive model", "Latent space"], "common_mistakes": ["Confusing AudioLDM, which is diffusion-based, with autoregressive token models", "Expecting polished studio-master quality from every prompt", "Thinking it only makes music — it also makes general sounds and ambience"], "scenario_contexts": ["Prototyping sound effects for a game", "Generating background ambience for a video", "Exploring sound ideas quickly from a text description"]}, "3533fa68-6228-46e1-a950-9dba8f1b7cf0": {"definition": "A model that generates a sequence one step at a time, predicting each new value — such as an audio sample or token — conditioned on the previously generated values; in audio, WaveNet is a classic example, predicting each waveform sample from the samples before it.", "plain_english": "An autoregressive model builds a signal one piece at a time. Each new piece is guessed from all the pieces that came before it. It is like writing a sentence word by word, where each word depends on the ones already written.", "purpose_function": "It captures how each moment of a signal depends on its history, which allows coherent step-by-step generation of audio or tokens.", "practical_application": "Technicians meet autoregressive models in neural vocoders and token-based music generators, where audio is produced sample by sample or token by token.", "category": "Generative audio models", "related_terms": ["Audio tokenization", "Audio-domain generation", "AudioLDM", "Waveform", "Sample rate"], "common_mistakes": ["Assuming autoregressive generation is fast — predicting one step at a time is often slow", "Confusing autoregressive models with parallel diffusion models", "Believing the model plans the whole output in advance rather than one step at a time"], "scenario_contexts": ["Neural vocoding of speech sample by sample", "Token-by-token music or audio generation", "Comparing real-time versus offline generation speed"]}, "34c0406d-7aff-46d6-be64-b274d9624f05": {"definition": "A modular-synthesizer patching format that uses single-conductor 4 mm banana plugs and jacks to route audio and control voltages between modules, with all modules sharing a common ground bus. Because the plugs are stackable, several can be stacked on one jack so a single output can feed many inputs, a scheme used notably in Serge and Buchla systems.", "plain_english": "It is a way to wire up a modular synth using round metal banana plugs. The plugs stack on top of each other, so you can send one signal to many places at once, like splitting one hose into several.", "purpose_function": "It carries the signal path in banana-format modular systems, letting a technician route audio and control voltages between modules while stackable plugs act as a built-in signal splitter without a separate multiple.", "practical_application": "When patching a Serge or Buchla system a technician first connects a common ground lead, then stacks banana plugs to send one control voltage to several destinations at the same time.", "category": "Modular Synthesis", "related_terms": ["Control voltage", "Modular synthesizer", "Patch cable", "Clock", "Glide"], "common_mistakes": ["Assuming banana cables carry a shield or ground like 1/4-inch or 3.5 mm cables; banana jacks are single-conductor and rely on a shared ground bus.", "Believing banana and 3.5 mm (Eurorack) formats plug together directly without adapters and matched signal levels.", "Stacking too many plugs on one output and loading it down instead of using a buffered multiple."], "scenario_contexts": ["Patching a Serge system where one control voltage must reach several modules at once.", "Connecting the common ground before signal cables when setting up a Buchla-style patch.", "Adapting a banana-format module into a mixed rig alongside 3.5 mm gear."]}, "3198b298-09b6-4cfa-8cda-d3d49b43d9a2": {"definition": "A regular stream of timing pulses that sets the tempo and synchronizes time-based devices such as sequencers, arpeggiators, drum machines and clocked LFOs. In analog systems it is a train of gate or trigger pulses; in MIDI systems it is a defined message stream running at 24 pulses per quarter note.", "plain_english": "A clock is a steady tick that keeps synth gear in time together. It works like a metronome that tells sequencers and drum machines when to take each step.", "purpose_function": "It provides the shared timing reference that locks several devices to the same tempo, so sequenced and rhythmic events line up instead of drifting apart.", "practical_application": "A technician picks one device as the clock master and sends its clock to the others, or patches an analog clock into a sequencer's clock input to set the step rate.", "category": "Timing & Control", "related_terms": ["Trigger", "Gate", "Sequencer", "Arpeggiator", "LFO"], "common_mistakes": ["Confusing the tempo clock in sequencing with the word/sample clock of digital audio; here 'clock' means the musical timing pulse.", "Setting two devices to both send clock, so they fight instead of one master driving the others.", "Assuming every device uses the same pulses per quarter note; analog clocks and MIDI clock at 24 ppqn differ."], "scenario_contexts": ["Syncing a drum machine and a sequencer so they start and run in time.", "Slaving a modular sequencer to MIDI clock coming from a DAW.", "Clocking an LFO to divide the master tempo for rhythmic modulation."]}, "0c4b9a6f-65b4-44dd-af88-219d46387718": {"definition": "An approach that implements classic DSP elements such as oscillators, filters and reverberators as differentiable functions, so they can be embedded in a neural network and trained end-to-end with gradient descent. It lets a machine-learning model directly control interpretable synthesis modules instead of generating raw samples or spectrograms.", "plain_english": "DDSP builds normal synth parts, like oscillators and filters, in a way a computer can learn to control. It joins old-school sound tools with modern AI, so a model can shape sound using controls it teaches itself to set.", "purpose_function": "It exists to combine the clear controls and efficiency of traditional signal-processing modules with the flexibility of deep learning, giving high-quality, controllable audio from far less training data than raw-waveform models.", "practical_application": "A developer or sound designer uses a DDSP model to resynthesize or transform audio, for example remapping a sung melody onto a violin timbre, while keeping pitch and loudness controls that map to real synthesis parameters.", "category": "Neural Audio Synthesis", "related_terms": ["Differentiable oscillator", "Filtered-noise synthesizer", "Harmonic additive synthesizer", "Generative music", "Oscillator"], "common_mistakes": ["Thinking DDSP is a generic network that outputs raw samples; it instead drives explicit, differentiable DSP modules.", "Assuming it needs huge datasets like waveform models when it can train on relatively little audio.", "Reading 'differentiable' as 'different'; it means the math can be differentiated for gradient-based training."], "scenario_contexts": ["Timbre transfer, mapping one instrument's playing onto another's sound.", "Building a low-data neural synthesizer for one specific instrument.", "Research into interpretable, controllable audio synthesis."]}, "d1444d33-412b-4244-ad39-dacaf2bba16d": {"definition": "An oscillator whose sample-generating process is written as a differentiable function, so its parameters such as frequency and per-harmonic amplitudes can be optimized by gradient descent inside a neural network. In DDSP it is typically a harmonic (additive) oscillator that sums sinusoids under the control of a trained model.", "plain_english": "It is a synth oscillator built so a computer can adjust it by learning. Because its math can be fine-tuned step by step, an AI model can teach itself the right pitch and tone.", "purpose_function": "It gives neural-synthesis systems a sound source with real, readable controls that the training process can tune directly, rather than generating waveforms blindly.", "practical_application": "In a DDSP model a developer feeds pitch and loudness features into a differentiable oscillator to resynthesize an instrument with controllable harmonics.", "category": "Neural Audio Synthesis", "related_terms": ["Differentiable digital signal processing (DDSP)", "Harmonic additive synthesizer", "Filtered-noise synthesizer", "Oscillator", "Clock"], "common_mistakes": ["Assuming it is a special analog circuit; it is a mathematical oscillator implemented in software for training.", "Thinking it is the whole model when it is one differentiable module among several.", "Overlooking that its harmonic amplitudes are usually set by a neural network, not dialed in by hand."], "scenario_contexts": ["Resynthesizing a monophonic instrument inside a DDSP model.", "Training a model to match a target timbre by tuning oscillator harmonics.", "Timbre-transfer applications driven by pitch and loudness features."]}, "3bfdcda8-a0f0-4df0-afbc-26694b13ac96": {"definition": "A synthesis component that generates sound by passing white noise through a linear time-varying filter, shaping the noise spectrum over time to model the stochastic, non-harmonic parts of a sound such as breath, bow scrape or consonants. In DDSP it is the subtractive-noise branch that complements the harmonic oscillator.", "plain_english": "It makes sound by filtering plain hiss into the right shape. This is how you get breathy or scratchy parts of a sound, like the air in a flute note, that pure tones cannot make.", "purpose_function": "It supplies the noisy, inharmonic energy that harmonic oscillators cannot produce, so combined synthesis can reproduce realistic breath, friction and transient textures.", "practical_application": "Inside a DDSP model a developer uses the filtered-noise branch to add breath and bow noise on top of the harmonic tone, with the filter shaped by the trained network.", "category": "Neural Audio Synthesis", "related_terms": ["Differentiable digital signal processing (DDSP)", "Harmonic additive synthesizer", "Differentiable oscillator", "Oscillator", "Clock"], "common_mistakes": ["Thinking noise is useless in synthesis; filtered noise is essential for realistic breath and transients.", "Confusing it with a plain noise generator when its filter changes over time under model control.", "Expecting it to produce pitch; it produces broadband, inharmonic content, not clear notes."], "scenario_contexts": ["Adding breath noise to a resynthesized wind instrument.", "Modeling bow-scrape or consonant sounds in neural synthesis.", "Combining with a harmonic oscillator to build a full instrument model."]}, "c2ba09ba-c818-49ec-a99a-bf4d66639d76": {"definition": "The use of generative or algorithmic systems, often machine-learning models, to create foley, the everyday sound effects such as footsteps, cloth movement, impacts and handling noise added to picture, instead of or alongside recording a foley artist. Such systems synthesize or select sounds, often conditioned on video or motion.", "plain_english": "Foley is the small everyday sounds added to film, like footsteps and rustling clothes. Generative foley uses a computer program to make those sounds for you. Often it uses AI, so you do not have to record them by hand.", "purpose_function": "It aims to speed up and scale sound-effects work by producing plausible foley automatically, which helps on large projects, previsualization, games and quick iteration.", "practical_application": "A sound editor may use a generative-foley tool to rough in footsteps and handling sounds synced to picture, then refine or replace the key hits with recorded foley.", "category": "Generative Audio", "related_terms": ["Generative music", "Sound design", "Differentiable digital signal processing (DDSP)", "Sampler", "Sound effects"], "common_mistakes": ["Expecting it to fully replace a skilled foley artist when results still usually need editing and quality control.", "Assuming output is automatically in perfect sync, since timing to picture often needs correction.", "Treating all generated sounds as license-clear without checking the model's training data and usage rights."], "scenario_contexts": ["Roughing in footsteps for an animatic or previs pass.", "Generating large volumes of impact and handling sounds for a game.", "Prototyping a scene's sound before a formal foley session."]}, "df53cb3d-7921-42de-aa87-b79e1aca66b2": {"definition": "Music produced by a system or set of rules that runs to create the output, so the result is ever-changing rather than fixed note-for-note by a composer. It spans algorithmic composition, rule-based and probabilistic systems and self-generating installations, and was popularized as a term by Brian Eno for music that is ever-different and changing.", "plain_english": "Generative music is made by a system that follows rules to keep making new sound. Instead of one fixed song, it can play for a long time without repeating. It is a bit like a wind chime that sounds different each time the wind blows.", "purpose_function": "It lets a designer set up processes and limits rather than fix every note, producing music that evolves on its own for installations, games, ambient scores and interactive media.", "practical_application": "A composer or technician builds rules, seeds and randomness in software or a modular patch so the system plays continuously, then tunes the parameters to keep the output musical.", "category": "Generative Audio", "related_terms": ["Generative foley", "Sequencer", "Clock", "Arpeggiator", "LFO"], "common_mistakes": ["Thinking generative means fully random, when most generative music uses rules and limits to stay musical.", "Confusing it with looping a finished track, since generative systems keep producing new variation.", "Assuming it requires AI, when many generative systems are simple rule- or probability-based."], "scenario_contexts": ["Creating an endless ambient soundscape for an installation.", "Building adaptive, non-repeating music for a game.", "Patching a modular system to self-play evolving sequences."]}, "d7807a7f-f728-47ea-a986-ab92cf333333": {"definition": "A synthesizer control that makes the pitch slide smoothly from one note to the next instead of jumping instantly, by ramping the oscillator's control voltage or pitch value over a set time. It is functionally the same as portamento, with a glide-time control that sets how long the slide takes.", "plain_english": "Glide makes a synth slide smoothly between notes instead of jumping straight to the new pitch. It is like sliding your finger along a guitar string from one fret to another.", "purpose_function": "It provides expressive, connected pitch movement between notes for leads, basslines and effects, and the glide-time control sets how fast the pitch travels.", "practical_application": "A player switches on glide and sets a glide time so a mono lead or bass slurs between notes; many synths glide only when notes overlap in a fingered or legato mode.", "category": "Performance Control", "related_terms": ["Portamento", "Oscillator", "Control voltage", "Pitch bend", "Clock"], "common_mistakes": ["Thinking glide and pitch bend are the same; glide moves automatically between played notes, while pitch bend is a manual real-time control.", "Setting a very long glide time and then finding fast passages sound out of tune between notes.", "Expecting glide on a polyphonic patch to behave like a mono lead, when its behavior depends on the voice mode."], "scenario_contexts": ["Programming a sliding synth-bass line.", "Adding expressive slurs to a monophonic lead.", "Setting fingered or legato glide so slides only happen on overlapping notes."]}, "365f5f14-cb09-427b-964f-5b3a8a2e05ec": {"definition": "An additive synthesizer that builds sound by summing sine-wave partials tuned to whole-number (harmonic) multiples of a fundamental frequency, with each partial's amplitude controlled over time. Restricting the partials to the harmonic series produces clearly pitched, periodic tones.", "plain_english": "It creates sound by stacking many simple sine tones that are all in tune with one base note. Because the tones are neat multiples of that note, the result has a clear pitch, like layering tuned whistles into one rich sound.", "purpose_function": "It lets a designer build a timbre partial by partial, giving precise control over the harmonic content and how each harmonic changes across the note.", "practical_application": "A sound designer sets the level and envelope of individual harmonics to sculpt an evolving tone; in a DDSP model a harmonic oscillator of this kind is driven by a trained network to match an instrument.", "category": "Additive Synthesis", "related_terms": ["Differentiable oscillator", "Differentiable digital signal processing (DDSP)", "Filtered-noise synthesizer", "Oscillator", "Clock"], "common_mistakes": ["Confusing harmonic additive synthesis with inharmonic additive synthesis; keeping partials at whole-number multiples is what gives a clear pitch.", "Assuming a few harmonics are enough for any timbre, when bright or complex tones need many partials.", "Treating amplitudes as static, when each harmonic usually needs its own time-varying envelope for a lifelike sound."], "scenario_contexts": ["Recreating an organ- or bell-like tone by stacking tuned harmonics.", "Analyzing and resynthesizing an instrument's harmonic spectrum.", "Driving a harmonic oscillator from a DDSP model for timbre transfer."]}, "a5b5b1d4-0513-4e4b-a2b3-951603fc5b0a": {"definition": "OpenAI Jukebox is a neural network model that generates raw-audio music, including rudimentary singing, by using a hierarchical VQ-VAE to compress audio into discrete tokens and autoregressive Transformers to predict those tokens conditioned on genre, artist, and lyrics.", "plain_english": "Jukebox is an AI from OpenAI that makes music as real sound, even with singing. You can give it a style, an artist, and words to sing, and it tries to build a matching song.", "purpose_function": "It exists to show that one model can generate long, coherent musical audio with vocals directly as a waveform, rather than as MIDI notes.", "practical_application": "A producer might use Jukebox to generate rough musical sketches or to study how neural models make raw-audio music, keeping in mind its slow, lo-fi output.", "category": "AI Music Generation", "related_terms": ["MusicLM", "MusicGen", "Neural audio synthesis", "Music generation", "Magenta"], "common_mistakes": ["Thinking Jukebox outputs clean studio-quality audio; its raw-audio results are noticeably lo-fi and noisy.", "Confusing it with a coin-operated jukebox machine rather than the AI model.", "Assuming it works in real time; sampling even a short clip can take a long time."], "scenario_contexts": ["Generating a short AI music sketch in a chosen artist style for experimentation.", "Studying VQ-VAE token-based audio generation in a machine-learning course.", "Comparing raw-audio models against text-to-music systems like MusicLM."]}, "12f97c9a-96b4-4b1a-8b03-e5c54d07fe42": {"definition": "Magenta is an open-source research project, started by the Google Brain team, that explores using machine learning to create music and art, providing models and libraries (built on TensorFlow) for tasks such as melody generation, performance modeling, and neural audio synthesis.", "plain_english": "Magenta is a free Google project that uses AI to help make music and art. It shares models and coding tools so people can build their own music-making programs.", "purpose_function": "It exists to research and share machine-learning tools that help musicians and artists create, giving developers ready-made models to build on.", "practical_application": "A developer might use Magenta's models and libraries to add AI features like melody continuation or a neural instrument to a music app or creative project.", "category": "AI Music Generation", "related_terms": ["Music generation", "Neural synthesizer", "Neural audio synthesis", "MusicGen", "MusicLM"], "common_mistakes": ["Thinking Magenta is a single app rather than a collection of research models and tools.", "Assuming it only makes audio, when many Magenta models work with symbolic MIDI notes.", "Expecting finished songs instead of building blocks a developer must assemble."], "scenario_contexts": ["Adding AI melody generation to a browser-based music toy.", "Prototyping a neural instrument with Magenta's DDSP or NSynth tools.", "Teaching students how ML models handle symbolic music."]}, "53a1ee18-0ad1-43c0-950e-9c2841ea437e": {"definition": "Melody-conditioning is a technique in generative music models where an input melody is supplied as a conditioning signal so the generated output follows that melodic contour, while other attributes such as instrumentation or style are set separately; it is implemented in models such as MusicGen and MusicLM.", "plain_english": "Melody-conditioning means giving an AI a tune to follow while it makes music. The AI keeps your melody but can change the style or instruments around it.", "purpose_function": "It exists to give users control over the tune of AI-generated music, so the result matches a chosen melody instead of being random.", "practical_application": "A producer can hum or play a melody, feed it to a model like MusicGen, and get back a fuller arrangement that keeps that tune in a requested style.", "category": "AI Music Generation", "related_terms": ["MusicGen", "MusicLM", "Music generation", "MuLan", "Neural audio synthesis"], "common_mistakes": ["Thinking the model copies the melody exactly; it usually follows the contour, not every note.", "Confusing melody-conditioning with text prompts, which control style rather than the tune.", "Expecting perfect pitch tracking from a rough or noisy input melody."], "scenario_contexts": ["Turning a hummed tune into a full backing track with a text-to-music model.", "Keeping a known melody while exploring different genres or instruments.", "Guiding AI generation so it stays in key with an existing song part."]}, "481dc259-94bf-4c01-b7a4-85037b95c563": {"definition": "MuLan (Music-Language Network) is a Google Research model that learns a joint embedding linking music audio and free-form natural-language text, trained on large amounts of music paired with descriptions so that audio and matching text land close together in a shared space; it underpins text-conditioned systems such as MusicLM.", "plain_english": "MuLan is a Google AI that connects music sounds with the words that describe them. It learns to place a song and its description near each other, so a computer can match music to text.", "purpose_function": "It exists to bridge audio and language, letting other systems find or generate music that matches a written description.", "practical_application": "Developers use MuLan-style embeddings to power text-to-music search or to give a music generator a text prompt it can understand.", "category": "AI Music Generation", "related_terms": ["MusicLM", "Music generation", "MusicGen", "Melody-conditioning", "Neural audio synthesis"], "common_mistakes": ["Thinking MuLan generates music; it links audio and text but does not create audio by itself.", "Confusing the joint embedding with a simple tag list or keyword match.", "Assuming it needs clean labels, when it learns from noisy real-world descriptions."], "scenario_contexts": ["Building a text search that finds music clips matching a phrase.", "Providing the text understanding behind a text-to-music model.", "Tagging or organizing a music library by natural-language descriptions."]}, "60256d5d-0fc8-4bcf-9c57-edad44fe5845": {"definition": "Music generation is the automated creation of new musical content — either symbolic (notes/MIDI) or raw audio — by an algorithm or model, increasingly using machine-learning systems that learn patterns from existing music to produce original melodies, harmonies, or full arrangements.", "plain_english": "Music generation is when a computer makes new music on its own. Modern tools learn from lots of existing songs and then create fresh melodies or full tracks.", "purpose_function": "It exists to let machines compose or assist with music, speeding up creation and enabling tools like backing-track makers and idea generators.", "practical_application": "A producer might use a music-generation tool to create background tracks, spark ideas, or fill in parts, then edit the result in a DAW.", "category": "AI Music Generation", "related_terms": ["MusicGen", "MusicLM", "Jukebox", "Magenta", "Neural audio synthesis"], "common_mistakes": ["Assuming generated music needs no editing; results usually need cleanup and arrangement.", "Confusing symbolic (MIDI-note) generation with raw-audio generation.", "Thinking all music generation uses AI, when rule-based and algorithmic methods also exist."], "scenario_contexts": ["Creating royalty-free background music for a video.", "Generating chord or melody ideas to start a new song.", "Filling out an arrangement with AI-made instrumental parts."]}, "1c152bf8-5f90-4e7a-ba85-16c3425ff017": {"definition": "MusicGen is a music-generation model from Meta AI that uses a single-stage autoregressive Transformer operating over discrete audio tokens from the EnCodec neural codec to produce music conditioned on a text description and, optionally, a reference melody.", "plain_english": "MusicGen is a Meta AI tool that makes music from a text description, and it can also follow a tune you give it. It builds the sound one small piece at a time using a compressed audio code.", "purpose_function": "It exists to generate controllable music from simple text or melody inputs using one streamlined model instead of several stacked stages.", "practical_application": "A creator types a prompt like 'upbeat acoustic folk' and optionally adds a melody, then MusicGen returns a matching audio clip to use or refine.", "category": "AI Music Generation", "related_terms": ["MusicLM", "Melody-conditioning", "Music generation", "Jukebox", "Neural audio synthesis"], "common_mistakes": ["Expecting long, fully arranged songs; outputs are usually short clips.", "Thinking the melody input is copied note-for-note rather than followed loosely.", "Assuming text prompts guarantee exact instruments; results can vary."], "scenario_contexts": ["Generating a short themed music bed from a text prompt.", "Adding a hummed melody to steer the generated track.", "Comparing single-stage MusicGen output with MusicLM's approach."]}, "eac48d61-ff7d-4784-8974-41fe318078f4": {"definition": "MusicLM is a Google model that generates high-fidelity music from text descriptions by framing generation as a hierarchical sequence-to-sequence task over audio tokens, using representations such as MuLan and audio codecs to stay faithful to the text over long durations.", "plain_english": "MusicLM is a Google AI that turns a written description into music that sounds fairly clean. You can ask for 'calm piano for studying' and it creates a matching piece.", "purpose_function": "It exists to produce longer, higher-quality music from text prompts while keeping the sound consistent with the description.", "practical_application": "A user writes a detailed prompt and MusicLM returns a matching music clip, useful for prototyping moods or background-music ideas.", "category": "AI Music Generation", "related_terms": ["MusicGen", "MuLan", "Music generation", "Melody-conditioning", "Jukebox"], "common_mistakes": ["Thinking it reliably makes clear vocals; it focuses on instrumental music and struggles with lyrics.", "Assuming instant results; high-quality generation is compute-heavy.", "Confusing MusicLM with MusicGen, which is a separate Meta model."], "scenario_contexts": ["Generating background music from a descriptive text prompt.", "Exploring different moods by rewording the prompt.", "Studying text-to-audio generation methods in a course."]}, "8a421a70-deb7-4d51-92b2-f66c1b8285d5": {"definition": "Neural audio synthesis is the generation of audio waveforms using deep neural networks that learn to model sound directly, rather than relying on fixed oscillators and filters; examples include autoregressive models like WaveNet and differentiable approaches such as DDSP.", "plain_english": "Neural audio synthesis makes sound with AI networks instead of the usual electronic parts. The network learns how real sounds work. Then it builds brand-new audio on its own.", "purpose_function": "It exists to create realistic or novel sounds and voices that traditional synthesis struggles to produce, by letting a network learn sound from data.", "practical_application": "Engineers use neural audio synthesis in text-to-speech voices, AI instruments, and sound-design tools that generate audio a network has learned.", "category": "Neural Audio Synthesis", "related_terms": ["Neural synthesizer", "Music generation", "Magenta", "MusicGen", "Jukebox"], "common_mistakes": ["Thinking it always needs huge compute; lightweight models like DDSP can run efficiently.", "Confusing it with sampling, which replays recordings rather than generating new audio.", "Assuming outputs are always artifact-free; some models add noise or glitches."], "scenario_contexts": ["Building a realistic text-to-speech voice.", "Designing a neural instrument that models a real instrument's timbre.", "Generating novel sound effects for media."]}, "1fc373ff-3c69-44a1-b0e5-8f36b116d781": {"definition": "A neural synthesizer is a sound-generating instrument or system that produces or shapes audio using neural networks in place of, or alongside, traditional oscillators and filters, learning a model of timbre from data; examples include Magenta's NSynth and DDSP-based instruments.", "plain_english": "A neural synthesizer is an instrument that makes sound using an AI network instead of the usual electronic parts. It learns the character of real sounds and can blend or create new tones from them.", "purpose_function": "It exists to create new and expressive sounds by learning timbre from real audio, going beyond what fixed oscillators can make.", "practical_application": "A sound designer plays a neural synth like NSynth to morph between instrument tones or craft unusual textures for a track.", "category": "Neural Audio Synthesis", "related_terms": ["Neural audio synthesis", "Magenta", "Music generation", "MusicGen", "MusicLM"], "common_mistakes": ["Thinking it works exactly like a subtractive synth with oscillators and filters.", "Expecting instant, low-latency play; some neural synths need pre-rendering.", "Assuming it replaces all synthesis, when it usually complements traditional methods."], "scenario_contexts": ["Morphing between a flute and a guitar tone with NSynth.", "Sound-designing unique textures for electronic music.", "Adding a learned instrument voice to a DAW project."]}, "f912816b-33ea-44c6-aa63-7183e3f967f0": {"definition": "An audible transient produced when a synthesizer oscillator's waveform makes a sudden step discontinuity, most often when its phase is reset to a fixed start point at note-on or at each hard-sync retrigger. The abrupt jump in the signal carries broadband energy that is heard as a click.", "plain_english": "A small click you hear when a synth's wave suddenly jumps instead of starting smoothly. It is like the pop you hear if you yank a rope tight all at once instead of pulling it gently.", "purpose_function": "It is usually an unwanted artifact rather than a feature, so knowing its cause lets a technician choose free-running phase, zero-crossing starts, or anti-click smoothing to keep note attacks clean. A subtle click is sometimes kept on purpose to sharpen a percussive attack.", "practical_application": "When a bass patch clicks on every note, a technician turns off the oscillator's phase reset (free-run) or enables the synth's click-removal option to clean up the attack.", "category": "Oscillator behavior", "related_terms": ["Oscillator sync", "Waveform", "Phase", "Envelope", "Sample and hold"], "common_mistakes": ["Assuming the click means broken gear when it is a normal phase-reset artifact.", "Confusing an oscillator click with digital aliasing or a DC-offset thump.", "Turning on phase reset for tighter attacks without realizing it can add clicks."], "scenario_contexts": ["A plucky bass patch clicks on every note because the oscillator resets its phase at each note-on.", "A hard-synced lead shows small clicks at high sync ratios from the abrupt waveform resets.", "Switching an oscillator from reset to free-run to remove clicks from held chords."]}, "24ff81db-b626-4380-81f6-8731d606c6c9": {"definition": "A synthesis technique in which one oscillator (the slave) has its waveform cycle forcibly restarted by another oscillator (the master). In hard sync the slave's phase is reset every master cycle, locking its perceived pitch to the master while the slave's own tuning reshapes the waveform into bright, harmonically rich tones; soft sync resets the slave only under certain conditions for a subtler effect.", "plain_english": "One oscillator forces a second one to restart its wave in step with it. Then you sweep the second one's tuning to get that screaming, tearing lead sound.", "purpose_function": "It exists to create complex, animated harmonics that a single oscillator cannot make, especially the classic aggressive sync-lead sound when the slave's pitch is swept.", "practical_application": "A technician sets oscillator 1 as master and oscillator 2 as slave, then modulates oscillator 2's pitch with an envelope to get the tearing sync-lead timbre.", "category": "Oscillator behavior", "related_terms": ["Oscillator click", "Waveform", "Phase", "Frequency modulation", "Envelope"], "common_mistakes": ["Thinking hard sync raises the pitch; the master sets the pitch and the slave's tuning shapes the tone.", "Not modulating the slave oscillator's tuning and then wondering why sync sounds static.", "Confusing hard sync with FM; both add harmonics but by different mechanisms."], "scenario_contexts": ["Programming an aggressive sync-lead by sweeping the slave oscillator with an envelope.", "Using soft sync to loosely lock two oscillators for a thicker unison.", "Recreating classic 1980s sync tones on a hardware or software synth."]}, "d7c957f3-6943-49b4-bd95-88a1c40cfdc0": {"definition": "Prompt-based sound design is the practice of creating or shaping sounds by writing natural-language text prompts (optionally with reference audio) that drive a generative AI model, rather than by manually programming synthesizer or sampler parameters.", "plain_english": "It means making sounds by describing them in words. You type something like a rusty metal door creak and the AI makes that sound for you.", "purpose_function": "It lets a creator specify a target sound in plain language and get usable audio fast, lowering the skill barrier and speeding up sketching or prototyping of sound effects and textures.", "practical_application": "A sound designer types a prompt such as distant thunder with light rain into a text-to-audio tool, auditions several takes, and drops the best result into the timeline for cleanup.", "category": "AI sound design", "related_terms": ["Text-to-audio", "Text-to-SFX", "AI sound effects generator", "Text-conditioning", "Stable Audio"], "common_mistakes": ["Expecting one prompt to nail the sound instead of iterating and refining the wording", "Ignoring sample rate, length, and quality limits of the generated output", "Assuming generated sounds are automatically license-cleared for release"], "scenario_contexts": ["Sketching placeholder SFX before a formal Foley session", "Generating ambient textures for a game prototype", "Creating quick sound variations from a written description"]}, "3e81bc60-2efe-4d3d-a3e9-466362f6c632": {"definition": "RAVE (Realtime Audio Variational autoEncoder) is a neural audio-synthesis model introduced by Caillon and Esling at IRCAM in 2021 that learns a compact latent representation of audio and decodes it back to a waveform, enabling fast, high-quality timbre transfer and generation that can run in real time, even on CPU.", "plain_english": "RAVE is an AI that learns the sound of an instrument or voice and lets you play or transform audio through it in real time. It is fast enough to run live.", "purpose_function": "It provides a lightweight neural model for real-time timbre transfer and sound generation, letting musicians route live audio through a trained model to reshape its timbre on stage or in the studio.", "practical_application": "A musician trains a RAVE model on a chosen sound set, then runs it as a plug-in (for example via nn~ in Max/MSP or Pure Data) to morph a live instrument into that timbre during performance.", "category": "Neural synthesis", "related_terms": ["Timbre transfer", "Style transfer", "Audio-domain generation", "Autoregressive model", "Audio tokenization"], "common_mistakes": ["Assuming RAVE needs a huge dataset - it can train on a few hours, but too little varied audio yields artifacts", "Confusing RAVE's real-time timbre transfer with text-to-music generation", "Expecting perfect fidelity at very low latency without tuning the model size"], "scenario_contexts": ["Real-time timbre transfer of a live vocal on stage", "Building a custom instrument from a trained sound model in Max/MSP", "Generating evolving textures for sound design"]}, "83df01ba-f6ee-4d30-b699-b58f0e954801": {"definition": "A quantization method that encodes a vector with a cascade of vector quantizers, where each stage stores the residual (the leftover error) from the previous stage using its own codebook; summing the selected code vectors from all stages reconstructs the input, giving high accuracy at a low bit rate. It is a core component of neural audio codecs such as SoundStream and EnCodec.", "plain_english": "A way to shrink audio into very little data by rounding it off in a few passes. Each pass fixes the small error left by the one before. It is like guessing a price in rounds: first the tens, then the ones, then the cents.", "purpose_function": "It exists to represent audio or other signals with very few bits while keeping quality high, by splitting the job across several small codebooks instead of one huge one.", "practical_application": "An engineer working with modern AI audio or low-bitrate speech tools meets RVQ as the layer that turns audio into the compact tokens those systems store and transmit.", "category": "Audio coding", "related_terms": ["Quantization", "Bit depth", "Codec", "Sample rate", "Compression"], "common_mistakes": ["Confusing this with dynamic-range compression; it is data quantization, not audio level control.", "Assuming one big codebook is used, when RVQ deliberately chains several small ones.", "Thinking each stage re-encodes the whole signal, rather than only the leftover error from the stage before."], "scenario_contexts": ["Understanding how a neural audio codec turns sound into discrete tokens.", "Trading bit rate against audio quality by choosing the number of quantizer stages.", "Reading the technical docs of an AI music or speech model that lists an RVQ bottleneck."]}, "0d9dd182-b069-4e03-8dc0-b4c44209b3ed": {"definition": "Riffusion is an AI music-generation system, released in 2022 by Seth Forsgren and Hayk Martiros, that fine-tunes the Stable Diffusion image model to generate spectrogram images from text prompts and then converts those spectrograms back into audio.", "plain_english": "Riffusion makes music from text by drawing a picture of the sound and turning that picture into audio. It reuses an image AI to do it.", "purpose_function": "It repurposes a text-to-image diffusion model for music by treating sound as spectrogram images, showing that existing image models can generate short musical clips from text descriptions.", "practical_application": "A user types a style prompt into Riffusion, which generates a spectrogram and renders a short audio clip, useful for quick musical sketches or experimentation.", "category": "AI music generation", "related_terms": ["Text-to-music", "Text-to-audio", "Stable Audio", "Audio-domain generation", "Suno"], "common_mistakes": ["Thinking Riffusion generates audio directly - it generates spectrogram images that are then converted to sound", "Expecting long, structured songs rather than short clips", "Assuming spectrogram-to-audio conversion is lossless"], "scenario_contexts": ["Generating a short musical riff from a text prompt", "Experimenting with spectrogram-based music generation", "Creating novelty clips by blending style prompts"]}, "e741be41-4575-4fe8-8ca7-bc6f5a2d3937": {"definition": "A circuit or module that captures (samples) the instantaneous value of an input signal at moments set by a clock or trigger and holds that value steady at its output until the next sample. In synthesizers it is most often fed with noise to generate stepped random voltages for modulation; in data conversion it is the front-end stage that freezes an analog value while an ADC digitizes it.", "plain_english": "It grabs the level of a signal at a chosen moment and keeps it steady until the next grab. Feeding it noise gives those classic random, stepping computer bleeps in synth music.", "purpose_function": "It exists to turn a smoothly changing signal into a series of held steps, either to create rhythmic random modulation in synths or to hold a steady voltage so a converter can measure it accurately.", "practical_application": "A technician patches noise into a sample-and-hold clocked by the LFO to modulate filter cutoff, adding stepped random movement to a patch.", "category": "Modulation source", "related_terms": ["LFO", "White noise", "Clock", "Modulation", "Analog-to-digital converter"], "common_mistakes": ["Forgetting sample-and-hold needs a clock or trigger; with no clock it just holds one value.", "Assuming its output is smooth, when it is stepped and changes only at each sample.", "Thinking it always makes random values, when the output depends entirely on the signal you feed it."], "scenario_contexts": ["Creating stepped random filter modulation by feeding noise into a clocked sample-and-hold.", "Understanding the sample-and-hold stage at the input of an ADC in a digital audio interface.", "Clocking sample-and-hold to tempo for rhythmic random pitch or timbre changes."]}, "0fc26e08-88c9-4f70-a42d-649563d79fa4": {"definition": "A device or software that stores and plays back a timed sequence of musical events - pitches, gates or triggers, and control values - driving synthesizers or other instruments to perform them automatically. Hardware step sequencers advance through a fixed number of steps, while MIDI and DAW sequencers record and edit note and controller data on a timeline.", "plain_english": "A tool that remembers a pattern of notes and plays it back for you, over and over, in time. It is like a player-piano roll that tells the synth which notes to hit and when.", "purpose_function": "It exists to automate performance so the musician does not have to play every note live, letting patterns loop, layer, and stay perfectly in time.", "practical_application": "A technician programs a bassline into a step sequencer, sets the tempo, and clocks it so it locks with the rest of the rig.", "category": "Control device", "related_terms": ["MIDI", "Clock", "Gate", "Arpeggiator", "Tempo"], "common_mistakes": ["Confusing a sequencer, which stores note events, with a synthesizer, which makes the sound.", "Forgetting to match clock or tempo, so the sequence drifts out of time with other gear.", "Mixing up a step sequencer's steps with musical bars, leading to wrong pattern lengths."], "scenario_contexts": ["Programming a repeating bassline or drum pattern on a hardware step sequencer.", "Recording and editing MIDI notes on a DAW's piano-roll sequencer.", "Slaving an external sequencer to the studio's master clock so everything stays in sync."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"c1ad14ad-d54e-4637-a028-3bf1cff94c56": {"definition": "SoundStream is a neural audio codec that uses a trained encoder, a residual vector quantizer, and a decoder to compress general audio (speech, music, and ambient sound) into a compact stream of discrete tokens and reconstruct it at very low bitrates. Introduced by Google in 2021, it can deliver quality comparable to or better than traditional codecs at bitrates as low as around 3 kbit/s.", "plain_english": "SoundStream is a smart way to shrink audio into a tiny stream of code and rebuild it later. It works like a smart packer that throws away tiny details you are unlikely to notice, so the file gets very small. A computer learned how to do it, so the playback still sounds close to the original.", "purpose_function": "It exists to compress audio to very low bitrates while keeping high perceived quality, so sound can be stored or streamed efficiently; its discrete tokens also serve as building blocks that feed generative audio models.", "practical_application": "Engineers use neural codecs like SoundStream to send good-sounding audio over limited-bandwidth links and to turn recordings into token sequences that drive AI music and speech systems.", "category": "Neural Audio Codec", "related_terms": ["Bitrate", "Audio codec", "Vector quantization", "Text-to-audio", "Waveform"], "common_mistakes": ["Assuming SoundStream is a synthesizer or oscillator; it is a codec that compresses and reconstructs existing audio, not a tone generator.", "Confusing a neural codec's discrete tokens with MIDI or symbolic notes; the tokens represent compressed audio, not musical notation.", "Expecting lossless output; like other low-bitrate codecs it discards detail to hit its target bitrate."], "scenario_contexts": ["Streaming voice or music over a low-bandwidth connection where a very low bitrate is required.", "Preparing audio as discrete tokens to train or drive a generative audio model.", "Comparing the perceived quality of a neural codec against a traditional codec at the same bitrate."]}, "58596c25-e9c1-4d39-92e9-264ac53fea6a": {"definition": "Spectral modeling synthesis (SMS) is an analysis/synthesis method that decomposes a sound into a deterministic part, modeled as a sum of time-varying sinusoids (the stable, pitched partials), plus a stochastic residual part, modeled as time-varying filtered noise. Storing and reshaping these two components lets the original sound be transformed and resynthesized flexibly.", "plain_english": "Spectral modeling synthesis splits a sound into two parts: clear humming tones and leftover noise. A computer studies the sound, saves both parts, and can rebuild or reshape it. It is a bit like separating a singer's steady voice from their breath.", "purpose_function": "It exists to give a flexible, meaningful model of a sound's spectrum so that pitch, timing, and timbre can be changed independently and still sound natural, which plain waveform playback cannot do.", "practical_application": "Sound designers and researchers use SMS tools to time-stretch, transpose, or morph recorded instruments and voices while keeping them sounding realistic.", "category": "Synthesis Technique", "related_terms": ["Additive synthesis", "Partial", "Fourier transform", "Phase vocoder", "Timbre"], "common_mistakes": ["Treating SMS as pure additive synthesis; the noise (stochastic) component is essential and is exactly what additive-only models miss.", "Assuming partial tracking works perfectly on very noisy or inharmonic sounds, where following the sinusoids becomes unreliable.", "Confusing SMS with a plain FFT display; it is a full analysis-plus-resynthesis model, not just a way to view a spectrum."], "scenario_contexts": ["Time-stretching a vocal without changing its pitch for a film scene.", "Morphing between two instrument timbres for sound design.", "Transposing a recorded instrument while keeping a natural tone."]}, "14f63351-ec26-464b-8377-ea74786f9e6f": {"definition": "In synthesis, 'squelchy' describes a wet, liquid, vocal-sounding timbre produced by sweeping a high-resonance low-pass filter while its cutoff is modulated (typically by an envelope or manual automation), most famously the Roland TB-303 acid bassline sound.", "plain_english": "Squelchy is that wet, rubbery 'wow' sound in acid basslines. You get it by turning a filter's resonance up high and sweeping its cutoff.", "purpose_function": "The term names a target timbre so musicians and technicians can communicate and dial in the resonant, filter-swept sound central to acid house, techno, and related electronic styles.", "practical_application": "To get a squelchy bass, a producer raises filter resonance, sets a low cutoff with envelope modulation, uses a sawtooth oscillator, and adds note slides so the filter sweep morphs between pitches.", "category": "Timbre descriptors", "related_terms": ["VCF", "VCO", "Sample and hold", "Sequencer", "Oscillator sync"], "common_mistakes": ["Thinking a special effect makes the squelch when it comes from filter resonance plus cutoff modulation", "Setting resonance so high it self-oscillates and masks the bassline", "Forgetting note slides and accents, which are key to the classic 303 squelch"], "scenario_contexts": ["Programming an acid bassline on a TB-303 or its emulations", "Describing a desired resonant filter sound to a bandmate", "Dialing in a squelchy lead on a subtractive synth"]}, "9aea726b-c5bb-4607-a387-bc548cf6f1d3": {"definition": "Stable Audio is a text-to-audio generative system from Stability AI that produces music and sound effects from text prompts using a latent diffusion model conditioned on both the text and timing information, which lets it generate audio of a requested length. Later open releases (Stable Audio Open) were published with documented model details.", "plain_english": "Stable Audio is a tool that makes music or sound effects from a written description. You type what you want, such as 'calm piano with rain,' and the computer creates matching audio. It works much like text-to-image tools that turn words into pictures.", "purpose_function": "It exists to let people create original audio clips of a chosen style and length from a simple text description, without recording or hand-building the sound.", "practical_application": "Producers and content creators use it to quickly generate background music, loops, or sound effects for drafts, videos, or games straight from a text prompt.", "category": "AI Music Model", "related_terms": ["Text-to-audio", "Text-conditioning", "Diffusion model", "Latent space", "Suno"], "common_mistakes": ["Assuming outputs are automatically cleared for commercial use; licensing and training-data rights depend on the specific version and its terms.", "Expecting exact, controllable musical parts; prompts steer overall style and mood, not precise notes or arrangement.", "Confusing it with a synthesizer; it generates finished audio from a trained model, not from oscillators and filters you patch."], "scenario_contexts": ["Generating a short background music bed for a video from a text prompt.", "Creating a custom sound effect of a set length for a game prototype.", "Auditioning musical style ideas quickly before recording real instruments."]}, "1c97cf89-5e76-479c-ac40-b8ad589b47b1": {"definition": "Style transfer is a technique in which the stylistic characteristics of one signal (for example an instrument's timbre or a genre's texture) are applied to the content of another, so a source performance is re-rendered in a target style. In audio it commonly refers to neural musical timbre or style transfer, which aims to keep the musical content while changing the sound.", "plain_english": "Style transfer means keeping what is played but changing how it sounds. For example, a melody played on a flute can be reshaped to sound like a violin. It is a bit like keeping the same sentence but swapping the speaker's voice.", "purpose_function": "It exists to separate the 'content' of audio from its 'style' so the same musical idea can be re-voiced in a different timbre, instrument, or genre.", "practical_application": "Producers and researchers use audio style transfer to convert a performance from one instrument's tone to another, or to restyle a recording, often as a creative or prototyping tool.", "category": "AI Audio Technique", "related_terms": ["Timbre", "Text-to-audio", "Stable Audio", "Symbolic music generation", "Spectral modeling synthesis"], "common_mistakes": ["Assuming perfect separation of content and style; pitch, timing, and tone artifacts are common in the output.", "Confusing timbre transfer with simple EQ or a preset; style transfer learns and remaps complex spectral behaviour, not just tone balance.", "Expecting it to work equally well on any material; polyphonic or noisy input is much harder than clean single-note input."], "scenario_contexts": ["Re-rendering a piano recording to sound like a guitar for a demo.", "Restyling a vocal or instrument tone as a creative effect.", "Researching how musical content can be separated from instrument timbre."]}, "abca1197-fd62-47d9-ba72-c0e559583ada": {"definition": "Suno is a commercial text-to-music platform from Suno, Inc. that generates complete songs - backing instrumentation plus sung vocals from supplied or AI-written lyrics - from short natural-language prompts; the company also released the open text-to-audio model Bark.", "plain_english": "Suno makes full songs from a few words. You describe a style and give or ask for lyrics, and it sings and plays a complete track.", "purpose_function": "It lets people with no musical training produce finished, vocal songs quickly, serving demos, social content, and idea sketches from a text description.", "practical_application": "A creator types a genre, mood, and lyrics into Suno, generates a full song with vocals, and downloads it for a video or social post.", "category": "AI music generation", "related_terms": ["Udio", "AIVA", "Riffusion", "Text-to-music", "Voice cloning"], "common_mistakes": ["Assuming Suno output is automatically cleared for commercial use - check the current license and plan", "Expecting precise editing control like a DAW rather than prompt-level control", "Treating AI-written lyrics as fact-checked or original"], "scenario_contexts": ["Generating a themed song for a social media clip", "Sketching a demo song idea before recording live musicians", "Making custom jingles from a text brief"]}, "ef2836d5-41c5-4bc0-844b-29f9e9aefec1": {"definition": "Symbolic music generation is the automatic creation of music in a symbolic representation, such as MIDI, a piano-roll, or score-like tokens that encode notes, timing, and dynamics, rather than as an audio waveform. A model produces sequences of these symbols, which can then be rendered to sound with any instrument.", "plain_english": "Symbolic music generation means a computer writes music as notes, not as a finished sound file. It builds something like sheet music or a MIDI file that you then play back with any instrument sound. It is like writing a recipe instead of cooking the meal.", "purpose_function": "It exists to produce editable, note-level musical material that a musician can change, re-orchestrate, or perform, giving far more control than generating raw audio.", "practical_application": "Composers and producers use symbolic generation to create melodies, chord progressions, or accompaniments as MIDI they can edit and assign to any instrument in a DAW.", "category": "AI Music Generation", "related_terms": ["MIDI", "Piano roll", "Text-to-audio", "Quantization", "DAW"], "common_mistakes": ["Confusing symbolic output with audio; the model produces notes, not a finished sound recording.", "Assuming the generated notes need no editing; they usually need human correction of timing, voicing, or range.", "Expecting realistic performance nuance from the symbols alone; expression depends on the instrument and rendering used to play them."], "scenario_contexts": ["Generating a MIDI chord progression to build a track around in a DAW.", "Creating a melody idea that a composer then edits and orchestrates.", "Producing accompaniment parts that are assigned to virtual instruments."]}, "b39bd944-d5f8-41f2-83e4-dc545c6c4a19": {"definition": "Text-conditioning is the practice of guiding a generative model's output with a text input: a written prompt is encoded (typically by a language or joint text-audio embedding model) and used to steer generation toward the described content. It is the mechanism behind text-to-audio and text-to-music systems.", "plain_english": "Text-conditioning means using written words to steer what a computer creates. The model reads your prompt and uses it as instructions. It is like telling an artist what to draw before they start.", "purpose_function": "It exists to give users simple, natural-language control over what a generative model produces, by linking a text description to the audio that is generated.", "practical_application": "A technician sees text-conditioning at work whenever a prompt like 'warm jazz piano' shapes the output of a text-to-audio tool, and adjusts the wording to change the result.", "category": "Generative AI", "related_terms": ["Text-to-audio", "Stable Audio", "Prompt", "Embedding", "Diffusion model"], "common_mistakes": ["Assuming the model 'understands' the prompt like a person; it matches learned patterns between text and audio.", "Expecting identical output for the same prompt every time; generation is usually random unless a seed is fixed.", "Writing vague prompts and blaming the model; specific, concrete wording strongly affects the result."], "scenario_contexts": ["Typing a descriptive prompt to steer a text-to-audio model.", "Refining prompt wording to get closer to a desired sound.", "Combining a text prompt with other controls such as length or tempo."]}, "2add0031-320c-482b-978f-6a9a4dd576c5": {"definition": "Text-to-audio is the task of generating an audio waveform, such as sound effects, ambient sound, or music, directly from a natural-language text description, typically using a text-conditioned generative model such as a latent diffusion or transformer model. It produces finished audio rather than symbolic notes.", "plain_english": "Text-to-audio turns a written description into actual sound. You type what you want to hear and the computer makes the audio. It works much like text-to-image tools that turn words into pictures.", "purpose_function": "It exists to let users create sound directly from words, without recording, sampling, or hand-building the sound.", "practical_application": "Creators use text-to-audio tools to generate sound effects, ambiences, or music beds for videos, games, and drafts straight from a prompt.", "category": "AI Audio Generation", "related_terms": ["Text-conditioning", "Stable Audio", "Symbolic music generation", "Diffusion model", "Waveform"], "common_mistakes": ["Confusing text-to-audio with symbolic generation; text-to-audio outputs a finished waveform, not editable notes.", "Expecting precise musical control; prompts guide overall style and content, not exact notes or the mix.", "Assuming generated audio is always free to use; usage rights depend on the tool and its training data."], "scenario_contexts": ["Generating a rain-and-thunder ambience for a scene from a text prompt.", "Creating a short music bed for a video without recording anything.", "Producing a custom sound effect for a game prototype."]}, "b3310d6d-b4a7-48cb-8969-b8896bfa949a": {"definition": "Text-to-music is a generative-AI approach in which a model produces musical audio (or symbolic music) from a natural-language text prompt that describes qualities such as genre, mood, instrumentation, or tempo.", "plain_english": "Text-to-music makes a piece of music from a written description. You type something like 'calm piano with soft rain,' and the model builds matching audio. It is like ordering a song by describing it in words.", "purpose_function": "It maps text descriptions to sound so people can create sketches, backing tracks, or full pieces without playing instruments or notating music. It exists to make music creation faster and more accessible.", "practical_application": "A content creator types a prompt to generate a royalty-free backing track for a video, then imports and arranges the result in a DAW.", "category": "Neural Audio Synthesis", "related_terms": ["Text-to-SFX", "Timbre transfer", "Generative AI", "Prompt", "MIDI"], "common_mistakes": ["Assuming the output is automatically original and copyright-clear; licensing and training-data questions still apply.", "Expecting exact control over individual notes; a text prompt gives broad direction, not a precise score.", "Believing longer or more detailed prompts always improve the result."], "scenario_contexts": ["Generating a mood-based background track for a podcast or video.", "Quickly sketching musical ideas from a short written brief.", "Producing variations of a theme by changing the text prompt."]}, "22c1b93e-680a-476b-a904-b00b4e0938ef": {"definition": "Text-to-SFX (text-to-sound-effects) is a generative-AI approach in which a model synthesizes non-musical sound effects, such as footsteps, rain, or an explosion, from a natural-language text description.", "plain_english": "Text-to-SFX makes sound effects from a written description. You type something like 'glass breaking on tile,' and the model creates that sound. It is like a sound library that builds the clip you ask for instead of making you search for it.", "purpose_function": "It maps text to audio so sound designers and editors get custom effects on demand without recording them or digging through a sample library. It exists to speed up sound design and cover sounds that are hard to record.", "practical_application": "A game or video editor types a prompt to generate a specific ambience or one-shot effect, then trims and layers it in their editor.", "category": "Neural Audio Synthesis", "related_terms": ["Text-to-music", "Foley", "Sound design", "Generative AI", "Sample library"], "common_mistakes": ["Expecting broadcast-ready quality every time; generated effects often need cleanup, EQ, or layering.", "Assuming generated effects are automatically license-free for commercial use.", "Confusing text-to-SFX with text-to-music; sound-effect models target non-musical sounds."], "scenario_contexts": ["Generating a custom ambience bed for a game level.", "Creating a one-off impact or whoosh for a video edit.", "Filling gaps in a Foley session with quick generated effects."]}, "4b6ac87c-c76b-4aeb-a109-15e40d760df9": {"definition": "Timbre transfer is a neural audio-synthesis technique that re-renders the timbre (tonal color) of one sound source onto the musical content of another, so that, for example, a sung or whistled melody is reproduced with the timbre of a violin while keeping the original pitch and dynamics.", "plain_english": "Timbre transfer swaps the 'voice' of a sound while keeping the tune. You could hum a melody and have it come out sounding like a trumpet, with the same notes and timing. It is like keeping the words of a song but changing who sings them.", "purpose_function": "It uses machine-learning models trained on a target instrument so a performance played on one instrument can be heard as another. It exists to separate the musical performance from the identity of the instrument.", "practical_application": "A producer records a simple vocal or monophonic line and uses a timbre-transfer model to turn it into a realistic solo instrument part without owning or playing that instrument.", "category": "Neural Audio Synthesis", "related_terms": ["Text-to-music", "Timbre", "Vocoder", "Style transfer", "Synthesis"], "common_mistakes": ["Assuming timbre transfer changes the melody or timing; it keeps the performance and only changes the tonal color.", "Expecting perfect, artifact-free results; models can add noise or smear fast passages.", "Confusing timbre transfer with pitch correction or EQ, which do not resynthesize the sound."], "scenario_contexts": ["Turning a hummed melody into a realistic saxophone line in a DAW.", "Reskinning a synth demo so it sounds like an acoustic instrument for a mockup.", "Experimenting with cross-instrument textures in electronic music production."]}, "d2d2077e-4258-4a7e-a5ee-653db51c88f5": {"definition": "Timing-conditioning is a technique in generative audio models where the network is conditioned on timing signals - such as the start offset and total duration of a clip - so it can generate audio of a specified length with coherent structure; Stability AI's Stable Audio uses seconds_start and seconds_total embeddings for this.", "plain_english": "It tells the AI how long the clip should be and where it is in the track. That way the music starts, builds, and ends at the right time instead of just stopping.", "purpose_function": "It lets a generative model produce variable-length outputs with proper beginnings, middles, and endings, rather than fixed-size chunks that cut off abruptly.", "practical_application": "In Stable Audio, a user sets the total seconds so the model renders a clip of that exact length with a natural intro and outro instead of a hard stop.", "category": "Model conditioning", "related_terms": ["Text-conditioning", "Text-to-audio", "Text-to-music", "Stable Audio", "Audio-domain generation"], "common_mistakes": ["Confusing timing-conditioning with tempo or BPM control - it governs length and position, not beat rate", "Requesting a length beyond the model's training window and expecting coherent structure", "Assuming any generator supports timing control; it must be trained with timing embeddings"], "scenario_contexts": ["Generating a 30-second cue that ends cleanly for an ad", "Producing audio of an exact duration to fit a video slot", "Rendering clips with proper intros and outros in Stable Audio"]}, "08ac4b5a-1f3f-4081-98fe-c2a82ba68324": {"definition": "Udio is a commercial text-to-music platform, launched in 2024 by Uncharted Labs, that generates songs with instrumentation and sung vocals from natural-language prompts and user-supplied or AI-generated lyrics.", "plain_english": "Udio makes songs from text. You describe the style and give lyrics, and it produces a track with singing and backing music.", "purpose_function": "It enables fast creation of full, vocal songs from a written description, giving non-musicians and creators finished audio for content, demos, or ideas.", "practical_application": "A user enters a style prompt and lyrics in Udio, generates short sections, then extends and stitches them into a full song for a project.", "category": "AI music generation", "related_terms": ["Suno", "AIVA", "Riffusion", "Text-to-music", "Stable Audio"], "common_mistakes": ["Assuming outputs are automatically license-cleared for commercial release", "Expecting a full arranged song in one pass rather than extending shorter sections", "Confusing Udio with Suno; they are separate competing platforms"], "scenario_contexts": ["Creating a full song with vocals from a text brief", "Extending a generated section into a complete track", "Prototyping song ideas before a studio session"]}, "ff2d25ea-669c-473b-8053-82749cfdff8e": {"definition": "A voltage-controlled filter (VCF) is an analog filter whose cutoff frequency (and usually resonance) is set by an applied control voltage. In subtractive synthesis it attenuates or emphasizes parts of an oscillator's harmonic content to shape timbre, most commonly as a low-pass filter.", "plain_english": "A VCF shapes the tone of a synth sound by cutting away some of its harmonics. A control voltage moves the cutoff point, which makes the sound brighter or more muffled. It is like a tone knob that something else can turn for you.", "purpose_function": "It sculpts timbre in subtractive synthesis by removing frequencies above (or below) a movable cutoff point. Voltage control lets an envelope or LFO sweep the cutoff to create evolving, dynamic sounds.", "practical_application": "A technician patches an envelope into the VCF cutoff input to create the classic filter sweep, and sets resonance to emphasize the cutoff without letting the filter self-oscillate unintentionally.", "category": "Filters", "related_terms": ["VCO", "VCA", "Cutoff frequency", "Resonance", "Envelope generator", "Low-pass filter"], "common_mistakes": ["Thinking the filter adds new frequencies; a VCF can only remove or emphasize harmonics already present in the source.", "Confusing cutoff (where filtering begins) with resonance (a boost right at the cutoff).", "Pushing resonance so high the filter self-oscillates when a clean sound was wanted."], "scenario_contexts": ["Routing an envelope generator to VCF cutoff so a bass note opens up and then closes.", "Adding resonance to a low-pass VCF to get a vocal, squelchy synth lead.", "Using an LFO on the cutoff for a slow, sweeping pad."]}, "21fec0f0-f121-4695-afdd-896592cb6902": {"definition": "A voltage-controlled oscillator (VCO) is an analog oscillator circuit whose output frequency is set by an applied control voltage, serving as the primary sound source in analog and modular synthesizers. Music VCOs typically use an exponential (1 volt-per-octave) response so that equal voltage steps produce equal musical intervals.", "plain_english": "A VCO is the part of an analog synth that makes the raw tone. A control voltage tells it what pitch to play, so a higher voltage gives a higher note. It works a bit like pressing higher keys on a piano to raise the pitch.", "purpose_function": "It generates the basic repeating waveform, such as saw, square, or triangle, that the rest of the synth then shapes. Voltage control lets a keyboard, sequencer, or envelope play and modulate the pitch automatically.", "practical_application": "A technician calibrates a VCO's 1 volt-per-octave tracking so the synth stays in tune across the keyboard, and patches control voltages into it to set or sweep pitch.", "category": "Oscillators", "related_terms": ["VCF", "VCA", "LFO", "Envelope generator", "Waveform"], "common_mistakes": ["Confusing the VCO (the sound source) with the VCF (which shapes tone, not pitch).", "Assuming an analog VCO stays in tune without warm-up; it can drift with temperature until warmed up and calibrated.", "Thinking control voltage sets volume; on a VCO it sets pitch, while a VCA sets level."], "scenario_contexts": ["Calibrating 1 volt-per-octave tracking on a vintage analog synth so it plays in tune across all octaves.", "Patching an envelope or sequencer control voltage into a modular VCO to create pitch sweeps or melodies.", "Tuning two VCOs slightly apart to create a thick, detuned lead sound."]}, "85b856e9-f120-44df-9016-b44ec4557dd6": {"definition": "w2v-BERT is a self-supervised speech-representation model that learns from unlabeled audio by combining wav2vec 2.0-style contrastive learning (to discretize speech into units) with BERT-style masked-language-modeling over those units, producing features used for downstream tasks such as speech recognition and audio generation.", "plain_english": "w2v-BERT is an AI that teaches itself the building blocks of speech from raw audio, with no labels. Those learned pieces then help other systems understand or make speech.", "purpose_function": "It provides strong, general speech representations learned without transcripts, reducing the labeled data needed to train accurate speech recognition and other audio models.", "practical_application": "An engineer uses a pretrained w2v-BERT model as a feature extractor or fine-tunes it on a smaller labeled set to build a speech recognizer or to tokenize audio for a generative model.", "category": "Speech representation", "related_terms": ["HuBERT", "Audio tokenization", "Autoregressive model", "SoundStream", "Audio-domain generation"], "common_mistakes": ["Thinking w2v-BERT transcribes speech by itself - it learns representations that other models use", "Confusing it with text BERT; w2v-BERT operates on audio, not written text", "Assuming pretraining alone is enough without fine-tuning for a specific task"], "scenario_contexts": ["Pretraining speech features to cut labeled-data needs for ASR", "Extracting audio tokens for a music or speech generation pipeline", "Fine-tuning on a low-resource language's speech"]}, "3d7ad23b-b01e-4596-afab-eaddba173b31": {"definition": "An audible click or transient artifact produced when an envelope generator changes a signal's level too abruptly, creating a step discontinuity in the waveform. It typically occurs with a near-instantaneous attack or release, or when a note is gated on or off at a non-zero point in the cycle.", "plain_english": "An envelope click is a short popping sound. It happens when a note's volume jumps up or down almost instantly, leaving a sudden step in the wave. That sharp step holds a burst of high tones you hear as a click.", "purpose_function": "The term names a discontinuity created by envelope shaping so technicians can recognise it; a click signals that an attack or release stage is too fast for the signal to settle, which is fixed by adding a short fade ramp.", "practical_application": "When a synth or sampler clicks on every note, a technician lengthens the attack or release by a few milliseconds, or enables the instrument's click-reduction or zero-crossing option, to smooth the transition.", "category": "Envelopes", "related_terms": ["ADSR envelope", "Attack time", "Release time", "Zero-crossing", "Zipper noise"], "common_mistakes": ["Setting attack and release to zero and assuming the sound stays clean, when instant level jumps cause clicks", "Blaming the oscillator, a cable, or a fault for a click that actually comes from envelope timing", "Confusing an intentional percussive transient with an unwanted envelope click"], "scenario_contexts": ["A bass patch with instant attack clicks on every note during a live set", "Gating a pad on and off in a DAW produces pops at each edit point", "A sampler clicks when its loop points or note-offs land at non-zero waveform values"]}, "640679b1-9787-4a9b-b2b8-0cbc1ab7f1fa": {"definition": "Filter resonance is a boost in level applied to frequencies near a filter's cutoff frequency, created by feedback within the filter. Raising resonance (often labelled Q) narrows and emphasises that band, and at high settings the filter can self-oscillate into a sine-like tone.", "plain_english": "Resonance makes the frequencies right around the filter's cutoff point louder, adding a sharp, ringing peak. Turn it up too far and the filter starts to whistle a tone all by itself.", "purpose_function": "It lets a designer emphasise a chosen frequency band and add character or bite to a filter, especially during a sweep; it exists because feedback around the cutoff shapes the timbre far more than a plain filter slope alone.", "practical_application": "A synth player raises resonance while sweeping the cutoff to create classic squelchy, vocal, or wah-like movement in a lead or bass, while watching for harsh peaks or self-oscillation that could overload a channel.", "category": "Filters", "related_terms": ["Cutoff frequency", "Q factor", "Low-pass filter", "Self-oscillation", "Filter sweep", "Modulation sweep"], "common_mistakes": ["Confusing the resonance (Q) control with the cutoff frequency control", "UNSAFE: pushing resonance into self-oscillation at high output can produce a loud sustained tone that risks hearing damage and driver stress", "Assuming more resonance always sounds better, when it can create harsh, thin, or unstable peaks", "Not allowing for the level boost resonance adds near cutoff, causing clipping"], "scenario_contexts": ["Dialing a squelchy acid bassline by combining high resonance with a moving cutoff", "Using a resonant peak to make a filter sweep more dramatic in a build-up", "A resonant filter self-oscillating and used as a tunable sine source"]}, "ce79526c-e430-4eb1-8c7e-16dcd4046b84": {"definition": "Frequency modulation (FM) is the varying of a carrier signal's instantaneous frequency in proportion to a modulating signal. In synthesis, when the modulator runs at audio rate it generates sidebands spaced around the carrier, producing rich, often inharmonic tones from a small number of oscillators (operators).", "plain_english": "In FM, one wave keeps speeding up and slowing down another wave very fast. This adds many new tones, so you can build bright, bell-like, or metallic sounds from just a few simple waves.", "purpose_function": "FM exists to generate complex, evolving spectra efficiently; a few operators can produce sounds such as bells, electric pianos, and gritty basses that would need many oscillators with other methods.", "practical_application": "A sound designer programs FM by choosing operator frequency ratios and modulation depth (index) to shape the harmonics, as on Yamaha DX-series hardware or modern FM plug-ins, to build electric pianos, bells, and aggressive basses.", "category": "Synthesis", "related_terms": ["Carrier", "Modulator", "Modulation index", "Operator", "Sidebands", "LFO wobble"], "common_mistakes": ["Confusing audio-rate FM synthesis with slow LFO vibrato, which is also frequency modulation but stays sub-audio", "Assuming operator ratios do not matter, when they set whether the result is harmonic or clangorous", "Expecting FM to behave like subtractive synthesis and reaching for a filter instead of adjusting the modulation index"], "scenario_contexts": ["Programming a DX7-style electric piano by tuning operator ratios and envelopes", "Adding a modulator at audio rate to an oscillator to create metallic bell tones", "Using cross-modulation between two oscillators to make aggressive bass timbres"]}, "d24d49a0-11a0-4c1c-a915-c6cbcd03a86a": {"definition": "LFO wobble is the pulsing, undulating change in timbre or level produced when a low-frequency oscillator (LFO) modulates a parameter, most often filter cutoff, at a sub-audio rate. Syncing the LFO to tempo produces the rhythmic 'wobble bass' associated with dubstep and related styles.", "plain_english": "A wobble is that pulsing, throbbing sound you hear when a slow control wave opens and closes a filter over and over. Matching its speed to the beat gives you the classic dubstep wobble bass.", "purpose_function": "It turns a static tone into rhythmic, moving texture; the LFO automates repeated parameter changes so the sound pulses in time without the player moving a control by hand.", "practical_application": "A producer routes a tempo-synced LFO to a low-pass filter's cutoff and adjusts the rate and depth to make a bass patch wobble in time with the track, often switching LFO rates from section to section.", "category": "Modulation", "related_terms": ["LFO", "Low-pass filter", "Cutoff frequency", "Modulation depth", "Tempo sync", "Filter resonance"], "common_mistakes": ["Leaving the LFO free-running so the wobble drifts out of time with the beat", "Setting LFO depth so high the filter fully closes and the sound drops out", "Confusing LFO wobble (sub-audio modulation) with FM, where the modulator runs at audio rate"], "scenario_contexts": ["Building a dubstep wobble bass with a tempo-synced LFO on filter cutoff", "Adding slow LFO movement to a pad so it breathes over time", "Assigning different LFO rates to a mod wheel to perform wobble changes live"]}, "e41800e6-5cf3-4749-8994-a91842febc29": {"definition": "A modulation sweep is a continuous, gradual change of a parameter over time driven by a modulation source such as an envelope, LFO, or manual control. The most common example is a filter sweep, where cutoff frequency moves smoothly across the spectrum.", "plain_english": "A modulation sweep is a smooth, gliding change to a control, like slowly opening a filter from dark to bright. It is the rising or falling movement you hear in build-ups and transitions.", "purpose_function": "It adds motion and tension by changing a setting gradually rather than in one step; sweeps are a core way to create build-ups, transitions, and evolving textures.", "practical_application": "An engineer automates a control, or uses an envelope or LFO, to sweep filter cutoff or another parameter upward through a build, then resets it at the drop, to shape energy across a song section.", "category": "Modulation", "related_terms": ["Filter sweep", "Cutoff frequency", "ADSR envelope", "LFO", "Automation", "Filter resonance"], "common_mistakes": ["Sweeping too fast, so the movement sounds like a click or jump instead of a smooth glide", "Forgetting that resonance greatly changes how a filter sweep sounds", "Confusing a one-time envelope sweep with a repeating LFO cycle"], "scenario_contexts": ["Automating a filter cutoff sweep to build tension before a drop", "Using an envelope to sweep pitch or cutoff at the start of each note", "Sweeping a phaser or wah parameter across a guitar solo"]}, "12f718e7-37d8-4f0f-9b07-0adc65f40651": {"definition": "A large-format modular synthesizer standard whose module front panels are five rack units tall (about 8.75 in / 222 mm), typically patched with 1/4-inch (6.35 mm) cables and following the 1 volt-per-octave control standard. It is the format of classic Moog modular systems and modern lines such as Synthesizers.com (Dotcom), MOTM, and Moog Unit (MU) modulars.", "plain_english": "A large style of modular synth. Each part has a tall panel, about 8.75 inches high. The big size leaves room for large knobs and thick 1/4-inch cables, like classic studio gear from the 1960s and 70s.", "purpose_function": "The tall panels give room for full-size knobs, switches, and widely spaced jacks, making complex patches easy to see and adjust, while the format preserves the look and workflow of classic 1960s-70s modular systems.", "practical_application": "A technician builds or maintains 5U systems by matching panel formats and connection conventions (1/4-inch jacks, and S-trig versus V-trig gates on vintage Moog gear) so modules from different makers interconnect correctly.", "category": "Modular format", "related_terms": ["Eurorack", "Control voltage (CV)", "Gate", "Trigger", "1V/octave", "Patch cable"], "common_mistakes": ["Treating '5U' as a single interchangeable standard, when MU (Moog), Dotcom, and MOTM differ in jacks, triggers, and power headers.", "Expecting vintage Moog S-trig gates to drive modern V-trig inputs without a converter.", "Reversing a module's power connector; verify pin-out and polarity before applying power to avoid damaging the module."], "scenario_contexts": ["Restoring a vintage Moog modular and matching replacement modules to the original 5U panel and trigger format.", "Building a new large-format studio synth from Synthesizers.com Dotcom modules with a matched power supply.", "Interfacing a 5U system with a Eurorack case using a format-bridging or level-shifting adapter."]}, "be673112-5587-436e-a265-46acc4689119": {"definition": "A modular-synthesizer format introduced by Doepfer (A-100 series, mid-1990s) in which module panels are 3U (128.5 mm) tall and their width is measured in horizontal pitch (HP, where 1 HP = 5.08 mm). Modules are patched with 3.5 mm (1/8-inch) cables, follow the 1 volt-per-octave pitch standard, and draw power over a ribbon connector supplying plus/minus 12 V (and often +5 V).", "plain_english": "A popular small format for modular synths. Each part is about 5 inches tall and uses thin 1/8-inch cables. Because the parts are small, you can fit many of them in one case.", "purpose_function": "Its small module size and shared power and signal standards let a technician fit many modules from many makers into one case, which has made Eurorack the most widely used modular format today.", "practical_application": "Technicians assemble Eurorack systems by budgeting HP width and power-rail current, aligning the ribbon cable's red stripe to the -12 V pins, and patching CV, gate, and audio between modules with 3.5 mm cables.", "category": "Modular format", "related_terms": ["5U modular", "Control voltage (CV)", "Gate", "Trigger", "1V/octave", "Patch cable"], "common_mistakes": ["Reversing the power ribbon: the red stripe must align with -12 V on both the module header and the bus board, or the module can be damaged.", "Overloading a power rail by adding modules without totaling each rail's current draw against the supply's rating.", "Confusing HP (panel width) with U (panel height) when planning a build.", "Assuming Eurorack CV/gate levels and 3.5 mm cables interconnect directly with 5U systems."], "scenario_contexts": ["Planning a case build by summing +12 V and -12 V current draw for every module before choosing a power supply.", "Troubleshooting a dead module after a ribbon cable was plugged in upside down.", "Patching an external CV keyboard into a Eurorack oscillator's 1V/octave input."]}, "3eaab9fa-2e5a-4d6a-a9bb-8c0b3b4f3fd4": {"definition": "In modular and CV systems, a trigger is a brief voltage pulse that signals the instant an event should begin, such as starting an envelope, advancing a sequencer step, or firing a drum voice. Unlike a gate, which stays high for the full duration of a note, a trigger conveys only the moment of onset, not how long to hold.", "plain_english": "A trigger is a quick pulse of voltage that tells a module to start something, like firing a drum or an envelope. Think of it as a tap on the shoulder: it marks the moment to go, but not how long to hold.", "purpose_function": "A trigger tells modules exactly when to act, keeping envelopes, sequencers, and drum modules synced to a rhythmic event without carrying any duration information.", "practical_application": "A technician routes a trigger from a clock, sequencer, or drum pad to a module's trigger input to fire it, and must match the trigger type (positive-going V-trig versus switch-to-ground S-trig on some vintage gear), using a converter when they differ.", "category": "Control signal", "related_terms": ["Gate", "Control voltage (CV)", "Envelope generator", "Clock", "Sequencer"], "common_mistakes": ["Confusing a trigger with a gate: a trigger marks only the onset, while a gate also holds the note and controls sustain and release.", "Expecting a trigger alone to sustain an ADSR envelope, when the sustain stage needs a held gate.", "Mixing S-trig (switch/short-to-ground, e.g. vintage Moog) and V-trig (positive voltage) signals without a converter, so nothing fires.", "Assuming all triggers share one voltage, when some modules need a minimum level (often around +2 to +5 V) to register."], "scenario_contexts": ["Clocking a drum module by sending a trigger pulse to each voice's trigger input.", "Advancing an analog sequencer one step per incoming trigger.", "Adapting a vintage Moog S-trig keyboard to fire a modern V-trig envelope through a converter."]}, "76e030b3-b4bd-4c64-b9c0-417c11da8ca2": {"definition": "A model of hearing that represents the cochlea as a bank of overlapping band-pass filters, called auditory filters, each centered on a different frequency, so a complex sound is analyzed by splitting it into frequency bands. The bandwidth of each filter, expressed as the critical bandwidth or equivalent rectangular bandwidth, sets the ear's frequency selectivity and governs how one sound masks another.", "plain_english": "This idea says your ear works like a row of many small filters. Each filter listens to one narrow band of pitches. Together they split a complex sound into separate pitch slices, a bit like sieves sorting sound by pitch.", "purpose_function": "It explains how the ear separates the many frequencies in a sound and predicts when one sound will hide, or mask, another, which underpins how we hear detail in speech and music.", "practical_application": "Engineers lean on it when setting EQ and reasoning about masking, since it explains why a boost in one band affects nearby frequencies and why some sounds bury others in a mix.", "category": "Psychoacoustics", "related_terms": ["Critical-band analysis", "Cochlear filter model", "Equal-loudness contour analysis", "Auditory scene analysis", "Masking"], "common_mistakes": ["Picturing the auditory filters as sharp, brick-wall bands rather than gradually sloping, overlapping shapes", "Assuming the filter bandwidths stay equal across frequency, when they widen at higher frequencies", "Confusing the auditory filter model, a functional model of hearing, with the physical cochlea itself"], "scenario_contexts": ["Explaining why a masking sound in one band hides a nearby tone", "Designing perceptual audio codecs such as MP3 or AAC that discard masked signal", "Setting EQ and understanding why adjacent frequencies interact"]}, "d0899fd3-d4bb-42ba-a3d3-40b9b328fff0": {"definition": "The process by which the auditory system organizes a mixture of sounds arriving at the ears into separate perceptual streams, each corresponding to a distinct sound source. It relies on cues such as onset timing, harmonic relationships, common frequency movement, and spatial location to group and segregate sound.", "plain_english": "This is how your brain sorts a jumble of sounds into separate sources. It works out which sounds belong to the singer, which to the drums, and which to a passing car. It uses hints like when sounds start and whether their pitches move together.", "purpose_function": "It lets us follow one voice or instrument within a busy mixture of sound, which is essential for understanding speech and music in the real world.", "practical_application": "Engineers use its cues of timing, pitch, and panning to make instruments sit as separate, hearable sources in a mix, and the same principles inform source-separation and noise-reduction tools.", "category": "Psychoacoustics", "related_terms": ["Cocktail-party effect study", "Auditory filter model", "Binaural masking level difference", "Haas-effect experiment", "Masking"], "common_mistakes": ["Treating stream segregation as fixed, when it shifts with tempo, pitch spacing, and attention", "Assuming spatial position alone groups sounds, when timing and harmonicity matter as much or more", "Confusing auditory scene analysis with simple frequency masking"], "scenario_contexts": ["Following one instrument through a dense arrangement", "Mixing so vocals stay distinct from backing tracks", "Designing algorithms that separate speech from background noise"]}, "862f51db-326b-48f6-84e9-8f81c33d0fd7": {"definition": "The improvement in the detectability of a signal in noise that occurs when the interaural phase or level relationship of the signal differs from that of the masking noise, compared with when signal and masker are identical at the two ears. The release from masking can reach roughly 15 dB at low frequencies, showing that binaural processing aids the detection of sounds in noise.", "plain_english": "This is how using both ears helps you pick out a sound hidden in noise. If the target sound and the noise reach your two ears in different ways, the target becomes much easier to hear. The gain can be worth up to about 15 dB.", "purpose_function": "It shows how the brain compares the sound at the two ears to unmask signals, which helps us detect and follow sounds in noisy places.", "practical_application": "It explains why stereo and binaural listening improve clarity in noise, and it underlies hearing tests and the design of hearing aids and headphone audio.", "category": "Psychoacoustics", "related_terms": ["Auditory scene analysis", "Cocktail-party effect study", "Masking", "Interaural time difference", "Interaural level difference"], "common_mistakes": ["Assuming the effect is equally large at all frequencies, when it is largest below about 500 Hz", "Thinking it depends only on level differences, when interaural phase is the main driver", "Confusing this release from masking with a simple increase in loudness"], "scenario_contexts": ["Explaining why two ears hear speech in noise better than one", "Audiology testing of binaural hearing", "Designing hearing aids and binaural noise reduction"]}, "8c15be32-3fb6-408c-b12f-622b6c9183d0": {"definition": "A model describing the frequency-selective, place-based filtering carried out by the cochlea, in which each location along the basilar membrane responds best to a particular frequency, forming a bank of overlapping, level-dependent band-pass filters. It links the mechanical tuning of the basilar membrane and the active gain of the outer hair cells to the auditory filters measured psychoacoustically.", "plain_english": "This describes how the inner ear itself acts like a set of tuned filters. Different spots along the coiled cochlea react to different pitches, high notes near the start and low notes deeper in. So the ear sorts sound by pitch using its own shape.", "purpose_function": "It connects the physical workings of the inner ear to the frequency selectivity we measure in hearing, explaining how the ear turns sound into place-coded frequency information.", "practical_application": "It helps technicians and audiologists understand frequency resolution and tuning sharpness, and why cochlear damage broadens the filtering and reduces the ability to separate frequencies.", "category": "Psychoacoustics", "related_terms": ["Auditory filter model", "Critical-band analysis", "Equal-loudness contour analysis", "Masking", "Basilar membrane"], "common_mistakes": ["Thinking cochlear tuning is passive and linear, when outer hair cells add active, level-dependent sharpening", "Assuming the filters keep a fixed width, when they broaden as level rises and with hair-cell damage", "Treating the cochlear filter model and the psychoacoustic auditory filter as unrelated"], "scenario_contexts": ["Explaining how the inner ear maps frequency to place", "Understanding how hearing loss broadens frequency tuning", "Relating basilar-membrane tuning to measured critical bands"]}, "37c6e02b-da36-453b-a1ca-de56a1a4cd32": {"definition": "Research into the auditory system's ability to selectively attend to one sound source, typically a single talker, amid competing sounds and background noise. Beginning with Colin Cherry's 1953 experiments, such studies examine how listeners use spatial, spectral, and temporal cues, together with binaural hearing, to focus on and follow a target voice.", "plain_english": "This is the study of how you can follow one voice at a noisy party. Your brain locks onto the person you want to hear and pushes the rest into the background. Researchers test which clues, like direction and pitch, make this possible.", "purpose_function": "It reveals how attention and binaural hearing let us pick out and track one source in a crowd, which is central to real-world listening and understanding speech.", "practical_application": "Findings guide the design of hearing aids, conferencing systems, and beamforming microphones, and they inform how engineers place and pan sources so a target stays intelligible.", "category": "Psychoacoustics", "related_terms": ["Auditory scene analysis", "Binaural masking level difference", "Masking", "Haas-effect experiment", "Auditory filter model"], "common_mistakes": ["Believing it works purely by direction, when pitch, timing, and voice quality also help", "Assuming background sound is fully blocked, when unattended streams still intrude, such as hearing your own name", "Confusing selective attention with the ear physically filtering the sound"], "scenario_contexts": ["Following a bandmate's voice on a loud stage", "Designing hearing aids that boost one talker in noise", "Evaluating microphone arrays that focus on a single speaker"]}, "2e410b3d-e2ae-4b4c-bbc8-1a2b3d3961e1": {"definition": "The analysis of hearing in terms of critical bands, the frequency ranges within which the ear integrates energy and within which sounds interact strongly for masking and loudness. Introduced by Fletcher and refined by Zwicker, it treats the ear as processing sound in about 24 critical bands across the audible range, expressed on the Bark scale.", "plain_english": "This looks at hearing as if the ear breaks sound into a set of frequency bands. Sounds inside the same band blend and fight each other for your attention. There are roughly two dozen of these bands across everything we can hear.", "purpose_function": "It explains how the ear groups nearby frequencies for loudness and masking, giving a basis for predicting when sounds combine or hide one another.", "practical_application": "It underlies perceptual audio coding such as MP3, loudness metering, and helps engineers understand why closely spaced frequencies mask each other in a mix.", "category": "Psychoacoustics", "related_terms": ["Auditory filter model", "Cochlear filter model", "Equal-loudness contour analysis", "Masking", "Auditory scene analysis"], "common_mistakes": ["Confusing the critical band on the Bark scale with the equivalent rectangular bandwidth, a related but narrower modern measure", "Assuming critical bandwidth stays constant in hertz, when it widens with center frequency", "Thinking the bands are fixed, non-overlapping channels rather than a continuous, sliding property of hearing"], "scenario_contexts": ["Explaining masking between close frequencies in a mix", "Designing perceptual codecs that hide coding noise within a band", "Predicting the loudness of complex sounds"]}, "75346711-7333-43c7-9b34-9700bffe62da": {"definition": "The study and use of equal-loudness contours, curves showing the sound pressure level needed at each frequency for a tone to be judged as loud as a reference tone, usually 1 kHz, across the audible range. Standardized in ISO 226 and historically known as the Fletcher-Munson curves, they map the frequency-dependent sensitivity of hearing and define the phon scale of loudness level.", "plain_english": "This studies curves that show how loud each pitch must be to sound equally loud to us. Our ears are less sensitive to very low and very high notes, so those need more level to match a mid tone. The curves map that pattern across all pitches.", "purpose_function": "It measures how our sensitivity changes with frequency and level, explaining why bass and treble seem to fade at low volume and providing the basis for loudness units like the phon.", "practical_application": "It guides monitoring levels, informs loudness-compensation controls, and reminds engineers that tonal balance shifts with playback volume, so mixes should be checked at realistic levels.", "category": "Psychoacoustics", "related_terms": ["Critical-band analysis", "Auditory filter model", "Cochlear filter model", "Masking", "Sound pressure level"], "common_mistakes": ["Assuming the contours are flat, when the ear is far less sensitive at low frequencies", "Treating one curve as valid for all levels, when the shape changes with loudness", "Still calling them the Fletcher-Munson curves when the current standard is ISO 226"], "scenario_contexts": ["Explaining why bass seems weaker at low listening volumes", "Checking a mix at several playback levels", "Understanding loudness-compensation controls on playback gear"]}, "faf9b5c1-9a24-4702-b7bd-08825d082a5d": {"definition": "The classic experiments by Helmut Haas that demonstrate the precedence effect, or law of the first wavefront: when two identical sounds arrive from different directions within roughly 1 to 40 ms of each other, the listener hears a single sound localized toward the earlier arrival, and the later sound can be up to about 10 dB louder before it is heard as a separate echo. The work quantifies how the ear fuses early reflections with the direct sound.", "plain_english": "These tests show that when the same sound reaches you twice, very close in time, you hear it as one sound coming from wherever it arrived first. The slightly later copy can even be a bit louder without sounding like a separate echo. This is why early room reflections blend with the original.", "purpose_function": "It explains how we localize sound and fuse early reflections with the direct sound, which is key to hearing direction correctly in reflective rooms.", "practical_application": "Engineers exploit it with delay in distributed loudspeaker systems, so sound seems to come from the stage even when nearer speakers are louder, and they use short delays to place or widen an image.", "category": "Psychoacoustics", "related_terms": ["Auditory scene analysis", "Binaural masking level difference", "Cocktail-party effect study", "Interaural time difference", "Sound pressure level"], "common_mistakes": ["Thinking any delay works, when the fusion effect holds only within roughly a 1 to 40 ms window", "Assuming the later sound is always inaudible, when enough delay or level turns it into a separate echo", "Setting delay-speaker timing by ear alone instead of measuring the arrival difference"], "scenario_contexts": ["Time-aligning delay speakers so sound images to the stage", "Explaining why early room reflections are not heard as echoes", "Using short delays to widen or position a stereo image"]}, "47d43e95-e081-434a-a5f6-0d9ee08593c1": {"definition": "Research into how listeners perceive sound presented over headphones, where each ear receives its signal directly without room or outer-ear cues. Such study addresses in-head localization, or lateralization, the lack of externalization, and how interaural time and level differences map a sound to a position along a line between the ears, in contrast with loudspeaker listening.", "plain_english": "This studies how sound seems different through headphones. Because the sound goes straight into each ear, it often feels like it sits inside your head rather than out in the room. Researchers look at how the balance and timing between the two earpieces move the sound left or right.", "purpose_function": "It explains why headphone listening differs from speaker listening and how left-right cues place a sound, guiding accurate headphone mixing and the design of realistic binaural and virtual audio.", "practical_application": "Engineers draw on it when mixing on headphones, which exaggerate panning and lack room sound, and when building binaural recordings, crossfeed, and virtual surround that push sound outside the head.", "category": "Psychoacoustics", "related_terms": ["Binaural masking level difference", "Interaural time difference", "Interaural level difference", "Auditory scene analysis", "Haas-effect experiment"], "common_mistakes": ["Assuming a headphone mix translates directly to loudspeakers, when panning and bass balance differ", "Expecting sound to sit outside the head without crossfeed or binaural processing", "Ignoring that headphones bypass the room and outer-ear cues that speakers provide"], "scenario_contexts": ["Mixing and checking how a track translates between headphones and speakers", "Creating binaural or 3D audio for headphones", "Understanding in-head localization during hearing tests"]}, "2968c09e-e12e-4be3-ad01-288ce9343bd9": {"definition": "The degree of similarity between the sound signals arriving at the two ears, expressed as the normalized interaural cross-correlation coefficient (IACC) ranging from 0 (completely dissimilar) to 1 (identical). Lower coherence is associated with greater apparent source width and a more enveloping, spacious sound field.", "plain_english": "A number that shows how alike the sounds reaching your two ears are. When they are nearly the same, a sound feels tight and easy to pinpoint; when they differ, it feels wide and wrapped around you.", "purpose_function": "It measures how similar the left- and right-ear signals are, a comparison the brain uses to judge how wide a source sounds and how enveloping a space feels. It exists because binaural hearing works by comparing the two ear signals.", "practical_application": "Acousticians measure interaural cross-correlation (IACC) to predict spaciousness in halls, and engineers decorrelate reverb or space microphones to widen or tighten a stereo or immersive image.", "category": "Psychoacoustics", "related_terms": ["Interaural time difference model", "Interaural level difference model", "Apparent source width", "Spaciousness", "Binaural hearing", "Cross-correlation"], "common_mistakes": ["Assuming higher coherence always sounds better; lower coherence is what creates a wide, enveloping image.", "Confusing interaural coherence with signal level or loudness, which it does not measure.", "Thinking a mono signal panned center has low coherence; identical ear signals give coherence near 1."], "scenario_contexts": ["Measuring IACC in a concert hall to rate its spaciousness and listener envelopment.", "Decorrelating reverb returns in a mix to widen the stereo image.", "Choosing spaced versus coincident microphone techniques for a wider or tighter recording."]}, "737a753f-7c2e-42de-b121-13905d696e44": {"definition": "A model of horizontal sound localization based on the difference in sound-pressure level between the two ears, caused by acoustic shadowing of the head. It dominates localization at higher frequencies (roughly above 1.5 kHz), where the head is large relative to the wavelength and casts a stronger shadow.", "plain_english": "A way of explaining how you tell left from right using loudness. Your head blocks some of the sound, so the far ear hears it a little quieter, and your brain reads that gap to place the sound. It works best for high, hissy sounds.", "purpose_function": "It explains and predicts how the auditory system locates sources using level differences between the ears, mainly in the high frequencies where the head casts an acoustic shadow.", "practical_application": "It underlies pan-pot laws, binaural and HRTF processing, and stereo miking; engineers rely on level differences between channels to place and widen images, especially in the highs.", "category": "Psychoacoustics", "related_terms": ["Interaural time difference model", "Interaural coherence", "Head-related transfer function", "Sound localization", "Head shadow", "Precedence-effect analysis"], "common_mistakes": ["Assuming level differences work equally at all frequencies; they are weak at low frequencies where the head does not shadow.", "Confusing interaural level difference (level cue) with interaural time difference (timing cue).", "Believing amplitude panning alone reproduces full, natural 3D localization."], "scenario_contexts": ["Setting pan positions on a console, where high-frequency content localizes largely by level.", "Designing HRTF-based binaural rendering for headphones or VR.", "Diagnosing why a low-frequency, boomy source is hard to localize in a room."]}, "397c7020-452e-4609-b97d-d727afddd82f": {"definition": "A model of horizontal sound localization based on the difference in arrival time, and ongoing phase, of a sound at the two ears due to the path-length difference around the head. It dominates localization below about 1.5 kHz, with a maximum interaural delay of roughly 600-700 microseconds for a source directly to one side.", "plain_english": "A way of explaining how you tell left from right using timing. A sound off to one side reaches the near ear a hair sooner, and your brain uses that tiny head start to place it. It works best for low sounds.", "purpose_function": "It explains and predicts how the auditory system locates sources using time and phase differences between the ears, the dominant cue at low frequencies where level differences are small.", "practical_application": "It underlies spaced-pair (A/B) microphone techniques and binaural recording; engineers exploit small inter-channel time differences to create width and stable low-frequency imaging.", "category": "Psychoacoustics", "related_terms": ["Interaural level difference model", "Interaural coherence", "Head-related transfer function", "Sound localization", "Precedence-effect analysis", "Binaural hearing"], "common_mistakes": ["Assuming timing cues work at all frequencies; above about 1.5 kHz the phase becomes ambiguous within a wavelength.", "Confusing interaural time difference (timing cue) with interaural level difference (loudness cue).", "Thinking the delay is large; the maximum is under about 0.7 milliseconds."], "scenario_contexts": ["Explaining why low-frequency sources are localized mainly by timing between the ears.", "Setting spacing on a spaced-pair (A/B) stereo array to capture time differences for width.", "Making a binaural recording with a dummy head that preserves inter-ear delays."]}, "3b964bfe-65c0-4edf-8cde-b9f389c79fa2": {"definition": "A statistical or psychoacoustic model that predicts listeners' subjective preference from objective measurements, for example predicting loudspeaker preference ratings from anechoic frequency-response metrics, or concert-hall preference from measured acoustic parameters. It links measurable physical properties to the average judgment of a listening population.", "plain_english": "This is a math tool that guesses which sound most people will like. It uses measurements alone. You do not need a big panel to rate every speaker. You feed in the numbers and it predicts the likely winner.", "purpose_function": "It lets designers estimate perceived quality without running a full listening panel, by tying measurable parameters such as flatness and smoothness of response to average listener preference.", "practical_application": "Loudspeaker engineers rank prototypes using predicted-preference ratings from anechoic spinorama data, and room or hall designers weigh reflection and reverberation choices against preference models.", "category": "Psychoacoustics", "related_terms": ["Loudspeaker perception study", "Perceptual evaluation protocol", "Frequency response", "Anechoic measurement", "Double-blind listening test", "Sound quality"], "common_mistakes": ["Treating a predicted preference score as an exact verdict rather than a population average with spread.", "Applying a model outside the conditions and program material it was trained on.", "Assuming personal taste always tracks the model; individual and trained-listener preferences can differ."], "scenario_contexts": ["Ranking loudspeaker prototypes from anechoic spinorama data before building listening panels.", "Predicting concert-hall preference from acoustic parameters during design.", "Screening headphone tunings against a preference target curve."]}, "b79ddc1b-0414-4381-859d-6673ebd24d5c": {"definition": "A controlled subjective listening test that evaluates how listeners perceive loudspeaker sound quality, typically double-blind, level-matched, and position-controlled to remove bias. Its results are related back to measured performance such as anechoic frequency response and directivity.", "plain_english": "A careful listening test that finds out how speakers really sound to people. Listeners judge them without knowing the brand and at matched loudness, so the choice is fair, and the results are tied back to the speaker's measurements.", "purpose_function": "It provides trustworthy subjective data on loudspeaker quality by controlling bias, so engineers can learn which measured properties actually predict what listeners prefer.", "practical_application": "Manufacturers and studios run blind, level-matched speaker comparisons to select monitors and to validate designs against measurements during research and development.", "category": "Psychoacoustics", "related_terms": ["Listener preference model", "Perceptual evaluation protocol", "Double-blind listening test", "Level matching", "Frequency response", "Anechoic measurement"], "common_mistakes": ["Running sighted comparisons, so brand, price, and appearance bias the result.", "Failing to match levels; the louder speaker is usually preferred regardless of quality.", "Ignoring position and room effects by not swapping speakers into the same location."], "scenario_contexts": ["Running a double-blind, level-matched speaker shootout to choose studio monitors.", "Correlating listener ratings with anechoic measurements in a manufacturer's research lab.", "Training a listening panel and screening for reliable, consistent listeners."]}, "94384649-5671-40fe-91ee-5cd38f6c9ef5": {"definition": "A standardized procedure for the subjective assessment of audio quality that specifies the test method, stimuli, listener screening, grading scale, and statistical analysis. Well-known examples include ITU-R BS.1116 for small impairments and ITU-R BS.1534 (MUSHRA) for intermediate-quality evaluation.", "plain_english": "An agreed rulebook for running a listening test the right way. It sets how to pick listeners, play the clips, hide the labels, and score results, so different tests can be trusted and compared.", "purpose_function": "It removes bias and makes listening tests repeatable and comparable across labs by fixing every step, from listener selection to scoring, so results are statistically meaningful.", "practical_application": "Engineers follow protocols such as MUSHRA or BS.1116 when comparing codecs, processors, or devices, and use ABX tests to check whether a change is even audible.", "category": "Psychoacoustics", "related_terms": ["Loudspeaker perception study", "Listener preference model", "MUSHRA", "ABX test", "Double-blind listening test", "Just-noticeable difference"], "common_mistakes": ["Skipping listener screening and training, which adds noise and unreliable scores.", "Using the wrong protocol for the impairment size, such as MUSHRA for very small differences that BS.1116 targets.", "Reporting results without hidden reference and anchor conditions, so the scale has no fixed meaning."], "scenario_contexts": ["Running a MUSHRA test to compare audio codecs at matched bitrate.", "Using ITU-R BS.1116 to assess small impairments in a new processor.", "Setting up an ABX test to confirm whether a processing change is audible."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"a1cfe1d3-0d0f-4129-bc65-857cdc717da9": {"definition": "The study of the precedence effect (the law of the first wavefront, or Haas effect), in which a sound and a delayed copy arriving from different directions within roughly 1-40 ms are heard as one event localized toward the first-arriving wavefront. It characterizes how the later sound is fused with the first and not localized separately until it exceeds the echo threshold.", "plain_english": "A look at how your ears lock onto the first sound to arrive. If a copy follows within a few thousandths of a second, you still hear one sound from the first direction. That is why a delayed speaker does not pull your ear off the stage.", "purpose_function": "It explains how the hearing system fuses early reflections with the direct sound and localizes toward the first arrival, which is essential for hearing clearly in reflective rooms.", "practical_application": "Sound designers add delay to fill and delay loudspeakers so the audience localizes toward the stage, typically setting reinforcement to arrive a few to a few tens of milliseconds after the direct sound.", "category": "Psychoacoustics", "related_terms": ["Haas effect", "Interaural time difference model", "Sound localization", "Delay", "Echo threshold", "Comb filtering"], "common_mistakes": ["Setting delay too long, so the second sound crosses the echo threshold and is heard as a distinct echo.", "Assuming the effect holds at any delay; it breaks down beyond roughly 40 ms depending on the signal.", "Confusing the precedence effect with electronic echo cancellation, which is a different process."], "scenario_contexts": ["Time-aligning delay and fill loudspeakers so the audience localizes toward the stage.", "Setting a short Haas delay on a vocal for width without a heard echo.", "Diagnosing when a strong reflection becomes an audible echo in a room."]}, "f15ace81-7af2-49f7-b988-f6d00e8d1e5f": {"definition": "The sound level below which a target signal becomes inaudible in the presence of a louder masker sound. The masker raises the hearing threshold for nearby frequencies, tracing a masking threshold curve that perceptual audio coders exploit to discard inaudible detail.", "plain_english": "The loudness line under which one sound gets hidden by a louder one. A strong tone lifts this line for nearby pitches, so quieter sounds beneath it simply vanish, much as a shout drowns out a whisper next to it.", "purpose_function": "It defines what can be removed or coarsely coded without an audible change, which is the basis of lossy audio compression such as MP3 and AAC, and it explains why one sound buries another.", "practical_application": "Perceptual codecs compute the masking threshold to decide which spectral detail to discard or quantize coarsely, and engineers use the same idea to understand why a loud instrument masks a quieter one in a mix.", "category": "Psychoacoustics", "related_terms": ["Simultaneous masking analysis", "Critical band", "Absolute threshold of hearing", "Temporal masking", "Perceptual audio coding", "Loudness"], "common_mistakes": ["Thinking a masked sound has been deleted; it is still present but falls below the raised threshold.", "Assuming the threshold is flat; it rises most near the masker's frequency and within the same critical band.", "Confusing the masking threshold with the absolute threshold of hearing in quiet."], "scenario_contexts": ["Tuning an MP3 or AAC encoder's psychoacoustic model so quantization noise stays masked.", "Understanding why a loud guitar buries a quiet shaker in a mix.", "Choosing EQ carving so overlapping instruments stop masking each other."]}, "d690c78f-1c4b-497b-bd19-a72926cd74f8": {"definition": "The study of masking that occurs when the masker and target sound are present at the same time, quantifying how a masker raises the detection threshold of other simultaneous sounds as a function of frequency. Masking is greatest within the same critical band and spreads more strongly upward in frequency than downward.", "plain_english": "A study of how a sound hides another that plays at the same moment. A loud tone hides quieter tones close to its pitch, and it blocks higher pitches more than lower ones, much as a bright light makes nearby dim stars disappear.", "purpose_function": "It characterizes how simultaneous sounds mask each other across the spectrum, which underpins codec bit allocation and explains why instruments sharing a frequency range fight for audibility.", "practical_application": "Codec designers use simultaneous masking curves to allocate bits and hide quantization noise, and engineers use the same idea when carving overlapping EQ so a lead cuts through a dense mix.", "category": "Psychoacoustics", "related_terms": ["Psychoacoustic masking threshold", "Temporal masking", "Critical band", "Frequency masking", "Perceptual audio coding", "Absolute threshold of hearing"], "common_mistakes": ["Confusing simultaneous (spectral) masking with temporal masking, which acts across short time gaps.", "Assuming masking spreads equally up and down in frequency; it spreads more strongly upward.", "Believing a sound must be louder than the masker overall to be heard; it only needs to exceed the local threshold."], "scenario_contexts": ["Explaining why a kick drum masks a bass note that shares the same frequency band.", "Designing codec bit allocation using simultaneous masking curves.", "Carving overlapping EQ regions so a lead vocal cuts through the mix."]}, "512aa3b4-5e40-4bf8-bdfa-3f347c70a86e": {"definition": "The scientific study of how the auditory system locates sound sources and perceives the spatial qualities of a sound field, including direction, distance, and spaciousness. It examines the cues the brain uses to do this: interaural time differences (ITD), interaural level differences (ILD), and spectral shaping from the head and pinnae, captured in head-related transfer functions (HRTFs).", "plain_english": "The study of how your ears and brain work out where a sound is coming from. For example, you can tell a car is on your left because the sound reaches that ear a bit sooner and a bit louder.", "purpose_function": "It explains the mechanisms of sound localization so audio systems, from stereo mixing to surround and immersive formats, can recreate a convincing sense of direction and space for the listener.", "practical_application": "Engineers apply its findings when panning tracks, choosing microphone spacing and angle for stereo imaging, building binaural or surround mixes, and time-aligning loudspeaker arrays so the audience perceives stable, accurate placement.", "category": "Psychoacoustics", "related_terms": ["Interaural time difference", "Interaural level difference", "Head-related transfer function", "Precedence effect", "Binaural hearing", "Sound localization"], "common_mistakes": ["Assuming localization relies only on loudness differences between the ears, and ignoring timing (ITD) and pinna spectral cues.", "Confusing left-right localization with front-back and up-down judgments, which depend mainly on spectral cues rather than interaural differences.", "Believing simple amplitude panning reproduces real-world localization; it lacks the natural HRTF and timing cues the ear expects."], "scenario_contexts": ["Setting the spacing and angle of a stereo microphone pair to capture a stable, well-localized image.", "Producing a binaural or immersive (e.g. Dolby Atmos) mix intended for headphone listening.", "Time-aligning and delaying a live loudspeaker system so the audience localizes sound toward the stage."]}, "19481162-a1e6-4b63-86e8-14d4a00e9cdd": {"definition": "The study and measurement of temporal masking, in which one sound reduces the audibility of another sound that is close to it in time. It characterizes forward (post-) masking, where a preceding sound masks a following one, and backward (pre-) masking, where a following sound masks a preceding one, describing how the threshold shift depends on level and on the time gap between the sounds.", "plain_english": "Looking at how one sound can hide another that comes just before or right after it. For example, a loud drum hit can cover up a soft note for a short moment.", "purpose_function": "It quantifies how the ear hides sounds across short time gaps, which underpins perceptual audio coding (such as MP3 and AAC) and helps predict when edits, noise, or artifacts will be inaudible.", "practical_application": "Engineers use it when setting bitrates for lossy codecs that discard masked detail, when timing edits, crossfades, or noise-gate action so any glitch falls under a masker, and when judging whether a quiet element will be heard next to a loud transient.", "category": "Psychoacoustics", "related_terms": ["Simultaneous masking", "Frequency masking", "Auditory threshold", "Critical band", "Perceptual audio coding", "Forward masking"], "common_mistakes": ["Confusing temporal masking with simultaneous (frequency) masking, which occurs between sounds present at the same time.", "Assuming forward and backward masking are equal; forward masking lasts far longer (up to about 100-200 ms) than backward masking (only a few ms).", "Thinking a masked sound has been removed from the signal; it is still present but simply not audible to the listener."], "scenario_contexts": ["Choosing bitrate and encoder settings for a lossy codec (MP3/AAC) that relies on masking to hide discarded data.", "Placing an edit or crossfade just after a loud transient so any glitch is masked.", "Judging whether a quiet reverb tail or artifact remains audible right after a strong drum hit."]}, "594c0f4d-7d61-4aa6-a216-fca3a18aec14": {"definition": "A double-blind comparison test in which a listener hears two known samples, A and B, then an unknown sample X that is randomly set to either A or B, and must decide whether X matches A or B. Repeating many trials and applying statistics reveals whether the listener can reliably hear any difference between A and B.", "plain_english": "You listen to sound A and sound B, then a mystery sound X that is secretly one of them. You guess whether X is A or B, and you do this many times. If you cannot beat a coin flip, the two sounds most likely sound the same.", "purpose_function": "It provides an objective, bias-resistant way to prove whether two audio items are actually distinguishable by ear, instead of relying on opinion or expectation.", "practical_application": "A technician runs an ABX test to check claims such as whether listeners can truly hear the difference between two cables, codecs, or sample rates before making a purchasing or workflow decision.", "category": "Listening Tests", "related_terms": ["Double-blind listening test", "Controlled listening evaluation", "Listening experiment", "Audio benchmarking", "Just-noticeable difference"], "common_mistakes": ["Assuming a heard difference is real without running enough trials to reach statistical significance", "Failing to level-match A and B, so a loudness difference gives away the answer", "Letting the software or operator reveal which sample is playing, breaking the blind", "Treating a single correct guess as proof, ignoring that 50 percent can be reached by chance"], "scenario_contexts": ["Testing whether listeners can distinguish a lossy codec from the original master", "Comparing two microphone preamps to see if the difference is audible", "Evaluating whether a high sample rate is distinguishable from CD quality", "Settling a studio debate about whether a cable swap changed the sound"]}, "c2bf6ca4-3d52-43b0-9b13-8a53b2d7d873": {"definition": "The process of measuring and comparing the performance of audio equipment, software, or systems against a defined reference or against one another, using consistent test signals, metrics, and conditions so results are repeatable and fair.", "plain_english": "It means testing audio gear or software the same way every time so you can compare them fairly. Like timing runners on the same track, you use fixed tests so the scores actually mean something.", "purpose_function": "It lets engineers rank or qualify equipment objectively and track whether a change improves or degrades performance, so decisions rest on repeatable data rather than impressions.", "practical_application": "A technician benchmarks converters, plugins, or DSP by running standard signals and logging metrics such as THD+N, frequency response, latency, or CPU load to compare products or verify a unit meets spec.", "category": "Research Methodology", "related_terms": ["Experimental validation", "Controlled listening evaluation", "ABX listening test", "Signal-to-noise ratio", "Total harmonic distortion"], "common_mistakes": ["Comparing devices under different settings or signal levels, so the results are not fair", "Reporting a single number without stating the test conditions that produced it", "Confusing measured benchmarks with how something actually sounds to listeners", "Using test material that cannot be run again identically"], "scenario_contexts": ["Comparing two audio interfaces' measured latency and noise floor", "Evaluating plugin CPU usage across different DAW buffer sizes", "Qualifying a batch of amplifiers against the manufacturer's published specs", "Choosing between converters by comparing THD+N under identical signals"]}, "7f0e4317-b395-44bd-9d8f-3fc616285c62": {"definition": "An organized working session dedicated to collecting audio data or perceptual judgments, in which stimuli are presented or recorded under planned, repeatable conditions to answer a defined research or evaluation question.", "plain_english": "It is a planned work session for studying sound. You set up your gear and test sounds ahead of time, then gather results in a careful, repeatable way, much like running a science lab.", "purpose_function": "It exists to gather reliable audio data or listener responses within one controlled block of time, keeping conditions consistent so the results can be trusted and repeated.", "practical_application": "A technician sets up the room, level-matches stimuli, and logs conditions before running listeners or capturing test recordings, so every trial in the session stays comparable.", "category": "Research Methodology", "related_terms": ["Listening experiment", "Controlled listening evaluation", "Experimental recording", "Audio benchmarking", "Double-blind listening test"], "common_mistakes": ["Changing gear or room setup partway through, so early and late results are not comparable", "Failing to document conditions, which makes the session impossible to repeat", "Running sessions so long that listeners fatigue and their judgments lose accuracy"], "scenario_contexts": ["Running a block of listening trials to compare loudspeaker voicings", "Capturing reference recordings of an instrument under set microphone positions", "Collecting localization judgments from a panel of listeners", "Measuring a room's response before a perceptual evaluation"]}, "a2320789-359d-445a-96ed-30f80d9a854a": {"definition": "A subjective assessment of audio quality or attributes carried out under standardized, controlled conditions, including level-matched stimuli, a defined playback system and room, blinding, and a structured response method, so that bias is reduced and the perceptual data is repeatable.", "plain_english": "It means judging how something sounds under strict, fair conditions. Loudness is matched, the room and gear are fixed, and you do not know which sample is which, so only the sound itself shapes your opinion.", "purpose_function": "It controls the many factors that bias hearing, such as loudness, expectation, room, and order, so that differences reported by listeners reflect the audio itself and can be reproduced by others.", "practical_application": "A technician sets up level-matched, blinded playback in a treated room and uses a fixed rating scale so listener panels can reliably compare speakers, codecs, or processing.", "category": "Listening Tests", "related_terms": ["Double-blind listening test", "ABX listening test", "Listening experiment", "Audio benchmarking", "Just-noticeable difference"], "common_mistakes": ["Skipping level-matching, so the louder sample is preferred regardless of quality", "Letting listeners see labels or brands, which biases their ratings", "Using an untreated room whose acoustics color every comparison", "Using too few listeners or trials to draw a statistically sound conclusion"], "scenario_contexts": ["Grading codec quality with a trained listening panel", "Comparing loudspeakers behind an acoustically transparent curtain", "Assessing the audibility of a processing change before release", "Rating the spatial quality of different surround mixes"]}, "9f269792-13e4-43de-a7cd-3d2eade53b25": {"definition": "A listening test in which neither the listener nor the person administering the test knows which stimulus is being presented at any given time, preventing conscious or unconscious cues from influencing the result. It is the standard method for objectively assessing audible differences and quality in audio.", "plain_english": "In this test, neither you nor the person running it knows which sound is playing. Hiding that from both sides stops any hint or body language from giving away the answer, so the results stay honest.", "purpose_function": "It removes both experimenter and listener bias, ensuring that reported differences come from what is actually heard rather than from expectation, branding, or subtle cues from the test operator.", "practical_application": "A technician runs double-blind comparisons, often using automated switching software, when evaluating gear, codecs, or formats so that conclusions will hold up to professional and scientific scrutiny.", "category": "Listening Tests", "related_terms": ["ABX listening test", "Controlled listening evaluation", "Listening experiment", "Audio benchmarking", "Experimental validation"], "common_mistakes": ["Running a single-blind test instead, where the operator still knows and can leak cues", "Not level-matching, so loudness rather than quality drives the choice", "Ending the test as soon as a right answer appears, ignoring the statistics", "Using too few trials or listeners for the result to be meaningful"], "scenario_contexts": ["Testing whether a lossy codec is transparent to listeners", "Evaluating amplifier or DAC differences without brand bias", "Comparing analog versus digital processing chains", "Validating a mastering change before committing to it"]}, "a19584f2-12b2-4e20-9a05-eb27dbe50a48": {"definition": "A recording made under deliberately controlled or varied conditions as part of a study, used either to test a recording technique or to produce standardized stimulus material for later perceptual or technical evaluation.", "plain_english": "It is a recording made to test something, not to release as music. You capture sound under set conditions so you can study a technique or use the clip as a test sample later.", "purpose_function": "It provides controlled, documented audio for research, either to compare capture methods or to serve as consistent stimuli, so that findings rest on known, repeatable material.", "practical_application": "A technician captures the same source with different microphone types, positions, or rooms, logging each condition, so the clips can be compared or reused in listening tests.", "category": "Research Methodology", "related_terms": ["Audio research session", "Listening experiment", "Controlled listening evaluation", "Experimental validation", "Localization experiment"], "common_mistakes": ["Changing more than one variable at once, so you cannot tell what caused a difference", "Not documenting microphone, position, and settings, which makes the recording unusable as data", "Letting recording level differ between conditions, biasing later comparisons"], "scenario_contexts": ["Recording an instrument with several microphones to compare their character", "Capturing binaural stimuli for a localization study", "Producing reference clips for a codec listening test", "Testing a new room-microphone technique under controlled conditions"]}, "43b41bf7-c083-4540-85d4-e42bfec7c537": {"definition": "The process of confirming a hypothesis, model, design, or performance claim by testing it under controlled conditions and comparing the outcomes against measured or perceptual evidence.", "plain_english": "It means proving an idea actually works by testing it, not just assuming it. You run a careful experiment and check the results against what you predicted.", "purpose_function": "It exists to separate claims that hold up from those that do not, giving engineers evidence-based confidence before a method, model, or product is trusted or shipped.", "practical_application": "A technician validates a new processing algorithm or measurement model by running controlled tests, such as listening trials or instrument measurements, and checking whether results match the predicted behavior.", "category": "Research Methodology", "related_terms": ["Audio benchmarking", "Double-blind listening test", "Controlled listening evaluation", "Listening experiment", "Experimental recording"], "common_mistakes": ["Treating a good result on one sample as proof without repeating the test", "Confirmation bias: looking only for evidence that supports the claim", "Skipping controls, so you cannot rule out other causes for the result"], "scenario_contexts": ["Confirming a new noise-reduction algorithm reduces noise without audible artifacts", "Checking that a room-correction model predicts the measured response", "Validating that a loudness meter matches the standard's reference values", "Testing whether a perceptual model agrees with listener ratings"]}, "6cefdcc7-0ad1-40ab-8f37-da1763f2c1ce": {"definition": "A controlled study in which human listeners are presented with audio stimuli and asked to detect, discriminate, identify, or rate them, so that their responses can be analyzed to reveal how sound is perceived or to evaluate audio quality.", "plain_english": "It is a test where people listen to sounds and report what they hear or prefer. Researchers study those answers to learn how hearing works or how good a sound is.", "purpose_function": "It turns subjective hearing into measurable data, letting researchers map the limits and behavior of human perception or judge audio systems against real listeners rather than meters alone.", "practical_application": "A technician runs listening experiments, such as detection, discrimination, or rating tasks with a listener panel, to establish thresholds, compare processing, or gather quality scores.", "category": "Listening Tests", "related_terms": ["Double-blind listening test", "ABX listening test", "Controlled listening evaluation", "Localization experiment", "Just-noticeable difference"], "common_mistakes": ["Using too few listeners or trials to reach a reliable conclusion", "Not randomizing stimulus order, letting learning or fatigue bias results", "Failing to screen listeners' hearing when the task demands it", "Leading listeners with biased instructions or labels"], "scenario_contexts": ["Measuring the threshold at which a distortion becomes audible", "Comparing preference scores for different loudspeakers", "Studying masking between two tones", "Rating the quality of coded audio at several bitrates"]}, "240dc543-7d6d-4f3d-9c2c-d43a3d6595f4": {"definition": "A listening experiment designed to measure how accurately a listener can judge the direction and/or distance of a sound source, typically by presenting sounds from known positions or with controlled interaural cues and recording the perceived location.", "plain_english": "It is a test of how well you can tell where a sound is coming from. Sounds are played from set spots or through headphones, and you point to or name where each one seems to be.", "purpose_function": "It reveals how the ear and brain use timing, level, and spectral cues to place sounds in space, which informs spatial audio, surround sound, and hearing research.", "practical_application": "A technician runs localization tests, using loudspeaker arrays or binaural playback, to evaluate spatial rendering systems, surround setups, or hearing performance.", "category": "Listening Tests", "related_terms": ["Listening experiment", "Double-blind listening test", "Controlled listening evaluation", "Interaural time difference", "Interaural level difference"], "common_mistakes": ["Ignoring head movement, which strongly affects real-world localization", "Using a reflective room whose echoes confuse the direction cues", "Not controlling loudness, which gives distance cues away", "Confusing front-back reversals with true localization errors"], "scenario_contexts": ["Testing how accurately listeners locate sources in a surround setup", "Evaluating a binaural rendering engine's directional accuracy", "Studying the precedence effect with paired sound sources", "Measuring localization blur at different frequencies"]}, "27b4b899-941d-494e-897c-ea1df168f864": {"definition": "A controlled psychoacoustic investigation of how perceived loudness relates to the physical properties of a sound, such as sound-pressure level, frequency, bandwidth, and duration. Such studies yield equal-loudness contours and loudness scales (phon and sone) that link measured intensity to subjective loudness.", "plain_english": "A test that measures how loud sounds seem to people, not just how strong a meter says they are. It shows that our ears hear some pitches as louder than others at the same level.", "purpose_function": "It quantifies the gap between measured level and perceived loudness so that meters, weighting curves, and loudness-normalization standards can be built to reflect human hearing.", "practical_application": "Technicians benefit from these results through A-weighting, equal-loudness compensation, and LUFS metering when setting mix levels or matching program loudness across content.", "category": "Psychoacoustic testing", "related_terms": ["Equal-loudness contour", "Phon", "Sone", "A-weighting", "LUFS", "Auditory masking"], "common_mistakes": ["Assuming a level meter reading equals perceived loudness at every frequency", "Confusing loudness (a perception) with sound-pressure level (a physical measure)", "Treating equal-loudness contours as fixed for all listeners and playback levels"], "scenario_contexts": ["Setting loudness-normalization (LUFS) targets for a streaming or broadcast mix", "Explaining why a mix sounds bass-light when played back quietly", "Choosing a weighting curve for a sound-level measurement"]}, "f9000789-fa12-476b-83b8-6cc54e48c12f": {"definition": "A psychoacoustic test that measures how the presence of one sound (the masker) raises the threshold of audibility of another sound, either in the frequency domain (simultaneous masking) or the time domain (temporal masking). Results define masking curves and critical bands that describe the limits of what a listener can hear.", "plain_english": "A test that shows how one sound can hide another so you cannot hear it. A loud tone can bury a soft tone near it in pitch, like a shout hiding a whisper.", "purpose_function": "It reveals which sounds the ear cannot detect in the presence of others, providing the data that underpins critical-band models and perceptual audio coding.", "practical_application": "Codec developers and mix engineers use masking data to predict when noise, artifacts, or quiet instruments will be hidden by louder material.", "category": "Psychoacoustic testing", "related_terms": ["Auditory masking", "Critical band", "Simultaneous masking", "Temporal masking", "Threshold of hearing", "Perceptual coding"], "common_mistakes": ["Assuming a sound is inaudible just because it is lower in level than another", "Ignoring temporal masking and considering only same-time masking", "Confusing the critical band with a fixed-width filter at all frequencies"], "scenario_contexts": ["Predicting whether a quiet reverb tail will be heard under a loud guitar", "Designing or evaluating an MP3/AAC encoder's masking model", "Deciding EQ moves to unmask a vocal buried by other instruments"]}, "fb24d399-9147-44dc-bb65-57cf7292ffc6": {"definition": "The subjective and objective assessment of how audible the artifacts of a lossy (perceptual) codec are, typically using standardized listening tests such as ITU-R BS.1116 for small impairments or BS.1534 (MUSHRA) for intermediate quality. It rates codec quality at a given bitrate by comparing coded audio against a hidden reference.", "plain_english": "A listening test that checks how good a squeezed audio file, like an MP3, sounds to real people. It finds out whether the parts thrown away to shrink the file can be heard.", "purpose_function": "It verifies that a codec removes only inaudible information and measures any remaining quality loss so bitrate and algorithm choices can be validated against human hearing.", "practical_application": "Broadcast and streaming engineers use these evaluations to choose codecs and bitrates that stay transparent for their delivery format.", "category": "Subjective evaluation", "related_terms": ["Perceptual coding", "MUSHRA", "ABX test", "Auditory masking", "Bitrate", "Codec"], "common_mistakes": ["Judging codec quality by bitrate alone instead of by controlled listening tests", "Running sighted, non-blind comparisons that bias the result", "Assuming transparency on one clip means transparency for all program material"], "scenario_contexts": ["Choosing a streaming bitrate that stays transparent for music", "Comparing two codecs for a broadcast delivery chain", "Verifying that a new encoder build adds no audible artifacts"]}, "0693ca2d-f09e-480e-b142-14ea41c69287": {"definition": "A subjective listening method in which listeners indicate which of two or more presented stimuli they prefer, often by paired comparison, producing preference scores or rankings. It measures liking or perceived quality rather than the detectability of a specific impairment.", "plain_english": "A test that asks listeners which of two sounds they like better. It helps pick the option most people enjoy, like a taste test for audio.", "purpose_function": "It captures listener opinion where no single physical measure defines 'better', guiding product, tuning, and mix decisions with votes that can be analyzed statistically.", "practical_application": "Loudspeaker and headphone makers, and mix engineers, run preference tests to choose voicings, tunings, or mix versions that most listeners favor.", "category": "Subjective evaluation", "related_terms": ["Paired comparison", "MUSHRA", "ABX test", "Double-blind test", "Subjective evaluation", "Listening test"], "common_mistakes": ["Letting listeners see labels or brands, biasing their choices", "Not level-matching the options, so the louder one is simply preferred", "Using too few listeners to reach a statistically meaningful result"], "scenario_contexts": ["Selecting a final headphone tuning from several candidates", "Choosing between two mix versions for release", "Voicing a loudspeaker for a target market"]}, "d6556277-6753-46f1-a07c-6b10956d7a36": {"definition": "An early, working design of an analog-to-digital or digital-to-analog converter built to validate its architecture and performance before production. It is tested for parameters such as resolution, sample rate, linearity, signal-to-noise ratio, and distortion, often including subjective listening evaluation.", "plain_english": "The early, trial version of a chip or board that turns sound between analog and digital form. Engineers build and test it before making the final product.", "purpose_function": "It lets engineers verify and refine a converter's real-world behavior, both measured specs and perceived sound, before committing to a final product.", "practical_application": "Audio-interface and console developers audition prototype converters on the bench and in listening rooms to confirm they meet target specifications.", "category": "Audio prototyping", "related_terms": ["Analog-to-digital converter", "Digital-to-analog converter", "Sample rate", "Bit depth", "Signal-to-noise ratio", "Dithering"], "common_mistakes": ["Trusting datasheet specs without bench-verifying and auditioning the actual prototype", "Assuming a higher sample rate or bit depth alone guarantees better sound", "UNSAFE: Reworking or probing powered prototype boards without proper ESD and electrical precautions"], "scenario_contexts": ["Bench-testing a new audio interface's converter before production", "Comparing a prototype DAC against a reference converter in a listening room", "Validating the linearity and SNR of an early ADC board"]}, "19bedc23-36b0-4289-9210-0c13b76759df": {"definition": "An experimental assembly of multiple microphones arranged in a defined geometry, built to evaluate a capture or beamforming concept before final design. It is tested for directivity, phase relationships, and spatial-capture performance.", "plain_english": "A first test build of several microphones set up in a fixed pattern. Engineers try it out to see how well it picks up sound before the real product is made.", "purpose_function": "It allows engineers to validate array geometry and processing, such as beamforming or Ambisonic capture, against real acoustic conditions before productizing.", "practical_application": "R&D teams use prototype arrays to trial new stereo, surround, or steerable-microphone designs in real rooms and outdoors.", "category": "Audio prototyping", "related_terms": ["Microphone array", "Beamforming", "Polar pattern", "Ambisonics", "Phase", "Comb filtering"], "common_mistakes": ["Ignoring phase and spacing, causing comb filtering when array signals are summed", "Testing only in an ideal room and assuming the same results outdoors or on-site", "Confusing more microphones with automatically better spatial capture"], "scenario_contexts": ["Trialing a new surround or Ambisonic capture rig in a concert hall", "Developing a steerable beamforming mic for conference rooms", "Testing array spacing for stereo imaging before a product launch"]}, "0712e71f-51ae-4045-834f-df4223fe5469": {"definition": "A trial configuration of the complete series of devices a signal passes through, such as microphone, preamplifier, converter, and processing, assembled to evaluate overall performance before a design is finalized. It is assessed end to end for gain structure, noise, headroom, and sound quality.", "plain_english": "A trial setup of all the gear that sound passes through, from mic to recorder. Engineers build it to test how it sounds before locking in the final design.", "purpose_function": "It lets engineers test how components interact as a whole, exposing noise, level, and coloration issues that individual specs may not reveal.", "practical_application": "Developers and system integrators build a prototype signal chain to audition and measure a proposed recording or playback path before deployment.", "category": "Audio prototyping", "related_terms": ["Signal chain", "Gain staging", "Preamplifier", "Signal-to-noise ratio", "Headroom", "Analog-to-digital converter"], "common_mistakes": ["Setting gain wrong so early stages add noise or later stages clip", "Judging the chain only by one component's specs, not the whole path", "UNSAFE: Making or breaking connections on powered, mains-connected gear instead of powering down first"], "scenario_contexts": ["Auditioning a proposed mic-preamp-converter path for a new studio", "Measuring end-to-end noise and headroom of a trial recording rig", "Comparing two candidate signal paths before choosing gear"]}, "b834279a-80d6-4862-ac19-f9a3cbd17bd8": {"definition": "A controlled scientific procedure that measures the relationship between physical sound stimuli and how human listeners perceive them, using methods such as thresholds, just-noticeable differences, and scaling under statistically designed conditions. It is the general experimental basis of psychoacoustics.", "plain_english": "A careful test of how people actually hear sound. It measures things like the softest sound we can notice or how we tell two sounds apart.", "purpose_function": "It provides the reliable, repeatable data on human hearing that underlies loudness models, masking curves, spatial-hearing theory, and audio coding.", "practical_application": "Its findings reach technicians as established rules and standards, such as thresholds, weighting curves, and codec behavior, used in everyday audio work.", "category": "Psychoacoustic testing", "related_terms": ["Psychoacoustics", "Auditory masking", "Just-noticeable difference", "Threshold of hearing", "Double-blind test", "Equal-loudness contour"], "common_mistakes": ["Running sighted tests, letting expectation bias the listener's response", "Failing to level-match stimuli, so loudness differences skew results", "Using too few trials or listeners to draw a reliable conclusion"], "scenario_contexts": ["Measuring the threshold of hearing across frequency", "Finding the just-noticeable difference in level for a study", "Testing localization accuracy for a spatial-audio project"]}, "132f0f2b-5679-426a-8e9c-7f0f8c162935": {"definition": "A structured listening-test method in which each stimulus is judged against a known reference, using a defined presentation and rating scheme such as a hidden reference and anchors (as in ABX, ABC/HR, or MUSHRA). It standardizes how listeners compare items so results are reliable and repeatable.", "plain_english": "A set of steps for judging audio by comparing it to a known good sample. Listeners rate how close each version comes to the trusted reference.", "purpose_function": "It controls bias and variability by fixing the reference, presentation order, and scoring, so quality differences can be measured and reproduced.", "practical_application": "Engineers follow a reference comparison protocol when evaluating codecs, converters, or processing to keep listening-test results valid and comparable.", "category": "Subjective evaluation", "related_terms": ["ABX test", "MUSHRA", "Hidden reference", "Double-blind test", "Preference testing", "Anchor"], "common_mistakes": ["Skipping the hidden reference and anchors, weakening the test's validity", "Not randomizing presentation order, allowing order bias", "Comparing items at different loudness levels instead of matching them"], "scenario_contexts": ["Running a MUSHRA test on codec candidates", "Using ABX to confirm whether two files are distinguishable", "Standardizing a listening test so results can be reproduced"]}, "18f3d254-1178-49ea-893f-671e9b5b738a": {"definition": "The branch of psychoacoustics research that investigates how listeners perceive the direction, distance, and spatial extent of sound sources and the acoustic environment. It examines the auditory cues that support localization and spatial hearing, chiefly interaural time differences (ITD), interaural level differences (ILD), and the spectral shaping imposed by the head and outer ears (head-related transfer functions), together with the precedence effect that governs how early reflections are fused with the direct sound.", "plain_english": "This is the study of how our ears work out where a sound is coming from. It looks at the tiny gaps in time and loudness between your two ears that tell your brain a sound's direction and distance. It is like how you can shut your eyes and still point at someone talking.", "purpose_function": "It exists to explain how humans build a mental map of sound in space, which grounds the design of stereo, surround, and immersive audio, room acoustics, and 3D or binaural rendering. Understanding these cues lets engineers reproduce or steer apparent source positions convincingly over speakers and headphones.", "practical_application": "A technician draws on these findings when placing stereo microphones, setting pan positions and delay times, aligning surround and immersive speaker layouts, or checking a binaural mix so listeners hear sources in the intended locations.", "category": "Spatial Hearing", "related_terms": ["Interaural time difference", "Interaural level difference", "Head-related transfer function", "Precedence effect", "Binaural hearing", "Localization"], "common_mistakes": ["Assuming loudness (level) difference alone fixes perceived position, and ignoring the arrival-time cues that dominate at low frequencies", "Confusing left-right localization cues with front-back and elevation cues, which depend mainly on outer-ear spectral shaping", "Treating headphone spatial impressions as identical to loudspeaker ones, forgetting that headphones bypass the natural crosstalk and room cues", "Believing more reverb automatically means better spatial realism, rather than the timing and spectrum of early reflections"], "scenario_contexts": ["Choosing and spacing a stereo microphone pair so the recorded image matches the real ensemble layout", "Calibrating a surround or Dolby Atmos room so phantom images sit where the mixer intends", "Producing a binaural mix for headphones using HRTF-based processing", "Diagnosing why a live mix collapses to one side because early reflections or delays confuse localization"]}, "a9167fcc-0d41-48da-a8ac-2f74c905d6a5": {"definition": "The branch of psychoacoustics research that investigates how the auditory system perceives the timing of sound over time, including temporal resolution, temporal integration, and temporal masking. It covers phenomena such as gap detection, the fusion of closely spaced events, forward and backward masking, and the way loudness and pitch build up over the duration of a sound.", "plain_english": "This is the study of how our ears sense the timing of sounds. It looks at how fast we can tell two clicks apart, and how a loud sound can hide a soft one that comes just before or after it. It is like your eyes needing a moment to adjust after a camera flash, but for hearing.", "purpose_function": "It exists to explain the limits of human hearing in time, which underpins how we perceive rhythm, transients, and speech clarity. This knowledge guides the design of audio codecs, dynamics processing, and reverberation, and sets realistic targets for timing accuracy in reproduction systems.", "practical_application": "A technician relies on these findings when setting compressor and gate attack and release times, judging how tight a delay or reverb early-reflection pattern should be, and understanding why perceptual codecs can discard sounds hidden by temporal masking.", "category": "Temporal Hearing", "related_terms": ["Temporal masking", "Temporal resolution", "Gap detection", "Temporal integration", "Precedence effect", "Auditory masking"], "common_mistakes": ["Confusing temporal masking (hiding in time) with simultaneous frequency masking (hiding by pitch overlap)", "Assuming the ear resolves events far faster than it does, and expecting listeners to hear timing errors below a few milliseconds", "Thinking loudness is judged instantly, when short sounds are perceived as quieter because loudness integrates over time", "Overlooking that very fast compressor attack times can audibly dull transients the ear would otherwise perceive"], "scenario_contexts": ["Setting attack and release on a compressor so drum transients stay punchy without pumping", "Understanding why a lossy codec like AAC or MP3 discards audio masked just before or after a loud transient", "Timing delay and early reflections so echoes fuse with the direct sound instead of being heard separately", "Judging speech intelligibility in a reverberant room where late energy smears the timing of syllables"]}, "dac52a44-566f-475a-a649-342eda969c61": {"definition": "ACE Studio is a commercial AI singing-voice software from TimeDomain that generates realistic sung vocals from entered MIDI notes and lyrics, letting users choose AI singer voices and control pitch, timing, and expression within a vocal-focused production environment.", "plain_english": "ACE Studio makes a computer sing your song. You give it notes and lyrics, pick a voice, and it produces vocals you can tweak.", "purpose_function": "It lets producers create lead and backing vocals without a human singer, useful for demos, songwriting, and productions where a specific voice or quick turnaround is needed.", "practical_application": "A songwriter draws a melody and types lyrics in ACE Studio, selects an AI voice, adjusts pitch and expression, and renders the vocal to drop into a DAW mix.", "category": "AI vocal synthesis", "related_terms": ["Singing voice synthesis (SVS)", "Synthesizer V", "Voice model", "Voice cloning", "Singing voice conversion (SVC)"], "common_mistakes": ["Confusing ACE Studio (synthesizes singing from notes and lyrics) with voice conversion that transforms an existing recording", "Expecting broadcast-perfect vocals with no editing of pitch, timing, and expression", "Assuming any voice can be used commercially without checking licensing and consent"], "scenario_contexts": ["Producing demo vocals for a song before hiring a singer", "Creating harmony and backing vocals from MIDI", "Generating a guide vocal in a chosen style"]}, "c5fc2fab-dd41-4ed2-9d55-f8c8ee81e621": {"definition": "An AI voice changer is software that uses machine-learning voice-conversion (voice-transformation) models to alter a speaker's vocal characteristics — such as timbre, pitch, and perceived identity or gender — so the output sounds like a different voice while preserving the spoken words, operating either offline or in real time.", "plain_english": "An AI voice changer is an app that makes your voice sound like someone else. It uses trained AI models, not just simple pitch shifting. You still say the same words, but the voice can sound like another person.", "purpose_function": "It lets a user take on a different voice or persona for privacy, entertainment, content creation, or accessibility, going beyond simple pitch or effect-based changers by learning realistic voice qualities from data.", "practical_application": "Creators and technicians run an AI voice changer on recorded tracks or on a live microphone feed, choosing a target voice and managing latency and audio quality within a DAW or streaming setup.", "category": "Voice Conversion", "related_terms": ["Voice conversion", "Real-time voice conversion", "Retrieval-based voice conversion (RVC)", "Pitch shifting", "Formant"], "common_mistakes": ["Confusing an AI voice changer with a basic pitch-shift or effect changer; AI models learn a full voice identity, not just pitch.", "Assuming perfect, artifact-free results, when quality depends on the model, its training data, and the input recording.", "Overlooking consent and likeness rules when cloning or imitating a real person's voice."], "scenario_contexts": ["Changing a streamer's or gamer's voice live on the microphone.", "Post-production redubbing, where a recorded voice is transformed into another character.", "Anonymizing a speaker's identity in an interview or podcast."]}, "643d6613-9bae-40dd-b5d5-1dc9b34f28e5": {"definition": "ElevenLabs is a commercial voice-AI company whose platform provides high-quality text-to-speech, voice cloning (instant and professional), speech-to-speech, and related tools via app and API, widely used for narration, dubbing, and character voices.", "plain_english": "ElevenLabs turns written text into natural-sounding speech and can copy a voice from a sample. People use it for narration, dubbing, and characters.", "purpose_function": "It lets creators generate realistic spoken audio and custom voices on demand, supplementing or replacing studio voice recording for scalable, multilingual narration and dubbing.", "practical_application": "A producer uploads a script to ElevenLabs, picks or clones a voice, generates narration, and exports the audio or integrates it through the API into a pipeline.", "category": "Voice AI platform", "related_terms": ["Voice cloning", "Resemble AI", "Text-to-audio", "Speech-to-speech", "Voice model"], "common_mistakes": ["Cloning a real person's voice without their explicit consent, which can breach law, platform terms, and publicity or likeness rights", "Assuming default voice settings suit every script instead of tuning stability and style", "Expecting flawless pronunciation of names and jargon without adjustments or phonetic input"], "scenario_contexts": ["Generating narration for an explainer video", "Dubbing content into multiple languages", "Creating consistent character voices for a game or audiobook"]}, "f24199f7-693b-4938-b8b4-5e7a30dff8bf": {"definition": "HuBERT (Hidden-Unit BERT) is a self-supervised speech representation learning model pre-trained to predict masked, discrete cluster labels — obtained by offline k-means clustering of audio features — from unlabeled speech, so it learns acoustic and linguistic structure that can later be fine-tuned for tasks such as speech recognition and voice conversion.", "plain_english": "HuBERT is an AI model that learns from speech with no labels. It hides parts of the audio and tries to guess what was there, like filling in blanks. Doing this teaches it the sound patterns of speech, which other tools can then reuse.", "purpose_function": "It turns large amounts of unlabeled audio into useful speech representations, reducing the need for costly transcribed data and providing strong features for downstream speech tasks.", "practical_application": "Engineers and developers use HuBERT (or its learned features) as a building block in voice-conversion, speech-recognition, and singing-voice pipelines, where its representations help separate what is said from who is saying it.", "category": "Speech AI Models", "related_terms": ["wav2vec 2.0", "Self-supervised learning", "Phonetic posteriorgram (PPG)", "Voice conversion", "Automatic speech recognition"], "common_mistakes": ["Thinking HuBERT transcribes or generates speech by itself, when it produces representations that other models use.", "Assuming it needs labeled or transcribed data to train, when its pre-training is self-supervised on unlabeled audio.", "Confusing HuBERT with wav2vec 2.0; they are related but use different training targets."], "scenario_contexts": ["Extracting speech features to train a voice-conversion model.", "Fine-tuning on a small labeled set to build a speech recognizer.", "Using its content representations to separate linguistic content from speaker identity in a voice pipeline."]}, "f765eb6f-f0df-4107-9708-80673723a80c": {"definition": "A phonetic posteriorgram (PPG) is a time-versus-class matrix in which each short frame of speech is represented by the posterior probabilities of phonetic classes (such as phones or senones), produced by a speaker-independent automatic speech recognizer; it captures the linguistic content of an utterance while being largely independent of the speaker's voice.", "plain_english": "A phonetic posteriorgram, or PPG, is a chart of speech over time. For each short moment, it shows how likely each speech sound is. Because it focuses on what was said, not who said it, tools use it to swap one voice for another.", "purpose_function": "It gives a speaker-independent description of what was spoken, so systems can keep the spoken content while changing the voice — a key reason it is used to bridge source and target speakers in voice conversion.", "practical_application": "Developers extract PPGs from a recording with a pretrained recognizer and feed them into a conversion model, so the output keeps the original words and pronunciation but takes on a different speaker's timbre.", "category": "Speech Features", "related_terms": ["Voice conversion", "Automatic speech recognition", "HuBERT", "Phoneme", "Prosody"], "common_mistakes": ["Thinking a PPG stores the audio or the speaker's voice, when it stores phonetic probabilities rather than sound.", "Assuming PPGs capture prosody and emotion, when they mainly carry linguistic content and usually need separate pitch/prosody modeling.", "Believing PPGs are perfectly speaker-independent in practice, when some speaker information can still leak through."], "scenario_contexts": ["Building a many-to-one voice-conversion system without parallel training data.", "Accent conversion, where content is kept but pronunciation is retargeted.", "Cross-lingual voice conversion using phonetic representations as a bridge."]}, "acb93e5a-cdfb-4484-acc5-2499d1b2e2f4": {"definition": "Prosody is the set of suprasegmental features of speech — variations in pitch (intonation), loudness (stress), duration, rhythm, and tempo — that span across syllables and words rather than individual speech sounds, and that convey emphasis, emotion, phrasing, and grammatical meaning.", "plain_english": "Prosody is the melody and rhythm of speech. It is the way pitch, loudness, and timing change while we talk. These changes stress important words, show feelings, and mark a question or a statement.", "purpose_function": "Prosody carries meaning that word choice alone cannot — signaling emphasis, emotion, sentence type, and phrase boundaries — so it is essential for natural, intelligible, and expressive speech.", "practical_application": "Audio and voice engineers judge prosody when editing dialogue, tuning vocals, or evaluating text-to-speech and voice-conversion output, since flat or unnatural prosody makes speech sound robotic even when every word is clear.", "category": "Voice Perception", "related_terms": ["Intonation", "Pitch", "Formant", "Phonetic posteriorgram (PPG)", "Text-to-speech"], "common_mistakes": ["Confusing prosody with pitch or intonation alone, when it also includes loudness, timing, and rhythm.", "Assuming prosody is only decorative, when it can change literal meaning, such as a statement versus a question.", "Treating clear pronunciation of every word as enough, while ignoring flat or wrong prosody that makes speech sound unnatural."], "scenario_contexts": ["Evaluating a text-to-speech or AI voice for natural, human-like delivery.", "Editing recorded dialogue or narration so emphasis and phrasing sound right.", "Comparing voice-conversion output to the source to check that emotion and phrasing survive.", "Coaching a voice actor on stress and intonation during a session."]}, "6ee08973-7520-4a65-9adf-4a1bbb5033d7": {"definition": "Real-time voice conversion is the transformation of a source speaker's voice into a target voice with low enough latency to be used live — as the person speaks — while preserving the linguistic content and, usually, the prosody of the original speech.", "plain_english": "Real-time voice conversion changes your voice into someone else's while you talk. It works fast enough that there is almost no delay. The words stay the same, but the voice sounds like a different person.", "purpose_function": "It lets a speaker take on another voice or persona instantly during live use — such as streaming, gaming, or performance — rather than only on pre-recorded files.", "practical_application": "A technician places a low-latency conversion model in the signal chain (often on a GPU) and manages buffer size, latency, and monitoring so the converted voice stays natural and stable during a live stream, broadcast, or show.", "category": "Voice Conversion", "related_terms": ["Voice conversion", "AI voice changer", "Latency", "Retrieval-based voice conversion (RVC)", "Timbre"], "common_mistakes": ["Confusing real-time voice conversion with offline conversion; real-time must run within a live latency budget and usually sacrifices some quality.", "Underestimating latency from buffering and processing, which breaks the live illusion when the converted voice lags the speaker.", "UNSAFE: Raising headphone or monitor level to mask processing delay, which can cause hearing damage; keep monitoring at safe levels per hearing-conservation practice and reduce latency instead."], "scenario_contexts": ["Live streaming or gaming with an altered on-mic voice.", "Live performance where a singer or presenter adopts a different vocal character.", "Broadcast or podcast where a guest's voice is changed on the fly for anonymity."]}, "dc36b473-e383-410f-8a37-e551210bf99b": {"definition": "Resemble AI is a commercial voice-AI company offering generative voice cloning, text-to-speech, speech-to-speech, and real-time voice tools, along with AI-speech (deepfake) detection and audio watermarking, delivered via app and API.", "plain_english": "Resemble AI copies and generates voices from samples, and also builds tools to spot fake AI voices. Companies use it for custom voices and for security.", "purpose_function": "It lets organizations create and deploy custom synthetic voices at scale while also providing detection and watermarking to help identify AI-generated or manipulated speech.", "practical_application": "A developer clones an approved voice in Resemble AI and calls its API to generate dynamic speech in an app, or uses its detection tools to flag possible voice deepfakes.", "category": "Voice AI platform", "related_terms": ["ElevenLabs", "Voice cloning", "Speech-to-speech", "Voice model", "Real-time voice conversion"], "common_mistakes": ["Cloning or deploying a voice without documented consent and rights, risking legal and ethical breaches", "Assuming AI-voice detection is infallible rather than a probabilistic aid", "Skipping watermarking or provenance steps when distributing synthetic voices"], "scenario_contexts": ["Building a branded synthetic voice for an IVR or assistant", "Generating localized speech for content at scale", "Screening audio for possible voice deepfakes"]}, "cf9c1ddf-1bff-4cfd-ba1f-5c34ecc9387c": {"definition": "Retrieval-based voice conversion (RVC) is an open-source voice-conversion method that extracts content features from source audio with a self-supervised model (HuBERT/ContentVec), replaces each feature with its closest match retrieved (top-1) from an index of the target speaker's training features to reduce timbre leakage, and resynthesizes speech in the target voice with a VITS-based generator and neural vocoder.", "plain_english": "RVC changes one person's recorded voice into another person's voice. It looks up the closest matching bits of the target voice so the result sounds more like them.", "purpose_function": "It converts the timbre of a recording to a target voice while keeping the original words and delivery, and its retrieval step improves similarity and reduces leftover traces of the source voice.", "practical_application": "A creator trains an RVC model on a target voice, then feeds in a vocal or speech recording to output the same performance in the target timbre, often for covers or dubbing.", "category": "Voice conversion", "related_terms": ["Voice conversion", "so-vits-svc", "Singing voice conversion (SVC)", "HuBERT", "Voice model"], "common_mistakes": ["Cloning or converting to a real person's voice without consent, raising legal and ethical issues", "Confusing RVC (converts an existing recording) with text-to-speech that starts from text", "Training on noisy or too little audio, which produces artifacts - clean data of adequate length is recommended"], "scenario_contexts": ["Making a song cover in another singer's timbre", "Changing a voice-over's timbre in post", "Building a custom voice model for a character"]}, "cdb111b8-b1ce-48ea-bafe-2ef403fc40b2": {"definition": "A form of voice conversion specialized for singing, which transforms a source singing recording so it sounds as though sung by a different target singer while preserving the melody, lyrics, timing, and expression of the original performance. Because it must maintain musical pitch and prosody such as vibrato, it is more tightly constrained than speech voice conversion.", "plain_english": "Singing voice conversion takes a recorded song and makes it sound like a different singer, but the tune and words stay the same. It is like re-skinning a performance with someone else's voice.", "purpose_function": "It lets producers change the singer on an existing vocal take without re-recording, which supports demos, character voices, and remixes. It keeps the musical performance intact while swapping only the singer's timbre.", "practical_application": "A producer might use an SVC model to hear how a topline sounds in a chosen vocalist's timbre, or to build a virtual guest-vocalist part from a guide vocal.", "category": "AI Voice Processing", "related_terms": ["Voice conversion", "Singing voice synthesis (SVS)", "Voice model", "Voice cloning", "so-vits-svc"], "common_mistakes": ["Confusing it with singing voice synthesis: SVC converts an existing sung recording, while synthesis generates singing from a score and lyrics.", "Feeding an off-key input and expecting the model to fix the tuning; SVC preserves the source pitch and timing.", "Assuming the lyrics can be changed during conversion, when SVC keeps the original words."], "scenario_contexts": ["Turning a songwriter's rough guide vocal into a chosen singer's timbre for a demo.", "Creating a virtual duet by converting one recorded take into a second singer's voice.", "Auditioning several vocal timbres on the same performance before committing to one."]}, "b0b5adff-5e48-476f-b8e6-4d683819c1fd": {"definition": "The generation of a singing vocal performance directly from a musical score (notes and timing) and lyrics, producing audio with no human singing input. Systems render pitch, phonemes, and expression into a sung voice using concatenative sampling or neural models.", "plain_english": "Singing voice synthesis makes a computer sing a song from written notes and words, with no real singer needed. It is like sheet music read aloud, but sung instead of spoken.", "purpose_function": "It exists to create sung vocals on demand for composition, demos, and virtual artists, giving producers a controllable voice without booking a singer. Users edit notes, lyrics, and expression to shape the performance.", "practical_application": "A composer enters a melody and lyrics into an SVS editor to hear a full sung vocal, then tunes phrasing and vibrato before mixing it like a real vocal track.", "category": "AI Voice Processing", "related_terms": ["Singing voice conversion (SVC)", "Synthesizer V", "Voice model", "Voice cloning", "Voice conversion"], "common_mistakes": ["Confusing synthesis with conversion: SVS builds singing from a score, while singing voice conversion transforms an existing sung recording.", "Expecting natural results without editing timing, vibrato, and pronunciation, which usually need manual shaping.", "Treating exported synthesized vocals as royalty-free, when the voice and library often carry licensing terms."], "scenario_contexts": ["Prototyping a topline vocal before a session with a human singer.", "Producing vocals for a virtual singer or Vocaloid-style project.", "Filling in a temporary guide vocal so instrumentalists can rehearse to the melody."]}, "0676f8ce-89fc-407d-8cde-a8887eea9fd7": {"definition": "so-vits-svc (SoftVC VITS Singing Voice Conversion) is an open-source singing-voice-conversion project that extracts content features from source audio with a SoftVC content encoder (HuBERT/ContentVec), combines them with extracted pitch (F0), and resynthesizes the performance in a trained target voice using a VITS-based model with a neural vocoder.", "plain_english": "so-vits-svc turns a recorded singing performance into another singer's voice while keeping the tune. It listens to what is sung and the pitch, then rebuilds it in the new voice.", "purpose_function": "It lets users convert a sung or spoken recording into a chosen target voice, preserving melody and timing, and became a widely used community tool for voice covers and character vocals.", "practical_application": "A user trains a so-vits-svc model on a target singer, then converts a dry vocal recording so the same melody and lyrics are sung in that voice for a cover.", "category": "Voice conversion", "related_terms": ["Singing voice conversion (SVC)", "Retrieval-based voice conversion (RVC)", "Voice conversion", "HuBERT", "Singing voice synthesis (SVS)"], "common_mistakes": ["Converting to a real artist's voice without consent, which raises legal and ethical concerns", "Confusing so-vits-svc (converts a recording) with singing voice synthesis that generates singing from notes and lyrics", "Feeding reverberant or noisy input; dry, clean vocals give far better results"], "scenario_contexts": ["Producing a song cover in a target singer's voice", "Converting a guide vocal to a character voice", "Creating fan covers with a trained voice model"]}, "1970e329-bb11-41d3-9e46-5b88dcc58158": {"definition": "A processing approach in which both the input and the output are speech audio, as in speech-to-speech translation or speech-driven voice conversion. The system takes spoken audio and produces new spoken audio, sometimes directly and sometimes via internal intermediate representations.", "plain_english": "Speech-to-speech means spoken audio goes in and spoken audio comes out. For example, it can hear one language and say the same thing in another. It can also change one voice into a different voice.", "purpose_function": "It exists to transform spoken audio end to end, for translation, voice change, or repair, without forcing a stop at written text. Keeping speech in and speech out preserves timing and delivery that text would lose.", "practical_application": "In voice-conversion work, a technician runs a source recording through a speech-to-speech model so the same words come out in a target voice.", "category": "AI Voice Processing", "related_terms": ["Voice-to-voice", "Voice conversion", "Voice cloning", "Voice model", "Singing voice conversion (SVC)"], "common_mistakes": ["Confusing speech-to-speech with text-to-speech: text-to-speech starts from written text, while speech-to-speech starts from spoken audio.", "Assuming it always translates languages, when speech-to-speech also covers same-language voice conversion.", "Believing there is never a text step inside, when some pipelines still transcribe internally."], "scenario_contexts": ["Speech-to-speech translation on a live call or conference.", "Converting a recorded voice-over into a different target voice for dubbing.", "Restyling a spoken take while keeping the natural delivery."]}, "4552430d-9214-4d8c-b691-3007d9d0a38b": {"definition": "Synthesizer V is an AI-based singing (and speech) voice synthesis software developed by Dreamtonics that generates a sung vocal performance from user-entered notes and lyrics. It uses voice databases built from recordings of real singers, supports third-party voices, and can render some voices across Japanese, Mandarin, and English.", "plain_english": "Synthesizer V is a program that sings for you. You type the notes and words, pick a voice, and the software makes a realistic sung vocal without a real singer.", "purpose_function": "It exists to give producers a controllable virtual singer, so they can create finished or demo vocals without booking a vocalist. Users shape pitch, timing, and expression to make the performance sound natural.", "practical_application": "A songwriter enters a melody and lyrics in Synthesizer V, chooses a voice database, and edits phrasing and vibrato to produce a lead or backing vocal for a track.", "category": "AI Voice Processing", "related_terms": ["Singing voice synthesis (SVS)", "Voice model", "Singing voice conversion (SVC)", "Voice cloning"], "common_mistakes": ["Assuming exported vocals are free to use commercially, when the voices and libraries carry their own licensing terms.", "Expecting natural results with no editing, when note timing, pronunciation, and vibrato usually need adjustment.", "Confusing it with voice conversion; Synthesizer V generates singing from notes and lyrics rather than converting an existing recording."], "scenario_contexts": ["Producing a virtual lead vocal for an original song.", "Creating a guide vocal so a human singer can learn the melody and phrasing.", "Adding layered backing vocals using different voice databases."]}, "fc926911-0764-458f-88bc-ec8d85a1842b": {"definition": "The creation of a synthetic model of a specific person's voice from a limited set of their recordings, enabling new speech (or singing) to be generated in that voice. It typically pairs a speaker-identity representation with a text-to-speech or voice-conversion system so arbitrary content can be rendered in the cloned voice.", "plain_english": "Voice cloning learns how a certain person sounds from a few recordings, then makes new speech in that same voice. It is like taking a voice print and using it to say things the person never actually said.", "purpose_function": "It exists to reproduce a target person's voice on demand for dubbing, accessibility, and personalization, so content can be made without that person re-recording. The cloned voice can then speak any new script.", "practical_application": "A studio might clone an actor's voice to patch a few missing lines in post, or build a personal text-to-speech voice for someone who has lost the ability to speak.", "category": "AI Voice Processing", "related_terms": ["Voice conversion", "Voice model", "Singing voice synthesis (SVS)", "Speech-to-speech", "Voice-to-voice"], "common_mistakes": ["Confusing voice cloning with voice conversion: cloning builds a reusable voice model that can speak new text, while conversion transforms one existing recording.", "Assuming a good clone needs only a few seconds of audio, when quality usually improves with more clean, varied recordings.", "Cloning a person's voice without written consent, which can breach likeness and publicity rights and platform policies."], "scenario_contexts": ["Recreating a narrator's voice to fix mispronounced words after the talent has left.", "Building an accessibility voice for a person who is losing their speech.", "Generating localized voice-overs that keep a brand's signature voice."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"44878367-dcea-4bb9-8f59-2d6f620d7ef3": {"definition": "A speech-processing technique that transforms the perceived speaker identity of a recorded utterance so it sounds as if spoken by a different target speaker, while preserving the linguistic content and usually the prosody. It maps voice-timbre characteristics such as the spectral envelope, formants, and pitch statistics from the source onto the target using statistical or neural models.", "plain_english": "Voice conversion makes a recording of one person sound like someone else said it, but the words stay the same. It is like keeping the sentence and swapping the voice that speaks it.", "purpose_function": "It exists to change who a voice sounds like without re-recording, which enables anonymization, dubbing, accessibility voices, and creative production. It separates what is said from who says it, so the identity can be replaced on its own.", "practical_application": "A technician might use a voice-conversion model to anonymize a contributor in a broadcast interview, or to keep a character voice consistent across takes.", "category": "AI Voice Processing", "related_terms": ["Voice cloning", "Voice-to-voice", "Speech-to-speech", "Singing voice conversion (SVC)", "Voice model"], "common_mistakes": ["Confusing voice conversion with text-to-speech: conversion needs an existing speech recording as input, while text-to-speech starts from written text.", "Assuming it changes the words too, when it changes the voice identity but keeps the spoken content.", "Expecting high quality from very short or noisy target recordings, when too little clean target data degrades the result."], "scenario_contexts": ["Anonymizing a whistle-blower's voice in a news package while keeping their words intact.", "Dubbing so a replacement performer's lines match the original character's voice.", "Producing consistent pickup takes when the original talent is unavailable."]}, "44bb7b7d-0346-4e22-9d07-c281f82558eb": {"definition": "A trained representation that captures the vocal characteristics of a particular voice, such as timbre, spectral qualities, and often pitch behavior, so that voice can be synthesized or converted to. In neural voice systems it is the set of learned parameters, or the voice database, associated with one speaker or singer.", "plain_english": "A voice model is the saved recipe a computer learns for how one person sounds. Once trained, it lets software speak or sing in that voice.", "purpose_function": "It exists to store a voice's identity in reusable form, so a system can generate or convert audio into that voice on demand. Swapping the voice model swaps the voice.", "practical_application": "A producer downloads or trains a voice model for a specific singer, then loads it into a conversion or synthesis tool to render vocals in that voice.", "category": "AI Voice Processing", "related_terms": ["Voice cloning", "Voice conversion", "Singing voice conversion (SVC)", "Singing voice synthesis (SVS)", "Voice-to-voice"], "common_mistakes": ["Thinking a voice model stores actual recordings, when it stores learned parameters that describe how the voice sounds.", "Expecting one model to work in every tool, when models are usually tied to a specific framework or software version.", "Using or sharing a voice model of a real person without permission or licensing."], "scenario_contexts": ["Loading a trained singer voice model into an SVC tool to convert a guide vocal.", "Selecting a voice database (voice model) inside a singing-synthesis program.", "Managing a library of voice models for different characters in a production."]}, "1caf9807-0828-4281-ad6e-76f76327c638": {"definition": "A voice-conversion mode in which a spoken or sung input from one voice is transformed directly into the voice of a target speaker, preserving the words and delivery. It is functionally synonymous with voice conversion and contrasts with text-to-voice, where the input is written text.", "plain_english": "Voice-to-voice takes audio of one person talking and turns it into another person's voice, keeping the same words. The input is a voice and the output is a different voice.", "purpose_function": "It exists to change the speaker identity of an existing recording without going through text, which keeps natural timing and expression. It is used when you already have the audio and just want a different voice.", "practical_application": "A creator records a line themselves, then runs it voice-to-voice through a target model so it comes out in the desired character's voice.", "category": "AI Voice Processing", "related_terms": ["Voice conversion", "Speech-to-speech", "Voice model", "Voice cloning", "Singing voice conversion (SVC)"], "common_mistakes": ["Confusing voice-to-voice with text-to-speech: voice-to-voice needs recorded audio as input, not typed text.", "Assuming it rewrites the words, when it keeps the original spoken content and only changes the voice.", "Expecting clean output from noisy or clipped input, since poor source audio carries through."], "scenario_contexts": ["Turning a guide take into a character's voice for a game or animation.", "Letting one performer voice several characters through different target models.", "Restyling a rough voice-over into a chosen voice for a demo."]}, "200a631e-ede4-462a-a2b9-b33b1c746fe4": {"definition": "A neural speech-synthesis technique that reproduces a target speaker's vocal timbre and identity from only a few seconds of reference audio, with no retraining or fine-tuning of the model on that speaker. A separately trained speaker encoder extracts a fixed speaker embedding from the reference clip, and this embedding conditions a text-to-speech or voice-conversion model to generate new speech in that voice; 'zero-shot' means the target speaker was never present in the training data.", "plain_english": "It is a way for a computer to copy a person's voice after hearing only a few seconds of them talk. The system does not have to be trained on that person first. It listens to a short clip, learns what makes the voice sound unique, then speaks new words in that same voice. It works like a mimic who can copy a stranger after one quick listen.", "purpose_function": "It lets a system produce speech in a new person's voice almost instantly, avoiding the large per-speaker datasets and model retraining that older voice-cloning methods require. This makes personalized text-to-speech, dubbing, and voice restoration practical at scale.", "practical_application": "A post or content technician can feed a short voice sample to a zero-shot cloning tool to generate ADR, pickup lines, narration, or localized dialogue in a chosen speaker's voice, and should confirm consent and likeness rights before using or delivering the result.", "category": "AI Voice Synthesis", "related_terms": ["Text-to-speech", "Voice conversion", "Speaker embedding", "Speech synthesis", "Audio deepfake"], "common_mistakes": ["Assuming 'zero-shot' means no training at all — the underlying model is heavily pre-trained on many speakers; only the specific target speaker was unseen.", "Confusing zero-shot cloning with fine-tuned cloning, which adapts the model on minutes of a speaker's audio for higher fidelity.", "Expecting a clone from a few seconds of audio to match full studio-quality fidelity, when short references limit prosody, accent, and expressiveness.", "Ignoring consent and likeness/publicity rights — cloning a real person's voice without permission can be unlawful and unethical."], "scenario_contexts": ["Generating ADR or pickup dialogue in an actor's voice during post-production when reshoots or re-records are not possible.", "Localizing or dubbing content into other languages while preserving the original speaker's vocal identity.", "Restoring a personalized synthetic voice for someone who has lost their speech, built from a short archived recording.", "Building conversational voice agents or narration that speak in a chosen presenter or brand voice."]}, "e08e091b-3495-4baa-bf65-1cb032538d72": {"definition": "A tonal descriptor for sound with a hard, forward, edgy character, typically from emphasized upper-midrange and presence energy (roughly 2-6 kHz) that pushes the sound toward the listener and can feel harsh at high levels.", "plain_english": "An aggressive sound is loud and in-your-face. It has a hard, biting edge in the upper-middle tones. It feels like the sound is pushing right at you.", "purpose_function": "It lets engineers describe a forward, in-your-face tone so they can decide whether to tame or add upper-mid and presence energy for the style of music.", "practical_application": "A mix engineer might call a rock vocal or guitar aggressive and cut a few dB around 2-5 kHz to soften it, or boost there when a part needs more bite.", "category": "Tonal Descriptor", "related_terms": ["Bright", "Brittle", "harsh", "presence", "edgy"], "common_mistakes": ["Confusing aggressive with simply loud; it is a spectral quality (a hard upper-mid and presence edge), not just high volume.", "Assuming aggressive always means bad, when many rock and metal tones are meant to sound aggressive.", "Trying to fix an aggressive tone with only a volume cut instead of EQ in the 2-6 kHz range."], "scenario_contexts": ["Describing a distorted electric guitar that cuts hard through a rock mix.", "A lead vocal that sounds forward and edgy and needs presence-range EQ.", "Comparing two synth patches where one is smooth and the other is aggressive and biting."]}, "c6de6eb2-f7d1-4327-9af2-68a1e4ab0cce": {"definition": "A tonal descriptor for sound with a strong sense of openness and space, produced by extended, smooth high-frequency response in the upper treble (roughly above 12-15 kHz), giving the impression of air around instruments and voices.", "plain_english": "An airy sound feels open and spacious. It has clear, gentle high notes at the very top of hearing. It is like the sense of air around a singer in a big, bright room.", "purpose_function": "It lets engineers describe pleasant top-end openness so they can decide whether a track needs a gentle high-shelf lift to add that sense of air.", "practical_application": "An engineer may add a broad high-shelf boost above 10 kHz to vocals or acoustic guitar to make them airy, or choose a condenser mic known for an airy top end.", "category": "Tonal Descriptor", "related_terms": ["Bright", "open", "presence", "high shelf", "sparkle"], "common_mistakes": ["Confusing airy with bright; airy is very-high-frequency openness and space, while bright emphasizes the lower treble and presence.", "Over-boosting the extreme highs to force air, which also raises hiss and sibilance.", "Expecting cheap or band-limited gear to reproduce air it cannot actually pass."], "scenario_contexts": ["Describing a well-recorded vocal with an open, spacious top end.", "Choosing a condenser microphone for its airy high-frequency character.", "Adding a high-shelf boost to make an acoustic guitar sound more airy in a mix."]}, "cf3ce6fc-22f9-48f2-aea9-636d3c0e6381": {"definition": "A tonal descriptor for sound that is thin and weak, lacking low-frequency weight, body, and fullness, so the fundamental range feels deficient and the overall tone seems underpowered.", "plain_english": "An anemic sound is thin and weak. It has almost no low-end weight or body. It is like a song played through tiny phone speakers, where the notes feel small and drained of power.", "purpose_function": "It flags a lack of low-end and body so an engineer knows the sound needs more weight, whether from EQ, mic choice, or the arrangement.", "practical_application": "If a bass or kick sounds anemic, the engineer may boost the low end, pick a fuller mic or DI, or thin out competing parts so the fundamentals come through.", "category": "Tonal Descriptor", "related_terms": ["thin", "Brittle", "warmth", "body", "boomy"], "common_mistakes": ["Assuming anemic means quiet; it describes a lack of low-end weight and body, not simply low volume.", "Fixing anemic tone with heavy deep-bass boost that causes boominess instead of adding useful body around 100-300 Hz.", "Blaming the source when a thin cable, mic, or high-pass filter is removing the low end."], "scenario_contexts": ["A kick drum that lacks punch and weight in the mix.", "A vocal that sounds thin and small on a small-diaphragm mic.", "A guitar amp tone that feels underpowered and needs more body."]}, "8759a1b0-3f55-42be-a4ae-3d6660eccb44": {"definition": "A tonal descriptor for a harsh, honking, horn-like coloration caused by a peaky emphasis in the midrange (roughly 500 Hz-1 kHz), which makes voices or instruments sound as if they are shouting or barking.", "plain_english": "A barky sound has a honking, shouty middle tone. It sounds a bit like a dog's bark or someone yelling through a cupped hand. It comes from too much energy in the middle frequencies.", "purpose_function": "It points to an unpleasant mid honk so the engineer knows to hunt around 500 Hz-1 kHz for a resonant peak to cut.", "practical_application": "When a vocal, sax, or guitar sounds barky, an engineer sweeps a narrow EQ boost to find the offending mid peak, then cuts it a few dB to smooth the tone.", "category": "Tonal Descriptor", "related_terms": ["Boxy", "nasal", "honky", "harsh", "midrange"], "common_mistakes": ["Confusing barky with boxy; the barky honk sits higher (around 500 Hz-1 kHz) while boxy sits lower (around 300-600 Hz).", "Cutting broadly across the whole midrange and hollowing out the tone instead of notching the single resonant peak.", "Overlooking that room reflections or a cupped mic technique can create the barky coloration."], "scenario_contexts": ["A brass or reed instrument that honks harshly in a live mix.", "A vocalist who cups the microphone and produces a barky, shouty tone.", "Tuning out a mid resonance on a guitar cabinet that sounds barky."]}, "15fedb45-caee-413a-8028-edb240801128": {"definition": "An informal tonal descriptor for sound that is muffled and dull, as if covered by a cloth, because the high frequencies are strongly reduced, leaving the tone lacking clarity and detail.", "plain_english": "Sound that is behind a blanket is muffled and unclear. The bright, detailed high notes are missing. It is like listening to music with a thick blanket thrown over the speaker.", "purpose_function": "The phrase quickly tells everyone the top end is missing, so an engineer knows to look for lost high frequencies from EQ, a bad mic, or an obstruction.", "practical_application": "If a mix sounds like it is behind a blanket, the engineer checks for an accidental high cut, a covered or off-axis mic, or a dull monitor, then restores the highs.", "category": "Tonal Descriptor", "related_terms": ["dull", "dark", "muffled", "blanket over the speakers", "Bright"], "common_mistakes": ["Assuming the source is bad when a covered mic, closed monitor, or engaged low-pass filter is removing the highs.", "Boosting extreme treble to compensate and adding hiss instead of finding why the highs are gone.", "Confusing a muffled behind-a-blanket tone with a simple low volume level."], "scenario_contexts": ["A recording that sounds dull because a mic was pointed away from the source.", "Checking a PA that suddenly sounds muffled, as if behind a blanket, after a setting change.", "Describing playback from a phone left inside a pocket."]}, "f129fe6d-f9aa-408a-8232-a0f199720792": {"definition": "An informal tonal descriptor for a dull, muffled sound with noticeably reduced high-frequency content, as though a blanket were draped over the loudspeakers, robbing the sound of brightness and detail.", "plain_english": "A blanket over the speakers means the sound is muffled and dull. The crisp high notes are gone. It sounds just like it would if you laid a thick blanket right over your speakers.", "purpose_function": "The phrase signals a clear loss of highs so the engineer knows to check for rolled-off treble in the signal chain, the speakers, or the room.", "practical_application": "Hearing this complaint, a technician checks for a blown tweeter, a wrong EQ or filter setting, speaker covers left on, or heavy drapes and absorption killing the highs.", "category": "Tonal Descriptor", "related_terms": ["dull", "dark", "muffled", "behind a blanket", "Bright"], "common_mistakes": ["Overlooking a blown or disconnected tweeter as the cause of the sudden loss of highs.", "Blaming the mix when the room's heavy curtains and absorption are removing the top end.", "Confusing a muffled tone with an out-of-phase speaker pair, which thins the sound differently."], "scenario_contexts": ["A club PA that sounds dull because a tweeter has failed.", "A studio monitor with its protective grille cloth or cover left on.", "Describing a room so heavily treated with absorption that it deadens the highs."]}, "62763c20-8f05-470b-aa07-19c217ff0817": {"definition": "A tonal descriptor for a hollow, resonant coloration centered in the lower midrange (roughly 300-600 Hz), which makes a sound resemble the tone of speaking or playing inside a small box or closet.", "plain_english": "A boxy sound is hollow, like it is coming from inside a cardboard box. It has too much of a certain low-middle tone. Think of how your voice sounds inside an empty box.", "purpose_function": "It identifies an unwanted lower-mid buildup so the engineer knows to cut around 300-600 Hz to open up and clarify the sound.", "practical_application": "When drums, guitars, or a room mic sound boxy, the engineer notches a few dB around 400 Hz, or treats reflections from a small tracking room that add the coloration.", "category": "Tonal Descriptor", "related_terms": ["muddy", "nasal", "barky", "hollow", "midrange"], "common_mistakes": ["Confusing boxy (around 300-600 Hz) with muddy, which sits lower, around 100-250 Hz.", "Cutting too wide and thinning the body instead of notching the specific resonant frequency.", "Ignoring that a small, untreated recording room often adds the boxy coloration."], "scenario_contexts": ["A snare or tom recorded in a small room that sounds hollow and boxy.", "A vocal tracked in a closet with a strong lower-mid resonance.", "An acoustic guitar with a boxy body resonance that needs an EQ notch."]}, "e4ea0368-6604-4336-a1ef-5cc7c20b3640": {"definition": "A tonal descriptor for sound with emphasized high-frequency content (roughly above 5 kHz), giving a crisp, present, detailed character; excessive brightness can tip into harshness.", "plain_english": "A bright sound has strong, crisp high notes. It sounds clear, sharp, and full of detail. It is the opposite of dull, like the sparkle of cymbals or crisp new speakers.", "purpose_function": "It describes how much high-frequency emphasis a sound has so engineers can match the tone to the music and keep it from turning harsh.", "practical_application": "An engineer may call a mic or mix bright and add or reduce a high shelf to suit the material, or pick a brighter mic to help a dull source cut through.", "category": "Tonal Descriptor", "related_terms": ["Airy", "Brittle", "dull", "presence", "harsh"], "common_mistakes": ["Assuming brighter is always better, when too much high end becomes harsh and tiring.", "Confusing bright with loud; brightness is a high-frequency balance, not overall level.", "Judging brightness on one dull or hyped speaker instead of trusted, calibrated monitors."], "scenario_contexts": ["Describing cymbals and hi-hats that sound crisp and detailed.", "Choosing a brighter microphone to help a dull vocal cut through a mix.", "Comparing two speakers where one sounds noticeably brighter than the other."]}, "8da6df45-cdfe-48c7-83ca-fa10ec430827": {"definition": "A tonal descriptor for a thin, harsh high-frequency character that lacks supporting low-end and body, so the treble sounds glassy and fragile and seems ready to break up, often from excessive or peaky high-frequency emphasis.", "plain_english": "A brittle sound is thin and harsh up high, with no warmth underneath. The high notes sound glassy and sharp, like thin glass about to crack. It can be tiring to hear.", "purpose_function": "It flags harsh, unsupported highs so an engineer knows to reduce peaky treble or add low-mid body to balance the tone.", "practical_application": "If a cymbal or vocal sounds brittle, the engineer may cut a sharp high-frequency peak, add warmth lower down, or swap a harsh-sounding mic or converter.", "category": "Tonal Descriptor", "related_terms": ["Bright", "harsh", "thin", "sibilance", "Airy"], "common_mistakes": ["Confusing brittle with bright; bright is pleasant crisp detail, while brittle is thin, harsh, and fatiguing.", "Fixing brittleness only by cutting highs when adding low-mid body may balance the tone better.", "Overlooking cheap converters, clipping, or heavy compression as a cause of a brittle top end."], "scenario_contexts": ["A cheap cymbal recording that sounds glassy and harsh.", "A vocal that becomes brittle after heavy high-frequency EQ boosting.", "Comparing a warm analog chain against a harsh, brittle digital one."]}, "f6861a0d-eb06-419c-b943-689911e7091e": {"definition": "A mix descriptor for an instrument or vocal that sits too low in level, or is masked by competing sounds, so it loses its intended presence and detail and is hard to pick out in the mix.", "plain_english": "Buried means a sound is too quiet in the mix, so louder parts cover it up. It is like a voice you can barely hear in a noisy, crowded room.", "purpose_function": "It flags a level or masking problem so the engineer knows an element needs more level, EQ carving, or arrangement space to be heard clearly.", "practical_application": "When a client says the lead vocal is buried, the engineer raises its fader, cuts competing frequencies in other tracks, or thins the arrangement so the vocal comes forward.", "category": "Tonal Descriptor", "related_terms": ["masking", "presence", "muddy", "mix balance", "fader"], "common_mistakes": ["Assuming a buried part just needs more of its own level, when cutting masking frequencies on other tracks often works better.", "Confusing buried with quiet; an element can be loud yet still buried under competing sounds in the same frequency range.", "Solving a buried vocal by pushing it far above everything else, which unbalances the whole mix."], "scenario_contexts": ["A lead vocal lost under dense guitars that the singer cannot hear back in the monitors.", "A bass line that disappears behind kick and rhythm guitar in a rock mix.", "A backing part masked by louder elements sharing the same frequency band."]}, "725f5ecc-f34d-48c9-8304-a0c905873eee": {"definition": "A subjective tonal descriptor for a sound that is smooth, rich, and pleasingly warm, with no harshness in the upper mids or highs, often applied to saxophone, vocals, or well-rounded analog tone.", "plain_english": "Buttery describes a smooth, rich sound with no harsh edges. It feels soft and pleasing, like the way warm butter melts smoothly.", "purpose_function": "It gives engineers a shorthand for a desirable smoothness so they can aim for it through mic choice, gentle EQ, or mild saturation.", "practical_application": "A player may ask for a buttery sax tone, so the engineer picks a warm-sounding mic and softens any harsh edge around 2-5 kHz.", "category": "Tonal Descriptor", "related_terms": ["warmth", "smooth", "creamy", "harsh", "presence"], "common_mistakes": ["Treating buttery as a measurable spec rather than a subjective quality of smoothness and warmth.", "Chasing a buttery tone by rolling off so much top end that the sound turns dull and lifeless.", "Assuming any warm source is buttery, when a harsh upper-mid peak can ruin the smoothness."], "scenario_contexts": ["Describing a smooth, rich saxophone or a mellow jazz guitar tone.", "A vocal captured on a warm ribbon or tube mic that sounds silky and smooth.", "Adding gentle analog-style saturation to make a synth pad feel buttery."]}, "3d852803-5ba0-4a5d-9ec2-e3beac5c5468": {"definition": "A negative tonal descriptor for a dull, boxy, lifeless sound with a hollow lower-midrange emphasis (roughly 300-600 Hz) and weak lows and highs, resembling the thud of tapping an empty cardboard box.", "plain_english": "Cardboardy means a dull, boxy sound with no life or sparkle. It sounds a bit like knocking on an empty cardboard box.", "purpose_function": "It flags an unwanted boxy midrange buildup and a lack of extension so the tone can be fixed with EQ or a better capture.", "practical_application": "A close-miked tom might sound cardboardy, so the engineer cuts a few dB around 400 Hz and adds some high end to restore snap and life.", "category": "Tonal Descriptor", "related_terms": ["Boxy", "dull", "hollow", "muddy", "midrange"], "common_mistakes": ["Confusing cardboardy with simply dull; cardboardy also carries a hollow, boxy lower-mid coloration.", "Cutting broadly across the mids and hollowing the sound further instead of notching the boxy resonance.", "Blaming the source when a small untreated room adds the boxy, cardboardy coloration."], "scenario_contexts": ["A tom or snare recorded in a small room that sounds dull and boxy.", "A cheap acoustic guitar with a lifeless, cardboard-like body tone.", "A speaker or cabinet with a hollow midrange that robs the sound of life."]}, "3bf408ec-cf20-4a5c-bf6a-ae8d3079fdda": {"definition": "A tonal descriptor, usually for voice, for an excess of lower-midrange energy (roughly 150-400 Hz) that adds a boomy, thick chest resonance, making the sound heavy, congested, or overly full.", "plain_english": "Chesty means a voice has too much low, boomy weight. It sounds heavy and thick, like a deep sound rumbling up from someone's chest.", "purpose_function": "It pinpoints an over-full low-mid region so the engineer can thin it out and restore clarity to a voice or instrument.", "practical_application": "A vocal recorded very close to the mic often sounds chesty from proximity effect, so the engineer cuts a few dB around 200-300 Hz or backs the singer off the mic.", "category": "Tonal Descriptor", "related_terms": ["boomy", "proximity effect", "muddy", "warmth", "low mids"], "common_mistakes": ["Confusing chesty with warm; warmth is pleasant body, while chesty is an excess that congests the tone.", "Fixing a chesty vocal with a broad low cut that also removes needed body and weight.", "Overlooking proximity effect from close mic technique as the cause of the boomy chest tone."], "scenario_contexts": ["A close-miked vocal that booms in the lower mids from proximity effect.", "A deep speaking voice that sounds thick and congested on a large-diaphragm mic.", "A male vocal that needs a low-mid cut to sit clearly in a dense mix."]}, "41e0e5b3-4afb-479f-99b0-e9820aa245c0": {"definition": "A tonal descriptor for a thick, punchy, powerful sound with strong low-mid weight and a tight, percussive character, commonly applied to distorted rhythm guitars and aggressive drum or bass tones.", "plain_english": "Chunky means a thick, punchy, powerful sound with lots of weight. Think of the solid crunch of a heavy rhythm guitar riff.", "purpose_function": "It describes a full, aggressive body that producers often want in rock and metal rhythm parts, guiding EQ, gain, and playing choices.", "practical_application": "To make a rhythm guitar chunky, the engineer tightens the low end, supports the low mids, and pairs palm-muted playing with controlled distortion.", "category": "Tonal Descriptor", "related_terms": ["punchy", "fat", "tight", "low mids", "crunch"], "common_mistakes": ["Adding more gain and distortion to sound chunky, when too much gain actually loosens and blurs the tone.", "Piling on low end so the part turns muddy instead of tight and chunky.", "Confusing chunky with simply loud; it is a thick, tight spectral character, not just volume."], "scenario_contexts": ["Dialing in a palm-muted metal rhythm guitar with a thick, tight crunch.", "Shaping a kick and bass pairing that feels solid and powerful.", "Comparing two amp settings where one sounds thin and the other chunky."]}, "5f7a5319-3d68-4647-b15d-e8a1395804ab": {"definition": "A descriptor for a signal or sound that is free of distortion, noise, and unwanted artifacts and is reproduced accurately with clear detail; also used for an undistorted, non-overdriven instrument or amplifier tone.", "plain_english": "Clean means a sound with no distortion, hum, or noise added. It is clear and pure, like looking through a clear window with no smudges.", "purpose_function": "It sets a reference for an accurate, artifact-free signal path, and also names a guitar or amp tone that has no overdrive.", "practical_application": "An engineer keeps a recording clean by setting gain to avoid clipping and noise, while a guitarist may select a clean amp channel for quiet passages.", "category": "Tonal Descriptor", "related_terms": ["distortion", "noise", "headroom", "clipping", "transparent"], "common_mistakes": ["UNSAFE: Pushing an amp or preamp into hard clipping to sound louder, which can overheat and damage tweeters and drivers.", "Confusing clean with sterile; a clean signal can still be warm and musical.", "Setting gain so low to stay clean that noise floor and hiss become audible."], "scenario_contexts": ["Setting preamp gain to capture a clean, undistorted vocal take.", "Selecting a clean amp channel for a soft, undistorted guitar part.", "Checking a signal chain for a clean path free of hum and noise."]}, "a4e095e6-740c-48c8-85b4-aba31ca36cf6": {"definition": "A mixing instruction to reduce muddiness and buildup in the low-midrange band (roughly 200-500 Hz), usually with EQ cuts, so the mix sounds clearer, tighter, and less congested.", "plain_english": "This means using EQ to cut extra mud in the low-middle frequencies. It clears out a crowded, boomy area so the whole mix sounds cleaner.", "purpose_function": "Many instruments pile energy into the low mids and mask each other there, so cutting in that band restores clarity and separation.", "practical_application": "An engineer might cut a few dB around 250-400 Hz on guitars, keys, and other layered parts so the mix stops sounding muddy and boxy.", "category": "Tonal Descriptor", "related_terms": ["muddy", "low mids", "EQ", "masking", "Boxy"], "common_mistakes": ["Cutting the low mids on every track so the mix loses warmth and body instead of just clearing masking.", "Using a wide, deep cut where a narrower notch on the worst offenders would keep more body.", "Confusing low-mid mud (around 200-500 Hz) with sub-bass boom much lower in the spectrum."], "scenario_contexts": ["A dense mix where stacked guitars and keys sound muddy in the low mids.", "Carving space so kick, bass, and low instruments stop fighting each other.", "Tidying a boomy live mix by cutting low-mid buildup on several channels."]}, "4c152b94-50bd-47d8-89a9-706a3b9b3619": {"definition": "A tonal descriptor for a sound with a pronounced high-frequency attack transient that produces an audible click, such as the beater click of a kick drum or the pick and fret noise on a bass.", "plain_english": "Clicky means a sound has a sharp, ticking snap at the very start. It is like the hard click you hear when a drum pedal hits the kick.", "purpose_function": "It names an emphasized attack transient so an engineer can boost it for definition and punch, or tame it when it is too harsh.", "practical_application": "For a kick to cut through a dense mix, an engineer boosts the beater click around 2-4 kHz; if the kick is too clicky, they cut in that range instead.", "category": "Tonal Descriptor", "related_terms": ["attack", "transient", "punchy", "presence", "beater"], "common_mistakes": ["Confusing clicky with bright; clicky is a sharp attack transient, while bright is a broad high-frequency balance.", "Boosting the click so hard the kick sounds like a typewriter with no body underneath.", "Overlooking the beater type or trigger sample as the real source of an overly clicky kick."], "scenario_contexts": ["Adding attack to a kick drum so it cuts through a loud rock mix.", "Taming a bass DI that has too much pick and fret click.", "Describing an electronic kick sample with a sharp, ticking front end."]}, "740c7536-ed0f-467f-af40-49be75077d2f": {"definition": "A subjective tonal descriptor for a sound that is technically accurate and highly detailed but cold, sterile, and lacking warmth, emotion, or musical character.", "plain_english": "Clinical means a sound is very clean and exact but feels cold and lifeless. It is correct but has no warmth, like a bare, white hospital room.", "purpose_function": "It warns that precision alone can feel emotionless, prompting an engineer to add warmth or character so the sound feels more musical.", "practical_application": "A mix that sounds clinical might get gentle analog-style saturation or harmonic coloring to feel warmer and more engaging.", "category": "Tonal Descriptor", "related_terms": ["sterile", "clean", "warmth", "transparent", "saturation"], "common_mistakes": ["Assuming clinical means high quality; accuracy without warmth can still sound cold and unmusical.", "Confusing clinical with clean; clean simply lacks distortion, while clinical also lacks warmth and character.", "Trying to warm a clinical mix with heavy EQ alone instead of subtle harmonic saturation."], "scenario_contexts": ["A very accurate digital mix that sounds cold and needs analog-style warmth.", "Comparing a sterile converter or plugin chain against a warmer analog one.", "Describing studio monitors that reveal every detail but feel emotionally flat."]}, "6cc2a3fc-dbfb-4e37-b5f6-1969e59f241f": {"definition": "A subjective timbral descriptor for sound that seems restricted in the high frequencies and lacking openness or air, as if the upper treble has been rolled off or the source is enclosed; the opposite of open or airy.", "plain_english": "A closed-in sound feels shut off at the top, like music playing with a blanket over the speakers. The bright, airy high notes are missing, so it seems dull and boxed in.", "purpose_function": "It gives engineers a shared word for a lack of high-frequency openness, pointing to where treble or air is missing so the problem can be diagnosed and corrected.", "practical_application": "Hearing a closed-in mix, a technician checks for rolled-off highs, a dull microphone, or heavy room absorption, then adds gentle high-shelf or air-band EQ to open it up.", "category": "Timbre descriptor", "related_terms": ["dull", "dark", "airy", "open", "muffled", "boxy"], "common_mistakes": ["Confusing closed-in with dark; closed-in stresses a lack of air and openness at the very top, not just weak treble overall", "Boosting a broad treble band and adding harshness instead of a narrow lift of the top air region", "Blaming the source when an absorptive or over-damped room is dulling the highs"], "scenario_contexts": ["A vocal recorded with a dynamic mic aimed off-axis sounds closed-in and needs high-shelf lift", "Playback in a heavily treated, over-damped room feels closed-in compared with a livelier space", "A tape or lossy digital copy loses top-end air and is described as closed-in"]}, "c1b7621e-93a4-4138-b640-07e19b75e63b": {"definition": "A subjective descriptor for a mix or sound in which too many competing elements or frequencies crowd the same space and mask one another, so individual parts lose clarity and definition.", "plain_english": "A cluttered mix is like a room where everyone talks at once. So many sounds pile into the same space that you can't clearly pick out any single one.", "purpose_function": "It labels a loss of clarity caused by crowding, helping engineers spot masking and decide what to thin out, pan, or EQ so parts can separate.", "practical_application": "When a mix sounds cluttered, a technician carves competing instruments with EQ, pans them apart, or mutes parts to open up space and restore clarity.", "category": "Timbre descriptor", "related_terms": ["congested", "muddy", "masking", "busy", "dense", "separation"], "common_mistakes": ["Confusing cluttered with simply loud; a quiet mix can still be cluttered when parts fight for the same frequencies", "Trying to fix clutter by raising levels, which usually deepens the masking", "Assuming clutter is only about the number of tracks rather than overlapping frequency ranges"], "scenario_contexts": ["A dense arrangement with several guitars and keys all in the midrange sounds cluttered", "A live mix where every channel is wide open competes for space and turns cluttered", "Layered synths occupying the same octave blur together until parts are EQ-carved"]}, "ed1ce59a-95c6-45c7-80d5-d4b05261d566": {"definition": "A subjective timbral descriptor for sound weighted toward the upper mids and highs with weak low-mid warmth, giving a clinical, analytical, or emotionally distant character; the opposite of warm.", "plain_english": "A cold sound is thin and clinical, like harsh office lighting instead of a cozy lamp. It has plenty of treble but little of the warm lower-middle body that makes music feel inviting.", "purpose_function": "It gives engineers a word for tone that lacks warmth and lower-mid body, flagging when a source or system feels sterile so warmth can be restored.", "practical_application": "If a track sounds cold, a technician may add low-mid EQ, choose a warmer mic or preamp, or use gentle saturation to bring back body and warmth.", "category": "Timbre descriptor", "related_terms": ["warm", "clinical", "thin", "bright", "sterile", "harsh"], "common_mistakes": ["Treating cold as the same as bright; a sound can be bright yet still warm, while cold specifically lacks low-mid body", "Adding broad treble to fix coldness, which makes it thinner rather than warmer", "Assuming cold is always a fault, when a clean, analytical tone is sometimes the goal"], "scenario_contexts": ["A digital recording with scooped low-mids is described as cold compared with an analog version", "A condenser mic with a rising top and lean lower mids sounds cold on a solo voice", "A room or monitor with little low-mid support makes mixes feel cold"]}, "07a22ef9-9089-43d5-84cc-a527a527b7d3": {"definition": "A descriptor for reproduction that departs from flat, neutral response by adding its own tonal character through frequency-response deviations, resonances, or harmonic distortion, so it audibly colors the sound rather than passing it unchanged.", "plain_english": "Colored sound has the gear's own flavor added on top, like a photo run through a filter. Instead of hearing the source exactly as it was, you hear it tinted by the equipment.", "purpose_function": "The term separates neutral, accurate reproduction from gear that imposes character, letting engineers judge whether coloration is a fault to avoid or an effect to use on purpose.", "practical_application": "A technician labels a mic, preamp, or speaker as colored when it stresses certain bands, then either picks a flatter tool for accuracy or uses the coloration deliberately for tone.", "category": "Timbre descriptor", "related_terms": ["coloration", "neutral", "transparent", "resonance", "harmonic distortion", "flat"], "common_mistakes": ["Assuming colored always means bad; many prized mics and preamps are valued precisely for pleasant coloration", "Confusing coloration with simple volume change rather than a tonal-balance or distortion change", "Blaming a source for coloration that is actually coming from the room or monitors"], "scenario_contexts": ["A vintage ribbon mic colors a voice with a warm, rolled-off top", "A resonant room adds coloration heard as peaks and dips on pink noise", "A saturating tube preamp is chosen to color a clean DI bass"]}, "1b733574-4b79-461f-924d-8d86d1481d2b": {"definition": "A subjective descriptor for sound, usually in the low-mids and midrange, that seems crammed and lacking space, where dense energy blurs together and reduces clarity and separation; closely related to cluttered but stressing a thick, stuffy quality.", "plain_english": "A congested sound feels stuffed and stuffy, like a blocked nose. The middle of the sound is so packed that notes smear together and lose their edges.", "purpose_function": "It names a thick, crowded midrange so engineers can target the buildup and thin it out, restoring space and definition to the sound.", "practical_application": "Facing a congested mix, a technician cuts low-mid buildup with EQ, uses high-pass filters on non-bass tracks, and creates space so parts breathe.", "category": "Timbre descriptor", "related_terms": ["cluttered", "muddy", "boxy", "masking", "dense", "separation"], "common_mistakes": ["Confusing congested with muddy; congestion is about crowding and lack of space, while mud is a specific low-mid tonal excess", "Cutting the wrong band and thinning the mix instead of clearing the crowded low-mids", "Adding compression to fix congestion, which can squeeze parts closer together and worsen it"], "scenario_contexts": ["A mix where kick, bass, and low guitars pile up in the low-mids sounds congested", "A full arrangement with no high-pass filtering builds congestion in the lower midrange", "Heavy reverb on many tracks fills the space and leaves the mix congested"]}, "e207ddd6-c957-42ff-a4ae-df326bf4ffe5": {"definition": "A subjective descriptor for a smooth, rich, pleasing tone free of harshness, often applied to a warm, full midrange or to smooth, well-blended overdrive or saturation.", "plain_english": "A creamy tone is smooth and rich, like melted ice cream instead of something sharp and scratchy. It sounds full and easy on the ears, with no harsh edges.", "purpose_function": "It gives engineers a word for smooth, pleasing richness, describing a target tone that flatters warmth and softens harsh edges.", "practical_application": "A technician chasing a creamy sound may pick a smooth-saturating amp or preamp, tame harsh upper mids, and use gentle compression to round the tone.", "category": "Timbre descriptor", "related_terms": ["smooth", "warm", "silky", "harsh", "saturation", "round"], "common_mistakes": ["Confusing creamy with muddy; creamy stays clear and smooth, while muddy loses definition", "Over-saturating in search of creaminess until the tone turns fuzzy or lifeless", "Assuming creamy means dull; a creamy tone can still have detail, just without harshness"], "scenario_contexts": ["A mildly overdriven tube guitar amp is prized for a creamy lead tone", "Smooth analog-style compression gives a vocal a creamy, rounded character", "A saxophone through a warm ribbon mic is described as creamy"]}, "7ec5dd6f-9c6c-499f-bfe4-d9340748180b": {"definition": "A subjective descriptor for clean, clear, well-defined high-frequency detail and sharp transient response, giving articulate, precise sound without harshness.", "plain_english": "A crisp sound has clear, sharp detail up top, like a fresh, snappy photo that is in focus. Fast sounds such as cymbals and picked strings come through clean and well defined.", "purpose_function": "It names clear high-end detail and sharp transients, describing a target for clarity and articulation that engineers aim for without tipping into harshness.", "practical_application": "To make a mix crisp, a technician adds tasteful high-frequency EQ, tightens transients, and keeps the top end clean so detail reads clearly.", "category": "Timbre descriptor", "related_terms": ["bright", "airy", "harsh", "transient", "articulate", "dull"], "common_mistakes": ["Confusing crisp with harsh; crisp is clean and detailed, while harsh is aggressive and fatiguing", "Over-boosting treble to force crispness and adding sibilance or hiss instead", "Thinking crispness is only EQ, when clean transients and low distortion matter just as much"], "scenario_contexts": ["A well-recorded acoustic guitar with clear pick detail is called crisp", "Adding a gentle high shelf makes a drum overhead track sound crisp", "A hi-hat with clean, defined top end reads as crisp in the mix"]}, "d0eca9a2-59cd-4541-b6d0-02f8368e370f": {"definition": "A subjective descriptor for a gritty, moderately distorted tone with an aggressive, textured character, such as an overdriven guitar amp or light clipping, sitting between a clean sound and heavy saturation.", "plain_english": "A crunchy tone is gritty and rough on purpose, like biting into a crunchy snack. It is the growling, textured sound of a guitar amp turned up until it just starts to break up.", "purpose_function": "It names a controlled, gritty distortion so engineers and players can aim for that textured character without pushing into full, mushy overdrive.", "practical_application": "To get a crunchy guitar tone, a technician sets an amp or overdrive pedal to the edge of breakup, balancing grit and note clarity.", "category": "Timbre descriptor", "related_terms": ["overdrive", "distortion", "gritty", "saturation", "clean", "fuzzy"], "common_mistakes": ["Confusing crunch with heavy distortion; crunch keeps note definition, while heavy gain smears it", "Adding too much gain and losing the tight, gritty texture that defines crunch", "Assuming crunch comes only from pedals, when amp breakup and speaker choice shape it too"], "scenario_contexts": ["A rock rhythm guitar set to the edge of amp breakup gives a crunchy tone", "An overdrive pedal adds crunch to a clean amp for a driving part", "Light clipping on a drum bus is described as crunchy"]}, "e3d103de-fa47-4eb7-8bea-1d883aed5fe8": {"definition": "A subjective descriptor for a hollow, honky midrange coloration resembling the sound of speaking through cupped hands, caused by a mid-frequency peak with reduced presence and openness; often heard when a vocalist cups a hand around a microphone's grille.", "plain_english": "A cupped sound is hollow and honky, like talking with your hands cupped around your mouth. It has a boxy middle and loses its clear, open top end.", "purpose_function": "It names a specific hollow, mid-boosted coloration so engineers can recognize its cause, often hand-cupping of a mic, and fix the tone or feedback it creates.", "practical_application": "Hearing a cupped vocal, a technician asks the singer not to cup the mic grille, since cupping raises feedback risk and adds a boxy, honky coloration.", "category": "Timbre descriptor", "related_terms": ["boxy", "honky", "coloration", "nasal", "feedback", "hollow"], "common_mistakes": ["Assuming a cupped tone is only an EQ issue when it is often caused by a hand cupped over the mic grille", "Confusing cupped with nasal; cupped is a hollow, boxy hand-cup coloration, while nasal is a pinched upper-mid honk", "UNSAFE: Cupping a handheld mic to boost low end greatly raises feedback risk and can trigger sudden loud howl-round through the PA"], "scenario_contexts": ["A performer wraps a hand around the mic ball and the vocal turns cupped and honky", "A directional mic loses its rear rejection when cupped, so feedback rises on stage", "A boxy midrange peak on a recording is described as sounding cupped"]}, "01654852-4423-4c55-9a0f-0b8c5516bfc6": {"definition": "A timbral descriptor for sound with reduced high-frequency energy and a relative emphasis on low and low-mid frequencies, giving a subdued, mellow, or closed tonal character.", "plain_english": "A dark sound has few high notes and more low ones. It sounds soft and warm, a bit like music heard through a closed door.", "purpose_function": "Provides a shared shorthand for tonal balance so engineers can quickly agree that a source or mix leans toward the low end and lacks treble.", "practical_application": "An engineer may call a mic or mix dark and then add high-frequency EQ or choose a brighter mic to open it up.", "category": "Tonal Balance", "related_terms": ["Bright", "Warm", "dull", "Muddy", "Boomy"], "common_mistakes": ["Confusing 'dark' with 'dull' — dark describes a mellow tonal balance while dull implies missing detail or clarity", "Treating dark as a fault when many sources and mixes are meant to sound dark", "Trying to fix darkness only by boosting treble instead of checking mic choice, placement, or the source itself"], "scenario_contexts": ["A ribbon mic on acoustic guitar sounds too dark, so the engineer tries a condenser or adds high-shelf EQ", "A club system is described as dark, prompting a check of high-driver level and system tuning", "A producer asks for a darker vocal to suit a moody ballad"]}, "9d9a25f3-f25c-4012-8dda-2c2cd74bd134": {"definition": "Describes sound that lacks a sharp, localizable point of origin and instead seems spread out in space, typically because reverberant or reflected energy dominates the direct sound.", "plain_english": "A diffuse sound seems to come from all around, not one clear spot. It is like hearing rain, where you cannot point to a single place it comes from.", "purpose_function": "Lets engineers describe how spread out or unlocalized a sound image is, which matters for imaging, reverb balance, and mic technique.", "practical_application": "A technician noticing a diffuse, washed-out image may move mics closer to reduce room reflections or lower the reverb send.", "category": "Spatial Descriptor", "related_terms": ["Dry", "distant", "Reverberant", "Ambience", "Stereo image"], "common_mistakes": ["Confusing diffuse (spread-out and unlocalized) with distant (far away but still placeable)", "Adding more reverb to a source that is already too diffuse", "Miking too far back and blaming the room instead of the distance"], "scenario_contexts": ["Room mics on drums sound too diffuse, so the engineer blends in close mics for focus", "A choir recording is overly diffuse, prompting closer or tighter mic placement", "A reverb setting makes a lead vocal too diffuse to sit forward in the mix"]}, "470e97b5-b187-4ec0-8a7f-afbedc7ee874": {"definition": "A timbral descriptor for sound containing added distortion, harmonic grit, or noise, giving a rough, aggressive, or gritty character rather than a clean tone.", "plain_english": "A dirty sound has extra grit or fuzz added to it. It is like a rough, scratchy voice instead of a smooth, clear one.", "purpose_function": "Gives a quick way to describe intentional or unwanted distortion and added harmonics, guiding choices about gain, saturation, and tone.", "practical_application": "An engineer may deliberately drive a preamp or amp sim to make a guitar or synth sound dirty, or track down an unwanted dirty tone caused by clipping.", "category": "Distortion Character", "related_terms": ["Clean", "Distortion", "Saturation", "edgy", "Overdrive"], "common_mistakes": ["Confusing an intentional dirty tone with a fault such as accidental clipping or a bad cable", "Adding dirt with distortion while ignoring the extra harmonics that can mask other tracks", "UNSAFE: cranking amp or monitor gain to chase a dirty tone and reaching harmful listening levels"], "scenario_contexts": ["A producer wants a dirty, distorted bass and adds a saturation plugin", "A guitarist's DI sounds too clean, so the engineer re-amps it for a dirtier tone", "An engineer traces a dirty-sounding vocal to an overdriven mic preamp"]}, "3d4945f4-44e3-4b3f-8140-594a632bd7aa": {"definition": "Describes a sound that seems far from the listener, typically due to lower level, reduced high-frequency content, weaker transients, and a higher ratio of reverberant to direct sound.", "plain_english": "A distant sound seems far away from you. Like someone talking from across a big room, it is quieter and less clear than a close sound.", "purpose_function": "Describes perceived depth and distance, helping engineers manage the front-to-back placement of sources in a mix.", "practical_application": "To push a backing vocal further back, an engineer adds reverb, rolls off highs, and lowers its level so it sounds more distant.", "category": "Spatial Descriptor", "related_terms": ["Diffuse", "Dry", "Presence", "Reverberant", "Depth"], "common_mistakes": ["Confusing distant (far away) with diffuse (spread out and unlocalized)", "Trying to fix an unwantedly distant sound with level alone while ignoring reverb and lost highs", "Miking a source too far away, then boosting gain and raising the noise floor"], "scenario_contexts": ["A lead vocal sounds distant, so the engineer reduces reverb and adds presence EQ", "A producer wants a distant, dreamy backing vocal and pushes it back with reverb", "Overhead-only drum mics sound distant, prompting added close mics"]}, "8c988b0e-425f-4039-9439-80c9d3c80e1f": {"definition": "Describes a signal with no added reverb, delay, or ambience — the source sound with no spatial effects, though a recording may still capture some of the room it was made in.", "plain_english": "A dry sound has no echo or reverb added. It is the plain, raw sound by itself, like singing in a small closet full of clothes.", "purpose_function": "Distinguishes the unprocessed source from a wet, effected signal, which is essential for effect balance, routing, and later re-processing.", "practical_application": "Engineers often record dry so reverb and delay can be added and adjusted later during the mix.", "category": "Effects Descriptor", "related_terms": ["Wet", "Reverberant", "distant", "Ambience", "Diffuse"], "common_mistakes": ["Confusing dry (no added effects) with a dead or dull tone", "Printing reverb onto a recording instead of keeping a dry track for flexibility", "Assuming a dry signal needs no room treatment, when recording still captures room sound"], "scenario_contexts": ["A vocal is recorded dry so the mix engineer can choose the reverb later", "A guitarist records a dry DI for re-amping", "A producer solos the dry signal to check tone before adding effects"]}, "15f117e5-6744-47b7-85c5-fbc19864e06c": {"definition": "A timbral descriptor for sound lacking high-frequency detail, brightness, and clarity, so it seems lifeless, muffled, or short on definition and attack.", "plain_english": "A dull sound is missing its bright, crisp detail. It sounds muffled and flat, like a cymbal hit with a soft cloth over it.", "purpose_function": "Flags a lack of clarity and high-frequency detail so engineers know to check the source, mic, or high-frequency EQ.", "practical_application": "A dull-sounding cymbal track may prompt a brighter mic, better placement, or a high-shelf boost.", "category": "Tonal Balance", "related_terms": ["Bright", "Dark", "Muffled", "Crisp", "Presence"], "common_mistakes": ["Confusing dull (lacking clarity and detail) with dark (a mellow but still clear tonal balance)", "Boosting treble to fix dullness when the real cause is a damaged cable, phase issue, or poor placement", "Ignoring a dull monitor sound that is actually a blown tweeter or failing crossover"], "scenario_contexts": ["A dull vocal recording leads the engineer to swap to a brighter condenser mic", "A PA sounds dull, so the tech checks for a blown high driver", "A mastering engineer adds gentle high-shelf EQ to lift a dull mix"]}, "89a66baf-6aa8-4470-917b-770ab2c90ca5": {"definition": "A timbral descriptor for sound with harsh, aggressive emphasis in the upper-midrange and high frequencies, producing a hard, biting, or slightly irritating character.", "plain_english": "An edgy sound is harsh and sharp on the ears. It has a biting, aggressive tone, a bit like a voice that is almost shouting.", "purpose_function": "Describes unpleasant or aggressive upper-mid energy so engineers know where to tame it, or where to add bite when wanted.", "practical_application": "An engineer may cut around 2 to 5 kHz to soften an edgy vocal or guitar, or add a little edge for aggression.", "category": "Tonal Balance", "related_terms": ["Harsh", "Bright", "dirty", "Presence", "Sibilance"], "common_mistakes": ["Confusing edgy (aggressive upper-mid tone) with dirty (added distortion)", "Cutting all the highs to fix edginess and ending up with a dull sound", "Blaming the source when edginess actually comes from a bright room or harsh monitors"], "scenario_contexts": ["An edgy vocal gets a narrow cut around 3 kHz to soften it", "A distorted guitar sounds edgy, so the engineer rolls off some presence", "A producer adds a touch of edge to a synth to help it cut through"]}, "bfade686-fec1-493f-811f-067e7cfad8a8": {"definition": "A colloquial timbral descriptor for a loose, buzzy, distorted low-frequency sound resembling flatulence, usually caused by driver over-excursion, clipping, or ill-defined bass distortion.", "plain_english": "A farty sound is a loose, buzzy low note that flaps instead of staying tight. It often comes from a speaker pushed too hard, and sounds a bit like the rude noise its name suggests.", "purpose_function": "Gives engineers a quick label for a specific loose low-end distortion so they can trace and fix overdriven or ill-defined bass.", "practical_application": "A farty kick or bass usually signals an overdriven speaker, too much low boost, or clipping, prompting less level or a high-pass filter.", "category": "Distortion Character", "related_terms": ["Distortion", "Boomy", "dirty", "Clipping", "fat"], "common_mistakes": ["Assuming farty always means a plugin problem when it is often a physical speaker being over-driven", "Boosting low bass further and worsening the loose, farty distortion", "UNSAFE: continuing to drive a farty, distorting subwoofer or amp, which can overheat voice coils and damage drivers"], "scenario_contexts": ["A subwoofer sounds farty at high level, so the tech engages a high-pass filter and lowers drive", "A synth bass patch sounds farty, prompting less distortion or a cleaner sub layer", "A bass amp goes farty when pushed, signaling the speaker is near its limit"]}, "fe041522-67f2-496a-ae5d-4e4afcdbd85a": {"definition": "A timbral descriptor for a full, rich, and weighty sound with strong low-mid content and often subtle harmonic saturation or width, giving a sense of size and body.", "plain_english": "A fat sound is big, full, and warm. It fills out the low-middle of the sound, making it feel large and rich, like a thick chord instead of a thin one.", "purpose_function": "Describes a sense of fullness and body so engineers can aim for or dial back weight in a source or mix.", "practical_application": "To make a thin snare or synth fatter, an engineer may add low-mid EQ, saturation, layering, or slight detuning and doubling.", "category": "Tonal Balance", "related_terms": ["Thin", "Warm", "Boomy", "Body", "Saturation"], "common_mistakes": ["Confusing fat (full and rich) with muddy (unclear and boomy)", "Adding too much low-mid to fatten a sound and cluttering the mix", "Assuming fat only means more bass rather than added body, saturation, and width"], "scenario_contexts": ["A thin-sounding synth bass is fattened with saturation and a sub layer", "A producer wants a fatter snare and adds low-mid EQ and parallel compression", "A vocal is doubled and slightly detuned to sound fatter"]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"a21933f3-d21f-481a-aa75-d80114a9467d": {"definition": "A subjective term for a thin, buzzy, effervescent high-frequency character, typically excess energy in the upper treble and presence region (roughly 4-10 kHz), often heard on harshly distorted electric guitar or low-quality digital distortion.", "plain_english": "Fizzy means the sound has a thin, buzzy edge up top, like the hiss of a soda. It usually comes from too much harsh treble, often on a distorted guitar.", "purpose_function": "The term lets engineers quickly flag unpleasant, grainy top-end energy so it can be tamed with EQ or a different cabinet, mic, or distortion setting.", "practical_application": "A tech hearing a fizzy guitar tone might roll off upper treble with EQ, swap the speaker cabinet or mic position, or reduce the amount of gain and distortion.", "category": "Tonal Descriptor", "related_terms": ["gritty", "harsh", "bright", "Glassy", "presence"], "common_mistakes": ["Confusing fizzy (thin, buzzy treble) with gritty (rough mid-range dirt)", "Adding more presence or treble EQ to a fizzy tone, which makes it worse", "Assuming fizz is always the amp when mic choice and placement often cause it"], "scenario_contexts": ["A high-gain electric guitar that sounds buzzy and thin in a mix", "Cheap digital distortion or amp-sim plugins adding harsh top end", "An overhead or cymbal track with brittle, effervescent high frequencies"]}, "53898cdb-4214-4f35-851d-4bba0cc58625": {"definition": "A subjective term for loose, poorly controlled, ill-defined low-frequency reproduction that lacks tightness and damping, so bass notes sound soft, boomy, and slow rather than firm and articulate.", "plain_english": "Flabby means the bass sounds loose and soft, with no firm edge. It is like a drum with a slack head that thuds instead of hitting cleanly.", "purpose_function": "The term flags bass that lacks control or definition, prompting fixes in damping, EQ, speaker or room setup, or playing technique.", "practical_application": "A tech may tighten a flabby low end by cutting a boomy frequency region, improving room treatment, or checking loudspeaker damping and port tuning.", "category": "Tonal Descriptor", "related_terms": ["flubby", "boomy", "muddy", "tight", "Full"], "common_mistakes": ["Boosting bass EQ to fix flabbiness, which makes it looser", "Blaming the source when room modes cause the flab", "Confusing flabby (loose bass) with full (rich, strong bass)"], "scenario_contexts": ["A bass guitar or kick drum with loose, undefined low end", "Loudspeakers in an untreated room with strong bass build-up", "A ported speaker or subwoofer tuned poorly, giving soft, slow bass"]}, "d982bc4d-4763-453e-87f8-8c92d15d0aad": {"definition": "A subjective term for soft, loose, undefined low-frequency character with weak transient definition, especially a kick drum or bass that sounds spongy and lacks punch or attack.", "plain_english": "Flubby means the low notes sound soft and spongy, with no punch. A flubby kick drum goes 'flub' instead of a tight thump.", "purpose_function": "The term identifies a lack of attack and control in the low end so it can be tightened for clarity and punch.", "practical_application": "A tech might tighten a flubby kick with EQ, gating, better tuning or muffling, or by adjusting compressor attack to restore punch.", "category": "Tonal Descriptor", "related_terms": ["flabby", "boomy", "muddy", "punchy", "tight"], "common_mistakes": ["Adding low-end EQ to a flubby kick instead of tightening it", "Ignoring drum tuning or muffling, which often causes flub", "Confusing flubby (soft, no punch) with punchy (tight, strong attack)"], "scenario_contexts": ["A kick drum that sounds soft and lacks thump in a mix", "An over-resonant bass note that blooms and loses definition", "A poorly tuned or undamped tom sounding loose and spongy"]}, "a4dbb271-3fee-413c-ab50-46f0683ef424": {"definition": "A subjective term for sound that is tight, coherent, and well-defined, with clear imaging and energy concentrated in a precise location rather than smeared or diffuse.", "plain_english": "Focused means the sound is tight and clear, and you can tell exactly where it sits. It is like a sharp photo instead of a blurry one.", "purpose_function": "The term describes strong definition and precise imaging, a goal when aligning, EQ-ing, or positioning sources so each one sits clearly.", "practical_application": "A tech aims for a focused image by time-aligning speakers, clearing masking frequencies, and controlling reflections so instruments sound tight and placed.", "category": "Mix Descriptor", "related_terms": ["tight", "forward", "imaging", "smeared", "Glue"], "common_mistakes": ["Thinking louder equals more focused, when clarity comes from definition", "Over-narrowing EQ and losing natural body while chasing focus", "Confusing focused (tight, defined) with forward (close, prominent)"], "scenario_contexts": ["A well-time-aligned PA where each instrument sits clearly", "A vocal that sits precisely in the center of a mix", "A tightly EQ-ed drum bus with clear, defined transients"]}, "124402b7-496f-4ff5-ba78-393b6563251c": {"definition": "A subjective term for sound that appears close and prominent to the listener, seeming to sit in front of the mix, often from emphasis in the upper-midrange and presence region (roughly 1-5 kHz).", "plain_english": "Forward means the sound feels close and up-front, like someone stepping toward you to speak. It often comes from a lift in the upper-middle frequencies.", "purpose_function": "The term describes a source's front-to-back position, guiding how prominent or intimate an instrument or voice sits in a mix.", "practical_application": "A tech can push a vocal forward with a presence boost, level, and compression, or pull it back by reducing upper mids and adding reverb.", "category": "Tonal Descriptor", "related_terms": ["presence", "Focused", "bright", "Glassy", "Full"], "common_mistakes": ["Confusing forward (close, prominent) with bright (extra treble)", "Pushing everything forward, so nothing stands out", "Using only level to make a source forward, ignoring EQ presence"], "scenario_contexts": ["A lead vocal that sits close and up-front in a pop mix", "A guitar with a presence boost that jumps out of the speakers", "A microphone with a presence peak making a voice sound immediate"]}, "d1bdb48f-dee5-4d26-9080-89615c65c815": {"definition": "A subjective term for a rich, weighty sound with strong low-frequency and low-midrange content, giving a sense of body and completeness across the spectrum.", "plain_english": "Full means the sound has plenty of body and weight, with strong lows. It is the opposite of thin, like a big, solid wall of sound with real weight behind it.", "purpose_function": "The term describes tonal weight and body, guiding EQ and arrangement choices to make a source or mix sound complete rather than thin.", "practical_application": "A tech may add fullness with low-mid EQ, layering, or mic choice, while watching that it does not tip into muddy or boomy.", "category": "Tonal Descriptor", "related_terms": ["thin", "warm", "boomy", "muddy", "flabby"], "common_mistakes": ["Overdoing low-mid EQ, turning full into muddy", "Confusing full (rich body) with simply loud", "Thinking only bass makes a sound full, ignoring low mids"], "scenario_contexts": ["A vocal that sounds rich and complete rather than thin", "A mix with strong low-mid body and weight", "Choosing a large-diaphragm mic to add fullness to a voice"]}, "5a2b0cea-7dad-4860-ba3f-b7e486efb9f0": {"definition": "A subjective term for a bright, clear, hard-edged high-frequency character that sounds smooth yet reflective and slightly brittle, like the surface of glass, usually in the upper treble.", "plain_english": "Glassy means the top end is very bright and clear, with a hard, shiny edge. It sounds smooth but can feel brittle, like tapping a glass.", "purpose_function": "The term flags a hard, reflective top end so it can be used for clarity and sparkle or softened when it becomes brittle or fatiguing.", "practical_application": "A tech might smooth a glassy top with a gentle high-shelf cut or de-essing, or keep it for sparkle on a clean electric piano or guitar.", "category": "Tonal Descriptor", "related_terms": ["bright", "brittle", "crisp", "fizzy", "presence"], "common_mistakes": ["Confusing glassy (hard, bright top) with warm", "Boosting a high shelf on an already glassy source", "Assuming glassy always sounds good, when it can be brittle and tiring"], "scenario_contexts": ["A clean electric piano such as a Rhodes or DX with a bright, shiny top", "A chime or bell with a hard, reflective high end", "A vocal recorded through a bright condenser sounding glassy"]}, "c2ece9a4-f715-481f-9bb4-2ae4951e1acb": {"definition": "A subjective term for a sense of cohesion that makes separate mix elements sound like one unified whole; commonly achieved with gentle bus compression (often called 'glue compression') and shared processing.", "plain_english": "Glue is when all the parts of a mix feel like they belong together, not like separate pieces. Gentle compression across the whole mix helps bind them, like tying a bundle together.", "purpose_function": "Glue helps a mix sound cohesive and finished, so instruments feel connected rather than like isolated tracks stacked on top of each other.", "practical_application": "A mix engineer often applies slow-attack, low-ratio bus compression, shared reverb, or subtle saturation across a group bus to add glue.", "category": "Mix Descriptor", "related_terms": ["bus compression", "compression", "cohesion", "Focused", "saturation"], "common_mistakes": ["Over-compressing the bus, which crushes dynamics instead of gluing", "Thinking glue is a single plugin rather than a result of cohesion", "Confusing glue (cohesion) with loudness"], "scenario_contexts": ["Adding gentle compression across a mix bus to bind a mix", "Using a shared drum-bus compressor to make a kit sound like one instrument", "Applying subtle saturation to make layered tracks feel connected"]}, "a9dc75eb-4ed4-49f8-9fe6-2782eef642f4": {"definition": "A subjective term for a rough, textured, slightly distorted character caused by added harmonic distortion or edge, giving a sound dirt and aggression without being fully clean.", "plain_english": "Gritty means the sound has a rough, dirty texture, like sandpaper. It comes from a bit of distortion that adds edge and attitude.", "purpose_function": "The term describes deliberate roughness or harmonic edge, used to add energy and character, or flagged when it is unwanted.", "practical_application": "A tech may add grit with saturation, overdrive, or a driven preamp for character, or reduce it by backing off gain when it becomes harsh.", "category": "Tonal Descriptor", "related_terms": ["fizzy", "harsh", "saturation", "distortion", "warm"], "common_mistakes": ["Confusing gritty (rough mid texture) with fizzy (thin, buzzy treble)", "Adding grit until it becomes harsh and fatiguing", "Assuming grit needs treble, when it is mostly harmonic distortion"], "scenario_contexts": ["An overdriven bass or guitar with rough, dirty texture", "A vocal run through saturation for edge and attitude", "A driven preamp or tape emulation adding gritty character"]}, "63936927-e031-47ad-9c13-0d550137a3d8": {"definition": "A subjective descriptor for a sound that lacks low-frequency energy, weight and power, coming across as thin, weak and underpowered with little punch or body.", "plain_english": "A gutless sound is weak and thin. It has almost no bass or punch, so it feels small and lacks power.", "purpose_function": "Gives engineers a quick shared term for a tonal balance that is short on lows and low-mids, pointing toward more level, low-end support, or a fuller source.", "practical_application": "A tech might call a bass DI 'gutless' and add low-mid EQ, re-amp it, or swap to a fuller-sounding source to restore weight.", "category": "Timbre Descriptor", "related_terms": ["thin", "punchy", "warm", "full", "boomy"], "common_mistakes": ["Confusing gutless (lack of low-end power) with thin (lack of body across the low-mids) and treating them the same.", "Trying to fix a gutless sound only with volume instead of restoring the missing low-frequency content.", "Boosting deep sub-bass to compensate, which adds rumble without the punch that was actually missing."], "scenario_contexts": ["A bass guitar DI that sounds gutless in the mix and needs low-mid support.", "A kick drum that lacks weight and punch through a small PA.", "A vocal that sounds gutless and underpowered next to a dense backing track."]}, "7d2782fb-57c6-4388-9226-3632818dd247": {"definition": "A subjective descriptor for an unpleasant, aggressive, edgy quality, usually caused by excess energy or distortion in the upper-midrange/presence region (roughly 2-5 kHz), that is fatiguing to listen to.", "plain_english": "A harsh sound is rough and hard on the ears. It has too much high-mid energy, so it feels sharp and tiring to hear.", "purpose_function": "Flags a specific tonal fault so engineers know to look for a peak, resonance or distortion in the presence band and tame it.", "practical_application": "An engineer hearing a harsh cymbal or vocal will sweep a narrow EQ cut through 2-5 kHz, check for clipping, or ease off a compressor or exciter to smooth it out.", "category": "Timbre Descriptor", "related_terms": ["bright", "sibilant", "edgy", "presence", "ice-pick", "brittle"], "common_mistakes": ["Confusing harsh (aggressive upper-mid/presence energy) with bright (extended but pleasant highs).", "Cutting broad high frequencies and dulling the whole source instead of finding the narrow offending band.", "Blaming the source when the harshness is actually clipping or distortion somewhere in the gain chain."], "scenario_contexts": ["A vocal that turns harsh on loud notes through a PA.", "Cymbals or an electric guitar amp that sound harsh on a bright console.", "A cheap microphone or converter adding a harsh edge to a recording."]}, "20cd27aa-90d7-48d6-8455-b9ec6ad3cf75": {"definition": "Short for high fidelity; reproduction that closely and accurately matches the original source, with wide, even frequency response, low distortion and low noise. As a timbre descriptor, a clean, detailed, full-range and refined sound.", "plain_english": "Hi-fi is short for high fidelity. It means the sound is clean, clear, and true to the real thing. It has full lows and highs with very little noise.", "purpose_function": "Serves as a benchmark of accurate, faithful reproduction against which colored or degraded 'lo-fi' sounds are judged.", "practical_application": "A tech describes a monitor chain or recording as hi-fi when it is clean, extended and uncolored, or deliberately degrades a track toward lo-fi for effect.", "category": "Timbre Descriptor", "related_terms": ["lo-fi", "flat response", "transparent", "detailed", "fidelity"], "common_mistakes": ["Assuming hi-fi just means loud or bass-heavy rather than accurate and low in distortion.", "Confusing a 'hyped', exciting sound with true high fidelity.", "Judging fidelity on colored consumer speakers instead of accurate monitors."], "scenario_contexts": ["Describing a mastering monitor chain that reproduces sources cleanly and accurately.", "Comparing a hi-fi full-range recording against a deliberately lo-fi effected track.", "Evaluating whether a converter or preamp adds coloration or stays hi-fi."]}, "edf66472-81b8-4dbf-9275-fdd59fd4adac": {"definition": "A subjective descriptor for a tone with a scooped or notched midrange and resonant coloration, giving a distant, cupped, tube-like quality; often the result of a midrange dip, phase cancellation or comb filtering.", "plain_english": "A hollow sound is missing its middle tones. It sounds far away and cupped, like someone talking into a tube or barrel.", "purpose_function": "Points to a midrange deficiency or comb-filter coloration so engineers can check mic placement, polarity and EQ.", "practical_application": "Hearing a hollow snare or vocal, a tech checks for phase cancellation between mics, corrects polarity or placement, and restores midrange with EQ.", "category": "Timbre Descriptor", "related_terms": ["boxy", "comb filtering", "phase cancellation", "nasal", "scooped"], "common_mistakes": ["Fixing a hollow, comb-filtered sound with EQ alone instead of correcting mic phase or placement.", "Confusing hollow (scooped mids) with boxy (excess low-mids).", "Scooping the mids on purpose and then wondering why the source sits poorly in the mix."], "scenario_contexts": ["Two mics on one source combining out of phase and sounding hollow.", "A vocal that sounds hollow and distant after a midrange cut.", "A snare recorded in a way that produces a hollow, tube-like tone."]}, "6d817368-2f76-450a-b6cf-4d8670c417f5": {"definition": "A subjective descriptor for a nasal, midrange-heavy coloration with excess energy roughly in the 500 Hz-1 kHz range, resembling speech through cupped hands or a megaphone.", "plain_english": "A honky sound is nasal and pinched. It sounds like someone talking through cupped hands, with too much middle honk.", "purpose_function": "Identifies an over-prominent lower-midrange resonance so it can be located and cut with EQ.", "practical_application": "An engineer tames a honky acoustic guitar or vocal by sweeping a narrow EQ cut through 500 Hz-1 kHz until the nasal quality clears.", "category": "Timbre Descriptor", "related_terms": ["nasal", "boxy", "midrange", "peaky", "hollow"], "common_mistakes": ["Confusing honky (around 500 Hz-1 kHz emphasis) with boxy (lower, around 300-600 Hz emphasis).", "Cutting too wide and hollowing out the midrange instead of notching the honk.", "Assuming the honk is the source when it is a room or enclosure resonance."], "scenario_contexts": ["An acoustic guitar that sounds honky through a piezo pickup.", "A vocal mic with a midrange resonance that sounds honky.", "A small speaker or wedge with a honky midrange bump."]}, "b8c3f064-1564-4799-93da-6f271d10de93": {"definition": "A subjective descriptor for a sound with a deliberately exaggerated, non-flat frequency response, typically boosted lows and highs with scooped mids ('smile' EQ), that sounds exciting and enhanced rather than accurate.", "plain_english": "A hyped sound has boosted lows and highs and scooped middles. It sounds exciting at first, but it is not a true, flat picture of the music.", "purpose_function": "Names an enhanced, flattering tonal balance so engineers can tell an impressive-sounding presentation from a true, flat one.", "practical_application": "A tech recognizes hyped consumer speakers or a hyped mix and cross-checks decisions on flat monitors so the balance translates elsewhere.", "category": "Timbre Descriptor", "related_terms": ["smile EQ", "scooped", "flat response", "hi-fi", "bright"], "common_mistakes": ["Mixing on hyped speakers and making a dull, thin mix that only sounds right on those speakers.", "Confusing a hyped, exciting sound with an accurate one.", "Adding hype with EQ on every channel until the mix is fatiguing and cluttered."], "scenario_contexts": ["Consumer earbuds or a boombox with a hyped, smiling response.", "A demo playback system voiced hyped to impress clients.", "A mix bus that has been hyped with too much high and low boost."]}, "4e4b5c2d-1b84-4bd8-b532-30740094e98a": {"definition": "A subjective descriptor for an extremely piercing, painful high-frequency peak, often around 3-8 kHz, that feels like a sharp stab in the ears; a severe, localized form of harshness.", "plain_english": "An ice-pick sound has a sharp, piercing high note that stabs your ears. It is a very painful, extreme kind of harshness.", "purpose_function": "Flags a narrow, painful treble resonance so it can be found and notched out before it causes listener discomfort.", "practical_application": "Hearing an ice-pick peak on cymbals or a vocal, a tech sweeps a narrow boosted EQ to locate the frequency, then cuts it sharply.", "category": "Timbre Descriptor", "related_terms": ["harsh", "sibilant", "bright", "presence", "brittle"], "common_mistakes": ["Cutting a wide band and dulling the whole top end instead of notching the narrow ice-pick frequency.", "Confusing ice-pick (a narrow, piercing peak) with general brightness.", "UNSAFE: Enduring an ice-pick peak at high monitoring levels, risking ear fatigue and hearing damage instead of cutting it."], "scenario_contexts": ["A cymbal or hi-hat with an ice-pick peak on a bright PA.", "A vocal sibilance region that stabs at a specific high frequency.", "A resonant tweeter or horn producing an ice-pick tone."]}, "ef909101-6d60-443c-9a61-5ade9c18af30": {"definition": "A subjective descriptor for a closed-in, boxy coloration in which the sound seems enclosed, caused by excess low-midrange resonance (roughly 300-600 Hz) and a lack of openness and air.", "plain_english": "A sound 'in a box' feels closed-in and boxy. It has too much low-middle tone, like the music is trapped inside a small box.", "purpose_function": "Identifies a low-mid buildup and lack of top-end openness so engineers can cut the boxiness and add air.", "practical_application": "A tech cuts around 300-600 Hz and may add a gentle high-frequency lift to open up a source that sounds 'in a box'.", "category": "Timbre Descriptor", "related_terms": ["boxy", "honky", "muddy", "hollow", "closed-in"], "common_mistakes": ["Confusing 'in a box' (low-mid boxiness, around 300-600 Hz) with honky (higher, around 500 Hz-1 kHz).", "Boosting highs to 'open it up' without cutting the low-mid buildup causing the boxiness.", "Overlooking that a small, untreated room or enclosure is adding the boxy resonance."], "scenario_contexts": ["A vocal recorded in a small untreated room that sounds in a box.", "A guitar cabinet close-mic'd in a way that produces a boxy, closed-in tone.", "A conference or podcast mic in a reflective space sounding in a box."]}, "24366474-2bf2-421e-b972-89d055d4f76e": {"definition": "A subjective descriptor for a very present, forward and immediate sound that seems close to the listener, usually from strong presence-region energy, high directness and little room ambience.", "plain_english": "An in-your-face sound is bold, close, and upfront. It feels like the music is right in front of you, with little room echo.", "purpose_function": "Describes a forward, upfront presentation so engineers can dial presence, dryness and level to place a source aggressively in the mix.", "practical_application": "To make a vocal in-your-face, a tech boosts presence, keeps it dry and compressed, and raises it forward in the balance.", "category": "Timbre Descriptor", "related_terms": ["present", "forward", "dry", "presence", "upfront"], "common_mistakes": ["Pushing every element in-your-face so nothing has depth or sits back in the mix.", "Confusing in-your-face (forward and present) with simply loud.", "Adding so much presence to be upfront that the source becomes harsh."], "scenario_contexts": ["A lead vocal mixed dry and forward to sound in-your-face.", "A rock guitar meant to be aggressive and upfront.", "A voiceover kept in-your-face for impact in a commercial."]}, "8cde8c95-ab2c-4e71-b5b9-7ea00c927eae": {"definition": "A subjective tonal descriptor for sound with a relaxed, unaggressive character created by reduced energy in the upper-midrange/presence region (roughly 2-6 kHz), so vocals and lead instruments sit slightly back rather than forward. It is the opposite of a forward or aggressive presentation, giving a smooth, easy overall balance.", "plain_english": "A laid-back sound feels calm and easygoing. The middle-high tones that make things sound close and in-your-face are pulled back a bit, so the music sits a little farther away, like a singer who steps back from the mic.", "purpose_function": "It describes where a sound sits front-to-back in a mix, helping engineers say that a source is too soft in its presence range or that a relaxed feel is wanted.", "practical_application": "An engineer may call a mix laid-back when the vocal lacks presence, then add a gentle boost around 3-5 kHz to bring it forward, or keep it laid-back on purpose for a mellow ballad.", "category": "Tonal Descriptor", "related_terms": ["forward", "presence", "dark", "smooth", "midrangey"], "common_mistakes": ["Confusing laid-back with dark or dull; laid-back mainly means reduced presence and a back-of-the-mix placement, not an overall loss of highs.", "Assuming laid-back is always a fault, when it is often a deliberate, pleasing choice for relaxed material.", "Trying to fix a laid-back vocal with volume alone when the real issue is a lack of presence-range energy."], "scenario_contexts": ["A client says the lead vocal sounds too laid-back and wants it more up-front.", "Describing a monitor whose relaxed presence region makes mixes sound distant.", "Choosing a laid-back balance on purpose for a mellow acoustic or jazz ballad."]}, "110baae8-610e-411a-ba2a-384366d4f05c": {"definition": "A subjective descriptor for sound that lacks energy, dynamics, brightness, and a sense of ambience, so it seems dull, flat, and unengaging. It is the opposite of lively or open, and often results from rolled-off highs, heavy compression, or a dead acoustic space.", "plain_english": "A lifeless sound is dull and flat, with no spark. It has little brightness, little bounce, and no sense of air or room, like a song playing through a thick blanket.", "purpose_function": "The term flags a recording or playback that fails to excite the listener, prompting the engineer to find and fix what is draining its energy.", "practical_application": "Hearing a lifeless drum track, a technician may restore high-frequency detail, ease off heavy compression, or add reverb to bring back a sense of life.", "category": "Tonal Descriptor", "related_terms": ["dull", "dead", "flat", "dark", "lively"], "common_mistakes": ["Fixing lifeless sound with volume alone, when the problem is missing highs, dynamics, or ambience.", "Confusing lifeless, which lacks energy overall, with dark, which specifically lacks high frequencies.", "Over-compressing while tracking or mixing and then wondering why the result sounds lifeless."], "scenario_contexts": ["A mix comes back from heavy limiting sounding lifeless and squashed.", "A vocal recorded in a dead, over-treated booth sounds lifeless and needs ambience.", "Comparing a lifeless reference speaker with a livelier one during monitor selection."]}, "304c5f68-261a-46cc-83f1-60c4ce22eb1c": {"definition": "A subjective descriptor, applied mainly to low frequencies, for bass that is poorly controlled or undamped, with blurred, drawn-out transients and imprecise pitch definition. It is the opposite of tight, where notes start and stop cleanly.", "plain_english": "Loose bass is sloppy and boomy. The low notes smear together and ring on instead of starting and stopping cleanly, like a drum with a floppy, untuned skin.", "purpose_function": "It describes a lack of control or damping in the low end so engineers can target the cause, such as room resonance, tuning, or gear, and tighten it up.", "practical_application": "Faced with loose bass, a technician may treat room modes, retune a kick, gate or EQ the low end, or improve speaker damping to tighten the sound.", "category": "Tonal Descriptor", "related_terms": ["tight", "boomy", "muddy", "flabby", "damping"], "common_mistakes": ["Assuming loose just means too much bass; the issue is control and timing, not only level.", "Cutting low-end level to fix loose bass when the real fix is transient control, tuning, or room treatment.", "Confusing a player's loose timing with loose low-frequency tone; here the term describes the sound, not the performance."], "scenario_contexts": ["A subwoofer in an untreated room produces loose, boomy bass at certain notes.", "A kick-and-bass combination sounds loose and undefined until gated and EQ'd.", "Describing an amplifier or speaker with poor damping factor as sounding loose in the low end."]}, "7d464080-1759-409f-b38d-70c3913953ea": {"definition": "A subjective studio instruction to make a sound or mix more sonically pleasing and refined, typically by smoothing harshness, adding warmth, sheen, or ambience, and correcting tuning or timing, rather than by any single defined process. It states an aesthetic goal, an attractive and polished result, instead of a specific technical operation.", "plain_english": "It means make it sound nicer and more polished. The person is not naming exact tools; they just want a smooth, easy-to-enjoy sound.", "purpose_function": "It gives a producer or client a quick way to ask for a more attractive, finished sound without naming tools. Understanding it lets the engineer turn a vague aesthetic request into concrete moves like de-essing, gentle EQ, reverb, or tuning.", "practical_application": "When a client says 'make it pretty' on a vocal, the engineer may tame sibilance and harsh mids, add a little high-end air and reverb, and tune stray notes to deliver a smoother, more flattering sound.", "category": "Mixing Direction", "related_terms": ["Make it sit", "Make it speak", "Sweetening", "Air", "Sibilance"], "common_mistakes": ["Treating 'make it pretty' as one fixed process rather than asking what the client finds unpleasant.", "Over-processing with heavy reverb or bright EQ until the sound is thin or washed out.", "Assuming 'pretty' means the same thing in every genre, when an aggressive style may want grit, not gloss."], "scenario_contexts": ["A client asks an engineer to 'make it pretty' on a lead vocal during a mix revision.", "A producer requests a smoother, more polished sound on a piano or string pad.", "A mastering client asks for a glossier, more flattering overall tone on a ballad."]}, "2e7dffe5-94f7-4fb4-9e8c-e7c025cad195": {"definition": "A mixing instruction to adjust an element so it blends into the mix and occupies its own space, balanced in level, tone, and stereo position, without masking other parts or sticking out unnaturally. It is commonly achieved with level, EQ, compression, panning, and reverb.", "plain_english": "Making something sit means getting it to fit smoothly into the song. You set its volume and tone so it takes its own spot, neither buried under other parts nor jumping out, like a puzzle piece that clicks in next to the rest.", "purpose_function": "It captures the core goal of mixing, blending each part into a cohesive whole, and tells the engineer to focus on fit rather than isolated tone.", "practical_application": "To make a vocal sit, an engineer may carve competing frequencies with EQ, add light compression to steady its level, and use reverb to place it at the right depth.", "category": "Mixing Direction", "related_terms": ["masking", "balance", "EQ", "compression", "blend"], "common_mistakes": ["Only turning an element up or down, when making it sit usually needs EQ and compression too.", "Carving so much frequency space that the element loses its own character.", "Judging how an element sits while soloed instead of in the full mix."], "scenario_contexts": ["A producer asks to make the rhythm guitar sit better under the vocal.", "A synth pad clashes with the piano until EQ helps it sit in its own range.", "Making a loud lead vocal sit by taming its peaks with compression."]}, "6447e734-4dbc-4718-aece-554573b74477": {"definition": "A direction to bring out the clarity, articulation, and projection of a sound so its note onsets and character come through clearly and it asserts itself in the mix. It is commonly achieved by emphasizing transients and presence-range detail and by ensuring adequate level and space.", "plain_english": "Making something speak means helping it come through clearly and say its part. You bring out the attack and detail so each note is easy to hear, like turning up someone who is mumbling so their words are clear.", "purpose_function": "It tells the engineer to improve the clarity and presence of a part that sounds buried, dull, or indistinct so it communicates its role.", "practical_application": "To make a snare speak, a technician may boost presence-range frequencies, sharpen the transient, or raise its level so each hit cuts through.", "category": "Mixing Direction", "related_terms": ["presence", "articulation", "transient", "clarity", "attack"], "common_mistakes": ["Only raising level, when clarity often depends more on transient and presence-range detail.", "Adding a harsh high boost that makes a part edgy instead of clear.", "Confusing making a part speak, which is about clarity and projection, with simply making it louder."], "scenario_contexts": ["A guitar solo sounds dull and buried, and the producer asks to make it speak.", "Getting a soft-spoken voiceover to speak clearly over background music.", "Sharpening a kick drum's attack so it speaks through a dense mix."]}, "ae4b7198-003f-4777-9758-f59580cf7660": {"definition": "A subjective descriptor for a hard, ringing, bell- or tin-like coloration in the upper midrange and highs, often caused by narrow resonances, artificial-reverb ringing, aliasing, or digital clipping. It gives sound an unnatural, clangy edge.", "plain_english": "A metallic sound has a hard, ringing, tinny edge, like tapping on metal. Certain high tones ring out in an unnatural way, making things sound cold and clangy instead of natural.", "purpose_function": "The term points to an unwanted resonant or distortion artifact so the engineer can track down its source and remove it.", "practical_application": "When a reverb or pitch-shifter sounds metallic, an engineer changes the algorithm or settings; when a converter or plugin aliases, they lower levels or use higher-quality processing.", "category": "Tonal Descriptor", "related_terms": ["ringing", "resonance", "harsh", "edgy", "aliasing"], "common_mistakes": ["Blaming the source when a metallic sound actually comes from reverb, pitch processing, or clipping.", "Boosting highs for air and unintentionally exciting metallic resonances.", "Confusing metallic, which is ringing and resonant, with simply bright or harsh."], "scenario_contexts": ["A cheap plate-reverb setting adds a metallic ring to a vocal.", "A pitch-shifted harmony sounds metallic and robotic.", "Digital clipping on a cymbal track gives it a metallic, clangy edge."]}, "ae427297-c0b2-40c2-930f-859161535f5d": {"definition": "An informal descriptor for sound with an emphasized midrange (roughly 250 Hz-2 kHz) relative to the lows and highs, giving a boxy, nasal, or honky character and a lack of low-end weight and high-end air. It is often likened to a small speaker or a telephone.", "plain_english": "A midrangey sound is heavy in the middle tones and light on deep lows and airy highs. It can sound boxy or nasal, a bit like a small phone speaker.", "purpose_function": "It flags a tonal imbalance tilted toward the mids so engineers know to add low and high extension or trim the middle.", "practical_application": "Calling a mix midrangey, an engineer may gently cut around 500 Hz-1 kHz and add low-end body and high-end air to open it up.", "category": "Tonal Descriptor", "related_terms": ["boxy", "nasal", "honky", "midrange", "thin"], "common_mistakes": ["Cutting mids so hard the mix becomes scooped and lifeless.", "Confusing midrangey, a broad mid emphasis, with harsh, which is an aggressive high-mid peak.", "Judging tone on midrangey small speakers and missing the real low and high balance."], "scenario_contexts": ["A laptop or phone speaker makes any mix sound midrangey.", "A guitar tone is too midrangey and honky, needing low and high shaping.", "A vocal chain leaves the voice midrangey and boxy until the low-mids are trimmed."]}, "bcb1faf4-8c50-4898-aa1e-ab94cb937f7a": {"definition": "A subjective descriptor for a contemporary production tonality, typically extended and controlled low end, clean and scooped low-mids, bright airy highs, and a loud, polished, precise character. It is used in contrast with a warmer, more colored vintage sound.", "plain_english": "A modern sound is the clean, bright, punchy tone of today's recordings. It has tight deep lows, clear mids, crisp airy highs, and a loud, polished feel, unlike the warmer vintage sound.", "purpose_function": "It communicates a target style, today's polished, hi-fi production sound, so gear and processing choices can aim for that goal.", "practical_application": "Asked for a modern sound, an engineer may tighten the lows, clean the low-mids, add high-end air, and use precise digital processing and heavier loudness.", "category": "Tonal Descriptor", "related_terms": ["vintage", "bright", "clean", "airy", "punchy"], "common_mistakes": ["Treating modern as a fixed EQ setting rather than a broad style that varies by genre.", "Chasing a modern loud sound with over-limiting that squashes the dynamics.", "Assuming modern always means better, when a vintage tone is often the right choice."], "scenario_contexts": ["A client asks for a modern pop vocal sound with bright air and tight low end.", "Choosing between vintage and modern voicings on an amp sim or console emulation.", "Mastering a track for a modern, loud, competitive level."]}, "3f17fad1-2470-43c4-aae7-f4523b6d6b73": {"definition": "A subjective tonal descriptor for sound with excessive or poorly defined low-mid energy (roughly 100-500 Hz) that masks clarity and makes individual instruments hard to distinguish from one another.", "plain_english": "Music that sounds thick and unclear, like everything is smeared together. It usually has too much low and low-mid sound, so you cannot pick out each instrument, a bit like a photo that is out of focus.", "purpose_function": "It flags a common, correctable tonal fault so engineers know to cut low-mid buildup and reduce masking; the shared shorthand lets people agree on the problem quickly.", "practical_application": "Hearing a muddy mix, an engineer sweeps an EQ to find and cut boxy buildup near 200-400 Hz, high-passes tracks that do not need low end, and checks for too many parts sharing the same range.", "category": "Tonal Descriptor", "related_terms": ["muffled", "Boomy", "Boxy", "Warm", "Congested", "one-note bass"], "common_mistakes": ["Confusing muddy (excess low-mids) with dark (rolled-off highs).", "Trying to fix muddiness by boosting treble instead of cutting the low-mid buildup.", "Assuming it is always one source's fault rather than masking from many layered instruments."], "scenario_contexts": ["A dense rock mix where bass and kick overlap around 100-250 Hz.", "An untreated room with strong low-mid reflections making vocals unclear.", "A home recording with no high-pass filtering, stacking low-mid energy across tracks."]}, "26348071-0883-48da-b6df-a7a7720fcb6b": {"definition": "A tonal descriptor for sound that seems covered or obstructed, with attenuated high frequencies and reduced clarity and intelligibility, as if heard through a barrier.", "plain_english": "Sound that seems covered up, like music playing behind a closed door or with a blanket over the speaker. The crisp high sounds are missing, so it feels dull and less clear.", "purpose_function": "It describes a treble-deficient, obstructed sound so a technician looks for rolled-off top end or a physical blockage rather than a low-end problem.", "practical_application": "A muffled complaint leads a tech to check mic placement or a heavy pop screen, a covered speaker grille, a failed tweeter, or an unwanted high cut, then restore high-frequency content.", "category": "Tonal Descriptor", "related_terms": ["Dark", "Dull", "Muddy", "Bright", "Presence", "Open"], "common_mistakes": ["Confusing muffled (missing highs or obstruction) with muddy (excess low-mids).", "Overboosting treble when the real cause is mic placement or a physical blockage.", "Overlooking a blocked grille or a failed high-frequency driver as the cause."], "scenario_contexts": ["A vocal recorded far off-axis or behind a thick pop screen.", "A PA with a blown high-frequency driver.", "Playback through a phone speaker that is partly covered by a hand."]}, "226a0684-25dd-4c8e-bac9-a7ae41ddeb3e": {"definition": "A tonal descriptor for sound lacking transient definition and tightness, where attacks and notes smear together and lose punch, often from over-processing, poor timing, or inadequate low-end damping.", "plain_english": "Sound that is soft and smeared, with no sharp hits or clear edges. The notes blur into each other instead of sounding tight and punchy, like soggy food that has lost its crunch.", "purpose_function": "It flags weak transients and poor definition so an engineer works on attack, timing, or damping rather than on frequency balance alone.", "practical_application": "A mushy low end leads a tech to check bass note definition, ease off gating and heavy compression or limiting, and improve monitor or room damping to sharpen transients.", "category": "Tonal Descriptor", "related_terms": ["Muddy", "Punchy", "Tight", "Boomy", "Flabby", "one-note bass"], "common_mistakes": ["Confusing mushy (smeared transients) with muddy (frequency buildup).", "Over-compressing, which flattens transients and makes the sound mushier.", "Blaming the source when the room or monitors lack low-end damping."], "scenario_contexts": ["A bass DI over-compressed until the notes lose their attack.", "A drum bus crushed by a limiter set too hard.", "A boomy, untreated room smearing kick-drum transients."]}, "4ab8195b-8102-41bb-bd5f-22c9164963ec": {"definition": "A subjective praise descriptor for a sound, device, or process that is pleasing, coherent, and easy on the ear, altering the source smoothly and agreeably rather than harshly or clinically.", "plain_english": "A sound or tool people call musical just sounds pleasing and easy on the ears. It changes the sound in a smooth, gentle way instead of a harsh or ugly one, so it feels right for music.", "purpose_function": "It conveys that a device or process flatters the source rather than sounding harsh or clinical, guiding gear and setting choices toward pleasing results.", "practical_application": "Engineers call an EQ, compressor, or reverb musical when it can be pushed hard yet still sound smooth, and use the label when picking gear or settings for a natural, flattering result.", "category": "Tonal Descriptor", "related_terms": ["natural", "Smooth", "Warm", "Harsh", "Open", "Transparent"], "common_mistakes": ["Treating musical as a measurable spec rather than a subjective judgment.", "Assuming musical always means colored or warm, when it can also mean transparent.", "Using the word so vaguely that it gives no actionable direction."], "scenario_contexts": ["Describing an analog-style compressor that stays smooth under heavy gain reduction.", "A broad EQ curve that flatters a vocal without sounding processed.", "A plate reverb that sits pleasingly behind a mix."]}, "bbd75fd6-182f-4c2b-a51b-d508f87bb154": {"definition": "A tonal descriptor for a pinched, honky quality resembling a voice with a blocked nose, caused by a narrow-band emphasis in the upper midrange (roughly 1 kHz), often with a dip nearby.", "plain_english": "Sound that is pinched and honky, like someone talking while holding their nose. It comes from too much sound in a narrow midrange band, which makes voices and instruments sound boxed-in.", "purpose_function": "It names a specific midrange coloration so a technician can find and reduce the offending emphasis rather than guessing across the whole spectrum.", "practical_application": "A nasal vocal or horn leads the engineer to sweep and cut a narrow band near 1 kHz, reconsider mic choice and placement, and restore a natural midrange.", "category": "Tonal Descriptor", "related_terms": ["Boxy", "Honky", "Presence", "natural", "Muddy", "muffled"], "common_mistakes": ["Confusing nasal (upper-mid honk near 1 kHz) with boxy (lower-mid buildup around 300-500 Hz).", "Cutting too wide a band and hollowing out the whole midrange.", "Blaming the microphone when the cause is room or placement."], "scenario_contexts": ["A vocal on a cheap dynamic mic that sounds honky and pinched.", "A saxophone with a pronounced peak near 1 kHz.", "A budget PA with a midrange bump making speech sound nasal."]}, "8f172fd4-63bb-477f-b29f-ef36553626e2": {"definition": "A descriptor for reproduction that sounds true to the original acoustic source, without obvious coloration, hype, or artifacts, and is timbrally balanced and realistic.", "plain_english": "Sound that seems real and true to life, like hearing the actual instrument in the room. Nothing is boosted or changed in an obvious way, so it feels honest.", "purpose_function": "It sets a reference target of uncolored, realistic reproduction, guiding mic, EQ, and monitor choices toward fidelity to the source.", "practical_application": "Engineers aim for a natural tone by choosing neutral mics and monitors and using light EQ so a recording matches how the source really sounds, and use it as an A/B reference.", "category": "Tonal Descriptor", "related_terms": ["musical", "Open", "Transparent", "Warm", "Balanced", "Colored"], "common_mistakes": ["Confusing natural with a perfectly flat measured response; a natural result may still need gentle EQ.", "Assuming heavy processing can still leave a sound natural.", "Chasing a natural tone on poor monitors that hide coloration."], "scenario_contexts": ["An acoustic guitar recording that matches the live instrument.", "A neutral studio monitor used as a reference.", "A classical recording made with minimal EQ and simple miking."]}, "455b7d4f-3861-4275-b610-d42099ca7c30": {"definition": "A low-end fault in which the bass region lacks pitch definition, so different bass notes sound at roughly the same level and character because one or a few resonant frequencies dominate, usually from room modes or a resonant speaker or port.", "plain_english": "A bass sound where every note seems to hit the same, so you cannot tell the notes apart. Usually one strong resonant pitch booms louder than the rest and hides the real bass line, like a room that rings on one note.", "purpose_function": "It names an evenness and resonance problem in the low end so a technician looks at room modes or equipment resonance rather than blaming the player.", "practical_application": "Hearing one-note bass, a technician checks room modes and monitor or subwoofer placement, adds treatment or a narrow EQ cut, and looks for a resonant port or cabinet rather than re-tracking the bassist.", "category": "Tonal Descriptor", "related_terms": ["Boomy", "Room mode", "Muddy", "mushy", "Tight", "Resonance"], "common_mistakes": ["Blaming the bass player or instrument instead of the room or monitors.", "Fixing it by cutting all bass instead of the specific resonant frequency.", "Ignoring monitor or subwoofer placement as the cause."], "scenario_contexts": ["A small untreated control room with a strong axial room mode.", "A bass guitar tracked in a resonant live room.", "A ported loudspeaker with a dominant port tuning frequency."]}, "38481a39-5e87-4d3a-8ef2-039b6608bed0": {"definition": "A positive tonal descriptor for sound with a sense of space, air, and clarity, with extended, unrestricted high frequencies and good separation, as if nothing sits between listener and source; the opposite of closed, congested, or veiled.", "plain_english": "Sound that feels spacious and clear, with plenty of air on top and room around each instrument. It seems like nothing is blocking the sound, the opposite of stuffy or boxed-in.", "purpose_function": "It describes airy, uncongested sound with good high-frequency extension and separation, serving as a positive target for clarity and space.", "practical_application": "Engineers aim for an open sound by managing high-frequency extension, reducing masking between parts, and using space and ambience so a mix breathes; it also helps judge mics and EQ.", "category": "Tonal Descriptor", "related_terms": ["Airy", "Open it up", "natural", "Congested", "Veiled", "muffled"], "common_mistakes": ["Confusing open (space, air, and separation) with simply loud or bright highs.", "Over-brightening to fake openness, which causes harshness.", "Cramming in too many parts, which kills the sense of openness."], "scenario_contexts": ["A sparse acoustic mix with plenty of air around each part.", "A condenser mic with extended top-end response.", "A well-separated stereo image with clear space between instruments."]}, "9864e307-96dc-4473-8afd-51d02a33451a": {"definition": "A studio directive meaning to make a sound more open, increasing clarity, air, and space, typically by adding high-frequency extension, removing masking or clutter, or easing back heavy compression that closes the sound down.", "plain_english": "A request to make a sound more open and airy. You do this by adding some top-end sparkle, easing off heavy compression, or clearing out clutter so the sound breathes and feels less boxed-in.", "purpose_function": "It is shorthand for the goal of increasing openness, telling an engineer to move the sound toward something more spacious and clear.", "practical_application": "Told to open it up, an engineer may add a high-shelf boost for air, back off compression, high-pass low-mid clutter, or lower masking parts so the mix breathes.", "category": "Tonal Descriptor", "related_terms": ["Open", "Airy", "Congested", "natural", "Presence", "Compression"], "common_mistakes": ["Only boosting treble while ignoring compression and masking that also close a sound down.", "Overdoing it until the sound becomes harsh or thin.", "Treating a broad direction as one fixed EQ move rather than a goal to reach."], "scenario_contexts": ["A producer asking to open up an over-compressed vocal.", "Making a dense, congested mix breathe.", "Adding air and space to a dull acoustic guitar."]}, "06f0f44c-4994-497a-acdd-6efd62c051f0": {"definition": "A timbral descriptor for a thin, dry sound that lacks low-frequency body and resonance, having a light, insubstantial, rustling character reminiscent of paper. It is commonly applied to snare drums, acoustic guitars, or midrange tones that seem hollow and weightless.", "plain_english": "A papery sound is thin and dry, with no real low-end weight behind it. It is like the light, rustling noise of a sheet of paper instead of a full, solid tone.", "purpose_function": "The term gives engineers a quick shorthand for a tone that is too thin and lacks body, flagging a problem to address with EQ, mic choice, or source treatment.", "practical_application": "An engineer might call a close-miked acoustic guitar 'papery' and add low-mid EQ or reposition the mic away from the soundhole edge to restore body.", "category": "Timbre Descriptor", "related_terms": ["thin", "dry", "boxy", "dull", "body"], "common_mistakes": ["Confusing 'papery' (thin, dry, no body) with 'crisp' or 'bright', which describe treble detail rather than a lack of low-end weight.", "Trying to fix a papery tone only by boosting treble, which makes it thinner instead of adding the missing body.", "Assuming it is always a fault; a papery quality is sometimes wanted for a dry, delicate texture."], "scenario_contexts": ["A close-miked acoustic guitar recorded near the bridge sounds papery and needs low-mid support.", "A snare drum with the mic too close to the rim reads as papery and lacks fullness.", "A vocal captured through a thin small-diaphragm mic is described as papery in a mix note."]}, "23cd3f23-2b18-4ec7-8e7c-52a886229932": {"definition": "A timbral descriptor for sound band-limited to a narrow midrange, roughly 300 Hz to 3.4 kHz, so that it lacks deep lows and crisp highs and resembles speech heard over a traditional telephone line. This corresponds to the standard telephone voice band and is sometimes created deliberately as a 'telephone' or lo-fi effect.", "plain_english": "A phone-y sound has no deep lows and no bright highs, leaving only the middle. It sounds boxed-in and small, just like a voice coming through an old telephone.", "purpose_function": "The term names a sound squeezed into the telephone midrange band, flagging it either as a fault to correct or as a deliberate special effect an engineer can dial in.", "practical_application": "To make a vocal sound 'telephone', an engineer sets a band-pass filter that cuts below about 300 Hz and above about 3.4 kHz, often adding light distortion for realism.", "category": "Timbre Descriptor", "related_terms": ["nasal", "boxy", "thin", "midrange", "band-pass filter"], "common_mistakes": ["Assuming any thin sound is 'telephone'; the term specifically means midrange-only, cutting both the lows and the highs.", "Setting the passband far too wide, so the effect never gets the boxed-in telephone character.", "Forgetting that a bit of distortion is usually needed to sell a convincing telephone effect."], "scenario_contexts": ["Creating a deliberate telephone voice for a phone-call moment in a song or film.", "Describing a badly EQ'd voiceover that has lost its lows and highs.", "A cheap intercom or laptop speaker playback that sounds phone-y."]}, "b032f2d0-8c88-41bb-b8f2-9901e0b011f5": {"definition": "A timbral descriptor for sound with excessive, painfully sharp high-frequency energy, typically in the 2-5 kHz presence and lower-treble region, that feels penetrating and physically uncomfortable to the ear. It is a stronger, more negative relative of 'bright' or 'edgy'.", "plain_english": "A piercing sound has too much sharp high-frequency energy. It feels like it is stabbing your ears, the way a shrill whistle does.", "purpose_function": "The term flags a harsh, fatiguing high-frequency region that needs taming with EQ or level control before it tires the listener or damages the mix balance.", "practical_application": "An engineer hearing a piercing cymbal or vocal will notch or shelve the offending 2-5 kHz range, or apply a de-esser, to make long listening comfortable.", "category": "Timbre Descriptor", "related_terms": ["harsh", "shrill", "bright", "sibilance", "presence"], "common_mistakes": ["Confusing 'piercing' with 'bright'; bright can be pleasant, while piercing is painful and fatiguing.", "Cutting too wide a band to tame it, which dulls the whole sound instead of the narrow harsh region.", "Ignoring that a piercing tone causes listener fatigue and leads to poor mix decisions over a long session."], "scenario_contexts": ["A cymbal or hi-hat with a sharp spike near 3 kHz that hurts on loud playback.", "A vocal with harsh sibilance that becomes piercing when the level is pushed.", "A live PA tuned with too much presence that sounds piercing to the audience."]}, "42f191c1-a61a-428e-a883-06cdcc49c657": {"definition": "A timbral descriptor for a constricted, narrow tone that sounds squeezed and lacking in openness, width, and air, as though the sound is being forced through a small opening. It often results from an over-emphasized narrow midrange or heavy dynamic processing.", "plain_english": "A pinched sound is tight and narrow, like it is being squeezed through a small gap. It lacks the open, airy feel of a full, relaxed tone.", "purpose_function": "The term flags a closed, constricted quality so the engineer can open the sound back up with EQ, lighter compression, or better mic placement.", "practical_application": "Hearing a pinched vocal, an engineer might ease off a fast, heavy compressor and add some upper-frequency air to restore openness.", "category": "Timbre Descriptor", "related_terms": ["nasal", "boxy", "thin", "honky", "open"], "common_mistakes": ["Mistaking 'pinched' for 'warm'; pinched is narrow and closed, not full and rounded.", "Over-compressing a source into a pinched tone, then blaming the microphone.", "Trying to open a pinched sound with more level instead of EQ or lighter processing."], "scenario_contexts": ["A vocal squashed by a fast compressor that sounds pinched and lacks air.", "A guitar amp mic'd tight at the center of the cone giving a pinched, narrow tone.", "A mix bus with too much narrow midrange EQ that reads as pinched."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"d8656577-a9c3-4262-a484-282c15b64bde": {"definition": "A timbral descriptor for a sound with strong, well-defined transient impact and dynamic energy, especially in the low-mids, giving a solid sense of 'hit' or force. Punch depends on preserved transients and tight, controlled low-frequency dynamics rather than sheer loudness.", "plain_english": "A punchy sound hits hard and feels powerful, with a strong, clear kick to each beat. It is like a firm punch you can feel, not a soft tap.", "purpose_function": "The term describes the desirable sense of impact and drive an engineer aims for on drums, bass, and full mixes to make them feel energetic and solid.", "practical_application": "An engineer creates punch by setting compressor attack and release so transients pass through, and by tightening the low-mid region on kick, snare, and bass.", "category": "Timbre Descriptor", "related_terms": ["tight", "transient", "attack", "fat", "dynamics"], "common_mistakes": ["Confusing 'punchy' (strong transients and impact) with simply 'loud'.", "Over-compressing with too fast an attack, which flattens transients and kills the punch.", "Boosting only deep bass to get punch, when tight low-mids and preserved transients matter more."], "scenario_contexts": ["Shaping a kick drum with compression and transient control to make it punchy.", "Choosing a compressor attack setting that lets a snare stay punchy.", "A live mix note asking for a punchier bass guitar in the low-mids."]}, "b0f63e09-f6c1-491e-a729-d95cf3dfa65a": {"definition": "A mix instruction to add very-high-frequency content, the 'air' band above roughly 10 kHz, to open up a sound and give it a sense of sparkle, breath, and spaciousness. It is usually achieved with a high-shelf boost or a dedicated air-band EQ.", "plain_english": "This means add a little boost to the very highest frequencies. It opens the sound up and gives it a light, airy sparkle, like letting fresh air into a stuffy room.", "purpose_function": "The instruction directs the engineer to lift the top octave so a source sounds more open and detailed and sits with a modern, expensive-sounding sheen.", "practical_application": "Told to 'put air on it', an engineer applies a gentle high-shelf boost above about 10 kHz to a lead vocal or overheads to add openness.", "category": "Mix Instruction", "related_terms": ["airy", "bright", "presence", "open", "sparkle"], "common_mistakes": ["Boosting midrange instead of the very top; 'air' lives above about 10 kHz.", "Adding so much air that the sound becomes harsh or hissy.", "Trying to add air to a dull, band-limited source that has no high-frequency content to lift."], "scenario_contexts": ["Adding a high-shelf boost to open up a lead vocal.", "Brightening acoustic guitar or cymbal overheads to add sparkle.", "A mastering note asking to 'put air on it' for a more open top end."]}, "57e48908-151d-4ce3-9977-b67bd4dc138c": {"definition": "A mix instruction to make a sound more present, forward, and aggressive so it sits up front in the mix and grabs the listener's attention. It is typically achieved by raising level, boosting the presence range around 2-5 kHz, and reducing competing ambience or masking elements.", "plain_english": "This means push a sound to the front so it feels close and bold. It is like someone stepping right up to you instead of standing across the room.", "purpose_function": "The instruction directs the engineer to bring a key element forward so it dominates and feels immediate, usually for a lead vocal or featured instrument.", "practical_application": "To put a vocal in your face, an engineer raises its level, adds presence EQ, and pulls back reverb so it feels close and upfront.", "category": "Mix Instruction", "related_terms": ["present", "forward", "aggressive", "upfront", "presence"], "common_mistakes": ["Only raising the fader, when presence EQ and reduced ambience also create the forward feel.", "Making every element 'in your face', which leaves nothing sitting back and crowds the mix.", "Confusing forward presence with simply making the whole track louder."], "scenario_contexts": ["Pushing a lead vocal forward so it grabs attention in a pop mix.", "Making a rock guitar aggressive and upfront for an energetic section.", "A producer asking for a rap vocal to be right in your face over the beat."]}, "91de5d50-882f-4445-9e1a-48852555def3": {"definition": "A timbral descriptor for a honking, nasal midrange coloration with a pronounced peak roughly in the 500 Hz to 1 kHz region, giving a hollow, duck-like 'quack' quality. It is often caused by a resonant EQ peak, a wah-type filter, or certain compressor artifacts.", "plain_english": "A quacky sound has a honking, nasal midrange bump that sticks out. It has a hollow, duck-like tone, a bit like talking through cupped hands.", "purpose_function": "The term pinpoints an unwanted resonant midrange honk so the engineer can notch it out and restore a natural, balanced tone.", "practical_application": "Hearing a quacky guitar, an engineer sweeps a narrow EQ cut through the 500 Hz to 1 kHz range to find and reduce the resonant peak.", "category": "Timbre Descriptor", "related_terms": ["nasal", "honky", "boxy", "midrange", "resonant"], "common_mistakes": ["Confusing 'quacky' (nasal midrange honk) with 'bright' or 'harsh', which are higher-frequency traits.", "Leaving a resonant EQ or wah peak in place, then blaming the source instrument.", "Cutting too broadly and dulling the tone instead of notching the narrow quacky peak."], "scenario_contexts": ["A guitar played through a parked wah pedal that sounds quacky.", "A vocal with a resonant peak near 700 Hz that reads as quacky.", "A cheap speaker or small enclosure adding a quacky midrange coloration."]}, "0414fa42-aa7b-4bb6-9c79-39d5ba7e122f": {"definition": "A timbral descriptor for a rough, gritty, edgy tone carrying audible harmonic buzz or grain, usually in the upper midrange, resembling the sound of a rasp or file. It can arise from natural source distortion, harmonic saturation, or the onset of breakup.", "plain_english": "A raspy sound is rough and gritty, with a scratchy edge to it. It is like a voice that has gone hoarse, or the buzz of a file scraping wood.", "purpose_function": "The term describes an edgy, grainy character that can be a flaw to smooth out or a wanted texture to preserve, depending on the style.", "practical_application": "An engineer may keep a singer's natural rasp for attitude, or tame it with gentle EQ and saturation control when it turns unpleasant.", "category": "Timbre Descriptor", "related_terms": ["gritty", "edgy", "harsh", "rough", "distorted"], "common_mistakes": ["Confusing 'raspy' (rough grit and buzz) with 'bright' (clean treble detail).", "Adding heavy saturation to get rasp and pushing it into unpleasant distortion.", "Trying to remove all rasp with a de-esser, which targets sibilance rather than midrange grit."], "scenario_contexts": ["A hoarse or gritty vocal described as raspy in session notes.", "A saxophone or overdriven guitar with a natural raspy edge.", "A bass amp on the edge of breakup giving a raspy tone."]}, "4c1723f5-3735-442a-bda0-5aba2078fed1": {"definition": "A tonal descriptor for a frequency range, most often the midrange, that sits lower in level than the rest of the spectrum, so those frequencies sound set back and distant rather than forward and present.", "plain_english": "A recessed sound has part of its tone pushed back and quiet, usually the middle notes. It is like turning the middle notes down while the lows and highs stay up, so the mids sound set back and the rest stays present.", "purpose_function": "It flags a dip or pull-back in one part of the spectrum so an engineer knows those frequencies may need a lift to bring the sound forward.", "practical_application": "If a vocal or guitar sounds recessed in a mix, the engineer may add a few dB in the presence range around 1-4 kHz, or lower competing parts so it sits more forward.", "category": "Tonal Descriptor", "related_terms": ["forward", "presence", "scooped", "dull", "midrange"], "common_mistakes": ["Confusing recessed with simply quiet; it describes one frequency range sitting back, not the overall level being low.", "Boosting broadly across the whole spectrum instead of lifting the specific recessed range.", "Blaming the source when a scooped EQ curve or an off-axis mic is pulling the mids back."], "scenario_contexts": ["A lead vocal that sounds distant and set back behind the band.", "Describing headphones or speakers with a laid-back, recessed midrange.", "A guitar tone that disappears in the mix and needs its mids brought forward."]}, "af49d841-9106-48b2-8438-2b0e19fbef82": {"definition": "A tonal descriptor for a full, warm sound with dense and complex harmonic content, so the tone feels layered and full-bodied rather than thin or plain.", "plain_english": "A rich sound is full and warm, with lots of layers in the tone. Think of a thick soup with many tastes, not thin, plain water.", "purpose_function": "It describes pleasing harmonic fullness so engineers can judge whether a source has enough body and overtone complexity for the music.", "practical_application": "An engineer may call a well-recorded cello or analog synth rich, or reach for tube gear, saturation, or a fuller mic to add harmonic richness to a thin source.", "category": "Tonal Descriptor", "related_terms": ["warmth", "body", "full", "harmonics", "thin"], "common_mistakes": ["Confusing rich with loud; richness is harmonic fullness and body, not overall level.", "Adding heavy low-end boost to force richness and creating muddiness instead of real harmonic body.", "Assuming more saturation always adds richness, when too much turns pleasant overtones into harshness."], "scenario_contexts": ["Describing a full-bodied vocal or string tone with warm, complex overtones.", "Choosing a tube preamp to add harmonic richness to a thin digital source.", "Comparing a plain sine tone with a rich, harmonically full analog synth patch."]}, "3e02814d-3fae-46c7-8387-49cbe749ed25": {"definition": "A tonal descriptor for a coarse, grating, unsmooth texture in a sound; in psychoacoustics, roughness is the sensation produced by rapid amplitude fluctuations, strongest for modulation rates around 70 Hz, which the ear hears as harshness rather than distinct beats.", "plain_english": "A rough sound feels harsh and scratchy, not smooth. It is like the buzz you feel when two close notes clash and grind against each other.", "purpose_function": "It names a coarse, grinding texture so an engineer can trace it to fast amplitude changes, distortion, or clashing tones and decide how to smooth the sound.", "practical_application": "When a distorted synth or overdriven vocal sounds rough, an engineer may ease the drive, soften a harsh EQ peak, or fix beating between two closely tuned sources.", "category": "Tonal Descriptor", "related_terms": ["sandy / grainy", "harsh", "screechy", "smooth", "distortion"], "common_mistakes": ["Confusing roughness with normal distinct beats; roughness comes from much faster amplitude fluctuations that fuse into a harsh texture.", "Assuming rough always means faulty, when many gritty distorted tones are meant to sound rough.", "Chasing rough texture with EQ alone when the real cause is clipping or over-driven gain."], "scenario_contexts": ["A heavily distorted guitar or synth with a coarse, grinding edge.", "Two detuned oscillators or voices that beat fast enough to sound rough.", "A clipped or over-compressed signal that has lost its smoothness."]}, "422c7318-1830-4c42-84fa-f8e231bde853": {"definition": "A tonal descriptor for a smooth, warm sound with a gentle top end and strong fundamentals and low-mids, so the tone has no hard or harsh high-frequency edge.", "plain_english": "A round sound is smooth and warm, with no sharp or harsh edge on top. It is soft and easy on the ears, like the mellow tone of a cello.", "purpose_function": "It describes a soft, edge-free tone so engineers can judge whether a source needs its harsh highs tamed or its low-mids supported to feel rounder.", "practical_application": "An engineer may call a mellow bass or vocal round, or gently roll off harsh highs and support the low-mids to give a sharp-sounding source a rounder character.", "category": "Tonal Descriptor", "related_terms": ["warmth", "smooth", "full", "harsh", "dark"], "common_mistakes": ["Confusing round with dull; round keeps a smooth, pleasant top end, while dull loses the highs entirely.", "Rolling off too much high frequency chasing roundness and making the sound muffled.", "Assuming round means weak, when a round tone can still be full and powerful in the low-mids."], "scenario_contexts": ["Describing a warm, smooth upright bass or cello tone.", "Softening a harsh vocal so it sounds rounder and easier to listen to.", "Comparing an edgy solid-state tone with a rounder tube-amp sound."]}, "eb9d429b-60bc-4ea3-9a06-75a02838d34f": {"definition": "A tonal descriptor for a gritty, granular texture in which a sound seems made of many small rough particles rather than being smooth and continuous, often caused by distortion, low bit-depth quantization, or high-frequency intermodulation.", "plain_english": "A grainy sound feels gritty, like it is made of tiny rough bits. It is like a photo full of specks instead of a clean, smooth picture.", "purpose_function": "It names a granular, unsmooth texture so an engineer can trace it to distortion, low-resolution processing, or converter issues and work to smooth it.", "practical_application": "When a track sounds grainy, an engineer may check for low bit-depth files, harsh digital plug-ins, or over-driven gain, then dither properly or ease the processing.", "category": "Tonal Descriptor", "related_terms": ["rough", "harsh", "smooth", "quantization noise", "distortion"], "common_mistakes": ["Confusing grainy texture with broadband hiss; graininess is a gritty quality tied to the signal, not steady background noise.", "Overlooking low bit-depth or missing dither as a cause of a grainy, granular top end.", "Boosting highs to add detail and only making the grainy texture more obvious."], "scenario_contexts": ["A low bit-depth or heavily processed sample that sounds gritty and granular.", "A cheap converter or plug-in that adds a sandy texture to the high end.", "An over-driven guitar tone with a coarse, grainy character."]}, "00d38e2b-7f6f-4317-8e41-3f9d650578d3": {"definition": "A tonal descriptor for a frequency balance in which the midrange is cut while the lows and highs are emphasized, producing a smiley-face response curve; the classic example is the scooped-mid metal guitar tone.", "plain_english": "A scooped sound has its middle tones turned down while the lows and highs stay up. On a graph the curve dips in the middle and smiles up at each end.", "purpose_function": "It describes a deliberate or accidental mid dip so engineers know the midrange is reduced and can decide whether that helps or hurts the sound.", "practical_application": "A guitarist may scoop the mids around 500-800 Hz for a heavy solo tone, though engineers often add mids back so the part still cuts through a full band mix.", "category": "Tonal Descriptor", "related_terms": ["recessed", "midrange", "smiley EQ", "presence", "forward"], "common_mistakes": ["Scooping mids so hard that the instrument disappears in a full band mix, since the midrange is where it competes for space.", "Confusing scooped with recessed; scooped is a deliberate mid cut with boosted ends, while recessed just means one range sits back.", "Judging a scooped tone alone in isolation, where it sounds huge, then finding it vanishes in the mix."], "scenario_contexts": ["A metal rhythm guitar dialed in with deeply scooped mids.", "A graphic EQ set in a smiley-face curve that scoops the midrange.", "Describing a hi-fi speaker with a mid dip that flatters vocals-light material."]}, "3fd51222-4886-4bd0-91d3-27182b9ac027": {"definition": "A tonal descriptor for an unpleasant, piercing, shrill quality caused by excessive or peaky upper-midrange and high-frequency energy (roughly 2-6 kHz and above), which makes a sound sharp and painful to hear.", "plain_english": "A screechy sound is sharp and piercing, and it hurts to hear. It is like nails on a chalkboard or a loud, shrill whistle.", "purpose_function": "It flags a harsh, ear-piercing peak so an engineer knows to hunt for and cut the offending upper-mid or high-frequency resonance.", "practical_application": "When a violin, cymbal, or vocal turns screechy, an engineer sweeps a narrow EQ to find the harsh peak around 2-6 kHz and cuts it, or tames feedback in a live rig.", "category": "Tonal Descriptor", "related_terms": ["harsh", "sibilance", "Brittle", "presence", "feedback"], "common_mistakes": ["Cutting broadly across the whole top end and dulling the sound instead of notching the single screechy peak.", "Confusing screechy with simply bright; bright is pleasant detail, while screechy is painful and shrill.", "UNSAFE: pushing a screeching live system louder to hear over feedback, risking hearing damage and speaker failure instead of cutting the gain."], "scenario_contexts": ["A live mic ringing toward feedback with a shrill, screechy edge.", "A cheap cymbal or violin recording with a harsh, piercing top end.", "A vocal with strong sibilance that sounds screechy on loud speakers."]}, "f32125d5-df08-4682-9644-65d82e19df89": {"definition": "A tonal descriptor for a smooth, glossy high-frequency brightness, a pleasant airy brilliance in the upper treble (roughly above 8-10 kHz) that adds polish and shine without harshness.", "plain_english": "Sheen is a smooth, shiny brightness on the top of a sound. It is like the soft gleam on a polished surface, adding a bit of sparkle.", "purpose_function": "It describes a flattering top-end gloss so engineers can decide whether a track needs a gentle high lift to add shine and polish.", "practical_application": "An engineer may add a broad high-shelf boost above 10 kHz, or use an exciter or a bright ribbon or condenser mic, to give vocals or cymbals a pleasing sheen.", "category": "Tonal Descriptor", "related_terms": ["Airy", "sparkle", "Bright", "presence", "high shelf"], "common_mistakes": ["Confusing sheen with harshness; sheen is smooth high-frequency gloss, not a sharp, peaky top end.", "Over-boosting the extreme highs to force sheen and raising hiss and sibilance instead.", "Expecting band-limited or dull gear to reproduce sheen it cannot actually pass."], "scenario_contexts": ["A polished pop vocal with a smooth, glossy top end.", "Adding a gentle high-shelf lift to give cymbals a pleasing sheen.", "Choosing a bright condenser mic known for adding sheen to acoustic guitar."]}, "208aaae5-4f9a-4bde-8a49-b08c3eded48b": {"definition": "A tonal descriptor for a bright, sparkling high-frequency character with a sense of movement and liveliness, as heard in cymbals, bells, or shimmer-style reverb effects, giving an airy, glistening top end.", "plain_english": "A shimmering sound is bright and sparkly, with a lively glow that seems to move. Think of the airy ring of cymbals catching the light.", "purpose_function": "It describes a lively, moving top-end sparkle so engineers can judge whether a source or effect adds the glistening high-frequency motion the music wants.", "practical_application": "An engineer may keep a cymbal's shimmering decay, add a shimmer reverb that pitches reflections up an octave, or lift the air band to enhance a glistening top end.", "category": "Tonal Descriptor", "related_terms": ["Airy", "sparkle", "sheen", "Bright", "reverb"], "common_mistakes": ["Confusing shimmering with static brightness; shimmering implies movement and sparkle, not just a fixed high-frequency boost.", "Over-lifting the top end to force shimmer and making the sound harsh and hissy.", "Drowning a mix in shimmer reverb so it loses focus and clarity."], "scenario_contexts": ["Describing the airy, glistening decay of ride and crash cymbals.", "Adding a shimmer reverb to a pad or guitar for a bright, moving wash.", "A vocal or synth with a lively, sparkling top end that catches the ear."]}, "21199af6-b66d-49b5-aa6f-f1f77ca7689d": {"definition": "A subjective timbre descriptor for a smooth, refined high-frequency character (roughly 5-20 kHz) that stays detailed yet free of harshness, grain, edge, or sibilance, giving the treble a soft, flowing quality.", "plain_english": "\"Silky\" means the high notes sound smooth and easy on the ears, with no harsh or scratchy edge. It is like the difference between rough cloth and soft silk.", "purpose_function": "It names a desirable treble quality so engineers can aim for detailed highs without listener fatigue. It exists to describe the goal of clear yet gentle high frequencies.", "practical_application": "An engineer may call a vocal or cymbal \"silky\" after gentle high-shelf EQ, de-essing, or a smooth-sounding mic or preamp, and the word guides gear and EQ choices toward non-fatiguing highs.", "category": "Timbre Descriptor", "related_terms": ["Smooth", "Sweet", "Bright", "Harsh", "Sibilant", "Air"], "common_mistakes": ["Assuming 'silky' just means more treble; boosting highs can add harshness, which is the opposite of silky.", "Confusing 'silky' (smooth, refined highs) with 'dull' (highs rolled off and lacking detail).", "Thinking any bright sound is silky, when brightness full of peaks and edge is not silky at all."], "scenario_contexts": ["Describing a lead vocal after gentle de-essing and a smooth high shelf.", "Praising the top end of a well-designed condenser or ribbon mic.", "Choosing a converter or preamp said to have 'silky' highs for strings or acoustic guitar."]}, "8b07767f-77e7-4280-a4ea-d485fde1ea09": {"definition": "A mixing descriptor meaning a sound sits clearly at or near the front and upper layer of a mix, audible above the surrounding elements rather than buried within or beneath them.", "plain_english": "If a sound \"sits on top,\" you can hear it clearly above everything else in the song. It floats on the surface instead of hiding underneath.", "purpose_function": "It describes good foreground placement in the mix balance so a key part, often the lead vocal, stays present and easy to follow. It exists to talk about where an element lives in the mix's level and front-to-back hierarchy.", "practical_application": "An engineer raises a fader, adds presence-range EQ, or uses light compression so a vocal sits on top of the band without being buried or too loud.", "category": "Mix Placement", "related_terms": ["Presence", "Upfront", "Buried", "Balance", "Punchy", "Cut through"], "common_mistakes": ["Just cranking the fader to make something sit on top, which throws off the overall balance instead of using EQ and compression.", "Confusing 'sits on top' (correct foreground balance) with simply being too loud.", "Forgetting that carving space in competing tracks can help an element sit on top better than boosting it."], "scenario_contexts": ["Getting a lead vocal to sit on top of a dense rock arrangement.", "Placing a lead synth so it sits on top of pads and rhythm parts.", "Balancing a snare so its crack sits on top of the drum bus."]}, "75eb023a-728d-4057-817c-1e6b9dacf3b2": {"definition": "A subjective descriptor for sound with strong, aggressive dynamic impact, a powerful wall-of-sound punch, usually from drums or a heavily compressed mix, that hits the listener with force.", "plain_english": "\"Slammy\" means the sound hits hard and feels powerful, like a punch you can feel in your chest. It often comes from heavy compression on drums.", "purpose_function": "It names the sensation of forceful impact and loudness-driven energy, helping engineers describe an aggressive, high-impact target sound. It exists to capture the wallop a mix or drum sound delivers.", "practical_application": "An engineer uses heavy bus or parallel compression plus level to make drums slammy for rock, hip-hop, or EDM, trading some dynamic range for perceived power.", "category": "Dynamics Descriptor", "related_terms": ["Punchy", "Slam", "Compression", "Tight", "Aggressive", "Parallel compression"], "common_mistakes": ["UNSAFE: Chasing a 'slammy' sound by pushing monitors to very high SPL for long stretches risks hearing damage; keep to safe listening levels and take breaks.", "Over-compressing for slam until the mix becomes flat, lifeless, and fatiguing.", "Confusing 'slammy' (aggressive impact) with simply loud; slam is about impact, not just level."], "scenario_contexts": ["Making a rock drum bus slammy with parallel compression.", "Getting a hip-hop beat to hit slammy on club systems.", "Describing an aggressively compressed master that slams."]}, "999bdba8-456b-425b-a3d2-c9940c41cab1": {"definition": "A subjective descriptor for a loose, imprecise sound that lacks tightness, showing smeared or ill-defined transients, poor timing, or an uncontrolled, boomy low end; it is the opposite of \"tight.\"", "plain_english": "\"Sloppy\" means the sound is loose and messy, not clean and controlled. Notes or beats feel smeared together or slightly out of time.", "purpose_function": "It flags a lack of rhythmic and transient control so the problem can be fixed. It works as the negative counterpart to \"tight,\" pointing to timing or low end that needs cleaning up.", "practical_application": "On the job a sloppy low end is tightened with EQ, gating, or shorter reverb, while sloppy timing may be fixed by editing, quantizing, or re-tracking.", "category": "Timing Descriptor", "related_terms": ["Tight", "Smeared", "Boomy", "Muddy", "Transient", "Loose"], "common_mistakes": ["Blaming EQ for a sloppy low end when the real cause is loose playing or timing that editing must fix.", "Confusing 'sloppy' (loose and uncontrolled) with 'warm' (full but still defined low end).", "Over-gating to fix sloppiness and cutting off the natural sustain of notes."], "scenario_contexts": ["A bass part that sounds sloppy because notes ring into each other.", "A live kick that is sloppy and boomy in a resonant room.", "Describing a rhythm section that plays slightly loose or sloppy."]}, "d4893a8b-c25f-4dad-90e4-de7e3220fbc0": {"definition": "The blurring or loss of detail and transient definition in a sound, in which distinct events or stereo images run together in time or space; it is commonly caused by phase problems, resonance, excess reverb, or time-domain processing artifacts.", "plain_english": "\"Smear\" is when sounds blur together and lose their sharp edges, like a photo that is slightly out of focus. Fine detail and clear timing get lost.", "purpose_function": "It names a loss of clarity so its cause can be found and reduced. It exists to describe blurred transients or imaging that make a mix less clear and detailed.", "practical_application": "A technician traces smear to phase misalignment, room resonance, heavy reverb, or linear-phase EQ pre-ringing, then corrects timing, damping, or processing to restore focus.", "category": "Transient Descriptor", "related_terms": ["Smeary", "Smooth", "Tight", "Transient", "Phase", "Definition"], "common_mistakes": ["Adding lots of reverb without noticing that it smears transients and blurs the mix.", "Assuming all EQ is neutral, when linear-phase EQ can smear transients through pre-ringing.", "Confusing time smear (blurred transients) with a simple loss of high frequencies."], "scenario_contexts": ["Transients smearing after heavy linear-phase EQ or convolution reverb.", "Stereo image smear from a phase problem between two mics.", "Low-end smear caused by room resonance blurring bass notes together."]}, "a9ae33b3-6628-40a3-919d-ae6e4ebde27d": {"definition": "A subjective descriptor for sound that exhibits smear, with blurred, poorly defined transients or imaging, so detail and clarity are lost and events run together instead of sounding distinct.", "plain_english": "\"Smeary\" describes a blurry sound where details run together and nothing is sharp. It is the fuzzy look of a smudged window, but for your ears.", "purpose_function": "It describes the audible result of smearing so engineers can flag and reduce it. It exists to label a lack of transient and spatial focus.", "practical_application": "When a mix sounds smeary, a technician reduces reverb, fixes phase, or avoids pre-ringing EQ to sharpen transients and tighten imaging.", "category": "Transient Descriptor", "related_terms": ["Smear", "Tight", "Smooth", "Muddy", "Transient", "Focus"], "common_mistakes": ["Treating a smeary mix with more EQ when the real fix is less reverb or better phase alignment.", "Confusing 'smeary' (blurred detail, a fault) with 'smooth' (pleasantly non-harsh, a good thing).", "Not checking in mono, which can reveal phase-related smear that is hidden in stereo."], "scenario_contexts": ["A vocal that turns smeary under too much plate reverb.", "A drum bus sounding smeary after aggressive time-domain processing.", "Bass and kick sounding smeary together because their transients overlap."]}, "267026cb-d0e2-479e-a9d9-53dbbee05ad2": {"definition": "A subjective descriptor for sound that is easy on the ears and free of harshness, with a flat, even frequency response lacking sharp peaks or dips and with low distortion, especially through the midrange and highs.", "plain_english": "\"Smooth\" sound has no harsh or jagged edges. It is easy to listen to for a long time, like a flat, even road with no bumps.", "purpose_function": "It describes an even, non-fatiguing tonal balance that engineers often aim for. It exists to capture the goal of clean response without harsh peaks.", "practical_application": "An engineer smooths a track by taming resonant peaks with EQ, lowering distortion, and choosing gear with even response, making it pleasant over long listening.", "category": "Timbre Descriptor", "related_terms": ["Silky", "Sweet", "Harsh", "Bright", "Warm", "Flat"], "common_mistakes": ["Thinking smooth means dull; smooth keeps detail while removing harshness, but dull loses the highs.", "Over-smoothing until the mix loses life, presence, and definition.", "Confusing a smooth, even response with a scooped one that has real dips in it."], "scenario_contexts": ["Taming a harsh peak near 3 kHz to make a vocal smooth.", "Choosing a smooth-sounding EQ or preamp for strings.", "Describing a well-balanced master that plays smoothly on many systems."]}, "add482a0-f4e5-42c9-8a17-ba02d6af25a2": {"definition": "A subjective descriptor for sound with fast, well-defined transient attack, a quick and crisp initial snap, typically on drums (especially the snare) or plucked and percussive sounds, giving a tight, articulate leading edge.", "plain_english": "\"Snappy\" means the start of each hit is quick and sharp, like the snap of your fingers. You clearly hear the crack at the front of the sound.", "purpose_function": "It highlights a strong, fast transient so engineers can dial in punch and articulation. It exists to describe a crisp attack that helps a sound cut through and feel tight.", "practical_application": "An engineer makes a snare snappy with transient shaping, attack-preserving compression, or a small boost around 2-5 kHz, keeping the initial crack intact.", "category": "Transient Descriptor", "related_terms": ["Punchy", "Tight", "Transient", "Attack", "Crisp", "Smeared"], "common_mistakes": ["Using a fast compressor attack that clamps the transient and kills the snap.", "Confusing 'snappy' (a fast transient) with 'bright' (extra high-frequency content); they are not the same.", "Boosting highs to fake snap instead of preserving the real transient."], "scenario_contexts": ["Shaping a snare to be snappy with a transient designer.", "Getting a funk bass to sound snappy and articulate.", "Keeping drum overheads snappy by using a slow compressor attack."]}, "49dbea99-c131-4da9-8769-07d58b433e24": {"definition": "A subjective descriptor for a bright, percussive, aggressive transient character, a sharp upper-midrange snap or slap, most often applied to funk or clean electric guitar, snare, or slap bass, combining a crisp attack with cutting brightness.", "plain_english": "\"Spanky\" means a sharp, bright, slapping attack, like the crack of a funk guitar chord. The sound has a quick, cutting snap to it.", "purpose_function": "It describes a lively, cutting mix of transient and brightness that helps percussive parts pop in a mix. It exists to name the spank of aggressive, bright attacks.", "practical_application": "An engineer gets a clean funk guitar or slap bass spanky with upper-mid and high EQ plus attack-preserving dynamics so it cuts through the groove.", "category": "Transient Descriptor", "related_terms": ["Snappy", "Punchy", "Bright", "Attack", "Crisp", "Transient"], "common_mistakes": ["Adding too much high EQ for spank until the part becomes harsh and thin.", "Confusing 'spanky' (a bright percussive attack) with 'warm' (full, rounded low-mids).", "Over-compressing and removing the very attack that makes a part spanky."], "scenario_contexts": ["Dialing a clean funk guitar to be spanky in the mix.", "Getting slap bass to sound spanky and cut through.", "Describing a bright, aggressive snare as spanky."]}, "f1fb9fb7-13cb-4ba4-ab5f-061112823828": {"definition": "A positive tonal descriptor for the presence of clean, extended high-frequency content, roughly above 10 kHz, that lends a recording air, brilliance and fine detail without edginess or harshness.", "plain_english": "A sparkling sound has clear, airy highs, like the shimmer of a cymbal or a small bell. It sounds bright and full of detail, but not harsh.", "purpose_function": "It communicates a desirable sense of top-end openness and detail, guiding EQ and microphone choices toward capturing or restoring high-frequency air.", "practical_application": "An engineer adds sparkle with a gentle high-shelf boost around 10 to 15 kHz, an air-band EQ, or a brighter condenser mic on sources such as acoustic guitar, cymbals or vocals.", "category": "Tonal Descriptor", "related_terms": ["Air", "Bright", "Brilliance", "Presence", "Sibilance", "High-shelf"], "common_mistakes": ["Confusing pleasant sparkle with harshness or sibilance, then boosting highs until the sound turns edgy", "Adding high-frequency boost to a dull source that lacks the content, only raising hiss and noise", "Assuming more sparkle is always better, ignoring how excess top end fatigues listeners"], "scenario_contexts": ["A producer asks for more sparkle on an acoustic guitar so it cuts through a dense mix", "Restoring air to a dull vocal recorded with a dark microphone", "Adding shimmer to drum overheads so cymbals sound open and detailed"]}, "599da359-739a-4814-b733-30eaf1e16cc0": {"definition": "A negative tonal descriptor for a harsh, spitting quality in the upper-midrange and high frequencies, typically exaggerated sibilance or plosive and transient artifacts in the region of roughly 4 to 8 kHz.", "plain_english": "A spitty sound has harsh, spitting 'sss' and 'tss' noises in the highs. It often comes from too much treble, a cheap mic, or heavy data compression.", "purpose_function": "It flags an unpleasant, aggressive top-end fault so it can be tamed, pointing the engineer toward de-essing or a narrow EQ cut.", "practical_application": "A technician who hears spitty consonants on a vocal applies a de-esser or a narrow cut around 5 to 8 kHz, swaps a harsh microphone, or checks for lossy-codec artifacts.", "category": "Tonal Descriptor", "related_terms": ["Sibilance", "Harsh", "De-esser", "Presence", "Brittle", "Edgy"], "common_mistakes": ["Fixing spittiness with a broad high cut that dulls the whole sound instead of a narrow, targeted cut", "Over-de-essing until the vocal lisps and loses clarity", "Blaming the mic when the real cause is a plosive pop or a lossy codec artifact"], "scenario_contexts": ["A lead vocal sounds spitty on loud 's' and 't' sounds and needs de-essing", "A speech track through an aggressive codec develops a spitty high end", "A cheap condenser makes an already bright singer sound spitty in the presence range"]}, "92bfcb07-4b75-444d-8bee-537816451f05": {"definition": "A negative tonal descriptor for an uncontrolled, distorted or smeared transient, most often on drums or cymbals, where the attack splatters rather than staying focused; commonly a symptom of over-compression, clipping or overdriven transients.", "plain_english": "A splatty sound is when a drum hit smears out instead of staying sharp and clean. It usually means the sound was pushed too hard or squashed too much.", "purpose_function": "It identifies a loss of transient control or the onset of distortion so the engineer can back off compression, gain or limiting.", "practical_application": "When a snare or cymbal sounds splatty, a technician lowers compressor ratio or input gain, checks for clipping in the chain, and restores a cleaner, more defined attack.", "category": "Tonal Descriptor", "related_terms": ["Transient", "Compression", "Clipping", "Distortion", "Attack", "Punch"], "common_mistakes": ["Pushing a limiter or clipper too hard on drums until transients splatter and lose punch", "Mistaking gain-stage clipping for a creative effect and leaving audible distortion in the mix", "Over-compressing the drum bus so every hit smears together"], "scenario_contexts": ["A heavily limited drum bus makes snare hits sound splatty on loud sections", "Cymbals distort and splatter after too much brickwall limiting in mastering", "An overdriven preamp adds a splatty edge to a close-miked snare"]}, "e58edcc9-1b2c-46f7-b07e-5a9e4491144c": {"definition": "A tonal descriptor, usually mildly negative, for a sound that is technically clean and accurate but lacks warmth, harmonic richness or emotional character; often associated with clinical, over-processed or early digital reproduction.", "plain_english": "A sterile sound is very clean but cold and lifeless. It is correct, yet it lacks warmth and feeling, like a room with no character.", "purpose_function": "It signals that a source or system, though free of obvious faults, feels lifeless, prompting the addition of warmth, saturation or ambience.", "practical_application": "To counter a sterile mix, an engineer may add analogue-style saturation, subtle harmonic distortion, room ambience or gentle low-mid warmth to reintroduce character.", "category": "Tonal Descriptor", "related_terms": ["Warmth", "Clinical", "Coloration", "Saturation", "Harmonics", "Dry"], "common_mistakes": ["Chasing so much technical cleanliness that the mix ends up sterile and dull", "Treating all added harmonics or noise as faults to remove, stripping out useful character", "Confusing a sterile source with an accurate, neutral monitor and 'fixing' the monitoring instead"], "scenario_contexts": ["A fully in-the-box mix sounds sterile and the producer wants analogue warmth added", "An early digital recording feels sterile compared with its tape counterpart", "A vocal captured in a dead, dry booth sounds sterile and needs ambience"]}, "5adda4ec-f723-4bd6-833d-c27d7719cd57": {"definition": "A common studio instruction to reduce excess low-midrange energy, typically in the region of roughly 200 to 500 Hz, that makes a source or mix sound muddy, boxy or congested; usually accomplished with an EQ cut in that band.", "plain_english": "This means cutting the low-middle tones that make a mix sound thick and cloudy. Doing this helps each part sound clearer.", "purpose_function": "It directs the engineer to clear low-mid buildup so individual parts gain definition and the mix sounds more open.", "practical_application": "A technician sweeps a narrow EQ boost to find the offending frequency around 250 to 400 Hz, then cuts it on guitars, piano or the mix bus to take the mud out.", "category": "EQ Instruction", "related_terms": ["Muddy", "Boxy", "Low-mids", "Equalization", "Masking", "Clarity"], "common_mistakes": ["Cutting too much low-mid so the sound becomes thin and loses warmth and body", "Cutting the same 300 Hz band on every track, hollowing out the whole mix", "Trying to fix muddiness with more high boost instead of removing the low-mid cause"], "scenario_contexts": ["A dense rock mix sounds muddy and the producer says to take the mud out of the rhythm guitars", "A boomy vocal recorded close to a mic needs low-mids cut for clarity", "A piano masks the bass, so the engineer clears low-mid mud to separate them"]}, "d2fc545c-8301-4691-8065-86326403de43": {"definition": "A negative tonal descriptor for a sound lacking low-frequency and low-mid body or fundamental energy, so it seems weak, lightweight and lacking fullness; the opposite of full, warm or fat.", "plain_english": "A thin sound is missing its low notes and body, so it feels weak and small. It is like a voice heard through a cheap phone speaker.", "purpose_function": "It flags a deficiency of low-end weight so the engineer can add body, adjust mic placement, or ease off excessive high-pass filtering.", "practical_application": "When a guitar or vocal sounds thin, a technician boosts low-mids around 100 to 250 Hz, moves the mic closer for proximity effect, or backs off an aggressive low cut.", "category": "Tonal Descriptor", "related_terms": ["Full", "Warmth", "Body", "Proximity effect", "High-pass filter", "Fundamental"], "common_mistakes": ["High-passing too aggressively on every channel until sources sound thin", "Confusing a thin source with good clarity and leaving it weak in the mix", "Adding low-mid boost to fix thinness until the sound becomes muddy instead"], "scenario_contexts": ["A DI electric guitar sounds thin and needs low-mid weight added", "A vocal recorded far from the mic loses body and sounds thin", "Over-aggressive low cuts on a live console leave the whole band sounding thin"]}, "e1bcd784-8349-4546-974a-06ac4db0214b": {"definition": "A tonal descriptor for a sound dominated by a strong, emphasized low-frequency thump or punch, typically the impact of a kick drum or bass in the region of roughly 50 to 100 Hz; positive when it means solid punch, negative when it means boomy or one-note.", "plain_english": "A thumpy sound has a strong, heavy low punch, like the thud of a kick drum you feel in your chest.", "purpose_function": "It describes the weight and impact of the low end, guiding decisions about kick and bass level, EQ and dynamics.", "practical_application": "An engineer may EQ a kick to be more thumpy by boosting around 60 to 80 Hz, or tame an over-thumpy low end that is masking the bass and clouding the mix.", "category": "Tonal Descriptor", "related_terms": ["Punch", "Boomy", "Low end", "Kick drum", "Sub-bass", "Tight"], "common_mistakes": ["Boosting kick thump so much it masks the bass guitar and muddies the low end", "Judging thump on small speakers that cannot reproduce those frequencies", "Confusing useful thump with uncontrolled room boom or resonance"], "scenario_contexts": ["A dance kick needs to be thumpy so listeners feel it on a club system", "A live kick drum sounds too thumpy and boomy and needs low-end control", "Adding thump to a lightweight kick to give it more impact in a rock mix"]}, "44de79c7-fcd0-403d-9f8c-b121816b710a": {"definition": "A positive tonal descriptor for a well-controlled, focused low end and transients with no boom, ringing or sloppy decay; also applied to rhythmic precision where parts lock cleanly together.", "plain_english": "A tight sound has a firm, controlled low end with no boom or ringing. The notes start and stop cleanly.", "purpose_function": "It signals control and definition in the low end and timing, guiding EQ, damping, gating and dynamics choices toward a clean, focused result.", "practical_application": "A technician tightens low end by cutting boomy resonances, damping a drum, gating decay, or high-passing rumble so notes and hits start and stop cleanly.", "category": "Tonal Descriptor", "related_terms": ["Punch", "Boomy", "Gate", "Damping", "Transient", "Low end"], "common_mistakes": ["Over-tightening with heavy gating so the low end sounds unnatural and choppy", "Assuming tight always means better and stripping away useful sustain and warmth", "Confusing a tight source with one that is simply thin or lacking low-end weight"], "scenario_contexts": ["A bass and kick are aligned and EQ'd so the low end sounds tight together", "A boomy live-stage low end is tightened with high-pass filters and EQ cuts", "A drum kit is damped and gated to give a tighter, more controlled sound"]}, "68b246ca-6ea2-4317-b0bc-e2e5820a8006": {"definition": "A studio and live-sound instruction to make a sound, usually the low end, more controlled and focused, for example by cutting boomy or excessive low frequencies, shortening reverb, damping resonance, or improving rhythmic timing.", "plain_english": "This means making the low end more firm and controlled. You cut boomy low notes or shorten long echoes so the sound is clean.", "purpose_function": "It directs the engineer to reduce looseness, boom or smear so the result sounds cleaner and more defined.", "practical_application": "In response, a technician may high-pass rumble, cut a boomy resonance, gate a ringing drum, or shorten a long reverb tail to tighten the sound.", "category": "Mix Instruction", "related_terms": ["Tight", "Boomy", "High-pass filter", "Gate", "Reverb", "Low end"], "common_mistakes": ["Over-tightening until the sound loses natural weight and sustain", "Only cutting lows when the real looseness is a timing or performance issue", "Applying heavy gating that chops the sound unnaturally"], "scenario_contexts": ["A mix engineer is told to tighten up a boomy bass so it sits cleanly with the kick", "A front-of-house engineer tightens up a loose, resonant stage low end", "A producer asks to tighten up a ringing tom by damping and gating it"]}, "0d035d58-8ca4-4a83-96a4-bd1b35d920af": {"definition": "A tonal descriptor for a boomy, boxy sound caused by excessive resonance in the low-mid range, roughly 150 to 400 Hz, giving a hollow, enclosed quality as if the sound were made inside a small box or tub.", "plain_english": "A tubby sound is boomy and boxy, with too much low-middle tone. It sounds a bit like talking inside an empty cardboard box.", "purpose_function": "It flags a build-up of unwanted low-mid resonance so an engineer knows to cut those frequencies for a clearer, more open tone.", "practical_application": "An engineer hearing a tubby kick, tom, or vocal will sweep an EQ to find and cut the offending low-mid frequencies, often around 200 to 400 Hz.", "category": "Tonal Descriptor", "related_terms": ["boxy", "boomy", "muddy", "woolly", "low-mids"], "common_mistakes": ["Confusing tubby with warm; warmth is pleasant fullness, while tubby is an unwanted boxy resonance.", "Boosting low-mids for body and pushing a source into tubbiness.", "Cutting far too wide a band to fix tubbiness and thinning out the whole tone."], "scenario_contexts": ["A kick drum recorded in a small untreated room sounding boxy and tubby.", "A vocal on a cheap microphone with a boomy low-mid build-up.", "Taming a tom that rings with a hollow, tubby resonance."]}, "2e58d074-864e-48f0-9aad-e2f6842a9230": {"definition": "A tonal descriptor for a sound that lacks high-frequency clarity and detail, as if a thin cover were placed over it, making it dull, distant, and slightly muffled.", "plain_english": "A veiled sound is missing its clear, detailed highs. It sounds like music playing behind a thin curtain, a little dull and far away.", "purpose_function": "It describes a loss of top-end openness and detail so an engineer can judge whether a source needs high-frequency lift or a cleaner signal path.", "practical_application": "An engineer may call a dull microphone or a covered vocal veiled, then add gentle high-shelf EQ or change mic position to restore clarity.", "category": "Tonal Descriptor", "related_terms": ["dark", "dull", "muffled", "airy", "presence"], "common_mistakes": ["Confusing veiled with warm; warm is pleasant, while veiled means a loss of wanted detail.", "Boosting highs harshly to lift a veiled sound and adding harshness instead of clarity.", "Blaming the source when a dirty pop filter, foam, or off-axis mic is veiling the sound."], "scenario_contexts": ["A vocal that sounds dull and covered through a worn or cheap microphone.", "Comparing a clear reference monitor with a veiled one that hides detail.", "A guitar tone that loses air and detail after heavy low-pass filtering."]}, "b3fc1c3b-a593-4c9f-adfe-50401dadd3e7": {"definition": "A subjective descriptor for a sound or recording with a strong, appealing mood or atmosphere, often coming from characterful gear, room sound, or slight imperfections rather than clinical accuracy.", "plain_english": "A vibey sound has a strong mood or feel that pulls you in. It is not perfectly clean, but it has character, like an old photo with a warm, moody look.", "purpose_function": "It describes emotional character and atmosphere so an engineer can aim for feel and mood, not just technical cleanness.", "practical_application": "An engineer chasing a vibey take may use vintage gear, room mics, tape, or a looser performance instead of a polished, sterile sound.", "category": "Timbre Descriptor", "related_terms": ["vintage", "warm", "character", "coloration", "lo-fi"], "common_mistakes": ["Treating vibey as a fixed EQ setting instead of an overall mood created by many choices.", "Adding noise or effects to fake a vibe and burying the actual performance.", "Assuming vibey means low quality, when a vibey sound is a deliberate creative choice."], "scenario_contexts": ["Using room mics and tape to give a live band recording a vibey feel.", "Choosing an old characterful microphone for a moody vocal.", "Keeping a slightly imperfect take because it feels more vibey than a clean one."]}, "2dff1460-6968-4268-98e0-9c6e3cea78f8": {"definition": "A subjective descriptor for a sound with the character of older analog equipment, marked by tube warmth, tape saturation, gentle harmonic coloration, and a slightly reduced, smoothed frequency range.", "plain_english": "A vintage sound copies the warm, colored tone of old analog gear. It is smooth and a little soft on the edges, like a classic record from decades ago.", "purpose_function": "It describes desirable old-school coloration so an engineer can recreate the warmth and character of classic analog recordings.", "practical_application": "An engineer wanting a vintage tone may use tube gear, tape emulation, or classic-style plug-ins to add warmth, saturation, and gentle high-end roll-off.", "category": "Timbre Descriptor", "related_terms": ["warm", "saturation", "tube", "tape", "coloration"], "common_mistakes": ["Assuming vintage always sounds better, when old-style coloration can hurt clarity in a modern mix.", "Confusing vintage with simply dark; vintage adds harmonic character, not only reduced highs.", "Stacking many vintage emulations and muddying the mix with too much coloration."], "scenario_contexts": ["Using a tape emulation to give a modern drum bus a vintage feel.", "Choosing a classic-style tube compressor for a vintage vocal sound.", "Recreating a 1960s tone with reduced bandwidth and gentle saturation."]}, "516a17ff-4ea8-4dbb-ab73-8234a355ba4d": {"definition": "A tonal descriptor for a full, pleasant sound with strong low-mids and fundamentals and a gentle, unforced top end, standing as the opposite of thin or harsh.", "plain_english": "A warm sound is full and gentle, strong in the low-middle tones with no harsh highs. It feels cozy and easy on the ears.", "purpose_function": "It describes pleasing low-mid fullness and smooth highs so an engineer can judge whether a source feels full and comfortable or thin and edgy.", "practical_application": "An engineer may add warmth by boosting low-mids, rolling off harsh highs, or using tube or tape coloration on a thin, brittle source.", "category": "Tonal Descriptor", "related_terms": ["full", "round", "rich", "thin", "harsh"], "common_mistakes": ["Confusing warm with muddy; warmth is controlled fullness, while mud is uncontrolled low-mid build-up.", "Boosting too much low-mid chasing warmth and losing clarity.", "Assuming warm means dull, when a warm sound can still have clear, open highs."], "scenario_contexts": ["Adding low-mid body to a thin vocal to make it warmer.", "Choosing a ribbon microphone for a warm horn or guitar tone.", "Softening harsh digital highs to give a mix a warmer feel."]}, "0f58b737-caec-43ae-b6c0-d05dc25f6620": {"definition": "A descriptor for a signal that contains audible effect processing, especially reverb or delay, as opposed to a dry, unprocessed signal; a fully wet signal is all effect and none of the original sound.", "plain_english": "A wet sound has effects like reverb or echo added to it, while a dry sound has none. Wet is like the echo you hear in a big empty hall.", "purpose_function": "It describes how much effect is in a signal so an engineer can set the balance between the processed and the clean sound.", "practical_application": "An engineer sets a wet/dry mix control or a reverb send level to decide how much effect sits on a vocal or instrument.", "category": "Effects Descriptor", "related_terms": ["dry", "reverb", "delay", "wet/dry mix", "send"], "common_mistakes": ["Confusing wet with loud; wet is the amount of effect, not the level of the channel.", "Making a mix too wet so vocals sound distant and lose clarity.", "Forgetting that a fully wet effect return should carry only the effect, not the dry signal."], "scenario_contexts": ["Setting the reverb send to make a snare sound wetter.", "Balancing wet and dry on a vocal delay so the words stay clear.", "Using a fully wet reverb return on an aux channel."]}, "d6e765fa-85cc-4c1b-9418-2fbd89685fb2": {"definition": "A tonal descriptor for a warm, resonant, slightly hollow midrange character like that of a hollow wooden instrument, giving body without a metallic edge.", "plain_english": "A woody sound is warm and a little hollow in the middle tones, like tapping on a hollow piece of wood. It has body but no metal-like ring.", "purpose_function": "It describes a natural wooden resonance so an engineer can judge or aim for the organic tone of instruments like clarinet, marimba, or upright bass.", "practical_application": "An engineer may call a well-recorded clarinet or kick drum woody, or shape the mids to bring out the natural woody body of an acoustic instrument.", "category": "Tonal Descriptor", "related_terms": ["warm", "hollow", "body", "resonant", "boxy"], "common_mistakes": ["Confusing woody with boxy; woody is a pleasant natural resonance, while boxy is an unwanted one.", "Cutting mids too hard and removing the natural woody character of an acoustic instrument.", "Assuming woody means dull, when it still carries clear midrange detail."], "scenario_contexts": ["Describing the warm, hollow tone of a well-recorded clarinet or marimba.", "Capturing the woody thud of an upright bass.", "Shaping a kick drum for a natural, woody attack instead of a clicky one."]}, "dcf95717-bdf0-4ce4-be3b-dc5422734c03": {"definition": "A tonal descriptor for excessive, loose, boomy low-frequency energy that is often undamped and lacking definition, producing a dull thump rather than tight, controlled bass.", "plain_english": "A woofy sound has too much loose, boomy bass with no tightness. It thumps in a dull way, like a big speaker with the bass turned up too high.", "purpose_function": "It flags an overblown, poorly controlled low end so an engineer knows to tighten or cut the boomy bass frequencies.", "practical_application": "An engineer hearing a woofy kick or bass will cut the boomy low frequencies and tighten the low end with EQ or damping.", "category": "Tonal Descriptor", "related_terms": ["boomy", "muddy", "tubby", "tight", "low-end"], "common_mistakes": ["Confusing woofy with powerful; woofy bass is loose and dull, not tight and strong.", "Boosting sub or bass too much and making a source woofy.", "Leaving a woofy low end unchecked, which can overdrive and damage small woofers or subs."], "scenario_contexts": ["A bass guitar with loose, boomy notes that lack definition.", "A kick drum that thumps woofily in an untreated room.", "Tightening a woofy low end on a club system to protect the subs and improve clarity."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"287c3bed-063b-4805-b0fe-ab56dcdfdcb2": {"definition": "A tonal descriptor for a low end or low-mid range that is loose, thick, and poorly defined, sounding muffled and unclear rather than tight and articulate.", "plain_english": "A woolly sound has thick, loose low tones with no clear edges. It sounds soft and fuzzy, like listening through a thick wool sweater.", "purpose_function": "It describes a lack of low-end clarity and definition so an engineer can tighten and clean up a muddy, undefined bottom.", "practical_application": "An engineer may call a muddy bass or vocal woolly, then cut the low-mid build-up and tighten the low end for clearer definition.", "category": "Tonal Descriptor", "related_terms": ["muddy", "boomy", "tubby", "undefined", "tight"], "common_mistakes": ["Confusing woolly with warm; warmth is controlled, while woolly is loose and unclear.", "Layering too much low-mid and making a mix woolly and muddy.", "Trying to fix woolliness with only a level cut instead of targeted EQ and cleanup."], "scenario_contexts": ["A bass guitar that sounds thick and undefined in a busy mix.", "Cleaning up a woolly low-mid build-up on an acoustic guitar.", "Tightening a woolly kick and bass so they sit clearly together."]}, "2892c95d-6b0b-4acd-bfee-eb7c81b38226": {"definition": "The stronger, sharper onset transient of a note played with a dynamic accent, in which the attack portion is emphasized so the note's leading edge is louder and more pronounced than the surrounding unaccented notes.", "plain_english": "An accent attack is the extra-strong start of a note that a player hits harder on purpose. It makes the beginning of that note pop out louder than the notes around it.", "purpose_function": "It marks which notes carry rhythmic or musical emphasis, shaping groove and phrasing. Recognizing it helps a technician keep that emphasis instead of flattening it during dynamics processing.", "practical_application": "When mixing, a technician uses gentle or slow-attack compression and careful transient shaping so accented hits keep their punch and still stand out from the rest of a part.", "category": "Attack Descriptor", "related_terms": ["Attack", "Transient", "Attack transient", "Punch", "Dynamics", "Accent"], "common_mistakes": ["Using a fast compressor attack that clamps the accented transient and erases the emphasis.", "Confusing an accent attack (a dynamic emphasis on the note's start) with a brighter tone or added EQ.", "Over-limiting a part until accented and unaccented notes all sound the same."], "scenario_contexts": ["Keeping accented snare hits punchy while compressing a drum bus.", "Preserving accented notes in a bass or piano line during mastering.", "Editing a MIDI performance so accented beats keep higher velocity and a stronger attack."]}, "c38461e6-54bb-4e84-be29-cc91d833d70c": {"definition": "Unwanted mechanical noise produced by an instrument's action, the moving mechanism that transfers a player's touch to the sound-producing element, such as key, hammer, damper, or pallet movement in pianos, keyboards, and organs; it is captured as clicks, thumps, or clatter alongside the intended tone.", "plain_english": "Action noise is the clicky, mechanical sound an instrument's moving parts make, like piano keys and hammers working. A microphone can pick it up along with the music, even though it is not the note itself.", "purpose_function": "Naming it lets a technician separate the wanted musical sound from mechanical racket. It exists as a recording and maintenance concern because too much action noise distracts from the performance.", "practical_application": "When recording piano or organ, a technician chooses mic placement and distance to reduce action noise, and flags a worn or poorly regulated action that needs servicing.", "category": "Mechanical Artifact", "related_terms": ["Key click", "Mechanical noise", "Hammer noise", "Bearing noise", "Noise floor", "Rumble"], "common_mistakes": ["Blaming the microphone for action noise when the real cause is a worn or poorly regulated instrument action.", "Placing a mic right over the keys or hammers, which captures the most action noise.", "Trying to EQ out action noise after the fact instead of fixing placement or the instrument first."], "scenario_contexts": ["Close-miking a grand piano and hearing hammer and key noise in quiet passages.", "Recording a pipe or electronic organ where key and pallet action is audible.", "A pianist's pedal and damper mechanism adding thumps to a solo take."]}, "fb615966-16c3-45bd-a538-669480b009f0": {"definition": "A brief, sudden blast of moving air reaching a microphone that produces a transient thump or overload, such as a vocal plosive, a breath or wind gust, or the puff of air at the onset of a wind-instrument note.", "plain_english": "An air burst is a quick puff or blast of air that hits the mic and makes a sudden thump. It happens with hard 'p' and 'b' sounds, a gust of wind, or a sharp breath.", "purpose_function": "Identifying it helps a technician stop air blasts from thumping or overloading a channel. It matters because a strong air burst can distort the signal or ruin an otherwise good take.", "practical_application": "A technician fits a pop filter or foam windscreen, adjusts mic angle, and may add a high-pass filter to tame air bursts on vocals and on outdoor or wind sources.", "category": "Air Artifact", "related_terms": ["Plosive", "Wind noise", "Pop filter", "Air noise", "Transient", "Windscreen"], "common_mistakes": ["Singing or speaking straight into the mic with no pop filter, so plosive air bursts thump the diaphragm.", "Confusing an air burst (a physical puff of air on the capsule) with electronic clipping.", "Removing air bursts only with EQ instead of preventing them with a screen and better mic angle."], "scenario_contexts": ["A vocalist's hard 'P' plosive thumping a large-diaphragm condenser.", "Wind gusts hitting a mic during an outdoor live event.", "The breath burst at the start of a flute or reed note."]}, "2b058e98-5125-41e8-a72f-1cddf3cdfc43": {"definition": "Broadband rushing or hissing noise caused by moving air reaching a microphone, coming from wind, ventilation and HVAC airflow, fans, or a performer's breath, and heard as an unwanted low-level rush behind the intended sound.", "plain_english": "Air noise is the soft rushing or hissing sound made by moving air, like wind, a fan, or an air vent. A mic can pick it up as an unwanted background rush under the real sound.", "purpose_function": "Naming it helps a technician track down and reduce noise caused by airflow rather than by electronics. It matters because air noise raises the background level and hurts clarity.", "practical_application": "On the job a technician uses windscreens outdoors, turns off or baffles HVAC and fans, and positions mics away from air currents to keep air noise out of a recording.", "category": "Air Artifact", "related_terms": ["Wind noise", "Windscreen", "Air burst", "Noise floor", "Hiss", "Rumble"], "common_mistakes": ["Leaving HVAC or a computer fan running near the mic and blaming the hiss on the preamp.", "Confusing air noise (from moving air) with electronic hiss (from gear and gain).", "Using no windscreen outdoors, then trying to fix heavy air noise in the mix."], "scenario_contexts": ["An air-conditioning vent adding a steady rush to a quiet studio take.", "Wind across a boom mic on an outdoor shoot.", "A close vocal mic catching breath rush between phrases."]}, "76bbf733-e271-4015-972e-59b218924137": {"definition": "A harmonic on a string instrument produced by stopping the string firmly with one finger while another finger lightly touches a nodal point above it, most commonly a perfect fourth higher to sound a flute-like tone two octaves above the stopped note; unlike a natural harmonic, it can be produced on a stopped (fingered) string at any pitch.", "plain_english": "An artificial harmonic is a high, bell-like note on a string. The player holds one finger down and lightly touches the string with another. Both fingers move as a pair, so the player can sound these pure tones at almost any pitch.", "purpose_function": "It lets players reach very high, pure, bell-like pitches beyond normal fingering and adds a special glassy color. It exists to extend the range and timbre of violins, guitars, and related strings.", "practical_application": "A technician recognizes the soft, high, pure tone of an artificial harmonic when miking or mixing strings, and takes care to capture its quiet level and delicate attack cleanly.", "category": "Playing Technique", "related_terms": ["Natural harmonic", "Harmonic", "Node", "Overtone", "Fundamental", "Flageolet"], "common_mistakes": ["Confusing an artificial harmonic (touching a node on a stopped string) with a natural harmonic (touching an open string).", "Expecting a loud sound; artificial harmonics are quiet and need careful gain and placement to record well.", "Reading the touched note as the pitch you hear, when the sounding harmonic is much higher."], "scenario_contexts": ["A violinist playing high artificial harmonics in an orchestral passage.", "A classical guitarist using artificial harmonics for a bell-like melody.", "Miking a string quartet where soft harmonics must stay audible in the mix."]}, "607f5a22-12ca-4efa-9408-91e0a7236ae0": {"definition": "A subjective timbre descriptor for a harsh, aggressive, honking quality in the lower midrange, typically a forceful, cutting attack from brass, reeds, saxophone, or an overdriven source, in which the sound seems to \"bark\" out with a hard, nasal edge.", "plain_english": "\"Bark\" describes a harsh, honking, aggressive sound, like a sax or trumpet blasting out with a hard edge. It is the sound seeming to snap or shout at you.", "purpose_function": "It gives a technician a quick word for an aggressive, honking midrange they may want to boost for attitude or tame for smoothness. It helps aim EQ at the right midrange.", "practical_application": "An engineer may add bark to a horn or guitar with an upper-mid EQ boost for aggression, or cut around 400 Hz to 1 kHz to reduce an unwanted honk.", "category": "Timbre Descriptor", "related_terms": ["Honk", "Nasal", "Aggressive", "Midrange", "Attack", "Harsh"], "common_mistakes": ["Confusing timbral 'bark' (an aggressive honk) with the Bark scale, a separate psychoacoustic frequency scale.", "Adding so much upper-mid bark that a horn or guitar becomes harsh and fatiguing.", "Blaming the source for bark when a resonant room or mic peak is causing the honk."], "scenario_contexts": ["Describing a punchy, aggressive baritone sax as having bark.", "Dialing bark into a rock guitar so it cuts through a dense mix.", "Cutting a honky midrange peak so brass stops barking."]}, "7ae43d61-2367-4a60-9fd6-cc48fb64aca2": {"definition": "Mechanical noise, ranging from low-frequency rumble to a high-pitched whine or grinding, produced by worn, dry, or damaged bearings in rotating equipment such as tape-machine motors and capstans, turntable platters, cooling fans, and hard drives; it can radiate into a room or couple into the signal path.", "plain_english": "Bearing noise is the rumble, whine, or grinding made by worn-out bearings in spinning parts, like motors, fans, or a turntable. As a bearing wears, the smooth spin turns rough and noisy.", "purpose_function": "Identifying bearing noise points a technician to a specific worn part that needs cleaning, lubrication, or replacement. It matters for quiet operation and for preventing equipment failure.", "practical_application": "A technician traces a rumble or whine to a motor, capstan, or fan bearing, then services or replaces it to restore quiet, smooth operation and keep the noise out of recordings.", "category": "Mechanical Artifact", "related_terms": ["Rumble", "Mechanical noise", "Action noise", "Wow and flutter", "Noise floor", "Hum"], "common_mistakes": ["Ignoring early bearing whine until the bearing seizes and damages the motor or shaft.", "Confusing mechanical bearing noise with electrical hum or hiss in the signal path.", "Over-oiling a sealed or self-lubricating bearing instead of replacing a worn one."], "scenario_contexts": ["A tape machine's capstan bearing adding rumble to playback.", "A turntable platter bearing producing low-frequency rumble picked up by the cartridge.", "A noisy cooling fan bearing whining inside an amplifier or console."]}, "c9779251-162c-4ce4-a5aa-1366a29fad94": {"definition": "The sharp, high-frequency click at the very start of a bass-drum (kick) note, produced when the beater strikes the batter head, especially with a hard felt, plastic, or wood beater; it forms the attack transient that gives the kick definition and helps it cut through a mix.", "plain_english": "Beater click is the sharp little \"click\" you hear at the start of a kick-drum hit, made by the pedal beater striking the head. A hard beater gives more click, which helps the kick punch through a loud mix.", "purpose_function": "It provides the attack and articulation that let a kick drum be heard clearly, especially on small speakers and in busy arrangements. Engineers manage it to balance punch against boom.", "practical_application": "An engineer adds or emphasizes beater click with a boundary or beater-side mic, a hard beater, or an EQ boost around 2 to 5 kHz so the kick stays audible in the mix.", "category": "Attack Artifact", "related_terms": ["Attack transient", "Kick attack", "Beater slap", "Punch", "Transient", "Click"], "common_mistakes": ["Boosting beater click so hard the kick sounds clicky and thin instead of full and punchy.", "Confusing beater click (the attack transient) with the low-end thump or boom of the drum.", "Removing all click with EQ, leaving a kick that disappears on small speakers."], "scenario_contexts": ["Adding beater click to a metal kick so it cuts through distorted guitars.", "Swapping to a hard plastic beater for more click in a live show.", "EQ-boosting the click region so a dance kick reads on phone speakers."]}, "a3fad350-82b2-48ae-830b-0edef938cd18": {"definition": "The percussive slapping or smacking transient heard when a bass-drum beater strikes and momentarily rests against the batter head, giving a harder, broader attack than a fine click; it is most prominent with hard beaters and a buried-beater pedal technique.", "plain_english": "Beater slap is the hard smack sound of the kick pedal's beater hitting the drumhead. It is a bigger, broader attack than the thin click, more like a slap than a tick.", "purpose_function": "It supplies an aggressive, punchy attack that helps a kick feel powerful and tight, especially in rock and metal. Engineers use it to add impact and articulation to the drum's front edge.", "practical_application": "An engineer captures beater slap with a hard beater and close mic placement, or shapes it with transient tools, to give the kick a strong slapping attack without losing low-end weight.", "category": "Attack Artifact", "related_terms": ["Beater click", "Attack transient", "Kick attack", "Punch", "Transient", "Slap"], "common_mistakes": ["Pushing beater slap so hard the kick sounds slappy and loses its low-end body.", "Confusing beater slap (a broad attack smack) with a thin high-frequency beater click.", "Relying on slap alone for punch while ignoring the drum's tuning and low-end tone."], "scenario_contexts": ["Getting an aggressive slapping kick attack for a metal track.", "Using a buried-beater technique for a tighter, slappier kick.", "Balancing beater slap against sub-low weight on a rock drum bus."]}, "2b6a1e76-79b8-4981-89e9-9b7e6ae1464c": {"definition": "The set of long-sustaining vibrational modes of a bell or bell-like body, whose partials (hum, prime, tierce, quint, nominal) are inharmonically related and ring on well after the initial strike. These modes give the bell its characteristic pitched, slowly decaying tone.", "plain_english": "It is the long ringing sound a bell keeps making after it is hit. The metal shakes at several pitches at once, which is why a bell sounds rich and rings for so long.", "purpose_function": "It is the acoustic mechanism that gives a bell its sustained, identifiable pitch and long ring-out. Recognising it lets a technician tell bell-type resonances apart from short percussive hits.", "practical_application": "An engineer identifies bell resonance when isolating the long ringing partials of chimes, cymbals, or metallic percussion in order to EQ, gate, or de-ring them in a mix.", "category": "Resonance", "related_terms": ["Bell strike", "Bell tone", "Body resonance", "Decay", "Sustain"], "common_mistakes": ["Confusing the brief metallic strike transient with the long resonant ring that follows it.", "Assuming a bell has one clear pitch, when its inharmonic partials (hum, prime, nominal) can imply several.", "Over-gating metallic percussion so the natural resonant decay is cut off and the sound feels unnatural."], "scenario_contexts": ["Gating or EQing orchestral tubular bells or a ride cymbal so the ring supports rather than clutters a mix.", "Identifying a ringing metallic resonance on a drum kit or in a room during a live soundcheck.", "Analysing a struck-metal sample to decide where to trim its long decaying tail."]}, "b61615a2-ebbc-4a4f-b074-5221a011484d": {"definition": "The sharp, broadband attack transient created at the moment a bell is struck by its clapper or a hammer, before its sustained partials fully develop. This brief, fast-rising onset dominates the sound's attack and contributes to the bell's perceived strike pitch.", "plain_english": "It is the sharp ping you hear the instant a bell is hit, before it settles into its long ring. That first split second is loud and bright and tells your ear a bell was struck.", "purpose_function": "The strike transient gives the bell its clear sense of attack and timing. Identifying it helps a technician judge onset and rhythmic placement apart from the long ring.", "practical_application": "A technician watches the bell strike transient on a meter or waveform to set a gate threshold or a transient shaper without clipping the fast peak.", "category": "Attack", "related_terms": ["Bell resonance", "Bell tone", "Attack", "Transient", "Onset"], "common_mistakes": ["Setting compressor or limiter attack so fast that the bright strike is flattened and the hit loses definition.", "Confusing the physical strike transient with the strike note pitch it produces.", "Gating with too high a threshold so quieter strikes are cut off entirely."], "scenario_contexts": ["Dialling in transient shaping on tubular bells or glockenspiel so each hit cuts through.", "Setting a noise gate on metallic percussion using the strike peak as the trigger.", "Editing a sampled bell so the attack lines up tightly with the beat."]}, "1a3475e0-bc39-4df4-a146-dd7b6f0d4f73": {"definition": "A clear, ringing, sustained pitched sound resembling that of a struck bell: a strong, focused fundamental with a smooth, gradually decaying tail and relatively pure harmonic content. In wind and brass playing the term also names an effect in which a note is sounded and allowed to ring and decay freely rather than being held.", "plain_english": "It means a clean, ringing note that fades away smoothly, like a bell. It sounds pure and round rather than harsh or buzzy.", "purpose_function": "The term gives technicians and musicians a shared word for a clean, ringing, well-focused tone. That is useful when describing a target sound or spotting when a tone has that quality.", "practical_application": "An engineer might aim for a bell tone when EQing a vibraphone or lead synth, lifting a clear fundamental while controlling harsh upper partials.", "category": "Timbre", "related_terms": ["Bell resonance", "Bell strike", "Sustain", "Decay", "Fundamental"], "common_mistakes": ["Thinking any metallic sound is a bell tone, when the term implies a clean, focused, ringing quality.", "Confusing bell tone (a timbre or ring-and-decay effect) with a bell's strike note pitch.", "Adding heavy distortion or clipping that destroys the clean ringing character."], "scenario_contexts": ["Describing the desired clean, ringing sound of a vibraphone, celeste, or clean electric guitar.", "EQing a synth patch so it sits in a clear, bell-like register in a mix.", "A wind ensemble sounding bell tones so the engineer captures the natural ring-out."]}, "a6d6af76-0db8-4c80-bf09-667d3f3fafbd": {"definition": "Unwanted mechanical creak, squeak, or movement noise produced by a performer's bench, stool, or seat and captured in a recording. It is a low-level artifact that intrudes on quiet passages and is unrelated to the instrument's own sound.", "plain_english": "It is the creak or squeak a piano bench or stool makes when a player shifts, and the mic picks it up. It has nothing to do with the music, but it can spoil a quiet part.", "purpose_function": "Naming bench noise helps a technician separate seat or furniture creaks from the actual instrument sound. That makes the artifact easier to prevent, edit out, or gate.", "practical_application": "When recording solo piano, an engineer who hears bench noise will tighten loose bolts, pad the bench, or ask the player to stay still, then edit any remaining creaks out of quiet sections.", "category": "Noise artifact", "related_terms": ["Gear noise", "Fret rattle", "Cabinet rattle", "Noise floor", "Room tone"], "common_mistakes": ["Blaming a creak on the instrument or the mic stand when it is actually the player's bench or stool.", "Trying to EQ out bench noise instead of fixing the source or editing the affected section.", "Ignoring quiet bench creaks during tracking, then finding them exposed in the final mix."], "scenario_contexts": ["A squeaking piano bench captured during a soft solo passage.", "An organ or drummer's stool creaking as the player shifts weight.", "Editing out seat creaks from an exposed acoustic take."]}, "584a25d7-07c5-46ad-9a71-38fe6faa4cd3": {"definition": "The natural resonant response of an instrument's body, its top and back plates and the enclosed air cavity, which amplifies and colours certain frequencies of the vibrating strings or reed. Key modes include the Helmholtz air-cavity resonance and the main top-plate resonance, which together shape the instrument's low-end response and overall timbre.", "plain_english": "It is the way an instrument's hollow body rings and boosts certain notes. Like blowing across a bottle top, the air and wood inside have favourite pitches that make the sound fuller.", "purpose_function": "Body resonance turns small string or reed vibrations into a louder, richer sound and gives each instrument its recognisable voice. Knowing it helps a technician predict and manage boomy or thin notes.", "practical_application": "When close-miking an acoustic guitar, an engineer moves the mic or applies EQ around the body's Helmholtz resonance (often roughly 90 to 110 Hz) to tame boom or add body.", "category": "Resonance", "related_terms": ["Bell resonance", "Helmholtz resonance", "Resonant frequency", "Sympathetic resonance", "Boom"], "common_mistakes": ["Miking directly over the soundhole and capturing an overpowering, boomy body resonance.", "Assuming body resonance is the same for all instruments rather than tuned to each body's size and shape.", "EQing out a boomy note without realising it is the body's Helmholtz resonance, and thinning the whole tone."], "scenario_contexts": ["Positioning a mic on an acoustic guitar or double bass to balance body resonance against string detail.", "Cutting a narrow EQ band to control a boomy body resonance on a cello in a live mix.", "Diagnosing why one note on an instrument sounds much louder, when a body resonance coincides with that pitch."]}, "be5770f4-74f3-400f-9848-ca14c62f0c83": {"definition": "An excessive or prominent low-frequency emphasis, typically in the roughly 60 to 200 Hz range, caused by resonance in a room, enclosure, or instrument that makes the low end sound loud, thick, and poorly defined. It is heard as a lingering, resonant heaviness rather than tight, controlled bass.", "plain_english": "Boom is when the low sounds are too strong and blurry, so the bass feels heavy and muddy. It is like the deep rumble you hear in a room where bass notes pile up.", "purpose_function": "Naming boom lets technicians identify and fix unwanted low-frequency buildup so the bass stays clear and even across a room or mix.", "practical_application": "During soundcheck an engineer sweeps a narrow EQ cut through the low frequencies to find and reduce a boom caused by a room mode or a resonant stage riser.", "category": "Resonance", "related_terms": ["Body resonance", "Room mode", "Resonant frequency", "Rumble", "Muddiness"], "common_mistakes": ["Blaming the subwoofer for boom that is actually caused by a room mode.", "Cutting broad low end and leaving the mix thin instead of notching the specific boom frequency.", "Confusing boom (low-frequency resonance) with rumble (very low, often mechanical, subsonic noise)."], "scenario_contexts": ["Taming boomy bass in a small, untreated room while mixing.", "Finding and notching a boom frequency caused by a hollow stage or a room mode at a live gig.", "Repositioning a subwoofer away from a corner to reduce boom."]}, "094ed2ed-918a-43ed-a075-ab28986e1679": {"definition": "The onset transient of a bowed-string note: the way the bow sets the string into steady Helmholtz (slip-stick) motion at the start of a stroke. Its character depends on bow speed, force, and placement, ranging from a clean, prompt attack to a slower or noisy start with audible pre-Helmholtz slipping.", "plain_english": "It is how a note starts when a player draws the bow across the string. A good bow attack starts the note cleanly and quickly, while a rough one begins with a scratchy or slow sound.", "purpose_function": "The bow attack defines the clarity and timing of each note's start. Recognising it helps a technician judge articulation and capture or preserve the natural onset.", "practical_application": "An engineer avoids over-fast compressor attack times on strings so the natural bow attack, including its slight initial noise, stays intact and expressive.", "category": "Attack", "related_terms": ["Bow change", "Bow bounce", "Attack", "Transient", "Articulation"], "common_mistakes": ["Compressing strings with a very fast attack and squashing the natural onset.", "Treating all bowed onsets as identical, ignoring how bow force and speed change the attack.", "Gating string tracks so tightly that soft bow attacks are chopped off."], "scenario_contexts": ["Recording a solo violin and choosing mic distance so the bow attack sounds natural, not scratchy.", "Editing sampled strings to align the bow attack transients to the grid.", "Judging a player's clean versus rough attacks while balancing a string section live."]}, "63a39dac-fd4a-415f-996a-068910354bbe": {"definition": "A bowing behaviour in which the bow leaves and returns to the string, producing separated, articulated notes. When controlled it is the spiccato and sautille family of off-string strokes; when involuntary it appears as unwanted chatter or uneven articulation, especially at certain bow speeds and contact points.", "plain_english": "It is when the bow hops on and off the string instead of staying glued to it. Done on purpose it gives short, bouncy notes, but by accident it makes an uneven, chattering sound.", "purpose_function": "As a technique it creates crisp, detached articulation; as an artifact it signals a loss of bow control. Identifying it helps a technician or player tell intended bounce from unwanted chatter.", "practical_application": "An engineer hears controlled spiccato as tight, rhythmic transients and may adjust gating or transient shaping to keep each bounced note distinct.", "category": "Attack", "related_terms": ["Bow attack", "Bow change", "Spiccato", "Articulation", "Transient"], "common_mistakes": ["Mistaking intentional spiccato for a fault, or unwanted bounce for a deliberate effect.", "Applying heavy compression that blurs the gaps between bounced notes.", "Assuming bow bounce is always an error, when much of it is deliberate off-string bowing."], "scenario_contexts": ["Capturing a fast spiccato passage cleanly so each note stays separate.", "Identifying unwanted bow chatter on a sustained note during a session.", "Setting transient shaping on a string sample library's spiccato articulation."]}, "f664c3b3-1311-4d96-b04a-7e1211259401": {"definition": "The moment a player reverses bow direction, from down-bow to up-bow or vice versa. A smooth, seamless bow change keeps the note sounding continuously, while an audible one produces a brief dip in level or a small articulation as the string's steady motion is re-established.", "plain_english": "It is the point where the player switches the bow from pushing to pulling, or back. Done well you barely hear it, but done poorly it makes a little bump or gap in the note.", "purpose_function": "Bow changes are unavoidable on long phrases. Spotting them helps a technician tell a natural articulation from an unwanted level dip or noise in a sustained line.", "practical_application": "When editing or comping strings, an engineer looks for the small level dips at bow changes and may cross-fade or ride the fader to smooth a phrase.", "category": "Artifact", "related_terms": ["Bow attack", "Bow bounce", "Articulation", "Sustain", "Legato"], "common_mistakes": ["Mistaking the natural dip at a bow change for a recording drop-out or edit error.", "Editing out every bow change so a line sounds unnaturally seamless.", "Applying heavy expansion that exaggerates the level dip at each change."], "scenario_contexts": ["Smoothing an exposed sustained violin note where bow changes cause small dips.", "Comping a string take and using bow changes as clean edit points.", "Deciding whether a fluctuation in a sustained cello note is a bow change or a mic or cable fault."]}, "7af3bfc1-844e-4120-bd8f-22d67ca83f62": {"definition": "An unintended, stuttering articulation on a bowed string instrument in which the bow bounces or repeatedly grips and slips against the string, producing a rapid rattling or clicking sound instead of a smooth, sustained tone. It typically results from an unbalanced bow-speed-to-pressure ratio or from loss of control in bounced strokes such as spiccato or sautille.", "plain_english": "This is a rattly, stuttering sound a violin or cello makes when the bow bounces or grabs the string in fits and starts instead of gliding along. It sounds a bit like a stone skipping on water instead of one clean note.", "purpose_function": "Identifying bow chatter lets a technician tell a performance or technique fault from an equipment fault, so effort goes toward a cleaner take rather than a hunt for a signal problem that does not exist.", "practical_application": "During string-session editing, an engineer flags notes that chatter and comps them from alternate takes, since the rattling transients cannot be repaired with EQ or dynamics processing.", "category": "Bowing artifact", "related_terms": ["Bow noise", "Bow scrape", "Spiccato", "Attack transient", "Transient"], "common_mistakes": ["Assuming the rattle is a loose connector or faulty mic when it is actually bow control in the performance.", "Trying to remove it with EQ or a de-noiser, which cannot restore the missing smooth tone.", "Confusing intentional bounced strokes such as spiccato with an accidental chatter."], "scenario_contexts": ["Editing a string quartet session and comping out notes where the bow chattered.", "A student violinist's fast passage rattles from an uncontrolled bounced stroke.", "Reviewing a film-score string take to flag chattered notes for a re-record."]}, "46c9749e-8d9a-495d-a7e7-add44a174d8b": {"definition": "The broadband friction noise produced by rosined bow hair dragging across a string, heard alongside the pitched tone and most prominent at bow changes, under heavy bow pressure, or when bowing near the bridge (sul ponticello). Close microphone placement emphasizes this scratchy component relative to the instrument's radiated tone.", "plain_english": "This is the scratchy, hissy sound made by the bow hair rubbing on the string, on top of the actual note. Close microphones pick it up, much like you can hear the scrape of a pencil as well as the line it draws.", "purpose_function": "Recognizing bow noise as a natural, expected part of a bowed-string signal helps a technician judge how much is musical realism and how much is excess from mic placement or technique.", "practical_application": "When a close-miked violin sounds overly scratchy, an engineer moves the mic farther from the bridge or slightly off-axis to reduce captured bow noise while keeping the tone.", "category": "Bowing artifact", "related_terms": ["Bow chatter", "Bow scrape", "Sul ponticello", "Rosin", "Proximity effect"], "common_mistakes": ["Treating all bow noise as a fault to be removed, when some is natural realism of a bowed string.", "Over-brightening a close string mic, which exaggerates bow noise.", "Blaming hiss on the preamp when the scratch is actually acoustic bow noise."], "scenario_contexts": ["Close-miking a solo violin where bow noise becomes prominent.", "Choosing mic distance on a cello to balance tone against bow scratch.", "Identifying scratchy sound in a string sample library as natural bow noise."]}, "9f491e65-d609-4d7a-b79e-c049822aa034": {"definition": "A harsh, crushed, noisy sound produced when excessive bow pressure relative to bow speed prevents the string from sustaining regular Helmholtz motion, breaking the tone into aperiodic noise. It may occur accidentally from poor technique or be used deliberately as an extended technique.", "plain_english": "This is a harsh, crunchy scratch that happens when a player presses the bow too hard, so the string cannot ring cleanly. The note turns into a rough, noisy sound instead of a smooth tone.", "purpose_function": "Identifying a bow scrape lets a technician tell a technique-driven noise from signal-chain distortion, so troubleshooting effort goes to the true source rather than the gear.", "practical_application": "An engineer hearing a scrape on a cello take checks whether it is intentional, such as a marked effect, or an error, then either preserves it or comps around it.", "category": "Bowing artifact", "related_terms": ["Bow noise", "Bow chatter", "Sul ponticello", "Extended technique", "Attack transient"], "common_mistakes": ["Mistaking a bow scrape for signal-chain distortion or clipping.", "Assuming every scrape is an error when it may be a marked extended technique.", "Trying to fix it with a limiter, which does not restore clean tone."], "scenario_contexts": ["A contemporary piece calls for deliberate sul ponticello scrapes.", "A beginner cellist presses too hard and the tone breaks into a scrape.", "Deciding whether a scrape on a take is an effect to keep or an error to fix."]}, "5a442eb6-2763-4b10-82ca-d32e8236f6fb": {"definition": "A note onset initiated by air flow alone, giving a soft, aspirated 'h'-like beginning rather than a hard tongue (wind) or glottal (vocal) articulation, so the attack rises gently. It is often a deliberate articulation choice but can also appear as an unintended soft or late onset.", "plain_english": "This is when a singer or wind player starts a note with a soft puff of air instead of a sharp tongue or throat kick. The note eases in gently, like the soft 'h' at the start of the word 'hello.'", "purpose_function": "Telling a breath attack apart from a tongued or glottal onset helps an engineer read a note's transient shape when editing timing or applying transient processing.", "practical_application": "When tightening a wind or vocal comp, an editor leaves extra room before breath-attacked notes because their soft onsets make the exact start point harder to place.", "category": "Note onset", "related_terms": ["Breath noise", "Breath release", "Attack transient", "Tonguing", "Glottal onset"], "common_mistakes": ["Confusing a soft breath attack with a late or missed entrance.", "Setting a gate or transient designer that chops off the gentle onset.", "Placing an edit point too early and clipping the air onset."], "scenario_contexts": ["A flute line starts each phrase with a soft breath attack.", "Editing a breathy vocal where onsets rise gently rather than snapping in.", "Setting transient processing on a sax track with air-based onsets."]}, "0b9dd87c-d187-49f0-8080-e6b0d76acda7": {"definition": "The audible sound of a performer inhaling before or between phrases, captured by the microphone as a short inrush of air that is distinct from the sung or played tone.", "plain_english": "This is the sound of a singer or player breathing in before they sing or play. Close microphones often catch this quick gasp between phrases.", "purpose_function": "Flagging breath intakes lets an editor decide which to keep for natural phrasing and which to reduce, since some breaths add realism while others distract.", "practical_application": "A vocal editor rides down or trims loud breath intakes between lines using clip gain or a de-breath tool, leaving quieter ones for a natural feel.", "category": "Breath artifact", "related_terms": ["Breath noise", "Breath release", "Breath pop", "Clip gain", "Sibilance"], "common_mistakes": ["Removing every breath, which makes vocals sound unnatural and robotic.", "Cutting a breath so abruptly that it leaves an obvious gap or click.", "Confusing a breath intake with room noise or HVAC rumble."], "scenario_contexts": ["Trimming loud inhalations between lines of a lead vocal.", "A voiceover session where gasps before sentences must be reduced.", "Deciding which breaths to keep for natural phrasing in a ballad."]}, "f76768eb-fb18-4eb4-9160-d7cb37017fb4": {"definition": "Audible breathing and air-turbulence sounds from a vocalist or wind player picked up by the microphone, including inhalations, exhalations, and the rush of air, which form part of the recorded signal and are often treated as artifacts.", "plain_english": "This is the sound of air and breathing from a singer or wind player that the microphone picks up. It includes breaths in and out and the rush of air, mixed in with the music.", "purpose_function": "Identifying breath noise helps a technician separate performer air sounds from electrical hiss or wind on the mic, so the right fix is applied.", "practical_application": "On a close-miked flute or vocal, an engineer uses gentle automation or a dedicated de-breath process to tame breath noise without dulling the tone.", "category": "Breath artifact", "related_terms": ["Breath intake", "Breath release", "Breath pop", "Sibilance", "Plosive"], "common_mistakes": ["Assuming breath noise is electrical hiss and chasing a gear fault.", "Aggressive de-breathing that dulls the tone or adds new artifacts.", "Forgetting that some breath noise adds intimacy and realism."], "scenario_contexts": ["Taming air sounds on a close-miked flute recording.", "De-breathing a podcast vocal without dulling the voice.", "Diagnosing whether an airy sound is breath noise or preamp hiss."]}, "93c97342-9295-43d3-8779-eec7d47c9e12": {"definition": "A low-frequency thump or brief overload caused by a burst of exhaled air striking the microphone diaphragm, similar to a plosive pop; the air blast momentarily displaces the capsule and produces a dull thud unrelated to the intended sound.", "plain_english": "This is a low thump you hear when a burst of breath hits the microphone. It is like the puff of air on the letter 'p' that makes a mic thud.", "purpose_function": "Recognizing a breath pop as an air-blast artifact rather than an electrical fault points the technician to windscreen, pop-filter, and placement fixes instead of the signal chain.", "practical_application": "An engineer adds a pop filter and angles the mic slightly off-axis so exhaled breath no longer strikes the diaphragm head-on and causes pops.", "category": "Breath artifact", "related_terms": ["Plosive", "Pop filter", "Breath noise", "Windscreen", "Proximity effect"], "common_mistakes": ["Confusing a breath pop with a consonant plosive or a DC thump.", "Relying only on EQ instead of a pop filter and a better mic angle.", "Assuming a low-cut fully fixes a pop when the capsule has already overloaded."], "scenario_contexts": ["A singer exhales into the mic and creates a low thud.", "Adding a pop filter to stop breath pops on a rap vocal.", "Angling a wind player's mic so exhaled air misses the diaphragm."]}, "dcb2de9d-4064-416a-9c72-d63bce9fe85e": {"definition": "The audible exhalation of air at the end of a note or phrase, heard as a singer or wind player releases the note and lets remaining breath out; a soft trailing air sound after the tone stops.", "plain_english": "This is the soft puff of air heard at the end of a note or phrase, as the singer or player lets their breath out. It is the little sigh of air right after the sound stops.", "purpose_function": "Identifying breath releases helps an editor shape phrase endings, keeping natural ones and trimming distracting ones.", "practical_application": "When editing a lead vocal, an engineer trims or fades long breath releases at phrase ends so they do not clutter the mix.", "category": "Breath artifact", "related_terms": ["Breath intake", "Breath noise", "Breath attack", "Decay", "Fade"], "common_mistakes": ["Cutting releases so hard that phrase endings sound clipped.", "Confusing a breath release with the note's natural decay.", "Leaving loud releases that clutter a dense mix."], "scenario_contexts": ["Fading the exhaled air at the ends of vocal phrases.", "A clarinet phrase ends with an audible breath release.", "Cleaning up trailing breaths in a dense pop mix."]}, "3573173e-d3b2-4662-841d-a47a0e1eaef8": {"definition": "A timbral descriptor for a voice or instrument tone that contains a prominent component of audible air and turbulence noise mixed with the pitched sound, giving a soft, airy, whispery quality; in the voice it arises from incomplete glottal closure that adds aspiration noise.", "plain_english": "This word describes a soft, airy voice or tone that has a lot of audible air mixed in with the note. Think of the whispery sound of a gentle flute or a singer who sounds like they are almost sighing.", "purpose_function": "The term gives technicians and musicians a shared word for an airy tonal quality, guiding mic, EQ, and processing choices to enhance or reduce it.", "practical_application": "An engineer chasing a breathy vocal sound picks a condenser mic with an airy top end and close placement, or adds high-frequency lift, to emphasize the air.", "category": "Timbral descriptor", "related_terms": ["Breath noise", "Sibilance", "Aspiration", "Timbre", "Air band"], "common_mistakes": ["Confusing 'breathy' (airy tone) with 'sibilant' (harsh S sounds).", "Assuming breathiness is always a fault rather than a desired style.", "Adding extreme high-frequency boost that turns air into harsh noise."], "scenario_contexts": ["Producing an intimate, breathy lead vocal for a ballad.", "Choosing a condenser mic to capture a breathy flute tone.", "Describing a singer's airy timbre in session notes."]}, "05473c2c-ac52-4a9d-8423-88890e2f3071": {"definition": "A mechanical resonance of an instrument's bridge, the part that transmits string vibration to the body or soundboard. On bowed and plucked string instruments the bridge has its own vibrational modes; the violin's broad 'bridge hill' near 2 to 3 kHz, for example, boosts a band of frequencies and shapes the instrument's brightness and radiated tone.", "plain_english": "The bridge is the small part that carries a string's shaking into the body. It shakes most easily at a few certain notes. Those notes get a small boost. That helps set how bright the instrument sounds.", "purpose_function": "It explains why the bridge is more than a passive support: its resonant modes filter and color the vibration passing from the strings to the body, strongly influencing timbre and radiated output in a certain frequency range.", "practical_application": "Luthiers tune bridge mass and cutouts to place this resonance where it flatters an instrument, and engineers hear it as a brightness peak when close-miking violins, guitars, or basses.", "category": "Resonance", "related_terms": ["Cabinet resonance", "Sympathetic resonance", "Wolf tone", "Sustain", "Timbre"], "common_mistakes": ["Assuming the bridge only transfers vibration and has no tone of its own", "Confusing bridge resonance with a body or air resonance of the instrument", "Trying to EQ out a brightness peak that is actually a natural, desirable bridge resonance"], "scenario_contexts": ["Close-miking a violin and hearing a harsh 2 to 3 kHz brightness peak from the bridge hill", "A luthier filing a bridge to shift its resonance and tame or brighten an instrument", "Identifying why a plucked bass note has an emphasized band of overtones"]}, "0da583a6-e51a-4675-91dd-b4dd2b01971d": {"definition": "A colloquial guitar-tone descriptor for a thick, warm, saturated high-gain distortion sound with a strong, smooth midrange, tight low end, and a rounded, compressed feel rather than a bright or fizzy edge. The term is most associated with Eddie Van Halen's cranked, modified Marshall-style tone.", "plain_english": "It is a warm, thick, growling electric guitar sound with lots of smooth distortion. People named it after Eddie Van Halen's famous tone, which sounds full and round, not thin or harsh.", "purpose_function": "The term gives players and engineers a shorthand for a particular warm, saturated rock guitar tone. It helps communicate a tonal target when choosing amps, gain settings, and EQ.", "practical_application": "To chase a brown sound, a player or engineer uses a high-gain tube amp pushed into saturation, favours midrange in the EQ, keeps the low end tight, and mics the cabinet carefully.", "category": "Tonal Descriptor", "related_terms": ["Saturation", "Distortion", "Midrange", "Harmonics", "Gain"], "common_mistakes": ["Believing the tone comes mainly from running the amp on a variac at a lowered voltage, when amp choice, gain staging, EQ, and playing matter far more.", "Adding so much gain that the tone becomes fizzy and thin, losing the warm, tight character.", "Assuming one pedal or setting alone recreates it, when it depends on the whole amp, cabinet, and mic chain."], "scenario_contexts": ["A guitarist asks for a 'brown sound' rhythm tone in a hard-rock session.", "An engineer dials in a warm, saturated high-gain guitar tone to match a classic Van Halen style.", "Choosing a high-gain amp and mic position to capture a thick, midrange-forward distortion."]}, "0977a261-7188-4c12-8742-7145ba6dd75a": {"definition": "A drum-brush technique in which the wire or nylon brush is dragged or swept across the drumhead, usually the snare, producing a continuous, sustained 'shhh' sound rather than a distinct attack. It creates legato texture and a soft, airy sustain used heavily in jazz and ballad playing.", "plain_english": "This is when a drummer slides a wire brush across the drum skin instead of hitting it. It makes a smooth, hissing sound that keeps going. Think of it like softly sweeping a broom across the floor.", "purpose_function": "It lets a drummer produce sustained sound and a smooth pulse with almost no sharp attack, filling a role a stick cannot in quiet, intimate music.", "practical_application": "Engineers close-mic the snare and often add a room or overhead mic to catch the delicate high-frequency swish, and ease off heavy gating and compression so the quiet sweep is not chopped up or over-emphasized.", "category": "Articulation", "related_terms": ["Brush tap", "Attack", "Sustain", "Transient", "Ghost note"], "common_mistakes": ["Gating the snare so aggressively that the continuous sweep is chopped up or lost", "Confusing the sustained sweep with the short brush-tap stroke", "Over-compressing the channel so the quiet swish jumps forward unnaturally"], "scenario_contexts": ["Recording a jazz ballad where brushes provide a soft, sustained pulse", "Choosing brushes over sticks to keep a low stage volume in an acoustic set", "Miking a snare to capture the airy high-frequency swish of a sweep"]}, "8a4a1117-5ac9-463a-ad94-45ddcb175d7a": {"definition": "A drum-brush technique in which the brush strikes the head with a short, defined stroke, giving a soft but distinct attack, a percussive tap rather than the sustained swish of a sweep. It is the brush equivalent of a stick stroke, providing rhythmic definition with a gentler transient.", "plain_english": "This is a quick, light hit on the drum with a brush. It gives a soft but clear tap, not a long hiss. It is like tapping a table with your fingertips instead of your whole hand.", "purpose_function": "It provides clear rhythmic accents and note definition at low volume, letting a drummer mark the beat without the loud attack of a wooden stick.", "practical_application": "Drummers combine taps with sweeps to keep time, and engineers set gain and gating so the soft taps still register cleanly above the noise floor when the kit is quiet.", "category": "Articulation", "related_terms": ["Brush sweep", "Attack", "Transient", "Ghost note", "Accent"], "common_mistakes": ["Confusing the short tap with the continuous sweep stroke", "Setting a gate threshold so high that quiet taps fail to open it", "Expecting a brush tap to cut through a loud mix like a stick rimshot"], "scenario_contexts": ["Marking beats 2 and 4 with light taps during a brushed jazz groove", "Playing a quiet dinner set where stick attack would be too loud", "Setting mic gain so soft brush taps stay above the noise floor"]}, "cd48e255-4c89-4cb6-b06b-821b63a2c7aa": {"definition": "An unwanted mechanical buzz or rattle radiated by a loudspeaker or instrument-amplifier cabinet when a loose panel, grille, screw, port, or internal part vibrates against another surface at certain frequencies and levels. It is a defect or artifact, distinct from the intended sound of the driver.", "plain_english": "This is a buzzing or rattling noise from a speaker box, not from the speaker cone itself. It happens when a loose panel, screw, or part shakes and knocks at some notes or volumes. It is like a loose window buzzing when a truck drives past.", "purpose_function": "As a diagnostic term it names a specific fault so technicians can tell enclosure buzz apart from driver distortion, then locate and fix the loose part.", "practical_application": "A tech isolates a rattle by sweeping a sine tone to find the offending frequency, then tightens screws, reseats the grille, or damps the panel; a persistent low-frequency rattle can also signal a damaged driver.", "category": "Artifact", "related_terms": ["Cabinet resonance", "Buzz", "Distortion", "Sine sweep", "Voice-coil rub"], "common_mistakes": ["Blaming the driver for a buzz that is actually a loose cabinet screw or grille", "Assuming a rattle heard at one frequency means the speaker is blown", "Not sweeping a test tone, so the exact rattle frequency is never found"], "scenario_contexts": ["A PA cabinet buzzes only on a specific bass note during soundcheck", "A guitar amp head rattles when a tube or panel screw works loose", "Sine-sweeping a monitor to trace a rattle before a show"]}, "277ba744-93ab-4e1a-88d7-1df34760f389": {"definition": "The natural resonant vibration of a loudspeaker enclosure's walls, excited by the driver and internal air pressure, which radiates sound of its own and colors the reproduced signal. Panel modes typically fall in the lower midrange and add unwanted coloration or 'boxiness'.", "plain_english": "Every speaker box has notes where its walls like to shake on their own. When the speaker drives those notes, the box adds its own sound on top. That extra ringing can make things sound boxy, like singing inside a cardboard box.", "purpose_function": "Naming this behavior lets designers and techs account for enclosure coloration; controlling it with bracing, damping, and stiffer panels is a key goal of good cabinet design, and the payoff is a cleaner, more neutral response.", "practical_application": "Designers brace and damp panels to push resonances up in frequency and lower their level, while a tech may feel a buzzing panel by hand or measure a response bump caused by wall vibration.", "category": "Resonance", "related_terms": ["Cabinet rattle", "Standing wave", "Damping", "Coloration", "Bridge resonance"], "common_mistakes": ["Confusing panel resonance (the box vibrating) with standing waves inside the enclosure's air", "Thinking a heavier box is always deader, when stiffness and damping matter more than mass alone", "Ignoring low-midrange coloration and blaming it entirely on the driver or the room"], "scenario_contexts": ["Feeling a studio monitor's side panel buzz on sustained bass notes", "A designer adding internal bracing to reduce a measured response bump", "Diagnosing a 'boxy' coloration in a subwoofer enclosure"]}, "a1c234f9-605f-4467-9e23-a3062b889d91": {"definition": "The short, crisp 'chick' sound produced by closing the two hi-hat cymbals with the foot pedal, without a stick strike. It is a percussive, damped attack with almost no sustain, used to mark time, most classically on beats 2 and 4.", "plain_english": "This is the tight 'chick' noise a drummer makes by pressing the hi-hat cymbals together with a foot pedal. There is no long ring, just a short, snappy sound. It is like quickly clapping two cymbals shut.", "purpose_function": "It gives the drummer a steady timekeeping accent using the foot, freeing the hands and adding a crisp pulse that anchors the groove.", "practical_application": "Engineers place the hi-hat mic to catch this foot chick cleanly without too much snare bleed, and program it as a separate articulation when sequencing electronic drums.", "category": "Articulation", "related_terms": ["Hi-hat", "Attack", "Transient", "Choked decay", "Bleed"], "common_mistakes": ["Confusing the foot 'chick' with a stick-struck closed hi-hat note", "Positioning the hi-hat mic where snare bleed drowns out the chick", "Expecting the chick to have audible sustain, when it is a damped, short sound"], "scenario_contexts": ["A jazz drummer marking beats 2 and 4 with foot chicks", "Setting hi-hat mic angle to reduce snare bleed while keeping the chick", "Sequencing a drum machine and choosing the pedal-chick sample"]}, "6572ac61-746f-443b-93de-3a2fc816a48e": {"definition": "A clear, bell-like tone marked by a bright, ringing sustain rich in high, largely inharmonic partials and a slow decay. As an instrument, 'chimes' (tubular bells) are tuned metal tubes struck to produce such tones; as a descriptor, 'chime' names this shimmering, resonant quality in other sounds.", "plain_english": "A chime is a bright, ringing, bell-like sound that hangs in the air. Its tone is clear and shimmering and fades slowly. Think of the ring of a wind chime or a struck metal tube.", "purpose_function": "The term identifies a bell-like resonant character, used to name orchestral tubular bells or to describe a shimmering, ringing quality engineers hear in guitars, cymbals, or synth patches.", "practical_application": "A technician might reach for the word 'chime' to describe a bright, ringing high end, and would mic tubular bells from a little distance to capture their long, resonant decay.", "category": "Timbre", "related_terms": ["Sustain", "Decay", "Partials", "Resonance", "Timbre"], "common_mistakes": ["Assuming a chime's partials are harmonic like a string, when tubular bells are strongly inharmonic", "Confusing the descriptive 'chime' quality with one specific instrument", "Over-brightening a mix chasing 'chime' until it becomes harsh"], "scenario_contexts": ["Describing the bright, ringing top end of a clean electric guitar", "Miking tubular bells to capture their long, bell-like decay", "Dialing a synth patch for a shimmering, chiming texture"]}, "80d428cb-3445-410b-bc42-92c9d2ad6fae": {"definition": "A resonant sound whose natural decay is abruptly cut short by damping rather than allowed to ring out fully. The classic example is the cymbal 'choke', grabbing the cymbal right after striking it, but the term applies to any note or resonance whose sustain is deliberately or accidentally clamped.", "plain_english": "This is when a ringing sound is stopped short instead of fading away on its own. A drummer grabbing a cymbal right after hitting it is the classic case. It is like pressing your hand on a struck bell to silence it.", "purpose_function": "As an effect it creates a sharp, punctuated accent by removing sustain; as a diagnostic term it flags when a sound is being damped too soon, on purpose or by a fault.", "practical_application": "Drummers choke cymbals for stabs and stops, and engineers recreate the effect with fast gating or volume automation; a tech also uses the term when a resonance is unintentionally muted by a damaged or over-damped part.", "category": "Decay", "related_terms": ["Decay", "Sustain", "Damping", "Gate", "Chick"], "common_mistakes": ["Confusing a choked (damped) decay with a naturally short decay", "UNSAFE: grabbing a cracked cymbal barehanded to choke it, as the sharp edge can cut the hand", "Setting too fast a gate release, so sustained notes are unintentionally choked"], "scenario_contexts": ["A drummer choking a crash for a sharp stop at the end of a phrase", "Programming fast gating to emulate a choked cymbal in a mix", "Diagnosing why a tom's sustain dies too quickly from over-damping"]}, "33ca8fa2-e856-4e20-8b7a-2ce2e423362d": {"definition": "A percussive, palm-muted rhythm-guitar articulation, usually on a low or down-tuned string through a high-gain amplifier, producing a tight, low-frequency-dominant transient with heavily damped sustain. The term names both the technique and the resulting chunky, staccato tone typical of metal and hard-rock rhythm playing.", "plain_english": "A chug is the short, punchy thump a metal guitarist makes by resting a hand on the strings and picking hard. It has a lot of low-end punch but rings out very little.", "purpose_function": "It gives heavy guitar parts percussive drive and low-end weight, using palm damping to cut sustain so fast riffs stay tight and clear instead of blurring together.", "practical_application": "A technician identifies the chug when tracking and mixing rhythm guitars, then uses gating, transient shaping, and low-mid EQ so each muted note stays punchy and locks with the kick drum.", "category": "Attack Descriptor", "related_terms": ["palm mute", "attack", "transient", "sustain", "gate", "distortion"], "common_mistakes": ["Assuming any distorted power chord is a chug, when the defining feature is the palm-muted, damped attack that shortens sustain.", "Over-gating the chug so hard that the natural low-end body of the note is cut off, leaving it thin and clicky.", "Boosting sub-bass to make chugs heavier, which muddies the mix instead of tightening the attack."], "scenario_contexts": ["Tracking down-tuned rhythm guitars for a metal record and dialing in tight palm-muted chugs.", "Mixing a heavy chorus where chugs must lock with the kick drum without masking it.", "Using a transient shaper to add punch to soft, undefined chugs in a re-amped DI track."]}, "26e1b855-b0b0-488c-a181-2174e7600d6c": {"definition": "A descriptive term for a hard, dry, high-frequency percussive transient with a fast rise and little sustain, resembling two rigid objects striking together. It is heard, for example, when a kick-drum beater slaps the head, a bass string strikes a fret, or castanets are played.", "plain_english": "A clack is a hard, sharp knock high up in the sound, like two pieces of wood or plastic hitting. You might hear it when a kick beater slaps the drumhead or a bass string smacks a fret.", "purpose_function": "As a listening label it lets technicians pinpoint a sharp contact transient in a sound, so they can decide whether that attack adds useful definition or should be reduced.", "practical_application": "An engineer uses the word to flag beater or string clack during tracking, then changes mic placement, beater material, or EQ to shape how much of that hard attack reaches the mix.", "category": "Attack Descriptor", "related_terms": ["click", "crack", "transient", "attack", "beater noise"], "common_mistakes": ["Confusing a musical clack, which is a wanted hard transient, with a click artifact caused by a fault or edit.", "Trying to EQ out all clack, which removes the high-frequency attack that gives the sound its definition."], "scenario_contexts": ["Identifying excess beater clack on a kick drum and adjusting mic position or beater material.", "Noticing string clack on a slap-bass track and deciding whether it adds definition or distraction.", "Describing a percussion sound to a producer using the word clack during a session."]}, "282fe8c4-0bae-4699-8d45-e277b799b49d": {"definition": "The short resonant ring that follows a hard clack transient, produced when the impact excites a natural resonance in the instrument, shell, hardware, or nearby structure. It is the brief, pitched or metallic decay heard immediately after the initial percussive knock.", "plain_english": "Clack resonance is the short ring that comes right after a hard clack sound. The knock sets a part of the instrument buzzing for a moment, like tapping a hollow box and hearing it hum.", "purpose_function": "Naming this resonance helps a technician separate the initial hard attack from the ring that follows, so each can be judged and treated on its own.", "practical_application": "A technician listens for the ring after a clack to decide if it adds character or needs taming, then uses damping, narrow EQ cuts, or a resonance suppressor to control it.", "category": "Resonance Descriptor", "related_terms": ["clack", "resonance", "ring", "sympathetic vibration", "decay"], "common_mistakes": ["Mistaking the resonant ring after a clack for a separate note or an added echo.", "Assuming the resonance is always a defect, when it is often a natural and wanted part of the instrument's tone."], "scenario_contexts": ["Hearing a short metallic ring after a hard drum hit and tracing it to shell or hardware resonance.", "Deciding whether the resonance after a clack adds character or should be damped.", "Using narrow EQ or a resonance suppressor to tame an unwanted ring after a percussive clack."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"0fa0abea-2114-4269-893a-78594563259c": {"definition": "A very short, sharp, broadband impulsive sound perceived as a single tick. In production it may be a wanted attack component, such as a beater or pick click, or an unwanted artifact caused by a waveform discontinuity, an uncrossfaded edit point, or a digital-clock or buffer error.", "plain_english": "A click is a very short, sharp tick, like a tiny snap. It can be a wanted part of an attack, or an unwanted glitch where the sound suddenly jumps.", "purpose_function": "The term lets a technician flag an impulsive event and then judge whether it is a musical attack to keep or a fault to remove, guiding the correct fix.", "practical_application": "On the job a technician traces a repeating click to word-clock or buffer settings, smooths an edit-point click with a short crossfade, and keeps a wanted beater click that helps a drum cut through.", "category": "Attack Descriptor", "related_terms": ["clack", "tick", "transient", "attack", "pop", "digital glitch"], "common_mistakes": ["Confusing a wanted attack click, such as a beater or pick click, with an unwanted digital click artifact.", "Assuming every click is a fault, when edit-point clicks are fixed with crossfades while attack clicks are musical.", "Ignoring that a steady repeating click can signal a real problem such as a bad clock or a buffer error."], "scenario_contexts": ["Hearing a repeating click in a digital recording and checking word-clock and buffer settings.", "Removing a click at an edit point by adding a short crossfade.", "Keeping the intended beater click on a kick drum because it helps the drum cut through the mix."]}, "25be9d7a-194f-485a-a9b8-68438b76a33c": {"definition": "The short, dry, high-pitched transient produced by a closed hi-hat or similarly damped cymbal, in which the two cymbals are held together so the sound stops quickly with minimal sustain. It contrasts with the open hi-hat's longer, sizzling decay.", "plain_english": "A closed tick is the short, dry tick a closed hi-hat makes. Because the two cymbals are pressed together, the sound stops fast instead of sizzling.", "purpose_function": "Identifying the closed tick lets a technician place a tight rhythmic accent in a groove and keep it crisp and controlled rather than smeared or ringing.", "practical_application": "An engineer balances the closed hi-hat tick against the snare, using EQ and level to keep it crisp without harshness, and checks that gating does not clip its short decay.", "category": "Attack Descriptor", "related_terms": ["hi-hat", "tick", "attack", "damping", "transient"], "common_mistakes": ["Confusing the closed hi-hat tick with an open hi-hat's longer sizzling decay.", "Gating a closed tick too tightly and cutting off its short natural decay."], "scenario_contexts": ["Balancing the closed hi-hat tick against the snare in a tight pop groove.", "EQing a hi-hat so its closed tick stays crisp without becoming harsh.", "Identifying whether a rhythmic tick comes from a closed hi-hat or a rimshot."]}, "573ca886-de29-49ee-a162-ac17792ad39a": {"definition": "A guitar tone created by setting a wah-wah pedal at a fixed position instead of rocking it, so its band-pass filter parks a strong resonant peak on one midrange band. The result is a fixed, nasal or honky filtered voicing rather than the sweeping wah effect.", "plain_english": "A cocked wah is the honky, nasal guitar tone you get by leaving a wah pedal parked in one spot instead of rocking it. It boosts one band of middle notes, so the guitar sounds like it is talking through its nose.", "purpose_function": "It lets a player carve a distinctive fixed midrange voice that adds presence and cut, helping a lead or rhythm part stand out without extra gain.", "practical_application": "A technician recognizes and recreates the cocked-wah sound by parking a wah pedal or setting a fixed band-pass filter, usually placing it early in the chain before the main gain stage.", "category": "Tonal Descriptor", "related_terms": ["wah-wah", "resonant filter", "midrange", "formant", "band-pass"], "common_mistakes": ["Thinking a cocked wah needs constant pedal movement, when the point is that it stays parked in one position.", "Placing the parked wah after high-gain distortion, when it usually works best before the gain stage."], "scenario_contexts": ["Parking a wah pedal to get a nasal lead tone in a funk or rock track.", "Recreating a classic cocked-wah guitar sound with a fixed band-pass filter in the box.", "Diagnosing an unwanted midrange honk and finding a wah pedal was left partly pressed."]}, "069a9d0a-2cf4-47aa-9655-62b1ceaee3b8": {"definition": "A string-playing technique, properly col legno battuto, in which the player strikes the string with the wooden stick of the bow rather than drawing the hair across it. It produces a dry, percussive attack with a soft, indefinite pitch and very short sustain.", "plain_english": "Col legno strike means hitting the string with the wooden stick of the bow instead of drawing the hair across it. It makes a dry, tapping sound with only a faint pitch.", "purpose_function": "It gives string writing a percussive, brittle color used for special effect, adding a rhythmic, ghostly attack that a normal bow stroke cannot make.", "practical_application": "When a score marks col legno, a technician expects a quiet, dry tapping sound and close-mics the section, since the strike is soft and its transient is easily lost.", "category": "Articulation", "related_terms": ["col legno tratto", "pizzicato", "spiccato", "attack", "articulation"], "common_mistakes": ["Confusing col legno battuto, striking with the wood, with col legno tratto, drawing the wood across the string.", "Expecting a strong, clear pitch, when the strike gives a dry percussive sound with only a faint pitch.", "Using a fine performance bow for the strike, risking damage, when many players keep a cheaper bow for this."], "scenario_contexts": ["Reading a col legno marking in a string score and preparing the section to strike with the bow stick.", "Recording a col legno passage and close-miking to capture the dry percussive tap.", "Choosing a spare bow for col legno to avoid marking a valuable performance bow."]}, "dc00efc9-2d30-41b1-9f98-558617d445f8": {"definition": "A descriptive term for a loud, sharp, explosive transient with strong high-frequency content and a very fast rise, such as a snare hit, rimshot, or whip. It denotes a bright, snapping attack that cuts sharply through a mix.", "plain_english": "A crack is a loud, sharp snap with lots of high end, like a whip or a hard snare hit. It jumps up very fast and then is gone.", "purpose_function": "As a listening label it marks the bright snapping attack that helps a hit sound powerful and present, guiding how a technician preserves or shapes that transient.", "practical_application": "An engineer aims for a strong snare crack while tracking, and tames an overly harsh crack in the mix with dynamic EQ or transient control rather than dulling the whole hit.", "category": "Attack Descriptor", "related_terms": ["snare", "transient", "attack", "clack", "rimshot", "peak"], "common_mistakes": ["Confusing a snare crack, which is a wanted sharp transient, with distortion or clipping.", "Cutting the high frequencies too far to tame harshness, which removes the crack and dulls the hit."], "scenario_contexts": ["Describing a desired snare tone as a sharp crack during a tracking session.", "Taming an overly harsh crack on a rimshot with dynamic EQ.", "Adding attack to a dull snare so it regains its crack in the mix."]}, "584f80b2-6145-4816-87a2-c63774077aa0": {"definition": "The decay portion of a crash cymbal's sound: the long, shimmering wash of sustained overtones that fades after the initial attack. It is the ring-out that follows the strike, not the transient hit itself.", "plain_english": "Crash decay is the long, shimmering wash a crash cymbal makes after you hit it. It is the sound slowly fading away, not the first loud hit.", "purpose_function": "Recognizing the decay separately from the attack lets a technician control how long a cymbal rings in a mix, so its wash supports rather than clutters the music.", "practical_application": "A technician sets gate and fade times so crash decays are not chopped off at section changes, and balances that wash against vocals and other instruments.", "category": "Decay Descriptor", "related_terms": ["cymbal", "decay", "sustain", "ring-out", "shimmer"], "common_mistakes": ["Confusing the crash decay, the fade-out ring, with the initial attack of the cymbal.", "Gating drums so hard that the crash decay is chopped off unnaturally.", "Treating a long crash decay as bleed to remove, when it is the intended sustain of the cymbal."], "scenario_contexts": ["Deciding how much crash decay to keep when gating a drum kit.", "Editing drum hits so crash decays are not cut off at section changes.", "Balancing crash decay against vocals so long cymbal washes do not clutter the mix."]}, "933b7ce0-9e59-49b2-875d-3c9f257ab630": {"definition": "A snare-drum technique in which the drummer lays the shoulder of the stick across the drumhead near the rim and strikes the rim with the butt end, producing a short, dry, woodblock-like click with almost no drum tone or sustain. It is also called a rim click or side stick.", "plain_english": "The drummer lays the stick flat across the drum and taps the rim with the other end. This makes a short, dry click, a bit like knocking on wood, instead of a full drum hit.", "purpose_function": "It gives a quiet, tight percussive accent with almost no ring, letting a drummer play soft grooves, often in ballads or verses, where a full backbeat would be too loud.", "practical_application": "An engineer hears the cross-stick as a low-level, transient-heavy click and often gives it its own gain, compression, and gating so it is not lost or cut off when it appears mid-song.", "category": "Articulation", "related_terms": ["rimshot", "ghost note", "dead note", "attack", "transient"], "common_mistakes": ["Confusing a cross-stick with a rimshot, which is loud with the stick tip and rim struck together, when the cross-stick is a soft click.", "Gating or editing the snare only for full hits, so quiet cross-stick clicks get cut off or lost.", "Assuming the cross-stick will match the open snare in pitch and body, when it is drier and far more transient."], "scenario_contexts": ["A ballad verse where the drummer plays cross-stick on beats 2 and 4 for a soft groove.", "Editing a drum take where cross-stick sections must be balanced separately from full backbeats.", "Setting a snare noise gate so it opens for both quiet cross-sticks and loud hits."]}, "28535082-a8fc-4415-9fb3-9ee2be153ac7": {"definition": "The portion of a sound's decay that is cut short because energy is being removed from the vibrating system faster than by its natural losses, for example by a hand, mute, felt, or damper touching the string, head, or bar. The result is a shorter decay time and a faster-than-normal fall in level after the attack.", "plain_english": "This is when a sound fades away faster than normal. It happens because something stops the vibration. Muting a guitar string with your hand is a good example. The note dies fast instead of ringing out.", "purpose_function": "Damping controls how long notes ring, which shapes rhythm and clarity, so players and engineers use damped decay to tighten timing and stop unwanted ringing or overlap between notes.", "practical_application": "A technician spots damped decay as a steep, short tail on a note and may add it, with a mute, palm, or gate, or preserve it so fast passages stay clean and defined.", "category": "Decay Descriptor", "related_terms": ["decay", "attack", "sustain", "palm mute", "dead note", "resonance"], "common_mistakes": ["Confusing damped decay with a fade made at the fader, when damping happens at the instrument itself.", "Thinking a shorter decay means a weaker attack, when the attack can be loud even while the tail is cut short.", "Over-damping so notes sound choked and lifeless when some natural decay was wanted."], "scenario_contexts": ["A palm-muted guitar riff where each note decays quickly for a tight, percussive feel.", "A drummer pressing a hand on a tom to shorten its ring.", "Judging whether a note's short tail comes from damping or from an over-aggressive noise gate."]}, "e911557a-aca9-4a55-ba07-7d27224a6490": {"definition": "On a piano or similar keyed string instrument, the moment the damper felt returns to rest on the string after a key or the sustain pedal is released, stopping the string's vibration and ending the note. The contact can also add a faint mechanical thump to the sound.", "plain_english": "On a piano, this is when the soft felt pad drops back onto the string and stops the note. It works like a finger touching a ringing string to quiet it. The landing can add a tiny soft thump.", "purpose_function": "The damper landing is what actually ends a piano note and sets its length, existing so strings do not keep ringing after the player lifts the key.", "practical_application": "When recording or sampling a piano, an engineer hears damper landings as soft thumps at note releases and decides whether to keep them for realism or edit them out as noise.", "category": "Decay Descriptor", "related_terms": ["damper lift", "damper noise", "decay", "sustain pedal", "sympathetic resonance"], "common_mistakes": ["Mistaking the soft thump of a damper landing for a click or fault in the recording chain.", "Editing out every damper landing, which can make a sampled piano sound unnatural.", "Assuming the note ends the instant the key is released, ignoring the brief damper travel and landing."], "scenario_contexts": ["Close-miking a grand piano and hearing soft thumps as keys are released.", "Programming a sampled piano that includes damper landing noise for realism.", "Deciding whether a low thump on a piano track is a damper landing or a stand or floor bump."]}, "ea75b11f-dab4-4df7-bbb0-81ed2f68874a": {"definition": "On a piano, the raising of the damper felt off the string, caused by pressing a key or the sustain (damper) pedal, which frees the string to vibrate and ring. It allows sustain and lets other undamped strings add sympathetic resonance.", "plain_english": "This is when the soft felt pads lift off the piano strings so the strings can ring freely. Pressing the sustain pedal lifts them all at once. That is why notes keep sounding after you let go of the keys.", "purpose_function": "The damper lift lets strings sustain and resonate, existing so the player can hold notes and add richness by letting strings ring together.", "practical_application": "A technician links a fuller, more resonant piano sound and added sympathetic ringing to pedal-driven damper lift, and may hear a faint mechanical noise as the dampers rise.", "category": "Resonance Descriptor", "related_terms": ["damper landing", "damper noise", "sustain pedal", "sympathetic resonance", "sustain"], "common_mistakes": ["Confusing damper lift, from the pedal or a key, with the una corda or 'soft' pedal, which shifts the action instead.", "Blaming added ring or resonance on a reverb setting when it is really sustained strings from lifted dampers.", "Thinking only the played note's damper lifts, when the sustain pedal lifts them all."], "scenario_contexts": ["A pianist using the sustain pedal so chords ring into each other.", "Hearing extra sympathetic resonance on a piano track while the pedal is held.", "Diagnosing why staccato notes still ring, and finding the dampers cannot land because the pedal is down."]}, "5a39e6f8-21f7-4c2e-ae5f-2eca877ce7b2": {"definition": "The incidental mechanical noise a piano's dampers make as their felts contact or leave the strings: soft thumps, felt friction, or a faint flutter heard alongside the musical tone. It is most noticeable in close-miked or sampled recordings.", "plain_english": "This is the soft, non-musical sound the felt pads make as they touch or leave the strings. It is a bit like a muffled tap. Close microphones pick it up along with the notes.", "purpose_function": "It is not a designed feature but an unavoidable by-product of the damping mechanism, and recognizing it helps a technician tell natural piano mechanics from an actual fault.", "practical_application": "An engineer identifies damper noise as soft felt thumps tied to key releases and pedal moves, then uses mic placement, gating, or editing to control it without losing natural feel.", "category": "Mechanical Artifact", "related_terms": ["damper landing", "damper lift", "sustain pedal", "decay", "mechanical noise"], "common_mistakes": ["Mistaking damper noise for a bad cable, connector, or clipping when it is really the instrument's felt.", "Trying to remove all damper noise, which strips natural realism from a piano recording.", "Confusing damper noise with pedal squeak or bench creak, which come from different parts."], "scenario_contexts": ["Close-miking a piano and hearing soft felt thumps on note releases.", "A/B-ing sampled pianos, some of which include modeled damper noise.", "Tracing a soft thumping on a piano recording and confirming it is damper felt, not a fault."]}, "b4b20cee-b879-4164-bc3d-6868ec93baaa": {"definition": "A deliberately muted note with no clear pitch, produced on guitar, bass, or similar string instruments by damping the strings, usually with the fretting hand resting lightly across them, while plucking or picking so only a short, dry percussive thud sounds. It is notated with an 'x' on the staff.", "plain_english": "A dead note is a muted note with no real pitch. The player rests fingers on the strings, so a pluck only makes a short, dry thud. It adds rhythm and groove without a clear note.", "purpose_function": "Dead notes add percussive rhythm and groove between pitched notes, filling space and driving the feel without changing the harmony.", "practical_application": "An engineer hears dead notes as short, click-like transients with little pitch and keeps compression and gating set so they stay part of the groove rather than being squashed or cut.", "category": "Articulation", "related_terms": ["ghost note", "palm mute", "cross-stick", "attack", "transient"], "common_mistakes": ["Confusing a dead note with a ghost note, which is very quiet but still pitched, when a dead note has no clear pitch.", "Gating a bass track so tightly that low-level dead notes disappear and the groove loses its feel.", "Reading the 'x' notation as a mistake or a cymbal choke instead of a muted note."], "scenario_contexts": ["A funk bass line using dead notes between pitched notes for a percussive groove.", "A guitar rhythm part with muted 'chuck' notes that drive the feel.", "Editing a bass DI where dead notes must stay audible after compression."]}, "a95fa156-b2e6-499b-9c35-80222cea46e9": {"definition": "An onomatopoeic term for a subgenre and guitar-tone style of modern progressive metal, marked by a heavily distorted, tightly palm-muted, percussive low-string 'chug', usually on down-tuned or extended-range (7- or 8-string) guitars and played in syncopated, rhythmically complex patterns. The word imitates the short, muted attack of the sound.", "plain_english": "Djent is the name for a heavy metal guitar sound. It is a tight, chunky, muted chug on low, down-tuned strings, played in tricky rhythms. The word copies the short, punchy sound the guitar makes.", "purpose_function": "The djent tone exists to make low, heavy riffs sound tight and percussive rather than muddy, so fast, syncopated rhythms stay clear and punchy.", "practical_application": "When mixing djent, an engineer keeps the guitars tight with high-pass filtering, careful gain staging, and a controlled low end so the palm-muted chugs stay defined and do not turn to mush.", "category": "Tonal Descriptor", "related_terms": ["palm mute", "chug", "distortion", "attack", "transient"], "common_mistakes": ["Thinking djent is just heavy distortion, when its defining feature is the tight, palm-muted, rhythmic chug, not raw gain.", "Adding too much low end so the chugs turn muddy and lose their percussive attack.", "Confusing djent with any down-tuned metal, when its rhythmic, muted articulation is the key trait."], "scenario_contexts": ["Mixing a modern metal track that needs tight, percussive palm-muted guitars.", "Dialing an amp or amp-sim for a djent tone with a controlled low end.", "Identifying a guitar part as djent by its syncopated, muted chugging."]}, "b471662d-748a-42e2-a733-e0544c30d8d9": {"definition": "A sound event that shows two distinct attack transients where a single onset is expected, heard as an unintended doubling of a note's start. It commonly appears as double-triggering on electronic drum pads or MIDI triggers, or as a flammed, doubled onset on an acoustic source.", "plain_english": "This is when one note or hit seems to start twice. You hear two quick attacks instead of one. On electronic drums it often happens when a single hit is read as two.", "purpose_function": "Recognizing a double attack helps a technician tell a genuine musical doubling from a fault, such as a mis-set trigger, so it can be fixed or kept on purpose.", "practical_application": "A technician spots a double attack as two close transients on a waveform and, for electronic drums, adjusts the retrigger cancel or mask time and trigger sensitivity so one hit no longer registers twice.", "category": "Attack Artifact", "related_terms": ["attack", "transient", "double-triggering", "flam", "retrigger"], "common_mistakes": ["Mistaking a double attack for a natural flam when it is really a trigger reading one hit as two.", "Raising trigger sensitivity to catch weak hits and causing more double attacks.", "Trying to fix double-triggering only in the mix instead of correcting the trigger's retrigger or mask setting."], "scenario_contexts": ["An electronic kick drum registering two hits from one pedal stroke.", "MIDI drum triggers producing doubled notes that need mask-time adjustment.", "Editing a drum take where a doubled onset must be judged as a flam or a fault."]}, "e982305a-f492-48a4-9016-6744daa5bdb5": {"definition": "Unwanted noise on a tonewheel (Hammond-type) organ caused by dirty, oxidized, or worn drawbar and manual contacts, typically heard as crackle, scratch, or intermittent dropouts when drawbars or keys move. It arises because the sliding, wiping electrical contacts pass the signal imperfectly.", "plain_english": "On a Hammond-style organ, this is the crackle you hear when the sliding controls or keys have dirty electrical contacts. It is like a scratchy volume knob. The sound comes from a poor connection, not the music.", "purpose_function": "Spotting drawbar noise tells a technician the organ's contacts need cleaning, so the real fault is fixed rather than mistaken for an amp or cable problem.", "practical_application": "A tech identifies drawbar noise as crackle tied to moving drawbars or keys and services it by cleaning the drawbar and manual contacts with the correct contact cleaner, restoring a clean signal.", "category": "Mechanical Artifact", "related_terms": ["drawbar", "tonewheel", "contact noise", "crackle", "signal dropout"], "common_mistakes": ["UNSAFE: Cleaning or probing inside a tonewheel organ while it is plugged in; it carries mains voltage, so unplug it and follow the service manual before opening it.", "Blaming crackle on the amplifier or cable when the real cause is dirty drawbar or key contacts.", "Spraying heavy oil or the wrong cleaner on the contacts, which attracts dirt and makes the noise worse."], "scenario_contexts": ["A Hammond organ crackles whenever a drawbar is moved during a session.", "Intermittent dropouts on certain notes traced to dirty key contacts.", "A tech scheduling contact cleaning after diagnosing drawbar noise."]}, "146ab74b-fe51-415d-bf8e-f315c7ba64dc": {"definition": "Sympathetic vibration of the non-speaking (duplex) string segments in a grand piano — the front and rear portions of each string beyond the agraffe and bridge — which are proportioned to sound harmonics of the struck note, adding high-partial brilliance and sustain to the tone.", "plain_english": "In a grand piano, the short bits of string on each side of the played part can be tuned to ring along with the note. This adds a bright, shimmering top to the sound.", "purpose_function": "It enriches a piano's timbre by letting extra string lengths resonate, reinforcing upper harmonics so the instrument sounds brighter and more sustained without any added striking force.", "practical_application": "An engineer close-miking a grand hears duplex resonance as extra sparkle and ring after each note, and can mute the duplex segments with felt strips when a cleaner, drier tone is wanted.", "category": "Piano Resonance", "related_terms": ["Sympathetic resonance", "Aliquot stringing", "Sustain", "Overtone series", "Decay"], "common_mistakes": ["Confusing designed duplex resonance with stray sympathetic ringing from other undamped strings.", "Treating it as unwanted noise to eliminate rather than a built-in part of the tone.", "Assuming every piano has tuned duplex segments, when many uprights and budget grands do not."], "scenario_contexts": ["Close-miking a concert grand and noticing extra high-frequency shimmer after each note.", "Damping the rear duplex with felt to tame brightness for a pop session.", "Comparing the tonal halo of a piano with duplex scaling against one without it."]}, "c100f574-356a-47a3-aa3b-6fb3d4d1c748": {"definition": "Striking a cymbal at its outer edge, rather than the bow or bell, to produce the loudest and most explosive attack, with a broad, fast-building spread of high overtones and a full crash character.", "plain_english": "Hitting a cymbal right on its outer rim. It gives the biggest, brightest crash and is the loudest way to strike it.", "purpose_function": "It gives a drummer the fullest, most cutting cymbal accent by exciting the widest range of vibration modes, producing a bright, sustaining crash that marks climaxes and transitions.", "practical_application": "When micing cymbals, engineers expect edge strikes to peak much hotter than bow strikes, so they set gain and limiting to survive the transient without clipping.", "category": "Percussion Attack", "related_terms": ["Bell strike", "Crash", "Transient", "Attack", "Cymbal wash"], "common_mistakes": ["Aiming a mic straight at the edge, where the strike moves the most air and can overload the capsule.", "Confusing an edge strike (crash) with a bow strike (ride ping).", "UNSAFE: Ignoring the very high peak SPL of close-miked edge strikes, risking hearing damage without protection."], "scenario_contexts": ["A drummer crashing a ride on the edge for a chorus accent.", "Setting cymbal mic gain to handle loud edge strikes during a rock take.", "Identifying edge-strike crashes versus bell hits while editing drum tracks."]}, "1111a910-4c0e-450e-aef6-7e63ecb04300": {"definition": "A faint mechanical click in a grand piano's action at let-off, produced when the jack escapes from under the hammer knuckle and releases the hammer to fly to the string; an incidental noise heard just before or with the note attack.", "plain_english": "A tiny click inside a grand piano when the key's lever lets the hammer go. It happens right as the note starts.", "purpose_function": "The escapement (let-off) exists so the hammer flies free and rebounds instead of jamming against the string; the click is a by-product of that release, not a designed sound.", "practical_application": "Engineers close-miking a piano may capture escapement clicks as mechanical noise and reduce them through mic placement, while a technician can regulate the action to quiet an overly loud let-off.", "category": "Piano Mechanism Noise", "related_terms": ["Let-off", "Piano action", "Attack transient", "Key noise", "Hammer"], "common_mistakes": ["Mistaking a normal escapement click for a fault or buzz in the instrument.", "Adjusting the wrong part instead of regulating let-off to reduce it.", "Assuming it can be removed entirely, when some mechanical noise is inherent to the action."], "scenario_contexts": ["Hearing faint clicks under quiet passages on a close-miked solo piano recording.", "A technician regulating let-off to quiet a noisy action.", "Editing mechanical clicks out of an exposed, intimate piano track."]}, "13bd9f24-a9fa-4ebf-8f9a-fd25eeb7da06": {"definition": "The onset transient of a note initiated directly by the finger — plucking a string with the fingertip or nail, or depressing a key — typically rounder and less percussive than the attack from a pick, hammer, or bow.", "plain_english": "The start of a note made with the finger instead of a pick. It is usually softer and warmer than a pick's sharp attack.", "purpose_function": "It shapes the very start of a note's envelope, and its gentler transient gives fingerstyle playing a warmer, more vocal character than plectrum or struck attacks.", "practical_application": "An engineer choosing mics and compression for fingerstyle guitar or bass works with a softer attack transient than for pick playing, setting attack times to preserve the natural onset.", "category": "String Articulation", "related_terms": ["Attack transient", "Finger pluck", "Pick attack", "Envelope", "Transient"], "common_mistakes": ["Setting compressor attack too fast and squashing the soft finger transient flat.", "Assuming a finger attack has no transient worth protecting and over-boosting highs.", "Confusing finger attack (the note onset) with finger noise (incidental string sounds)."], "scenario_contexts": ["Recording fingerstyle acoustic guitar and choosing a compressor that keeps the gentle attack.", "Dialing bass tone for a fingered part versus a picked part.", "Comparing the softer onset of fingered notes with slapped or picked ones."]}, "7515079d-164e-4d7d-8711-17a6dacc2f53": {"definition": "Incidental, non-pitched sounds produced by a player's fingers contacting the strings or fingerboard — squeaks, scrapes, buzzes and position-shift noises — regarded as an artifact when unwanted in a recording.", "plain_english": "Extra little sounds the fingers make moving on the strings, like squeaks and scrapes. They are often unwanted noise on a recording.", "purpose_function": "It is not a designed feature but a natural by-product of playing; spotting it lets a technician decide whether it adds realism or should be reduced.", "practical_application": "Engineers cut distracting finger noise with mic placement, EQ dips in the squeak range, or editing, while leaving enough to keep a natural, human feel.", "category": "Performance Artifact", "related_terms": ["Finger squeak", "Finger slide", "Fret noise", "String noise", "De-essing"], "common_mistakes": ["Over-editing until the track sounds lifeless and unnatural.", "Confusing normal finger noise with a mechanical fault in the instrument.", "Boosting presence EQ so far that finger noise turns harsh and obvious."], "scenario_contexts": ["Cleaning up an exposed solo acoustic guitar track.", "Choosing a string type that squeaks less for a session.", "Deciding how much natural finger noise to keep for realism."]}, "fa77c3fb-8dea-4be9-b24c-4ef690fd0cad": {"definition": "Setting a string into vibration by pulling it aside with the fingertip or nail and releasing it (fingerstyle), producing a rounder, warmer attack and different harmonic emphasis than a plectrum.", "plain_english": "Playing a string by pulling it with a finger and letting go. It gives a rounder, warmer sound than a pick.", "purpose_function": "It is the basic fingerstyle way to excite a string, giving the player direct control of dynamics and tone and a softer onset than a pick.", "practical_application": "Engineers record finger-plucked bass or guitar with attention to its fuller low end and softer transient, adjusting compression to suit.", "category": "String Articulation", "related_terms": ["Finger attack", "Fingerstyle", "Pizzicato", "Pick attack", "Transient"], "common_mistakes": ["Assuming a finger pluck and a pick stroke need identical processing.", "Overlooking hand and string position, which strongly change plucked tone.", "Confusing a finger pluck with slap technique."], "scenario_contexts": ["Tracking a fingerstyle electric bass line.", "Recording classical guitar plucked with the nails.", "Blending plucked and picked passages within one performance."]}, "a3abf2ab-4acd-40b7-90c0-54b685384ead": {"definition": "The sound produced when a fingertip slides along the length of a string, either as an intentional glissando between notes or as an incidental squeak during a position shift on a fretted instrument.", "plain_english": "The sound of a finger sliding along a string. It can be done on purpose between notes, or happen by accident when the hand shifts.", "purpose_function": "As a technique it connects notes with a smooth glissando; as an artifact it marks hand movement, and telling the two apart helps a technician keep musical slides and reduce accidental ones.", "practical_application": "Engineers keep expressive slides but tame unwanted slide squeaks with EQ or editing, and may suggest flatwound strings to reduce them.", "category": "String Articulation", "related_terms": ["Finger squeak", "Glissando", "Finger noise", "Fret noise", "Portamento"], "common_mistakes": ["Editing out musical slides along with the unwanted squeaks.", "Confusing an intentional glissando with accidental position-shift noise.", "Assuming any string slides the same, when flatwounds squeak far less."], "scenario_contexts": ["An electric guitar solo using slides for expression.", "Cleaning accidental shift squeaks from an acoustic take.", "Choosing strings to reduce slide noise for a close-miked session."]}, "ed98c85d-c556-4b68-aa16-990ead4002e8": {"definition": "A sharp, broadband percussive transient produced by snapping the thumb and middle finger together so the finger strikes the palm; used as a rhythmic sound source and recognizable by its brief, click-like envelope.", "plain_english": "The quick, sharp sound made by snapping your fingers. It is a short click used to keep or add rhythm.", "purpose_function": "It provides a natural, portable percussive accent, common in vocal and pop arrangements, with a very fast attack and almost no sustain.", "practical_application": "Engineers record finger snaps up close and often layer several takes for a fuller sound, using fast transient handling to keep the crisp attack.", "category": "Percussion Attack", "related_terms": ["Transient", "Attack", "Hand clap", "Percussive layer", "Envelope"], "common_mistakes": ["Recording a single snap and expecting it to sound big without layering.", "Using slow compressor attack that dulls the snap's sharp transient.", "Placing the mic so close the snap overloads the input."], "scenario_contexts": ["Layering finger snaps as a backbeat in a pop production.", "Capturing snaps for a sample library.", "Adding live snaps over a sparse verse."]}, "7bad7b42-6bb5-47dc-9a79-9ae9dda95885": {"definition": "The squeaking sound made when a finger slides across the ridges of a round-wound string, caused by friction between skin and the winding; a common and often unwanted artifact on close-miked guitar and bass.", "plain_english": "The squeak you hear when a finger slides over a wound string. It comes from the skin rubbing on the string's ridges.", "purpose_function": "It is not a designed sound but a natural by-product of finger movement on wound strings; recognizing it lets a technician decide whether to keep it for realism or reduce it.", "practical_application": "Engineers reduce finger squeak with flatwound or coated strings, string lubricant, EQ dips, or editing, keeping just enough for a natural feel.", "category": "Performance Artifact", "related_terms": ["Finger slide", "Finger noise", "Fret noise", "String noise", "De-essing"], "common_mistakes": ["Trying to remove every squeak and making the track sound unnatural.", "Blaming the instrument for a normal playing artifact.", "Boosting high EQ that makes the squeaks worse."], "scenario_contexts": ["An exposed acoustic guitar intro with audible string squeaks.", "Switching to coated strings to cut squeak for a session.", "Editing squeaks out of position shifts on a bass track."]}, "cfb3c65a-f604-4cc8-a7dd-7699f6726006": {"definition": "A wind-instrument articulation in which the player rolls the tongue tip (as in a rolled 'r') or flutters the throat or uvula while sustaining a note, adding a rapid buzzing or growling tremolo to the tone. It is used on flute and other woodwinds and on brass, and is marked 'flz.' or 'Flatterzunge' in the score.", "plain_english": "The player rolls their tongue, like a long rolled 'rrrr,' while blowing a note. This makes the sound flutter and buzz, like a growl on top of the note.", "purpose_function": "It colours a sustained tone with a fast, buzzing texture, giving players an expressive effect that ranges from a gentle shimmer to an aggressive growl.", "practical_application": "When miking or mixing a flute or trumpet passage marked 'flz.', an engineer expects a dense, buzzy tremolo and sets levels and any noise reduction so the flutter reads as intended rather than as a fault.", "category": "Articulation", "related_terms": ["Ghost note", "Grace note", "Tremolo", "Growl", "Vibrato", "Transient"], "common_mistakes": ["Confusing flutter tongue with vibrato; vibrato is a pitch or loudness wobble, while flutter tongue is a fast tongue- or throat-driven buzz.", "Assuming every player uses the tongue roll; some brass and low-flute players flutter with the throat instead.", "Applying heavy noise reduction that strips the buzzing texture and makes the note sound flat and unnatural."], "scenario_contexts": ["Recording an orchestral flute solo marked 'Flatterzunge' and capturing the buzz cleanly.", "A trumpet player using a flutter-tongue growl for a jazz or big-band effect.", "Identifying a buzzing wind note as an intended flutter tongue rather than a reed or valve fault."]}, "0dd0ffb2-f100-4fce-a8c5-9059d9fc3dc9": {"definition": "The short, crisp 'chick' sound a drummer produces by pressing the hi-hat pedal to clap the two cymbals together, without striking them with a stick. It marks time, often on beats 2 and 4, and gives a tight, quickly decaying accent.", "plain_english": "It is the short 'chick' sound a drummer makes by clapping the two hi-hat cymbals shut with their foot. No stick is used, so the sound is tight and stops fast.", "purpose_function": "It lets the drummer keep steady time and add a crisp accent with the foot while the hands play other drums, and it sets the tightness of the hi-hat groove.", "practical_application": "When recording drums, an engineer places the hi-hat mic to catch a clean 'chick' without too much snare bleed, and checks that the foot pattern sits in time with the backbeat.", "category": "Percussion articulation", "related_terms": ["Foot splash", "Ghost note", "Attack", "Decay", "Transient", "Backbeat"], "common_mistakes": ["Confusing the foot chick with a stick-struck closed hi-hat; the chick is made by the pedal alone and is shorter and softer.", "Mis-timing the foot so the chick drifts off the backbeat.", "Miking the hi-hat so far away that the chick loses its crisp attack and buries under the cymbal wash."], "scenario_contexts": ["A drummer marking beats 2 and 4 with the hi-hat foot during a quiet verse.", "Identifying a soft rhythmic tick in a drum recording as the hi-hat foot chick.", "Setting the hi-hat mic to capture a tight chick for a pop track."]}, "65859fd1-544d-4b3d-a80a-a35a81b187e1": {"definition": "A hi-hat sound made by quickly pressing the pedal to clash the cymbals and then releasing it, so the cymbals splash open and ring rather than close tightly. It produces a loose, sloshy, sustaining accent played with the foot alone.", "plain_english": "The drummer taps the hi-hat pedal and lets it open again fast, so the cymbals crash and keep ringing. It gives a loose, splashy sound instead of a tight click.", "purpose_function": "It adds an open, washy accent or fill using the foot, giving colour and a sense of lift without needing the hands.", "practical_application": "An engineer identifies a sloshy, ringing hi-hat accent as a foot splash and, if it clutters a mix, controls it with the hi-hat fader or gentle gating between hits.", "category": "Percussion articulation", "related_terms": ["Foot chick", "Ghost note", "Decay", "Sustain", "Attack", "Transient"], "common_mistakes": ["Confusing a foot splash with a splash cymbal; the splash here is the hi-hat opening, not a separate small cymbal.", "Releasing the pedal too slowly, so the cymbals close into a dull chick instead of ringing open.", "Gating the hi-hat too hard and cutting off the natural splash decay."], "scenario_contexts": ["A drummer accenting the end of a phrase with an open hi-hat foot splash.", "Recognising a loose, ringing hi-hat wash in a track as a foot splash.", "Deciding how much of a foot splash to keep when balancing a busy drum mix."]}, "8a3dc125-91b7-437d-a75e-37c9f395e356": {"definition": "An unwanted buzzing or rattling on a fretted string instrument caused by the vibrating string striking one or more frets along its length. It commonly results from low string action, uneven or high frets, too little neck relief, or very hard picking.", "plain_english": "It is the buzzing sound a guitar string makes when it slaps against the metal frets while it vibrates. It usually means the strings sit too low or a fret is uneven or too high.", "purpose_function": "It is a fault to spot and cure, not an effect; recognising fret rattle tells a technician that the instrument's setup, such as action, neck relief, or fret level, needs adjustment.", "practical_application": "A guitar tech listens and watches for fret rattle when setting string height and neck relief, and traces it to a specific fret to decide whether to adjust the truss rod, raise the saddle, or dress the frets.", "category": "Mechanical artifact", "related_terms": ["Gear noise", "String action", "Neck relief", "Sustain", "Attack", "Buzz"], "common_mistakes": ["Blaming the strings or amp for a buzz that is really fret rattle from the setup.", "Lowering the action for playability without checking that it causes fret rattle.", "Assuming all buzz is a bad fret when too little neck relief or a high nut can cause it."], "scenario_contexts": ["Setting up a guitar and lowering the action until fret rattle appears, then raising it slightly.", "Tracking a clean electric guitar and hearing a buzz that turns out to be fret rattle, not amp noise.", "Diagnosing a buzz at one position on the neck to locate a high or worn fret."]}, "ae2fa7db-54f4-4a32-bd76-ae3ec3307ef7": {"definition": "Unwanted background noise added to a signal by the audio equipment itself rather than by the source, such as the hiss of a preamp or converter or hum picked up in the gear. It sets the noise floor beneath the wanted sound and is measured as a device's self-noise or equivalent input noise.", "plain_english": "It is the faint hiss or hum that your recording gear adds on its own, even with no one playing. Every piece of gear makes a little noise, and this is the quiet floor under the real sound.", "purpose_function": "Naming gear noise helps a technician tell faults in the equipment apart from noise in the room or performance, so the right fix is chosen.", "practical_application": "An engineer checks gear noise by turning up a channel with no input and listening for hiss or hum, then improves gain staging or swaps a noisy preamp to keep the noise floor low.", "category": "Noise artifact", "related_terms": ["Fret rattle", "Noise floor", "Self-noise", "Hum", "Hiss", "Gain staging"], "common_mistakes": ["Blaming the microphone or room for hiss that is really the preamp's own self-noise.", "Turning up a noisy channel's gain instead of fixing the gain structure, which raises the noise along with the signal.", "UNSAFE: chasing a hum by lifting the mains earth or ground on equipment; this defeats a safety ground and can leave exposed metal live."], "scenario_contexts": ["Comparing two preamps by their self-noise to pick the quieter one for a soft acoustic source.", "Tracing a steady hiss under a quiet recording to a specific noisy device.", "Setting gain structure across a console to keep gear noise below the wanted signal."]}, "dfaed48d-7ec8-41a2-8a0f-13ac3a384854": {"definition": "The faint, low-level onset transient of a ghost note or similarly de-emphasized note: an attack so quiet it is felt or implied more than clearly heard, sitting well below the level of the accented notes around it. It marks the start of a note played with very light force.", "plain_english": "It is the soft start of a very quiet note, the kind a drummer or bass player slips in gently between the loud hits. You feel it more than you really hear it.", "purpose_function": "The term describes the quiet onset that gives a groove its subtle sense of motion and feel. Recognising it helps a technician preserve those soft attacks instead of losing them to gating or heavy compression.", "practical_application": "When mixing drums or bass, an engineer sets gate thresholds and compression so ghost attacks survive, keeping the groove's light, in-between notes audible.", "category": "Articulation", "related_terms": ["Ghost note", "Attack", "Transient", "Articulation", "Dynamics"], "common_mistakes": ["Setting a noise gate threshold so high that ghost attacks are cut off and the groove loses feel.", "Over-compressing until the quiet ghost attacks jump forward and lose their subtle role.", "Confusing a ghost attack with a recording glitch or noise, when it is an intended soft note."], "scenario_contexts": ["Preserving soft ghost-note attacks on a snare while gating a drum kit.", "Keeping the light in-between notes of a funk bass line audible in a mix.", "Editing programmed drums so ghost attacks stay quiet relative to the accents."]}, "be773e2e-520b-49e1-b1e1-14f14a97513b": {"definition": "A note played very quietly and with reduced articulation, so it is felt as rhythmic texture more than heard as a clear pitch or hit. On drums it is common on the snare between the main backbeats, and on bass or guitar it appears as a muted, percussive note; it is often written in parentheses.", "plain_english": "A ghost note is a note played so softly that you feel its rhythm more than you hear it. On drums it is a light tap on the snare between the loud hits that makes a groove feel alive.", "purpose_function": "Ghost notes add groove, swing, and rhythmic detail between the main accents without cluttering the music or fighting the backbeat.", "practical_application": "When mixing drums, an engineer sets compression and gating carefully so quiet snare ghost notes stay audible and are not squashed flat or gated out.", "category": "Articulation", "related_terms": ["Foot chick", "Foot splash", "Grace note", "Flutter tongue", "Attack", "Dynamics"], "common_mistakes": ["Confusing ghost notes with grace notes; ghost notes are about very low volume, while grace notes are quick ornaments before a main note.", "Playing ghost notes too loud, so they compete with the backbeat instead of supporting it.", "Over-compressing a drum bus so ghost notes jump up to the level of the main hits."], "scenario_contexts": ["A drummer adding light snare ghost notes to make a funk groove breathe.", "A bassist muting strings for percussive ghost notes between main notes.", "Setting snare compression so ghost notes stay quiet but present in a mix."]}, "c49263e2-3610-46a1-ac69-4756d33181ac": {"definition": "An informal descriptive term for a sound that resembles a gong: metallic and shimmering, with a slow swell, a spreading wash of inharmonic overtones, and a long, ringing decay. It is used to describe cymbals, reverbs, or resonances that ring in this metallic, gong-like way.", "plain_english": "'Gong-y' means a sound is metallic and ringing, like a big gong. It swells up and rings for a long time with a shimmery, clangy tail.", "purpose_function": "It gives engineers and musicians a quick shared word for a metallic, long-ringing character, whether that character is wanted or is an unwanted resonance to tame.", "practical_application": "An engineer might call a boomy metallic drum reverb 'gong-y' and pull back the tail or notch a ringing resonance to clean it up.", "category": "Tonal descriptor", "related_terms": ["Resonance", "Decay", "Sustain", "Ring", "Inharmonicity", "Timbre"], "common_mistakes": ["Treating 'gong-y' as a precise measurement rather than a subjective description that should be backed up by listening or a spectrum view.", "Confusing a gong-y ring from a genuine resonance with one added by reverb.", "Boosting high mids to add shimmer and accidentally making a cymbal or reverb sound harshly gong-y."], "scenario_contexts": ["Describing a long, metallic reverb tail as too gong-y during a mix.", "Identifying a gong-y ring on a floor tom as a resonance to be tuned or damped.", "Choosing a cymbal that is bright but not overly gong-y for a dense mix."]}, "df50b441-c8c4-4cb2-a7f0-4132dc3fd477": {"definition": "A small ornamental note, or short group of notes, of very brief duration, printed in smaller type and played immediately before or on the beat of the main note it decorates. Common types are the acciaccatura, crushed in as quickly as possible, and the appoggiatura, which leans on the beat and takes value from the main note.", "plain_english": "A grace note is a tiny, quick note squeezed in right before a main note to decorate it. It is printed small and passes by so fast it barely takes any time.", "purpose_function": "Grace notes ornament a melody, adding emphasis, flourish, or a smooth lead-in to the main note without changing its place in the rhythm.", "practical_application": "When editing MIDI or comping takes, an engineer keeps a grace note tight against its main note so the ornament reads clearly and does not sound like a flam or a timing error.", "category": "Ornament", "related_terms": ["Ghost note", "Flutter tongue", "Attack", "Transient", "Articulation", "Trill"], "common_mistakes": ["Confusing a grace note with a ghost note; a grace note is a quick ornament, while a ghost note is simply a very quiet note.", "Playing an acciaccatura too slowly so it sounds like a full melodic note.", "Quantising MIDI so hard that grace notes snap onto the beat and lose their ornamental feel."], "scenario_contexts": ["A guitarist adding a quick hammer-on grace note before a melody note.", "Editing a sampled string line so grace notes stay crisp and unquantised.", "Reading a score and recognising a small-printed note as a grace note ornament."]}, "45f3e4ff-dde8-4146-9991-3efe509faab9": {"definition": "A subjective timbral descriptor for a rough, buzzy, low-pitched and harmonically dense tone with an aggressive, gritty character. On wind and brass instruments 'growl' also names a specific technique in which the player hums or sings while blowing, producing rough beating overtones against the sounded note.", "plain_english": "A growl is a rough, buzzy, low sound, like a big animal grumbling. On a sax, players make it by humming while they blow, which roughs up the note.", "purpose_function": "The label lets engineers and players quickly aim for and describe a gritty, aggressive low-end character during tracking, mixing, or sound design.", "practical_application": "An engineer might add saturation, mild distortion, or a resonant low-mid boost to make a bass or synth sound growly, or close-mic a saxophone's bell to capture a played growl.", "category": "Timbre Descriptor", "related_terms": ["Grit", "Distortion", "Saturation", "Harmonic content", "Hard attack", "Rasp"], "common_mistakes": ["Confusing growl with plain distortion, when growl specifically implies a rough, low, buzzy quality rather than any harmonic clipping.", "Assuming a saxophone growl is added in the mix, when it is actually a live playing technique.", "Over-adding low-mid saturation until the tone becomes muddy rather than growly."], "scenario_contexts": ["Describing a distorted bass guitar tone in a mix note.", "A saxophonist adding growl to a solo in a jazz or funk chart.", "Sound-designing an aggressive synth bass for electronic music."]}, "678d961b-0311-4ba0-9f6e-bb841b862d3e": {"definition": "The initial percussive transient of a struck-string instrument such as a piano, produced at the moment the felt-covered hammer strikes the strings, before the note settles into its sustained, harmonically rich decay.", "plain_english": "The sharp start of a piano note, made when the hammer hits the strings. It is the quick 'thock' you hear just before the note rings out.", "purpose_function": "It gives a piano note its clear, percussive onset, which helps the ear place the note in time and recognize the instrument.", "practical_application": "When close-miking a piano, a technician balances mic position and transient handling so the hammer attack stays crisp without sounding clicky.", "category": "Attack Characteristic", "related_terms": ["Transient", "Hammer strike", "Attack", "Hammer noise", "Decay", "Onset"], "common_mistakes": ["Confusing the hammer attack (the musical transient) with mechanical hammer noise (unwanted action sound).", "Over-compressing the attack until the piano loses its natural percussive punch.", "Placing the mic so far back that the attack goes soft and undefined."], "scenario_contexts": ["Setting a compressor's attack time so a piano's initial transient is not squashed.", "Choosing a sample library based on how realistic its hammer attack sounds.", "EQ-ing a pop piano so the attack cuts through a dense mix."]}, "1ca3df87-868d-4fc1-8a18-1c342769c5fe": {"definition": "The soft, non-tonal component of a piano note's onset caused by the felt of the hammer compressing against the strings, heard as a cushioned thud layered under the pitched attack. Its character depends on felt hardness, wear, and voicing.", "plain_english": "The soft, dull sound the fuzzy hammer felt makes as it hits the piano strings. It is the padded thump mixed into the note's start.", "purpose_function": "It is a natural part of a real piano's tone, and its softness or hardness is shaped by voicing the felt to make the instrument brighter or mellower.", "practical_application": "A technician may notice heavy felt noise on a close-miked piano and adjust mic placement, or a piano technician may voice or reshape worn felt to control it.", "category": "Mechanical Noise", "related_terms": ["Hammer noise", "Hammer attack", "Voicing", "Hammer thump", "Attack transient"], "common_mistakes": ["Mistaking normal felt noise for a mechanical fault.", "Trying to remove felt noise entirely with EQ, which thins the natural attack.", "Ignoring hardened, worn felt that has made the noise harsh and clicky."], "scenario_contexts": ["Recording a soft solo piano passage where felt noise becomes noticeable.", "A piano technician voicing hammers to reduce a hard, noisy felt strike.", "Editing a close-miked piano track to tame distracting attack noise."]}, "5b3261e6-06ba-4426-9716-494d8bc98744": {"definition": "Non-tonal mechanical sound generated by a piano's hammer and action striking the strings, distinct from the pitched tone; it includes felt contact, wood knock, and action movement, and is heard mainly at the note's onset.", "plain_english": "The mechanical clunk of the piano's moving parts as a key is played, apart from the musical note. It is the 'machine' sound of the hammer hitting.", "purpose_function": "In small amounts it adds realism and presence to a piano's attack, but heavy hammer noise usually signals worn parts or poor voicing.", "practical_application": "When close-miking a piano, a technician sets mic distance and levels so hammer noise stays natural rather than distractingly loud.", "category": "Mechanical Noise", "related_terms": ["Hammer felt noise", "Hammer attack", "Hammer strike", "Voicing", "Hammer thump"], "common_mistakes": ["Assuming all hammer noise is a defect rather than a normal part of piano tone.", "Placing mics right over the hammers, which exaggerates the noise.", "Confusing hammer noise with string buzz or pedal noise."], "scenario_contexts": ["Diagnosing loud mechanical noise on a close-miked grand piano.", "A technician judging whether hammer noise points to worn felt.", "Choosing mic distance to balance tone against action noise."]}, "929625cb-c918-4d49-83ca-05f291e4f8f4": {"definition": "The physical event in which a piano hammer contacts the string or strings, imparting energy that sets them vibrating; it is the excitation that begins each note.", "plain_english": "The moment the piano hammer actually hits the strings and makes them ring. It is what starts every piano note.", "purpose_function": "It is the mechanism that turns a key press into sound, transferring the player's energy into string vibration.", "practical_application": "Understanding the hammer strike helps a technician judge attack character and diagnose issues like double-striking or uneven tone across keys.", "category": "Attack Characteristic", "related_terms": ["Hammer attack", "Hammer noise", "Excitation", "Transient", "String vibration"], "common_mistakes": ["Confusing the hammer strike (the physical event) with the hammer attack (the resulting sound).", "Overlooking a hammer that strikes twice and causes a stuttered note.", "Assuming a harder key press changes only loudness, when it also changes strike tone."], "scenario_contexts": ["Explaining why velocity changes both level and timbre in a piano sample.", "A technician regulating the action so each hammer strikes cleanly.", "Analyzing the onset of a piano note for sample editing."]}, "ca466777-c967-490c-9e39-afcad679959c": {"definition": "A dull, low-frequency thud in a struck-instrument onset produced by the mass of the hammer contacting the sounding element, heard as a soft low knock beneath the pitched attack.", "plain_english": "A low, soft thump at the start of a note when the hammer hits. It is the deep knock you feel more than hear.", "purpose_function": "It adds weight and body to the attack, but too much can muddy the low end or mask the note's pitch.", "practical_application": "An engineer may use a high-pass filter or transient control to tame an excessive hammer thump on a close-miked piano or mallet instrument.", "category": "Mechanical Noise", "related_terms": ["Hammer attack", "Hammer noise", "Hammer felt noise", "Low-frequency transient", "High-pass filter"], "common_mistakes": ["Confusing musical low-end body with unwanted hammer thump.", "High-passing so hard that the instrument loses its natural weight.", "Blaming the room for a thump that is actually mechanical."], "scenario_contexts": ["Cleaning up a boomy close-miked piano recording.", "Taming low thump on a mallet percussion track.", "Setting a high-pass filter on a piano channel in a live mix."]}, "0aa10839-73e4-4524-ae1d-7f54cf1067ae": {"definition": "A performance artifact consisting of the incidental sound made when a player moves or resets a hand on an instrument, such as fingers shifting on a fretboard, string bed, or keys, captured as a brief non-musical noise between or during notes.", "plain_english": "The little noise a player makes when they move a hand to a new spot on an instrument. Think of fingers sliding to a new place on guitar strings.", "purpose_function": "Recognizing it helps an engineer decide whether the noise is natural performance detail worth keeping or a distraction to edit out.", "practical_application": "During editing, a technician may fade, mute, or lightly EQ a hand-reposition noise so it does not distract in an exposed passage.", "category": "Performance Artifact", "related_terms": ["Fret noise", "Finger noise", "Artifact", "Editing", "Handling noise"], "common_mistakes": ["Removing every reposition noise, which can make a recording sound lifeless and unnatural.", "Missing loud reposition noises in quiet, exposed sections.", "Confusing a hand-reposition noise with a mechanical instrument fault."], "scenario_contexts": ["Editing finger-slide noise on a solo acoustic guitar track.", "Cleaning up an exposed harp or piano passage.", "Deciding how much natural handling noise to keep for realism."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"381d6dc0-08e3-464a-8803-a45d4bdf31fb": {"definition": "A convex steel percussion instrument (an idiophone) formed from two joined hemispherical shells, with a central tuned note and a surrounding ring of tuned tone fields hammered into the top surface, played with the hands and fingers. It descends from the Hang, which was developed using steelpan tuning techniques.", "plain_english": "A rounded steel drum played with the hands, shaped a bit like a flying saucer. Tapping its dented spots gives soft, bell-like notes.", "purpose_function": "It produces gentle, sustaining, harmonically rich tones for melodic and rhythmic playing without sticks, filling a mellow tuned-percussion role.", "practical_application": "When recording a handpan, an engineer usually uses one or two condenser mics to capture its wide tuned resonance and long sustain while controlling room reflections.", "category": "Instrument", "related_terms": ["Steelpan", "Idiophone", "Resonance", "Sustain", "Tuned percussion", "Overtone"], "common_mistakes": ["Calling every handpan a 'Hang', which is one specific maker's trademarked instrument.", "Miking too close, which loses the instrument's blended overtones and sustain.", "Expecting steel-drum brightness when the handpan is far mellower."], "scenario_contexts": ["Recording a handpan for ambient or meditative music.", "Placing mics to capture its long, ringing sustain in a live set.", "Blending a handpan with soft percussion in a mix."]}, "302b2d2f-6d36-4d4f-be06-b24991dbca9b": {"definition": "An onset with a fast, sharp, high-energy transient in which a note reaches full level almost immediately, giving a percussive, aggressive character. It contrasts with a soft or slow attack that fades in gradually.", "plain_english": "A note that starts fast and sharp, hitting full volume right away. Think of slapping a drum instead of gently blowing a flute.", "purpose_function": "A hard attack helps a sound cut through a mix and read as punchy or percussive, which aids rhythm and clarity.", "practical_application": "A technician can create or keep a hard attack by setting a synth's amp envelope to a near-zero attack time, or by using a slower compressor attack that lets the transient through.", "category": "Attack Characteristic", "related_terms": ["Attack", "Transient", "Envelope", "Soft attack", "Hammer attack", "Compression"], "common_mistakes": ["Setting a fast compressor attack that clamps the transient and softens the intended hard attack.", "Confusing a hard attack (fast onset) with high overall loudness.", "Adding a click transient so sharp it distorts or tires the listener."], "scenario_contexts": ["Programming a plucky synth bass with an instant attack.", "Dialing compressor attack time to keep a snare's hard hit.", "Describing a percussive piano or mallet sound in a session note."]}, "a69f5b42-df4d-418b-b0e7-5beede37d6a0": {"definition": "The harmonically rich portion of a sound that rings on after the initial attack, formed by the instrument's vibrating modes decaying at their own rates. It carries much of the note's pitch, richness, and timbre as the energy fades.", "plain_english": "It is the ringing sound that lingers after you first hit or pluck a note. Like a bell that keeps humming after you tap it, this tail slowly fades away.", "purpose_function": "It carries much of a sound's pitch and character, so the ear still recognises the instrument even after the sharp attack has passed.", "practical_application": "Engineers listen to the harmonic tail when setting reverb decay, gate release, and edit fades so a note dies away naturally instead of being cut off.", "category": "Decay & Resonance", "related_terms": ["Initial transient", "Head resonance", "Decay", "Sustain", "Overtone"], "common_mistakes": ["Confusing the harmonic tail with added reverb, when it is part of the instrument's own sound.", "Cutting the tail short with a fast gate release, which makes notes sound unnatural.", "Assuming the tail has no pitch, when it often defines the note."], "scenario_contexts": ["Setting a noise gate's release so a piano note's tail is not chopped off.", "Editing a guitar sustain in a DAW to fade smoothly.", "Matching reverb decay to the natural tail of a snare drum."]}, "c6dd92f3-1d19-4280-8178-d5229fab0b7c": {"definition": "The loose, washy, sustaining sound produced by hi-hat cymbals that are not fully closed, letting the two cymbals ring and rattle together. In recordings it is often heard as a smeared, uncontrolled wash rather than a tight, defined stick attack.", "plain_english": "It is the loose, washy sound of hi-hats that are not squeezed shut. The two cymbals slap and ring together, making a splashy 'shh' instead of a crisp tick.", "purpose_function": "Spotting hat slosh helps a technician judge whether a hi-hat part is tight and controlled or loose and messy, which affects the groove and clarity of a mix.", "practical_application": "When hi-hats sound washy, an engineer may ask for tighter playing, or use gating and EQ to tame the slosh in the recorded track.", "category": "Artifact Identification", "related_terms": ["Cymbal wash", "Bleed", "Decay", "Initial transient", "Hi-hat"], "common_mistakes": ["Trying to fix a washy hi-hat entirely with EQ instead of asking for tighter playing.", "Confusing hi-hat slosh with cymbal bleed picked up by other mics.", "Over-gating the hi-hat, which strips wanted stick detail along with the slosh."], "scenario_contexts": ["Diagnosing a loose, splashy hi-hat during a drum tracking session.", "Cleaning up washy hats in a dense mix with automation.", "Choosing hi-hat mic placement to reduce excess wash."]}, "b7245f9e-4170-42e0-a764-9de27e33ef03": {"definition": "The sharp initial transient produced at the moment a stick, mallet, or hand strikes a drumhead, before the membrane settles into its resonant ringing. It is the bright, click-like onset that defines a drum's punch and articulation.", "plain_english": "It is the sharp 'thwack' you hear the instant a stick lands on a drum. This first quick sound comes before the drum's longer ringing tone.", "purpose_function": "The head attack gives a drum its punch and clarity, helping each hit cut through a mix and letting the ear place the beat precisely.", "practical_application": "Engineers protect or boost the head attack with transient shapers, fast compressor timing, or close mic placement to keep drums punchy.", "category": "Attack Characteristics", "related_terms": ["Initial transient", "Head resonance", "Impact", "Transient shaper", "Attack"], "common_mistakes": ["Using a slow compressor attack that dulls the head attack.", "Confusing the head attack with the drum's ringing resonant tone.", "Over-boosting high frequencies to fake attack, which adds harshness."], "scenario_contexts": ["Setting compressor attack time on a snare to keep the stick 'crack'.", "Using a transient designer to add punch to a soft kick.", "Choosing mic position to capture the beater or stick strike."]}, "864c23fa-f546-406f-8a9a-7ed32f1622ae": {"definition": "The sustained ringing of a drumhead's membrane modes after it is struck, together with the tonal contribution of a drum's resonant (usually lower) head. It shapes the pitch, body, and sustain of the drum's sound.", "plain_english": "It is the ringing tone a drumhead makes after it is hit. Like a trampoline still bouncing after you jump, the skin keeps vibrating and singing for a moment.", "purpose_function": "Head resonance gives a drum its pitch, body, and sustain, and tuning it controls how long and how musically the drum rings.", "practical_application": "Technicians tune the resonant head and add muffling to control ring, adjusting sustain and pitch so the drum sits well in a mix.", "category": "Decay & Resonance", "related_terms": ["Harmonic tail", "Initial transient", "Head attack", "Sustain", "Resonance"], "common_mistakes": ["Over-muffling the head, which kills the drum's natural tone and sustain.", "Ignoring resonant-head tuning and blaming ring on the batter head alone.", "Confusing the drum's own head resonance with room reverb."], "scenario_contexts": ["Tuning a tom's resonant head to set its pitch and sustain.", "Adding a gate to control excessive snare ring.", "Diagnosing an unwanted ringing note in a kick drum."]}, "9be8155e-93e2-4ef4-a316-d057119e3c77": {"definition": "A bright, high-transient stroke made by slapping a drumhead sharply with the hand or fingers near the rim, common on hand drums such as congas and djembes. It produces a cracking, cutting attack distinct from the fuller open tone.", "plain_english": "It is a sharp slapping hit on a drum skin that makes a bright cracking sound. It cuts through more than a soft, round drum tone.", "purpose_function": "The slap adds a bright accent and rhythmic punctuation in hand drumming, giving contrast against the fuller open tones.", "practical_application": "Engineers recording congas or djembes set mic placement and transient control to capture the slap's crack without harshness or distortion.", "category": "Attack Characteristics", "related_terms": ["Head attack", "Initial transient", "Impact", "Transient", "Hit"], "common_mistakes": ["Confusing a slap tone with an open tone when identifying strokes.", "Placing a mic too close, which exaggerates the slap into harshness.", "Over-compressing and squashing the slap's sharp attack."], "scenario_contexts": ["Micing a djembe to capture both slap and bass tones.", "Balancing slap accents against open tones in a percussion mix.", "Taming a harsh conga slap with EQ."]}, "26a145c8-ae01-4370-8164-d6de93d9c560": {"definition": "A narrowband, high-frequency creaking or squeaking noise caused by friction in a mechanical hinge or pivot, such as a door, chair, mic-stand joint, or kick-drum pedal, captured unintentionally in a recording. It is an unwanted mechanical artifact identified during monitoring or editing.", "plain_english": "It is the high creaky sound a stiff hinge makes when it moves. In a recording it sneaks in as an unwanted squeak that you have to find and remove.", "purpose_function": "Identifying a hinge squeak lets a technician trace and stop the noise at its source or remove it, keeping the recording clean.", "practical_application": "Engineers hunt down squeaks from doors, pedals, or stands, then oil or isolate the source, or edit and use spectral repair to remove them.", "category": "Artifact Identification", "related_terms": ["Mechanical noise", "Spectral repair", "Noise floor", "Isolation", "Artifact"], "common_mistakes": ["Failing to trace the squeak to its source, so it returns on later takes.", "Confusing a hinge squeak with an intended sound in the performance.", "Trying to remove a resonant squeak with broad EQ instead of targeted spectral repair."], "scenario_contexts": ["Finding a squeaky kick-pedal during a drum session.", "Removing a chair or door squeak from a spoken-word recording with spectral repair.", "Isolating a mic-stand joint that creaks when touched."]}, "5073adb8-2b6c-4c12-b3fb-765d665c3f1a": {"definition": "A single percussive strike, or the short recorded or sampled sound of one such strike, made up of an attack transient followed by a decay. The term also covers layered one-shot samples such as an orchestra hit.", "plain_english": "It is one single strike of a drum or other sound, or a short sample of that one strike. Think of a single hand clap captured as one quick sound.", "purpose_function": "Individual hits are the building blocks of programmed beats and sample libraries, letting producers trigger precise, repeatable percussive events.", "practical_application": "Producers load hits into samplers and drum machines, trimming and shaping each one-shot's attack and decay before sequencing a groove.", "category": "Attack Characteristics", "related_terms": ["Initial transient", "Impact", "One-shot", "Sample", "Head attack"], "common_mistakes": ["Leaving silence or a click before a hit's attack, which causes timing errors.", "Trimming a hit too tightly and cutting off its decay.", "Confusing a single hit sample with a looped phrase."], "scenario_contexts": ["Programming a beat from individual drum hits in a sampler.", "Editing a recorded snare hit into a clean one-shot.", "Layering hits to build a bigger drum sound."]}, "0cadce3f-4e13-4ed7-855d-940f530a4d68": {"definition": "The brief, high-energy onset of a percussive or collision sound, carrying the sense of physical force and low-frequency punch felt at the moment of contact. It is the perceived weight of a transient rather than its bright click alone.", "plain_english": "It is the powerful 'boom' or 'thud' you feel when something hits hard. It is the part of a sound that makes it feel heavy and forceful.", "purpose_function": "Impact conveys power and physical weight, which is vital for drums, sound effects, and cinematic hits that need to feel big.", "practical_application": "Sound designers and engineers boost low-mid punch, layer sub-bass, and shape transients to strengthen the impact of drums and effects.", "category": "Attack Characteristics", "related_terms": ["Initial transient", "Head attack", "Hit", "Punch", "Transient"], "common_mistakes": ["Confusing impact, the low-frequency weight, with attack, the high-frequency click.", "Over-compressing until the impact loses its punch.", "Adding sub-bass so loud that it muddies the impact."], "scenario_contexts": ["Layering a sub-bass drop under a cinematic impact effect.", "Enhancing kick-drum weight so it hits harder on a club system.", "Shaping a gunshot effect to feel powerful in film sound."]}, "37854718-a2c7-4fbd-bf80-724a7048ec96": {"definition": "The very brief, high-amplitude, rapidly changing onset of a sound, occurring before it settles into a steadier state. It carries much of the information the ear uses to identify an instrument and to locate an event in time.", "plain_english": "It is the tiny burst of sound at the very start of a note, like the pluck before a guitar string rings. This quick first moment tells your ears what instrument it is.", "purpose_function": "The initial transient defines a sound's attack and articulation and is key to how clear and punchy it feels in a mix.", "practical_application": "Engineers protect the initial transient when compressing, using slower attack times or transient tools so drums and plucks stay punchy and clear.", "category": "Attack Characteristics", "related_terms": ["Head attack", "Impact", "Harmonic tail", "Transient shaper", "Attack"], "common_mistakes": ["Using a fast compressor attack that flattens the initial transient.", "Confusing the transient with the sustained body of the sound.", "Over-limiting a master and dulling all the transients."], "scenario_contexts": ["Setting compressor attack to preserve drum punch.", "Using a transient shaper to sharpen a dull sample.", "Diagnosing a mix that sounds flat because transients are squashed."]}, "2af7d923-af53-4dbf-915d-6fa80b097663": {"definition": "The manner in which individual notes on an instrument are started, sustained, connected, and released — including techniques such as legato, staccato, marcato, and accent — which shapes each note's attack, duration, and separation from its neighbours.", "plain_english": "Articulation is how a player starts, holds, and ends each note. It sets whether notes sound smooth and joined or short and clipped. Think of how you can say a word softly or sharply — notes work the same way.", "purpose_function": "It gives music expression and clarity by controlling note onsets, lengths, and transitions, and engineers use articulation cues to read a performance's attack and decay character.", "practical_application": "A technician listens for articulation when setting compressor attack and release, gating, or transient shaping so staccato and legato passages keep their intended feel; in sampling, articulation switches select different recorded playing styles.", "category": "Performance Technique", "related_terms": ["Attack", "Transient", "Envelope", "Legato", "Staccato", "Sustain"], "common_mistakes": ["Confusing articulation with dynamics — articulation is about note shaping and connection, not loudness.", "Setting a fast compressor attack that flattens staccato transients and blurs the articulation.", "Treating legato and staccato as notation marks only, rather than audible attack and decay changes."], "scenario_contexts": ["Choosing a sample-library articulation (legato vs staccato) for a virtual string part.", "Setting gate and compressor timing so a rapid staccato line stays crisp.", "Deciding whether a muddy passage is a room issue or blurred articulation."]}, "bb5e8053-60f7-4bf2-a3ef-7ad7a67b6a04": {"definition": "A bright, ringing, treble-rich timbre with prominent high harmonics and a shimmering, chiming quality, most associated with clean electric guitar — especially 12-string and compressed single-coil tones — where doubled or closely tuned strings add sparkle and sustain.", "plain_english": "Jangle is a bright, ringing guitar sound with lots of sparkle up top. It chimes and shimmers, a bit like sunlight on water. It is the classic clean, chiming tone of a 12-string electric guitar.", "purpose_function": "The term labels a specific high-frequency, chiming tonal character so players and engineers can aim for or pull back that sparkle, serving as shorthand for a recognisable clean-guitar timbre.", "practical_application": "An engineer chasing jangle boosts presence and 'air' EQ, adds light compression and chorus, and favours bright pickups or a 12-string, while taming any harshness that tips sparkle into brittleness.", "category": "Timbral Descriptor", "related_terms": ["Chime", "Presence", "Harmonics", "Shimmer", "Sustain", "Chorus"], "common_mistakes": ["Confusing jangle with harshness — jangle is musical sparkle, not thin, fatiguing high end.", "Trying to add jangle with EQ alone, ignoring string type, pickups, and light compression.", "Over-brightening until the tone becomes brittle and masks the vocals."], "scenario_contexts": ["Mixing a clean 12-string electric rhythm part to sit bright above the band.", "Deciding whether a guitar sounds jangly or simply too trebly.", "Recreating a chiming 1960s-style guitar tone."]}, "c7966cc2-d0b3-442c-83db-db5e54edcbaf": {"definition": "The resonant response of a kalimba (thumb piano) — the sustained, ringing tone produced when a plucked metal tine vibrates and couples to the instrument's soundboard and hollow body or resonating box, which amplifies and colours the sound and lengthens its decay.", "plain_english": "Kalimba resonance is the ringing hum of a thumb piano after you pluck a metal key. The wooden box under the keys makes the sound louder and last longer. It works like the body of a guitar boosting a plucked string.", "purpose_function": "Body and cavity resonance amplify the quiet vibration of each tine and shape the instrument's warm, bell-like sustain, which explains the kalimba's long decay and its ringing overtones.", "practical_application": "When recording a kalimba, a technician places the mic to balance direct tine attack against body resonance from the sound hole, and manages low-frequency boom or buzzing overtones the body emphasises.", "category": "Instrument Resonance", "related_terms": ["Resonance", "Sustain", "Decay", "Soundboard", "Overtones", "Body resonance"], "common_mistakes": ["Miking only the tines and missing the body resonance that gives the kalimba its warmth.", "Mistaking the instrument's natural buzzing overtones for a fault or rattle.", "Close-miking the sound hole and capturing excessive low-end boom."], "scenario_contexts": ["Recording a solo kalimba and choosing mic distance to capture body resonance.", "Diagnosing whether a low boom is room resonance or the kalimba body.", "Identifying the long ringing decay of a thumb piano in a mix."]}, "40d7f496-2fc8-44ed-9fd9-73e6dfc07081": {"definition": "A short, low-frequency percussive thump with strong impact and little sustain, such as the deep punch of a kick drum, 808, or low tom that is felt in the chest as much as heard. The term describes the tight low-end impact of a transient rather than a ringing or sustained tone.", "plain_english": "Knock is the deep, punchy thump of a kick drum or bass hit that you feel in your chest. It is a short, hard hit, not a long ringing note.", "purpose_function": "The term gives engineers a word for the tight, chest-hitting low-end impact of a percussive hit. It helps them aim for or dial in punch when shaping kicks and low percussion.", "practical_application": "To add knock to a kick, an engineer emphasizes the low-frequency thump near the beater impact with EQ or transient shaping while keeping the sustain short and controlled.", "category": "Percussive Artifact", "related_terms": ["Punch", "Attack", "Transient", "Boom", "Sub-bass"], "common_mistakes": ["Confusing knock, a short low-frequency impact, with boom, a longer resonant low-end buildup.", "Adding so much low end that the kick booms and muddies the mix instead of knocking cleanly.", "Assuming 'knock' always means a musical thump, when it can also describe a mechanical knocking fault noise."], "scenario_contexts": ["Shaping an 808 or kick so it knocks on club and car systems.", "Adding low-end punch to a hip-hop or dance kick during mixing.", "Judging whether a kick has enough knock to cut through on small speakers."]}, "e8b3da13-18af-47bd-ba30-d113d52869aa": {"definition": "The mechanical noise generated by the electric drive motors, belts, and bearings of a Leslie rotating-speaker cabinet — a low-level hum, whir, or rumble that can be captured by close microphones alongside the intended rotating-speaker sound.", "plain_english": "A Leslie speaker spins its horns using small electric motors. Those motors and belts make a faint hum or whir. Leslie motor noise is that mechanical sound leaking into the mic along with the music.", "purpose_function": "Recognising this hum as a mechanical artifact — not part of the musical tone — lets engineers reduce or clean it so it does not intrude on quiet passages.", "practical_application": "When close-miking a Leslie, a technician angles or spaces mics to reject motor and bearing noise, services worn belts and bearings that worsen it, and may gate or edit residual hum during silent sections.", "category": "Mechanical Artifact", "related_terms": ["Leslie swirl", "Rotating speaker", "Mechanical noise", "Rumble", "Close miking", "Doppler effect"], "common_mistakes": ["Mistaking motor rumble for low-frequency room noise or mic handling.", "Ignoring worn belts and bearings that make the noise louder over time.", "Placing mics so close that motor whir becomes audible in quiet passages."], "scenario_contexts": ["Close-miking a Leslie cabinet for a Hammond organ recording.", "Diagnosing a faint whir under a slow organ passage.", "Servicing a Leslie whose motor noise has grown louder."]}, "9704c393-e845-467b-aa29-d4776e430c07": {"definition": "The characteristic swirling, pulsating modulation produced by a Leslie rotating-speaker cabinet, created as the spinning treble horn and bass rotor sweep sound around the room and past the microphones, combining Doppler pitch shift, amplitude (tremolo) variation, and shifting phase and comb-filtering into a rich, three-dimensional movement.", "plain_english": "Leslie swirl is the spinning, wobbly sound of a Leslie speaker. As the horns rotate, the pitch and volume rise and fall and the tone seems to move around you. It is like a merry-go-round whooshing the sound past your ears.", "purpose_function": "The swirl adds motion, depth, and animation to organ and other sounds, and identifying its Doppler and tremolo parts helps engineers capture or emulate it faithfully.", "practical_application": "Engineers record the swirl in stereo with spaced mics on horn and rotor to capture its movement, choose chorale (slow) or tremolo (fast) speed, and match rotary-effect plug-in settings to imitate it.", "category": "Modulation Effect", "related_terms": ["Leslie motor noise", "Rotating speaker", "Doppler effect", "Tremolo", "Amplitude modulation", "Comb filtering"], "common_mistakes": ["Miking a Leslie in mono and losing the stereo movement that defines the swirl.", "Assuming the effect is only tremolo (volume) when Doppler pitch shift is a key part.", "Setting a rotary plug-in to a static speed and missing the slow-to-fast ramp between chorale and tremolo."], "scenario_contexts": ["Recording a Hammond organ through a Leslie for its swirling tone.", "Dialling a rotary-speaker plug-in to emulate the swirl on a synth.", "Distinguishing rotary swirl from chorus modulation in a mix."]}, "4dd95e37-6cec-4b03-8149-6a0e06bd042c": {"definition": "The audible mechanical click produced when a lever mechanism on an instrument is engaged or released — most commonly the sharping levers of a lever (folk/Celtic) harp that raise a string's pitch by a semitone — heard as a short, percussive tick that can be captured as an artifact in a recording.", "plain_english": "A lever click is the small tick a lever makes when you flip it on an instrument. On a folk harp, players flip levers to raise a string's pitch, and the flip can click. It is like the snap you hear when you click a light switch.", "purpose_function": "Identifying the click as mechanical action noise — separate from the played note — lets engineers minimise or edit it so it does not distract in quiet passages.", "practical_application": "Recording a lever harp, a technician anticipates lever changes, adjusts mic placement, and edits or gates stray clicks, while players may pre-set levers to avoid mid-piece changes near the mic.", "category": "Mechanical Artifact", "related_terms": ["Lever harp", "Mechanical noise", "Transient", "Artifact", "Key click", "String buzz"], "common_mistakes": ["Mistaking a lever click for an edit glitch or digital tick.", "Failing to plan lever changes so clicks land in loud, masked moments.", "Miking too close to the lever mechanism and exaggerating the click."], "scenario_contexts": ["Recording a Celtic lever harp with frequent lever changes.", "Cleaning stray mechanical ticks from a solo harp take.", "Distinguishing a lever click from a string buzz during editing."]}, "c9e23079-106d-43d8-a313-f30a36a79d92": {"definition": "The onset transient of a brass or lip-reed note as shaped by the player's embouchure and lips at the start of the tone; a lip- or breath-started attack, made without hard tonguing, produces a softer, more gradual onset than a crisply tongued attack.", "plain_english": "Lip attack is how a brass note begins from the player's lips. Starting a note with just the lips and breath gives a soft, gentle start. Using the tongue instead gives a sharper, crisper start.", "purpose_function": "It determines the shape and speed of a brass note's onset, affecting how punchy or smooth the attack sounds, and recognising it guides transient control and mic choice for brass.", "practical_application": "An engineer hearing soft lip attacks may choose a slower compressor attack and a closer mic to keep brass onsets natural, or add transient shaping when the section needs more bite.", "category": "Attack Characteristic", "related_terms": ["Attack", "Transient", "Lip buzz", "Embouchure", "Articulation", "Envelope"], "common_mistakes": ["Confusing a soft lip attack with a slow fade or a slow compressor attack.", "Over-compressing brass and squashing the natural difference between lip and tongued attacks.", "Assuming every brass note starts with a hard tongued transient."], "scenario_contexts": ["Miking a trumpet section and preserving natural note onsets.", "Setting compressor attack time so soft brass entries keep their shape.", "Deciding whether a gentle brass onset is a lip attack or an edited fade-in."]}, "0bdfe754-d7b7-4332-acb6-1311f9426ebe": {"definition": "The vibration of a brass player's lips — the lip reed — that acts as the sound source for brass instruments, produced by forcing air through tensioned, nearly closed lips so they open and close rapidly; the resulting buzz is amplified and filtered by the mouthpiece and instrument. The term also names the practice technique of buzzing on the lips or mouthpiece alone.", "plain_english": "Lip buzz is the buzzing a brass player makes with their lips. Air pushed through tight lips makes them flap open and shut fast, which starts the tone. The instrument then turns that buzz into a full note, a bit like blowing a raspberry into the mouthpiece.", "purpose_function": "The lip buzz is the primary sound generator for every brass instrument; without it the horn cannot sound, and the buzz frequency and strength set the note's pitch and tone.", "practical_application": "Players use lip buzzing, free or on the mouthpiece, to warm up and check embouchure, while engineers may hear the buzz character in close-miked brass and choose mic and EQ to keep the tone full but not harsh.", "category": "Sound Production", "related_terms": ["Lip attack", "Embouchure", "Mouthpiece", "Brass instrument", "Harmonics", "Resonance"], "common_mistakes": ["Thinking the mouthpiece or valves make the sound, when the buzzing lips are the true source.", "Confusing lip buzz with a cane-reed instrument — brass use the lips as the reed.", "Mistaking a player's audible buzz for a mechanical rattle or equipment fault."], "scenario_contexts": ["A trumpeter warming up by buzzing on the mouthpiece before a session.", "Explaining why brass tone depends on the player's lips, not the valves.", "Identifying lip buzz character in a close-miked trombone recording."]}, "66a4b73d-fdb4-41d9-9c6f-4b1e681bfa28": {"definition": "In sound-envelope analysis, decay is the portion of a sound in which its level falls after the initial attack; a long decay describes a note or event whose energy dies away slowly, ringing audibly for an extended time before fading to silence. It is typical of resonant instruments such as cymbals, gongs and sustained piano, and of reverberant spaces and long-release effects.", "plain_english": "Decay is how a sound fades after it first hits. A long decay means the sound rings out for a while instead of stopping fast, like a cymbal that keeps shimmering after you strike it.", "purpose_function": "Judging decay length tells a technician how an instrument, room or effect sustains energy over time, which shapes clarity and note separation in a recording or mix.", "practical_application": "When miking cymbals or a live room, an engineer identifies long decay and may add damping, shorten reverb or gate the tail to keep the low end and rhythm tight.", "category": "Decay characteristic", "related_terms": ["Attack transient", "Decay", "Sustain", "Resonance", "Reverberation time", "Ring-out"], "common_mistakes": ["Confusing an instrument's own long decay with reverb added by the room or a plug-in", "Assuming a long decay always needs shortening, when it is often musically wanted", "Gating too hard and cutting the natural tail, leaving an unnatural abrupt stop"], "scenario_contexts": ["Miking a ride cymbal that rings long after each hit", "Recording piano with the sustain pedal held down", "Tracking in a live room with a long natural reverberation tail"]}, "1d5f4a11-0550-4404-b22f-df30046da3eb": {"definition": "An unwanted buzzing or rattling artifact produced when loose mechanical hardware — drum lugs, cymbal-stand fittings, snare wires, screws or rack and console parts — vibrates sympathetically with a sound source, adding non-musical noise to a recording or live signal.", "plain_english": "This is the buzzing you get when a loose screw or fitting shakes along with the music. Like a rattling car door when the bass hits, it adds noise that should not be there.", "purpose_function": "Recognizing this artifact lets a technician trace and fix a mechanical noise at its source instead of blaming the mic, preamp or signal chain.", "practical_application": "When a drum kit buzzes on certain notes, an engineer hunts down and tightens the loose lug, stand or rattling object rather than reaching for an EQ.", "category": "Mechanical artifact", "related_terms": ["Mechanical noise", "Sympathetic resonance", "Buzz", "Snare buzz", "Rattle"], "common_mistakes": ["Trying to EQ or gate out a rattle instead of finding and tightening the loose part", "Blaming the microphone or cable for a noise that is mechanical", "Missing that the rattle only appears at frequencies that excite the loose part"], "scenario_contexts": ["A cymbal-stand fitting buzzing during loud passages", "Snare wires rattling when the floor tom is hit", "A loose screw in a guitar or lighting rig vibrating on stage"]}, "061cd758-29e4-4493-a881-7238a26a3b45": {"definition": "A swelling or buildup of low-frequency energy that develops just after the initial attack, caused by room resonances (modes), close-mic proximity effect or resonant sustain in the source; a moderate amount reads as warmth and fullness, while excess reads as muddiness or boom.", "plain_english": "This is when the bass swells up and fills out just after a note is played. A little makes music sound warm and full, but too much makes it boomy and muddy, like standing in a corner where the bass piles up.", "purpose_function": "Naming this behavior helps a technician judge whether the low frequencies are blooming pleasantly or building into muddiness that needs control.", "practical_application": "Hearing too much low-end bloom, an engineer may move a mic off a boundary, engage a high-pass filter or treat room modes to tighten the bass.", "category": "Resonance characteristic", "related_terms": ["Proximity effect", "Room modes", "Boominess", "Resonance", "Low-frequency buildup", "Sustain"], "common_mistakes": ["Confusing room-mode buildup with the instrument's own low end", "Cutting all low frequencies to fix bloom and leaving the sound thin", "Ignoring mic placement, which often causes bloom through proximity effect or boundaries"], "scenario_contexts": ["Close-miking a kick drum where the low end swells from proximity effect", "A bass guitar booming up in a small untreated room", "Vocals recorded near a wall picking up low-frequency buildup"]}, "ab75983a-84d5-471d-8c8d-69bd6243cee9": {"definition": "The rapid bounce of a mallet, beater or stick off the surface of a struck instrument (drumhead, keyboard-percussion bar, timpani) immediately after impact; it shapes the attack transient and can add a brief secondary contact sound or alter note articulation.", "plain_english": "When a mallet hits a drum or bar, it bounces right back off instead of staying pressed down. This quick bounce shapes how the note starts and can add a small extra tap sound.", "purpose_function": "Understanding rebound helps a technician recognize how the striking action shapes the attack and any short secondary contact noise in a percussion recording.", "practical_application": "Close-miking marimba or timpani, an engineer listens for how mallet rebound affects the attack and chooses mic placement or mallet hardness to get the wanted articulation.", "category": "Attack characteristic", "related_terms": ["Mallet strike", "Attack transient", "Articulation", "Transient", "Percussion"], "common_mistakes": ["Confusing the rebound contact sound with a recording glitch or click", "Overlooking that mallet hardness changes both attack and rebound character", "Blaming mic placement for articulation that comes from playing technique"], "scenario_contexts": ["Recording marimba where mallet rebound shapes each note's attack", "Timpani rolls where fast rebounds build a sustained texture", "Choosing mallet hardness to control attack on vibraphone"]}, "53d11053-c796-45e7-977c-6c11b90aac3c": {"definition": "The impact of a mallet or beater against a percussion instrument, generating the initial attack transient and exciting the instrument into vibration; the strike's speed, hardness and location set the tone's brightness, loudness and harmonic content.", "plain_english": "This is the moment a mallet hits a drum or bar and makes it sound. How hard, how fast and where you hit change how bright and loud the note is, like tapping a glass gently versus hitting it hard.", "purpose_function": "The strike defines the attack and initial tone of a percussion note, so identifying it helps a technician capture the transient cleanly and at the right level.", "practical_application": "An engineer sets mic distance and level headroom to handle the sharp transient of a mallet strike without clipping while keeping its punch.", "category": "Attack characteristic", "related_terms": ["Mallet rebound", "Attack transient", "Transient", "Percussion", "Articulation"], "common_mistakes": ["Setting levels for the sustain and then clipping on the sharp strike transient", "Miking too close and exaggerating the strike over the instrument's body tone", "Confusing strike-location changes with EQ problems"], "scenario_contexts": ["Recording xylophone where each mallet strike is a fast transient", "Setting gain to avoid clipping on hard timpani strikes", "Placing mics to balance strike attack against bar resonance on marimba"]}, "5f5e1514-c2e4-4140-8166-978205d52a72": {"definition": "Non-musical sound produced by the moving mechanical parts of an instrument as it is played — piano hammer and damper action, organ key and tracker action, or wind-instrument key pads and levers — which close microphones can capture alongside the intended tone.", "plain_english": "This is the sound of an instrument's moving parts, not the notes themselves, like the soft thump of piano keys or the click of a flute's keys. Close mics can pick it up along with the music.", "purpose_function": "Identifying action noise helps a technician decide whether it is natural character to keep or a distraction to reduce through mic choice and placement.", "practical_application": "When close-miking piano or woodwinds, an engineer repositions mics or adjusts distance to control how much key and hammer action noise is recorded.", "category": "Mechanical artifact", "related_terms": ["Mechanical noise", "Mechanical click", "Key noise", "Hammer noise", "Transient"], "common_mistakes": ["Trying to remove natural action noise entirely and losing the instrument's realism", "Placing mics right over the action and capturing excess mechanical noise", "Confusing action noise with an electrical or signal-chain fault"], "scenario_contexts": ["Close-miking a grand piano and hearing hammer and damper action", "Recording flute or clarinet where key pads click", "Tracking a pipe organ with audible tracker action"]}, "a02aceb1-1acc-4d44-87b1-00f6b70b0f3a": {"definition": "A brief, sharp transient noise of mechanical origin — such as a key, valve, pedal or switch contact — that appears as a short click in the audio, distinct from electronic clicks caused by digital or clocking faults.", "plain_english": "This is a short, sharp tapping sound made by a moving part, like a key or pedal snapping into place. It is a physical click, not a glitch from the electronics.", "purpose_function": "Telling a mechanical click apart from a digital one lets a technician fix the right thing — the instrument or hardware, not the signal chain.", "practical_application": "Hearing clicks on a track, an engineer checks whether they line up with a player's key or pedal movements before suspecting a digital dropout.", "category": "Mechanical artifact", "related_terms": ["Mechanical action noise", "Mechanical noise", "Key noise", "Digital click", "Transient"], "common_mistakes": ["Assuming every click is a digital dropout when it is really a physical mechanical click", "Missing that the click times with a player's key or pedal movement", "Editing out mechanical clicks that are part of the instrument's natural character"], "scenario_contexts": ["A pedal or key click captured on a close vocal or instrument mic", "Distinguishing a mechanical relay click from a digital error", "Woodwind key clicks appearing between notes"]}, "528d2a45-3fdf-4d45-b1dd-dd904217d92d": {"definition": "A dull, low-pitched thud or knock of mechanical origin, produced by heavier moving parts or contact — a pedal hitting its stop, a stand or boom moving, or hardware impact — heard as a brief low-frequency transient in the signal.", "plain_english": "This is a dull, heavy thud from a moving part, deeper than a light click. Think of a pedal hitting the floor or a stand knock, a low bump that lands in the recording.", "purpose_function": "Recognizing a clunk as mechanical helps a technician trace it to a physical part rather than an electronic fault.", "practical_application": "When a low thud shows up on a track, an engineer looks for a pedal, stand or hardware knock and isolates or dampens the source.", "category": "Mechanical artifact", "related_terms": ["Mechanical noise", "Mechanical click", "Rumble", "Thump", "Transient"], "common_mistakes": ["Confusing a mechanical clunk with a low-frequency electronic pop", "Overlooking floor or stand vibration that carries the clunk into a mic", "Trying to EQ out a clunk instead of stopping the physical knock"], "scenario_contexts": ["A sustain pedal clunking against its stop during a piano take", "A mic stand or boom knocked on stage", "A heavy switch or fader creating a low thud"]}, "e53a5a90-0370-408e-8859-67134dfa8d0a": {"definition": "Any unwanted sound arising from the physical motion, vibration or contact of mechanical parts — instrument mechanisms, hardware, stands, fans or tape transports — as opposed to electrical, acoustic or musically intended sound; it enters the signal when picked up by microphones or transmitted structurally.", "plain_english": "This is any unwanted noise made by moving or vibrating parts, like keys, stands or a cooling fan, rather than by the electronics or the music itself. Mics can catch it, or it can travel through the floor into the gear.", "purpose_function": "Grouping these noises as mechanical helps a technician separate physical-source problems from electrical ones and fix them at the source.", "practical_application": "Troubleshooting stray noise, an engineer checks mechanical sources — loose hardware, stands, fans, HVAC — and isolates, tightens or dampens them before touching the signal chain.", "category": "Mechanical artifact", "related_terms": ["Loose hardware rattle", "Mechanical action noise", "Mechanical click", "Mechanical clunk", "Structure-borne noise"], "common_mistakes": ["Assuming noise is electrical when it is mechanical in origin", "Trying to fix mechanical noise with EQ or gates instead of at the source", "Ignoring structure-borne paths, such as vibration through floors and stands"], "scenario_contexts": ["A computer or amplifier fan bleeding into a quiet vocal take", "Loose kit hardware buzzing during loud drumming", "HVAC or foot noise transmitted through the floor into stands"]}, "0b1aa628-51b0-4880-93d2-ad62046cb569": {"definition": "A short, percussive pop produced at a brass or wind instrument's mouthpiece, created either deliberately as an extended technique (slapping the palm over the mouthpiece rim or a hard tongue-stop release) or incidentally at a note's onset; its rough pitch is set by the air volume of the mouthpiece and instrument, including any valves depressed.", "plain_english": "A quick pop sound made right at a horn player's mouthpiece. A player can make it on purpose as an effect, or it can slip in by accident at the start of a note. It sounds a bit like tapping the top of an empty bottle.", "purpose_function": "As an effect it gives brass and winds a drum-like percussive sound without a normal tone; as an artifact, spotting it flags an over-hard attack that a microphone can capture as a click or thump.", "practical_application": "An engineer learns to recognize it so a wanted pop in a contemporary piece is preserved, while an unwanted one is tamed with mic placement, distance, or gentle transient control rather than harsh gating.", "category": "Attack artifact", "related_terms": ["Mute insertion noise", "Slap tongue", "Transient", "Attack transient", "Plosive"], "common_mistakes": ["Confusing a mouthpiece pop with a breath plosive hitting the microphone.", "Assuming every pop is a fault to remove, when it may be a scored effect.", "Gating the pop out and cutting the note's real attack along with it."], "scenario_contexts": ["Recording a contemporary brass piece that scores mouthpiece slaps as percussion.", "Spotting a percussive click at note onsets while editing a trumpet track.", "Live-miking a trombone where hard attacks pop in the PA."]}, "3555ad41-7f9c-480e-b1cd-9a9a4f7e0697": {"definition": "The brief mechanical scrape, bump, or squeak captured when a player pushes a mute into a brass instrument's bell, heard as a short non-tonal noise just before a muted passage begins.", "plain_english": "The little scrape or bump you hear when a player pushes a mute into the bell of a trumpet or trombone. It is like the sound of sliding a cork into a bottle. A close mic can pick it up by accident.", "purpose_function": "It is an incidental artifact rather than a musical sound; recognizing it tells an engineer that a mute change happened and helps them decide whether to keep or clean it.", "practical_application": "On close-miked brass an engineer edits or crossfades over insertion noise, or arranges enough rest so the player can mute quietly and off-axis between phrases.", "category": "Mechanical noise", "related_terms": ["Mute removal noise", "Mouthpiece pop", "Handling noise", "Transient"], "common_mistakes": ["Mistaking mute insertion noise for a digital dropout or edit click.", "Editing it out so tightly that the following note's attack is clipped.", "Not leaving enough rest in the arrangement for a quiet mute change."], "scenario_contexts": ["Editing a jazz trumpet solo where the player switches to a Harmon mute.", "Close-miking a muted trombone section in the studio.", "Cleaning stray noises from an orchestral brass recording."]}, "66668e41-ac49-4312-82fe-2db3301f863f": {"definition": "The short mechanical noise captured when a player pulls a mute out of a brass instrument's bell, often a soft pop, scrape, or rattle heard as a muted passage ends and open tone returns.", "plain_english": "The small pop or scrape you hear when a player pulls the mute back out of the bell. It is like tugging a cork free. A close mic can catch it as the muted part ends.", "purpose_function": "Like insertion noise, it is an incidental artifact and not a tone; recognizing it lets an engineer judge whether to keep the natural sound or remove it.", "practical_application": "Engineers clean or crossfade removal noise on close-miked brass, or coach players to withdraw the mute slowly and away from the microphone axis.", "category": "Mechanical noise", "related_terms": ["Mute insertion noise", "Mouthpiece pop", "Handling noise", "Decay"], "common_mistakes": ["Confusing mute removal noise with a note's natural release.", "Cutting too aggressively and removing the tail of the muted note.", "Assuming it is microphone self-noise rather than the player."], "scenario_contexts": ["End of a muted brass phrase returning to open tone.", "Editing a big-band chart with frequent mute changes.", "Live sound where a soloist removes a mute near a sensitive mic."]}, "acab400f-c5d9-444c-b3ce-6574f88f40ea": {"definition": "The rapid, shortened decay of a note whose vibration is deliberately damped, such as a palm-muted guitar string, a hand-stopped horn, or a felt-muted piano string, giving a clipped tail instead of the full natural ring.", "plain_english": "How fast a note dies away when the player deadens it. Resting a hand on a guitar string is one way to do this. Instead of ringing out, the sound stops short and feels tight.", "purpose_function": "Muting controls sustain and note length to tighten rhythm and cut wash; recognizing muted decay helps an engineer read how a part was played and how long its tail really is.", "practical_application": "An engineer hears muted decay and sets gate release, reverb time, and compression to match the short tail rather than fighting it or adding unnatural sustain.", "category": "Decay characteristic", "related_terms": ["Natural decay", "Palm mute", "Damping", "Sustain", "Release"], "common_mistakes": ["Trying to add sustain with heavy compression, which mostly lifts noise between notes.", "Setting a slow gate release that lets the choked tail ring unnaturally.", "Confusing intentional muting with a dead string or a failing pickup."], "scenario_contexts": ["Palm-muted electric guitar chugs in a rock mix.", "A hand-stopped french horn passage.", "Choosing reverb tail length for a staccato, muted part."]}, "07c4c46e-0460-4867-9c3a-847e3505373a": {"definition": "The bright, percussive onset produced when a plucked-string player strikes the string with the fingernail, as on classical guitar or harp, giving a sharper, higher-transient attack than playing with the flesh of the fingertip alone.", "plain_english": "The sharp, bright start of a note when a player plucks with a nail instead of just skin. The nail gives a crisp ping, much like a pick would. It makes the note stand out more.", "purpose_function": "The nail shapes tone color and attack sharpness; a player uses more nail for brightness and projection and more flesh for a rounder, softer onset.", "practical_application": "An engineer recognizes a nail-heavy attack and may soften harsh transients through microphone choice, angle, and distance, or gentle high-frequency control, rather than assuming an EQ fault.", "category": "Attack characteristic", "related_terms": ["Nail click", "Pick attack", "Transient", "Attack", "Natural harmonic"], "common_mistakes": ["Assuming a bright attack is harsh EQ when it is really the player's nail.", "Over-brightening a track that already has a strong nail attack.", "Confusing a musical nail attack with an unwanted nail click."], "scenario_contexts": ["Close-miking a classical guitar for a solo album.", "Recording a fingerstyle acoustic part.", "Balancing brightness on a harp track."]}, "d3875aa7-2262-4090-bd80-c14cfe68f272": {"definition": "An unwanted clicking or ticking artifact caused by a fingernail contacting a string, or a nail catching a wound string, heard as a short non-tonal tick separate from the intended note.", "plain_english": "A small unwanted tick when a player's nail catches a string. It is a tiny clatter that sits on top of the note. Most of the time it was not meant to be there.", "purpose_function": "It is an artifact, not a technique; spotting it lets an engineer or player decide whether to fix it at the source or edit it out.", "practical_application": "Engineers reduce nail click by adjusting mic position, coaching nail length and angle, or editing isolated ticks, since EQ alone rarely removes them cleanly.", "category": "Performance artifact", "related_terms": ["Nail attack", "String noise", "Finger squeak", "Nut buzz", "Fret buzz"], "common_mistakes": ["Trying to EQ out a click, which shares frequencies with the wanted note.", "Blaming the instrument when the cause is nail length or angle.", "Confusing nail click with fret buzz or nut buzz."], "scenario_contexts": ["Fingerstyle guitar recording with audible ticks on position shifts.", "Classical guitar close-mic capturing nail noise.", "Cleaning stray ticks in a solo guitar edit."]}, "c95432e4-5597-4956-bcb5-63efb62fe126": {"definition": "The natural, uninterrupted fading of a sound after its initial excitation, as the vibrating source loses energy to internal damping and radiation; the note rings out and quiets on its own rather than being cut or damped short.", "plain_english": "How a sound fades away on its own after it is played. A struck bell slowly going quiet is a good example. Nothing stops it early; it just loses energy and dies out.", "purpose_function": "Natural decay defines a sound's tail and its sense of space; recognizing it guides how much reverb, sustain, or gating a part needs.", "practical_application": "An engineer sets gate and reverb times to respect a note's natural decay so tails are not chopped off or buried under added effects.", "category": "Decay characteristic", "related_terms": ["Muted decay", "Sustain", "Release", "Reverberation", "Resonance"], "common_mistakes": ["Setting a fast gate that clips the natural tail.", "Mistaking room reverb for the instrument's own decay.", "Adding reverb that masks the natural decay instead of extending it."], "scenario_contexts": ["Choosing gate release on tom or piano tracks.", "Judging a cymbal's ring-out before an edit cut.", "Matching a reverb tail to an acoustic guitar's decay."]}, "5cce0762-8496-477c-8a73-d3365908a0d8": {"definition": "A flute-like harmonic sounded on an open string by lightly touching it at a node point (for example over the 12th, 7th, or 5th fret on guitar) so that only a higher mode of the harmonic series speaks while the fundamental is suppressed.", "plain_english": "A clear, bell-like note made by resting a finger very lightly on an open string. You do not press it down to a fret. Touching the right spot lets a higher, pure tone ring out instead of the normal note.", "purpose_function": "Natural harmonics extend an instrument's range with a distinctive chime-like timbre and give pure overtone pitches; their node positions also serve as reference points for tuning and intonation.", "practical_application": "A player uses them for chiming effects and harmonic tuning, while an engineer notes their low level and pure tone and may need extra gain or careful mic placement to capture them cleanly.", "category": "Harmonic", "related_terms": ["Artificial harmonic", "Node", "Overtone", "Fundamental", "Resonance"], "common_mistakes": ["Pressing the string down instead of touching it lightly, which kills the harmonic.", "Touching between nodes so the harmonic does not speak.", "Confusing a natural open-string harmonic with an artificial fretted one."], "scenario_contexts": ["A guitarist chiming 12th-fret harmonics to tune.", "Recording harmonics that need extra gain to sit in a mix.", "Identifying bell-like overtones in a string part."]}, "ddb08598-7b1d-4f4b-aff7-d3100103ca5c": {"definition": "A buzzing or rattling artifact originating at the nut of a fretted string instrument, usually caused by a nut slot cut or worn too low so an open string vibrates against the slot or the first fret; it affects open strings and disappears once the string is fretted.", "plain_english": "A rattly buzz from an open string near the top of the neck, at the small slotted part called the nut. It usually means a string slot is worn too low. The buzz goes away once you press the string down on a fret.", "purpose_function": "It is a fault symptom, not a feature; recognizing nut buzz tells a technician that the nut slot is too low or worn and needs shimming, filling, or replacement.", "practical_application": "A technician confirms nut buzz by checking that it occurs only on open strings, then raises the slot with a shim or filler or fits a new nut, since it cannot be fixed with EQ.", "category": "Buzz artifact", "related_terms": ["Fret buzz", "String buzz", "Action", "Setup", "Nail click"], "common_mistakes": ["Confusing nut buzz with fret buzz, though nut buzz stops when the string is fretted.", "Filing a slot even deeper, which makes the buzz worse.", "Blaming the strings or pickup for a mechanical nut problem."], "scenario_contexts": ["Open strings buzz on a guitar while fretted notes stay clean.", "Setting up a guitar after fitting a new nut.", "Diagnosing a rattle on an acoustic before recording."]}, "d7b4b08f-914d-4b05-8be1-ec726260f9e3": {"definition": "The onset is the moment a note or sound begins, the instant its amplitude starts rising from silence, marking the leading edge of the attack. In signal analysis it is the detected start time of an acoustic event, distinct from the attack (the rise itself) and the transient (the brief energetic burst around it).", "plain_english": "The onset is the exact moment a sound starts. It is like the first tick you hear when a drum is hit, before the note fully blooms.", "purpose_function": "Marking the onset lets engineers and software line up the true start of each note for timing, editing, and rhythmic analysis.", "practical_application": "A technician relies on onset points when quantizing drums, tightening edits, or setting a gate or transient shaper to trigger on a note's true start.", "category": "Attack", "related_terms": ["Attack", "Transient", "Decay", "Sustain", "Envelope", "Transient shaper"], "common_mistakes": ["Confusing the onset (when the sound starts) with the attack (how fast it rises to its peak).", "Placing an edit or gate slightly after the onset, which cuts off the note's leading edge.", "Assuming onset detection is exact on soft or slow-building sounds, where the true start is gradual and hard to pin down."], "scenario_contexts": ["Quantizing a multitracked drum kit by aligning each hit to its onset.", "Setting a noise gate to open at a vocal's onset without clipping the first consonant.", "Using onset detection in a DAW to slice a loop into individual hits."]}, "047e4d12-505c-449a-b443-f898e82c5bc8": {"definition": "Open wash is a broad, undamped blend of sustained, overlapping sound with no clear pitch or transient focus, such as the ringing spread of open cymbals or a diffuse reverb tail. It is heard as a continuous, blurry layer of energy rather than as distinct notes.", "plain_english": "An open wash is a wide, blurry cloud of sound that keeps ringing. Think of crash cymbals or a big echo smearing together into one smooth haze.", "purpose_function": "Naming it helps a technician spot when sustained, undamped sound is filling space and masking detail, so they can judge whether it adds atmosphere or clutters the mix.", "practical_application": "An engineer hears an open wash when open cymbals or heavy reverb blur a mix, and may dampen the source or shorten the reverb to regain clarity.", "category": "Resonance", "related_terms": ["Reverb tail", "Cymbal wash", "Sustain", "Overtone ring", "Decay", "Masking"], "common_mistakes": ["Mistaking an open wash of reverb for a problem with the source instrument itself.", "Letting cymbal wash build up unchecked until it masks vocals and bleeds into every drum mic.", "Adding more reverb to fix a thin mix and turning it into an indistinct wash."], "scenario_contexts": ["A live drummer rides open cymbals, creating a wash that blurs the whole kit mix.", "A long hall reverb on many tracks blends into a single open wash.", "An ambient guitar part and reverb combine into a continuous wash of sound."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"133a07ea-1026-430c-b194-b920726789f8": {"definition": "Overtone ring is the audible, sustained resonance of one or more overtones (harmonic or inharmonic partials) that keep sounding after the fundamental attack, often as an unwanted ringing on drums, cymbals, or strings. It is heard as a pitched or metallic ringing tail sitting above the main note.", "plain_english": "Overtone ring is a high, ringing tone that keeps buzzing after you hit something. A drum that goes 'boinnng' after the hit is ringing with overtones.", "purpose_function": "Identifying overtone ring lets a technician decide whether the resonance is musical or an unwanted artifact that needs damping or retuning.", "practical_application": "A technician damps a ringing tom with a muffling ring or gel, or retunes the heads, to control overtone ring before recording.", "category": "Resonance", "related_terms": ["Resonance", "Overtone", "Sustain", "Damping", "Decay", "Sympathetic resonance"], "common_mistakes": ["Confusing an instrument's natural overtones with an unwanted overtone ring that should be tamed.", "Over-damping a drum to remove ring until it sounds dead and lifeless.", "Trying to EQ out a ring that is really a tuning problem in the drum heads."], "scenario_contexts": ["A tom rings loudly after each hit and needs damping before tracking.", "A snare produces a metallic overtone ring picked up by nearby mics.", "A guitar string keeps ringing sympathetically and colors sustained chords."]}, "49c8fdcc-7ec1-40d9-a7e5-8b6713efb1c5": {"definition": "Pad click is a short click or transient heard at the onset of a sustained synth or sampler 'pad' sound, typically caused by an abrupt amplitude-envelope attack or a waveform discontinuity at the sample start or loop point. It is an unwanted artifact riding on the front of an otherwise smooth, slow-swelling sound.", "plain_english": "A pad click is a tiny click at the very start of a smooth, floaty synth sound. It happens when the sound switches on too suddenly instead of easing in.", "purpose_function": "Spotting a pad click tells the technician the sound is starting too abruptly, so they can soften the attack or fix the waveform start.", "practical_application": "A producer lengthens the amplitude envelope's attack or adds a tiny fade at the sample start to remove a click from a pad patch.", "category": "Noise artifact", "related_terms": ["Attack", "Envelope", "Transient", "Zipper noise", "Fade", "Onset"], "common_mistakes": ["Blaming the click on the audio interface when it is really the patch's envelope.", "Setting a pad's attack to zero, which reintroduces a click on every note.", "Editing a sample loop without zero-crossing edits, leaving clicks at the seams."], "scenario_contexts": ["A slow synth pad clicks on every note because its attack is set too fast.", "A looped sampler pad clicks at the loop point during sustained chords.", "A bounced pad track shows clicks where fades were not applied at region edits."]}, "ee553c50-dc7f-451f-80a9-861b1f94df81": {"definition": "Palm mute is a guitar and bass articulation in which the side of the picking-hand palm rests lightly on the strings near the bridge while picking, damping the strings to shorten their decay and give a tight, muffled, percussive tone. The amount of muting varies with palm pressure and distance from the bridge.", "plain_english": "A palm mute is when a guitarist rests the edge of their hand on the strings near the bridge while playing. This makes the notes short and chunky instead of ringing out.", "purpose_function": "Palm muting controls sustain and adds a tight, percussive attack, letting a player create rhythmic 'chug' parts and dynamic contrast.", "practical_application": "An engineer recognizes palm-muted guitar by its short, thick, low-sustain notes and may adjust gating, compression, or mic choice to capture the tight attack cleanly.", "category": "Articulation", "related_terms": ["Damping", "Attack", "Decay", "Sustain", "Transient", "Muting"], "common_mistakes": ["Confusing a palm mute (bridge-hand damping) with fretting-hand muting, which sounds different.", "Pressing too hard and choking the note into a dead thud with no pitch.", "Assuming heavy distortion alone gives the 'chug' when the tightness actually comes from the palm mute."], "scenario_contexts": ["Recording a metal rhythm guitar built on fast palm-muted chugs.", "Adding palm-muted verses for dynamic contrast against ringing choruses.", "Setting a gate that must not cut the short decay of palm-muted notes."]}, "fc76b014-6a4f-403e-afe9-6252202bf20a": {"definition": "Pedal click is a short, sharp mechanical click captured in a recording when a foot pedal engages or releases, for example a piano sustain pedal's trapwork, an organ pedal action, or an effects footswitch or relay. It is a brief transient artifact unrelated to the musical note.", "plain_english": "A pedal click is a quick clicking sound made by a foot pedal's parts. It sneaks into the recording when someone presses or releases the pedal.", "purpose_function": "Identifying a pedal click tells the technician a mechanical noise is entering the signal, so they can service, adjust, or re-mic to keep it out.", "practical_application": "A technician traces a click on a piano track to the sustain pedal mechanism and repositions mics or services the pedal to reduce it.", "category": "Mechanical artifact", "related_terms": ["Pedal noise", "Pedal thump", "Pedal squeak", "Mechanical noise", "Transient", "Bleed"], "common_mistakes": ["Mistaking a mechanical pedal click for a digital glitch or a bad edit.", "Placing a mic close to the pedal trapwork, which captures every click.", "Trying to EQ out the click transient instead of fixing the mechanical source."], "scenario_contexts": ["A grand piano recording has a faint click each time the sustain pedal lifts.", "A guitar DI track has a click whenever a true-bypass pedal is switched.", "An organ recording picks up clicks from the pedalboard action."]}, "5616ba38-5d1b-4c30-93e8-0247a3879cfb": {"definition": "Pedal noise is any unwanted mechanical noise produced by an instrument's foot pedal and captured in a recording, including clicks, squeaks, thumps, and rattles from the pedal's linkage, springs, or contact points. It is a broad category of pedal-related artifact rather than one specific sound.", "plain_english": "Pedal noise is any unwanted sound made by a foot pedal's moving parts. It covers the clicks, squeaks, and thumps that leak into the recording.", "purpose_function": "Grouping these sounds as pedal noise helps a technician diagnose that the problem is the pedal mechanism, not the instrument's tone or the electronics.", "practical_application": "When a technician hears pedal noise on a track, they service or lubricate the pedal and adjust mic placement to keep it below the noise floor.", "category": "Mechanical artifact", "related_terms": ["Pedal click", "Pedal squeak", "Pedal thump", "Mechanical noise", "Noise floor", "Bleed"], "common_mistakes": ["Assuming pedal noise is an electrical fault rather than a mechanical one.", "Ignoring pedal noise during tracking and only noticing it once the mix is quiet.", "Boosting a track's level and raising the audible pedal noise along with it."], "scenario_contexts": ["A close-miked piano captures pedal noise during soft passages.", "A pedal-harp recording reveals mechanical noise from the pedals.", "A quiet ballad exposes pedal noise that was masked in louder sections."]}, "535b5ec1-a3aa-4b46-9cd8-51c6631f12fe": {"definition": "Pedal squeak is a high-pitched squeal or creak from friction in a dry or worn foot-pedal pivot, hinge, or spring, commonly a piano sustain pedal or a drum kick pedal, captured as an unwanted artifact. It is heard as a thin, rising squeak tied to pedal movement.", "plain_english": "A pedal squeak is a high, whiny squeal from a dry foot pedal. It is the same kind of squeak a rusty door hinge makes when it moves.", "purpose_function": "Recognizing a pedal squeak points the technician straight to a friction point that needs lubrication or repair before recording.", "practical_application": "A technician lubricates a squeaky kick-pedal spring or piano pedal hinge, or times pedal moves around the squeak, to keep it off the recording.", "category": "Mechanical artifact", "related_terms": ["Pedal noise", "Pedal click", "Pedal thump", "Mechanical noise", "Bleed", "Noise floor"], "common_mistakes": ["UNSAFE: spraying a flammable or conductive aerosol lubricant near electronics, pickups, or heat sources instead of using the correct dry lubricant.", "Mistaking a kick-pedal squeak for a squeak in the drum head or the stand.", "Only noticing the squeak after tracking, when it is already baked into the take."], "scenario_contexts": ["A kick drum track has a squeak on every beater stroke from a dry pedal.", "A grand piano recording squeaks each time the sustain pedal is pressed.", "A hi-hat pedal squeaks during quiet verses and is caught by nearby mics."]}, "9ad52f26-cab4-4660-99ed-61bf4f2ced43": {"definition": "Pedal thump is a low-frequency thump or thud transmitted through the floor or instrument when a foot pedal is operated, such as a piano sustain pedal seating, a kick-pedal footboard, or a stomp on a stage riser, and picked up by microphones. It is a dull, low-end artifact rather than a pitched note.", "plain_english": "A pedal thump is a low, dull thud you hear when a foot pedal is pressed hard. It is like the soft boom of a footstep picked up by the mics.", "purpose_function": "Spotting pedal thump tells the technician that low-frequency mechanical energy is entering through the floor or instrument, so they can isolate or filter it.", "practical_application": "A technician isolates the instrument on a riser or mat and applies a high-pass filter to reduce pedal thump without thinning the instrument.", "category": "Mechanical artifact", "related_terms": ["Pedal noise", "Pedal click", "Pedal squeak", "High-pass filter", "Rumble", "Isolation"], "common_mistakes": ["Trying to fix pedal thump only with EQ instead of isolating the source from the floor.", "High-passing so aggressively that the instrument loses needed low end.", "Placing mics or stands in direct mechanical contact with a resonant floor."], "scenario_contexts": ["A close-miked upright piano thumps each time the sustain pedal is seated.", "A kick pedal's footboard sends a low thump into the floor tom mics.", "A stage riser transmits a thump to vocal mics when a pedal is stomped."]}, "9375ec33-f5b8-4781-9594-214f41dcb382": {"definition": "The transient onset of a plucked or strummed string note produced as a plectrum releases the string; it is the brief, bright, high-energy leading edge of the sound that carries the percussive contact and the fastest-rising portion of the amplitude envelope.", "plain_english": "The sharp, bright start of a note when a guitar pick hits the string. It is the quick snap you hear just before the note rings out.", "purpose_function": "Names the initial transient that gives a picked note its clarity, articulation, and rhythmic definition, so it can be identified and shaped deliberately.", "practical_application": "A technician listens to or meters the pick attack when setting a compressor's attack and release, or when EQing a guitar DI, to decide how much of that transient to keep for punch versus smooth over.", "category": "Attack Transient", "related_terms": ["Pluck", "Pick click", "Pick noise", "Transient", "Attack"], "common_mistakes": ["Setting a compressor attack so fast that it clamps the pick attack and the guitar loses its punch and definition.", "Confusing pick attack (the whole bright onset) with pick click (just the percussive contact tick).", "EQing away all of the attack's high end, leaving notes that sound dull and poorly defined."], "scenario_contexts": ["Dialing a compressor's attack time on a recorded electric guitar DI to keep the picked notes punchy.", "EQing an acoustic guitar so picked notes stay clear in a dense mix.", "Judging note definition when comping fast picked passages."]}, "ac0c7ef3-5ce1-4ca2-bc6d-796fb6bdff9a": {"definition": "A short, high-frequency percussive click imprinted on a note's onset by the hard plectrum tapping the string before it begins to vibrate tonally; it is the sharpest component of pick attack, most audible with stiff picks, bright strings, and close miking or direct recording.", "plain_english": "The tiny tick sound a stiff pick makes as it taps the string, heard right at the start of each note. Hard picks and bright strings make it louder.", "purpose_function": "Isolates the percussive contact component of pick attack so it can be recognized and controlled; a little adds articulation and cut, while too much sounds clicky and unmusical.", "practical_application": "An engineer hearing excessive pick click on a bass DI or acoustic guitar reduces it with a softer pick, a narrow high-frequency EQ cut, or transient shaping.", "category": "Picking Noise", "related_terms": ["Pick attack", "Pick noise", "Pick drag", "Transient"], "common_mistakes": ["Trying to remove pick click with heavy broadband EQ, which dulls the whole tone instead of notching the narrow click band.", "Assuming the click is a fault in the pickup or interface when it is really a stiff pick on bright strings.", "Adding an aggressive transient shaper that exaggerates the click until the part sounds unmusical."], "scenario_contexts": ["Reducing a clicky onset on a close-miked acoustic guitar in a quiet ballad.", "Taming pick click on a bright bass DI so it does not distract in the mix.", "Choosing a softer pick to cut click during a clean recording session."]}, "bfdab217-b29b-4951-bf22-dbc3eef508b5": {"definition": "The scratchy frictional sound produced as a plectrum slides across the ridged windings of wound strings during a stroke or a position change; it is a broadband, noise-like artifact concentrated in the upper midrange and treble, separate from the tonal note.", "plain_english": "The scratchy sound of the pick rubbing across the rough wound strings as your hand moves. It is a bit like running a fingernail over a rope.", "purpose_function": "Identifies incidental friction noise from the pick on wound strings so it can be judged and managed, separating it from the musical note and from equipment faults.", "practical_application": "A technician who hears drag on a take addresses it with lighter picking, smoother or coated picks, flatwound or coated strings, or targeted upper-mid EQ and cleanup.", "category": "Picking Noise", "related_terms": ["Pick noise", "Pick scrape", "Pick click", "Pick attack"], "common_mistakes": ["Mistaking pick drag for a cable or grounding fault when it is just friction on the wound strings.", "Trying to fix drag only with EQ instead of a lighter touch, a smoother pick, or coated strings.", "Editing out drag so aggressively that natural playing detail and realism are lost."], "scenario_contexts": ["Hearing scratchy friction as a player shifts position on wound strings during a take.", "Deciding whether to edit out or keep drag noise on a solo acoustic recording.", "Switching to coated or flatwound strings to reduce drag on a session guitar."]}, "fd45b0c8-a932-4e9b-b1c7-790de48520aa": {"definition": "Any unwanted, non-tonal sound generated by the plectrum's contact with the strings, including clicks, scrapes, and frictional scratch, captured alongside the intended note; it is most prominent on bright acoustic and clean electric sources that are close-miked or recorded direct.", "plain_english": "Extra scratchy or clicky sounds made by the pick itself, not the musical note. It is the noise you do not want, picked up along with the playing.", "purpose_function": "Serves as an umbrella term that lets engineers flag and treat plectrum-generated noise as distinct from the intended tone and from equipment problems.", "practical_application": "During tracking or mixing, a technician controls pick noise through mic choice and placement, technique coaching, string choice, EQ, and gentle de-noising.", "category": "Picking Noise", "related_terms": ["Pick click", "Pick drag", "Pick scrape", "Pick attack"], "common_mistakes": ["Treating all pick noise as a defect and gating it out, which can chop the start of real notes.", "Blaming the microphone or preamp for noise that is actually the player's pick technique.", "Boosting presence or air EQ that makes pick noise worse while chasing clarity."], "scenario_contexts": ["Cleaning up a close-miked acoustic guitar track full of clicks and scrapes.", "Coaching a guitarist to lighten pick pressure to lower noise during recording.", "Setting EQ and light de-noising on a clean electric part to control pick noise."]}, "d3c022d6-ab63-4335-afca-a4b963dae156": {"definition": "The return, or reset, phase of a pickstroke in which the plectrum lifts away from the string and repositions after the initial attack, before the next stroke. On close-miked or high-gain guitar it can add a faint secondary contact noise as the pick clears or grazes the string, distinct from the louder pick attack.", "plain_english": "It is the moment the pick pulls back off the string after a note and gets ready for the next one. Sometimes the mic catches a small extra scratch as the pick lifts away.", "purpose_function": "Naming the recovery phase separates the pick's return motion and its faint noise from the main pick attack. That helps a technician identify and manage stray picking sounds in a take.", "practical_application": "On a close-miked clean guitar, an engineer who hears pick-recovery noise may adjust mic placement, ask for a lighter touch, or edit the faint contact sounds out of exposed sections.", "category": "Picking Noise", "related_terms": ["Pick attack", "Pick noise", "Pick click", "Pick scrape", "Transient"], "common_mistakes": ["Confusing the faint pick-recovery noise with the main pick attack when editing.", "Trying to remove every recovery sound and making the playing feel unnatural.", "Blaming pick-recovery noise on a faulty cable or pickup rather than the picking hand."], "scenario_contexts": ["Hearing faint pick reset noises on a close-miked clean electric guitar.", "Cleaning up stray picking sounds in an exposed acoustic guitar take.", "Coaching a player toward a lighter touch to reduce picking-hand noise."]}, "133adc72-f049-469e-8f08-fc57b333d099": {"definition": "A guitar effect produced by dragging the edge of a plectrum lengthwise along the windings of a wound string, generating a sustained scratching or screeching glissando; it is commonly used with distortion as an accent or transition in rock and metal.", "plain_english": "A screechy sliding sound made by dragging the pick along the length of a thick wound string. Rock and metal players use it as an effect, often with distortion.", "purpose_function": "Names a deliberate friction effect so it is treated as intended content rather than noise, and can be recognized and reproduced on demand.", "practical_application": "A guitarist performs a pick scrape as a transition or accent, and the engineer preserves it through editing and de-noising rather than gating it out.", "category": "Playing Technique", "related_terms": ["Pick noise", "Pick drag", "Pinch harmonic", "Pick attack"], "common_mistakes": ["Confusing an intentional pick scrape with an accidental pick drag or string squeak.", "Expecting a strong scrape on plain unwound strings, which have no windings to catch the pick.", "Gating or de-noising a track and accidentally removing a deliberate pick-scrape effect."], "scenario_contexts": ["Recording a rock guitarist's deliberate pick slide before a chorus hit.", "Adding a distorted pick scrape as a transition effect in a metal track.", "Checking that a de-noiser does not erase an intentional scrape."]}, "62ec2ea0-0a19-4f32-8130-6b72f366c9f3": {"definition": "An artificial harmonic technique in which the pick strikes the string while the edge of the thumb lightly grazes it at the same instant, damping the fundamental and forcing a higher overtone to sound; it produces the characteristic high-pitched squeal, especially with distortion and a bridge pickup.", "plain_english": "A squealing high note made by letting your thumb lightly touch the string at the same moment the pick hits it. Rock players use it to make notes squeal, usually with distortion.", "purpose_function": "Lets a player sound a chosen upper harmonic instead of the normal note, adding expressive high squeals; the thumb touch acts as a node that selects which overtone rings.", "practical_application": "A guitarist positions the pick and thumb over a harmonic node, usually between the pickups, to nail a pinch harmonic, while the engineer keeps bridge-pickup brightness and sustain so the overtone reads in the mix.", "category": "Harmonic Technique", "related_terms": ["Harmonic", "Overtone", "Node", "Pick attack", "Sustain"], "common_mistakes": ["Pressing the thumb too hard so it fully mutes the string and no harmonic sounds.", "Picking over an antinode instead of near a node, so the overtone is weak or absent.", "Assuming distortion is required; it helps the squeal cut through, but the harmonic exists on a clean tone too."], "scenario_contexts": ["A metal guitarist adding squealing pinch harmonics over a riff.", "An engineer keeping bridge-pickup brightness and sustain so pinch harmonics read in the mix.", "Troubleshooting why a player's pinch harmonics will not sound, such as thumb muting or the wrong pick spot."]}, "cb3d202d-2e06-4bd7-b8f5-9a8de8f1d69f": {"definition": "A short, bright, pitched resonant ring excited by a sharp transient, such as the metallic overtone that lingers after a drum is struck or the brief tone produced when a narrow, high-Q resonant filter is hit with an impulse; it is a decaying tonal artifact riding on top of the main sound.", "plain_english": "A quick, bright, bell-like ring that follows a sharp hit, like the ting a drum or metal object makes. It is a short ringing tone sitting on top of the main sound.", "purpose_function": "Names a narrow, ringing resonance so it can be identified and judged, since it is sometimes wanted as character and sometimes an unwanted artifact to tune out or notch.", "practical_application": "An engineer who hears an annoying ping on a snare finds its frequency with a narrow EQ sweep and notches it or dampens the drum; when pinging a reverb, they feed a click into a high-Q filter to make it ring.", "category": "Resonant Artifact", "related_terms": ["Resonance", "Decay", "Transient", "Overtone", "Sustain"], "common_mistakes": ["Notching out a wanted resonant ping and leaving the drum sounding lifeless.", "Sweeping a wide EQ band instead of a narrow high-Q band, removing good tone along with the ping.", "Mistaking a resonant ping for feedback or an oscillation fault in the signal chain."], "scenario_contexts": ["Notching a resonant metallic ring out of a snare drum during mixing.", "Pinging a high-Q filter or plate to create a tuned resonant reverb effect.", "Identifying an unwanted ringing overtone on a tom before tuning or damping it."]}, "1444980a-1346-4192-b11c-7a94f77ec16a": {"definition": "The excitation of a string by displacing it with a finger or plectrum and releasing it, setting it into free, decaying vibration; the resulting note has a sharp attack transient followed by a harmonically rich, exponentially decaying tail. The term also names a synth patch shaped to imitate this short, percussive-attack, quick-decay envelope.", "plain_english": "Pulling a string and letting it go so it rings, like snapping a rubber band. The note starts with a sharp pop and then fades away.", "purpose_function": "Describes the basic way plucked-string instruments make sound, giving a note its punchy start and natural fade; the term also names synth sounds shaped to copy that quick attack and decay.", "practical_application": "A technician recognizes a pluck envelope when setting gate or compressor timing on bass, or when programming a synth pluck with a fast attack and short decay.", "category": "Attack Transient", "related_terms": ["Pick attack", "Attack", "Decay", "Transient", "Sustain"], "common_mistakes": ["Setting a gate release so short that it cuts off the natural decay tail of a plucked note.", "Confusing the sharp pluck attack transient with unwanted click or distortion.", "Programming a synth pluck with a slow attack, which removes the percussive character."], "scenario_contexts": ["Setting attack and decay when programming a synth pluck patch.", "Recognizing the pluck envelope to time a compressor or gate on bass.", "Comparing pluck attack and decay when identifying a plucked versus bowed source."]}, "42f8b2e5-b162-432f-bfbe-6e349bba5c8c": {"definition": "A brief, high-energy transient heard as a sharp click or thump, produced when a sudden pressure blast (such as a plosive consonant hitting a microphone) or an abrupt electrical discontinuity (such as making or breaking a live connection) injects a fast step into the signal.", "plain_english": "A pop is a quick, loud burst of sound, like the thump you hear when someone says a hard 'P' too close to a mic. It can also come from plugging in a cable while the sound is turned up.", "purpose_function": "Naming this artifact tells a technician the fault is a fast transient event, not a steady tone, which points to a plosive, a switching event, or a bad connection so the right fix is applied.", "practical_application": "An engineer who hears pops on a vocal fits a pop filter and high-pass filter, and at a patchbay mutes the channel before plugging so a pop is not sent through the PA.", "category": "Transient artifact", "related_terms": ["Plosive", "Pop filter", "Transient", "Click", "DC offset"], "common_mistakes": ["Confusing a plosive pop with a low-frequency rumble or handling noise", "Thinking a pop filter will stop electrical pops caused by patching or switching", "UNSAFE: patching or unplugging live sources into a powered system, which can send a loud pop that damages drivers or hearing"], "scenario_contexts": ["A singer's hard consonants pop the vocal mic during a quiet ballad", "A loud pop bursts through the PA when an engineer patches a live channel hot", "A guitar amp pops when its footswitch is stepped on"]}, "6f6d8144-a947-4694-8527-6b0cd7085e95": {"definition": "The acoustic resonance of the air column in a bass-reflex loudspeaker's port. At the enclosure's Helmholtz tuning frequency it reinforces low bass, but the same air column also exhibits higher-frequency pipe (standing-wave) resonances that appear as unwanted peaks and coloration in the port's output.", "plain_english": "A ported speaker has a tube, the port, that helps it make deeper bass. The air in that tube can also ring at higher notes, adding a peak or a hollow, pipe-like sound you do not want.", "purpose_function": "The port's main air resonance is designed to extend low-frequency output, so telling it apart from the port's unwanted higher resonances lets a technician separate useful tuning from coloration and port noise.", "practical_application": "When a sub or monitor sounds boomy or has a hollow honk, a technician measures the response and impedance to find the peak, then fits a longer or flared port or adds damping to control it.", "category": "Resonance artifact", "related_terms": ["Bass reflex", "Helmholtz resonance", "Port noise", "Standing wave", "Enclosure tuning"], "common_mistakes": ["Confusing the intended Helmholtz tuning resonance with the unwanted pipe resonance higher up", "Mistaking port chuffing (air turbulence noise) for port resonance", "Assuming a larger port always removes resonance, when port length sets the pipe resonance frequency"], "scenario_contexts": ["A ported PA sub develops a hollow midbass coloration traced to a port pipe resonance", "A studio monitor shows a response peak above its tuning frequency caused by port resonance", "A home-built cabinet honks on sustained bass notes"]}, "5c0b90e4-f9bd-4e6c-8e9c-17b9f303d3c9": {"definition": "An audible change in the apparent location of a sound source within the stereo or surround image, where a phantom source drifts from its intended position because of shifts in interchannel level or time differences, phase relationships, or comb filtering.", "plain_english": "This is when a sound seems to move to a different spot between your speakers than where it should sit. It usually happens when the two channels differ in loudness or timing, so your ears place the sound off to one side.", "purpose_function": "Spotting a position shift lets a technician separate an imaging problem, such as a level imbalance or a timing or phase error, from a tonal problem, so they correct the pan, delay, or wiring instead of the EQ.", "practical_application": "If a centered vocal pulls to one side, an engineer checks channel levels, pan, cable polarity, and any delay to bring the image back to center.", "category": "Imaging artifact", "related_terms": ["Phantom image", "Panning", "Interchannel level difference", "Comb filtering", "Phase"], "common_mistakes": ["Trying to fix a position shift with EQ instead of level, timing, or phase", "Overlooking a swapped or out-of-polarity cable that pulls the image off center", "Assuming the pan control is wrong when a delay or strong reflection is actually moving the image"], "scenario_contexts": ["A mixed lead vocal drifts left because one channel is a few dB louder", "A stereo mic pair images off-center after one leg is wired out of polarity", "A phantom-centered instrument shifts sideways when a channel delay is misset"]}, "45443e7b-82f7-44f5-bc56-26fcf7fe5d04": {"definition": "A nasal, honking midrange timbre resembling a duck's call, produced by a strong resonant peak in roughly the 700 Hz to 1.5 kHz region, characteristically from a wah or envelope filter parked near its resonance or from a narrow midrange EQ boost.", "plain_english": "'Quack' is a nasal, honking sound, a bit like a duck. You get it when one part of the midrange is pushed way up, often by a wah pedal or auto-wah on a funky bass or guitar.", "purpose_function": "Calling a sound 'quack' quickly tells others it is a peaky, nasal midrange resonance, which guides whether to keep it as an effect or tame it by lowering the mid peak or reducing filter resonance.", "practical_application": "A funk bassist dials an envelope filter to get a quack, while a mix engineer who finds an unwanted quack on a track notches the offending midrange band.", "category": "Timbral descriptor", "related_terms": ["Envelope filter", "Wah", "Resonance peak", "Formant", "Midrange"], "common_mistakes": ["Confusing quack, a narrow mid resonance, with a general boxy or nasal tone", "Boosting instead of cutting the mid peak when trying to remove an unwanted quack", "Assuming quack always means a wah pedal when a sharp EQ boost can cause it"], "scenario_contexts": ["A bass player sets an auto-wah for a quacky funk line", "A vocal has an unwanted quacky honk from a room or mic mid peak", "A guitar tone quacks when the wah pedal is left parked mid-sweep"]}, "624dfefa-7688-4553-936e-de0c68d47f0d": {"definition": "An intermittent buzzing or clattering noise caused by a loose or poorly secured mechanical part vibrating against an adjacent surface when excited by sound or vibration, often appearing only at specific frequencies or drive levels.", "plain_english": "A rattle is a buzzy, clattering noise made when something loose shakes against something else. A loose screw or speaker grille buzzing when the bass hits is a rattle.", "purpose_function": "Identifying a rattle points a technician to a mechanical fault, a loose part or a sympathetic vibration, rather than an electrical or driver fault, so they tighten, damp, or isolate the offending part.", "practical_application": "When a cabinet buzzes on certain low notes, a technician sweeps a tone to find the frequency, then locates and tightens the loose screw, grille, or panel; on stage they damp rattling hardware or set pieces.", "category": "Mechanical artifact", "related_terms": ["Rub and buzz", "Buzz", "Sympathetic resonance", "Driver", "Enclosure"], "common_mistakes": ["Blaming the driver when a loose grille or screw is the real source of the rattle", "Missing that a rattle may appear only at one frequency or level, so testing at the wrong level hides it", "Confusing a mechanical rattle with electrical buzz from a grounding or hum problem"], "scenario_contexts": ["A PA cabinet rattles on kick-drum notes from a loose handle bolt", "A drum shell buzzes from a loose lug or stray snare wire", "A studio finds a rattle from a resonating light fixture during loud playback"]}, "3dff5d4d-a186-4e77-91bf-5c1a0b2afd78": {"definition": "The gradual exponential dying-away of energy stored at a resonance after the driving excitation stops, heard as a ringing tail at the resonant frequency whose duration is set by the system's damping (Q).", "plain_english": "When something that rings is driven and then stops, the sound fades out slowly instead of stopping at once. That slow fade at the ringing note is resonant decay, like a struck bell that keeps humming.", "purpose_function": "Hearing how a resonance decays tells a technician how sharp and how damped it is, helping separate a lightly damped ringing mode with a long decay from a well-controlled one, and guiding EQ, damping, or treatment.", "practical_application": "A technician uses a sine sweep or a decay (waterfall) plot to spot long resonant decays in a monitor, a room mode, or a drum, then adds damping or a notch to shorten the ring.", "category": "Decay behavior", "related_terms": ["Resonance", "Q factor", "Damping", "Reverberation time", "Ringing"], "common_mistakes": ["Confusing resonant decay, a single ringing frequency dying away, with broadband reverberation", "Judging a resonance by its level only while ignoring how long it rings", "Trying to cut a resonance with static EQ when a long decay actually needs damping or dynamic control"], "scenario_contexts": ["A room mode gives a long resonant decay on a bass note, seen on a waterfall plot", "A snare drum rings with a resonant decay that a gate or damping tames", "A monitor's cone breakup shows a long resonant decay in a cumulative spectral decay plot"]}, "e5ab24ad-41e0-4289-bdd9-e1cb551ce9ab": {"definition": "A string bowing technique (also called jete) in which the player throws or drops the bow onto the string, usually in the upper half and on a down-bow, letting it bounce freely to produce a rapid series of short, decreasingly loud notes within a single stroke.", "plain_english": "Ricochet is when a string player drops the bow onto the string and lets it bounce, like skipping a stone on water. Each bounce makes a quick, light note, and they get softer as the bow slows.", "purpose_function": "Ricochet gives players a fast, sparkling group of repeated notes from one bow throw, and recognizing its bouncing, decaying attack pattern helps an engineer mic and capture the transients cleanly.", "practical_application": "When recording strings, an engineer who hears ricochet passages sets placement and levels for its sharp, bouncing transients and avoids over-compressing the natural decay of each bounce.", "category": "Bowing technique", "related_terms": ["Spiccato", "Sautille", "Jete", "Staccato", "Attack transient"], "common_mistakes": ["Confusing ricochet with spiccato or sautille, which are separately controlled bounces rather than a single thrown bounce", "Gating or heavily compressing ricochet and killing the natural decay of each bounce", "Assuming every bounce is equally loud when they naturally get softer"], "scenario_contexts": ["A violinist plays a ricochet flourish in an orchestral part", "A film-score session captures rapid ricochet figures in the upper strings", "A quartet uses ricochet for a light, bouncing passage the engineer must record without clipping the transients"]}, "c048f3d1-f372-417d-85c8-af8aff3a6c66": {"definition": "A snare-drum technique (also called cross-stick or side-stick) in which the stick rests on the head while its butt end strikes the rim, producing a short, dry, woody click at low volume, distinct from the loud rimshot where head and rim are struck together.", "plain_english": "A rim click is a soft, woody tap a drummer makes by laying the stick on the snare and clicking its end on the metal rim. It sounds like a quiet knock and is common in gentle parts of a song, like a bossa nova.", "purpose_function": "The rim click gives a quiet, short percussive accent in place of a full backbeat, and recognizing its dry, clicky transient helps an engineer mic and gain-stage it, since it is far softer than a normal snare hit.", "practical_application": "For ballads or bossa-nova grooves a drummer plays rim clicks, so the engineer raises the snare-mic gain or adds a dedicated close mic because the rim click is much quieter than a struck head.", "category": "Percussion technique", "related_terms": ["Cross-stick", "Side stick", "Rimshot", "Snare drum", "Backbeat"], "common_mistakes": ["Confusing a rim click (quiet, stick on head with butt on rim) with a rimshot (loud, head and rim struck together)", "Setting snare-mic gain for a full hit, so the much quieter rim click disappears in the mix", "Placing the stick wrong so the click sounds thin instead of woody"], "scenario_contexts": ["A drummer plays rim clicks through a soft verse, then switches to a full backbeat in the chorus", "A bossa-nova track uses rim clicks throughout", "An engineer boosts the snare channel to catch quiet rim clicks"]}, "e5c8ed4b-edcb-4239-bfaf-1efede89a3ff": {"definition": "A ringing overtone arising from the vibration of a drum's rim (counterhoop) and its coupling to the heads and shell, or from the edge modes of a cymbal or similar plate, often heard as an unwanted high-pitched metallic ring after the main strike.", "plain_english": "This is a ringing sound that comes from a drum's metal rim, or from the edge of a cymbal, buzzing on after you hit it. It can add a thin, metallic 'ping' on top of the drum's main sound.", "purpose_function": "Identifying rim resonance tells a technician the unwanted ring comes from the hoop or edge rather than the drumhead or shell, so they damp or retune the rim and hardware instead of the head.", "practical_application": "When a snare or tom has an annoying metallic ring, a technician checks for rim resonance from loose or resonant hoops and lugs, then adds tape, gaskets, or retunes to reduce it before a session.", "category": "Resonance artifact", "related_terms": ["Resonant decay", "Sympathetic resonance", "Rim click", "Overtone", "Damping"], "common_mistakes": ["Blaming the drumhead for a ring that is actually rim or hoop resonance", "Over-damping the whole drum instead of just the resonant rim, which kills the tone", "Confusing rim resonance with snare-wire buzz"], "scenario_contexts": ["A tom rings metallically from its die-cast hoop resonance during tracking", "A snare's rim resonance adds an unwanted ping picked up by the overhead mics", "A cymbal's edge resonance lingers and needs light damping for a dry mix"]}, "4ba7cba2-095a-439c-846c-6288aa46ae06": {"definition": "The sustained, pitched metallic overtone that trails a drum's initial attack, arising chiefly from vibration of the metal counterhoop (rim), the shell, and an unmuffled head. On snares and toms it is heard as a high, bell-like sustain or ping after the stick strike.", "plain_english": "The long, bell-like ping a drum makes after you hit it. It comes from the metal rim and shell still buzzing. Players often add tape or a gel pad to calm it down.", "purpose_function": "Naming this overtone lets an engineer separate the wanted drum tone from the unwanted ringing sustain, guiding whether to tune, dampen, or EQ the drum.", "practical_application": "Hearing rim ring on a snare or tom, a technician controls it by retuning the head, adding a dampening gel or ring, or notching the ringing frequency with EQ before it muddies the mix.", "category": "Resonance artifact", "related_terms": ["Ring", "ringy", "Rimshot", "Resonance", "Decay", "Sustain"], "common_mistakes": ["Confusing wanted drum sustain with unwanted rim ring and over-damping the drum.", "Blaming the microphone when the ring is really the rim, shell, or head resonating.", "Cutting too wide an EQ band and dulling the whole drum instead of notching the ringing frequency."], "scenario_contexts": ["Tracking a snare that pings for too long after each hit and needs a dampening gel.", "Taming a ringing tom during a drum session with tuning and muffling.", "Notching a specific ringing overtone on a close snare mic during mixdown."]}, "4ff4e290-122e-44df-9033-bd70a3b7b399": {"definition": "A drumming technique in which the stick strikes the drumhead and the metal counterhoop (rim) at the same instant, producing a loud, sharp, accented crack with a strong transient and added overtones. On the snare it yields the characteristic cutting backbeat.", "plain_english": "A drum hit where the stick smacks the head and the metal rim at the same time. It makes a loud, sharp crack, like the snare sound in a lot of rock and pop songs.", "purpose_function": "It exists to give the snare or tom a louder, more cutting accent than a plain head-only stroke, so the backbeat carries over a loud band.", "practical_application": "An engineer expects rimshots on the backbeat and sets gain and compression so the extra level and sharp crack do not clip the snare channel, choosing mic placement that captures the fast transient.", "category": "Playing technique", "related_terms": ["Rim ring", "Ring", "Attack", "Transient", "Sustain"], "common_mistakes": ["Confusing a rimshot with a cross-stick (rim click), which is a much softer, woodblock-like sound.", "Assuming every loud snare hit is a rimshot; it specifically needs simultaneous head-and-rim contact.", "Setting snare channel level from a soft stroke, then clipping the preamp when louder rimshots arrive."], "scenario_contexts": ["Tracking a rock backbeat where the drummer plays rimshots on beats 2 and 4.", "Gain-staging a snare channel so consistent rimshots do not overload the preamp.", "Reinforcing snare hits with samples and matching the rimshot's brighter, sharper tone."]}, "3eb431e6-3f6e-45c4-8407-3f6551cf03bf": {"definition": "A sustained, resonant tone at one or a few frequencies that continues audibly after the initiating attack, caused by a lightly damped resonance in an instrument, room, or signal chain. It is perceived as a pitched ringing tail rather than a quick decay.", "plain_english": "A clear note that keeps humming after the sound that started it has stopped. It is like tapping a glass and hearing it sing for a moment.", "purpose_function": "Identifying ring tells a technician where a resonance is storing energy and decaying slowly, which guides tuning, damping, or notch-EQ decisions.", "practical_application": "An engineer rings out a monitor system by raising gain until a frequency starts to ring, then notches it, and dampens a drum or room mode that rings on after each hit.", "category": "Resonance artifact", "related_terms": ["ringy", "Rim ring", "Resonance", "Feedback", "Decay", "Sustain"], "common_mistakes": ["Confusing wanted musical sustain with unwanted ring or resonance.", "Assuming ring is always in the source when it may be a room mode or feedback in the PA.", "Cutting too wide an EQ band and dulling the source instead of notching the ringing frequency."], "scenario_contexts": ["Ringing out floor monitors before a show to find feedback frequencies.", "Taming a snare or tom that rings after each hit during tracking.", "Hearing a low-frequency room mode ring on in an untreated control room."]}, "0eaeac98-07ce-442d-a424-055790e5672c": {"definition": "A descriptive term for a sound dominated by prominent, sustained narrow-band resonance, giving it an audible pitched ringing quality and a slow, resonant decay rather than a clean, well-damped one.", "plain_english": "A word for a sound that has too much of that humming, bell-like ring in it. A drum or room that keeps singing after each hit sounds ringy.", "purpose_function": "The label lets engineers quickly flag a source or space whose resonances need tuning, damping, or EQ before it muddies a recording or mix.", "practical_application": "On hearing a ringy tom or a ringy room, a technician tunes or dampens the drum, adds acoustic treatment, or notches the offending resonance with EQ.", "category": "Tonal descriptor", "related_terms": ["Ring", "Rim ring", "Resonance", "Boomy", "Boxy", "Decay"], "common_mistakes": ["Using ringy loosely for any bright sound; it specifically means resonant or ringing, not just trebly.", "Over-damping to kill the ring and leaving the source dull and lifeless.", "Blaming the mic when the ring is really the instrument or room resonating."], "scenario_contexts": ["Describing a snare that needs a dampening gel because it sounds ringy.", "Noting a ringy conference room that needs acoustic panels.", "Flagging a ringy resonance in a mix that a narrow notch filter can fix."]}, "7e3e6f74-c828-4dc2-9930-98a7118406dd": {"definition": "The fine, granular scraping or scratching sound produced as the rosin-coated bow grips and slips across a string, part of the bowed-string stick-slip mechanism. It is heard as a gritty texture layered on the note, most noticeable at the start of a stroke or under heavy bow pressure.", "plain_english": "The soft, scratchy grit you hear when a violin or cello bow drags across a string. Players rub sticky rosin on the bow hair so it grips the string, and that grip makes tiny scrapes.", "purpose_function": "A small amount is a natural part of bowed-string tone; recognizing excess rosin noise tells an engineer to adjust mic distance or the player to adjust bow pressure and speed.", "practical_application": "Recording strings, an engineer who hears too much bow grit moves the mic off the bowing point or higher over the instrument, and may gently reduce the harsh band with EQ.", "category": "Playing artifact", "related_terms": ["Attack", "Transient", "Rustle", "Sustain", "Ring"], "common_mistakes": ["Confusing natural rosin noise with a microphone or preamp fault.", "Close-miking right at the bow contact point, which exaggerates the grit.", "Over-processing to remove all bow noise, making the strings sound artificial."], "scenario_contexts": ["Close-miking a solo violin and hearing rosin grit on each stroke.", "A cellist using fresh, heavy rosin producing extra scrape at note onsets.", "Editing a string-section take to reduce distracting bow noise."]}, "19fad014-cd51-4bf6-8390-8e8bdce106ed": {"definition": "The transitional period in a rotary (Leslie-type) speaker when a rotor speeds up from a slower to a faster spin rate, such as from chorale (slow) to tremolo (fast). Because the horn and bass rotors have different inertia, they ramp up at different rates, producing a rising swirl of Doppler pitch and amplitude modulation.", "plain_english": "The moment a spinning Leslie speaker speeds up, so its wobbling, swirling sound gets faster. The high horn and the low drum speed up at slightly different rates, which gives that rising whoosh.", "purpose_function": "The speed change is a musical effect: switching a Hammond and Leslie from slow to fast makes an accelerating swirl that players use for expressive builds.", "practical_application": "When emulating or miking a Leslie, an engineer sets the acceleration (ramp) time so the speed-up sounds natural, capturing both horn and bass rotor with the correct spin-up feel.", "category": "Rotary modulation", "related_terms": ["Rotor deceleration", "Rotor noise", "Tremolo", "Modulation", "Resonance"], "common_mistakes": ["Setting the acceleration time too fast and losing the natural gradual ramp.", "Treating the horn and drum rotor speeds as identical when they differ.", "Confusing the pitch swirl (Doppler) with vibrato added elsewhere in the chain."], "scenario_contexts": ["Miking a real Leslie while the organist kicks it from slow to fast.", "Dialing ramp times in a rotary-speaker plugin or pedal.", "Automating a slow-to-fast Leslie switch during an organ solo."]}, "c312984d-62e8-42a6-a63a-19dde503fb41": {"definition": "The transitional period in a rotary (Leslie-type) speaker when a rotor slows from a faster to a slower spin rate, such as from tremolo (fast) to chorale (slow). The horn and bass rotors coast down at different rates due to differing inertia, giving a falling, settling swirl of Doppler pitch and amplitude modulation.", "plain_english": "The moment a spinning Leslie speaker slows down, so its swirling sound gently winds down. Because the parts have different weight, they slow at different speeds, which gives that settling wind-down.", "purpose_function": "The slow-down is used musically to relax the sound after a fast passage, the falling counterpart to rotor acceleration.", "practical_application": "Emulating or recording a Leslie, an engineer sets the deceleration (ramp-down) time so the wind-down feels natural after switching from fast to slow.", "category": "Rotary modulation", "related_terms": ["Rotor acceleration", "Rotor noise", "Tremolo", "Modulation", "Decay"], "common_mistakes": ["Setting a deceleration time so short that the swirl stops abruptly.", "Assuming both rotors coast down together when they settle at different rates.", "Confusing the natural wind-down with a tempo or pitch problem."], "scenario_contexts": ["Capturing the wind-down as an organist switches a Leslie from fast to slow.", "Setting ramp-down time in a rotary plugin to match a vintage cabinet.", "Automating a fast-to-slow Leslie transition at the end of a phrase."]}, "22d1fed2-d098-47f5-bb2f-43e0a9444455": {"definition": "The mechanical and aerodynamic sound produced by a rotary (Leslie-type) speaker's spinning rotors and motors, including bearing whir, belt-drive noise, and the air turbulence of the moving horn and drum. It is a low-level artifact distinct from the intended Doppler and amplitude modulation of the program audio.", "plain_english": "The whirring, mechanical sound a spinning Leslie cabinet makes on its own, from the motors, belts, and moving parts pushing air. It is the background noise of the machine, not the swirling organ tone itself.", "purpose_function": "Recognizing rotor noise helps a technician tell normal mechanical sound from a fault and decide how closely to mic the cabinet without capturing too much whir.", "practical_application": "Miking a real Leslie, an engineer balances mic distance to keep the intended swirl while limiting bearing and belt whir, and listens for new rattles or squeals that signal worn bearings or a loose belt.", "category": "Mechanical noise", "related_terms": ["Rotor acceleration", "Rotor deceleration", "Rustle", "Modulation", "Hiss"], "common_mistakes": ["Mistaking normal bearing whir for a defect, or ignoring a genuinely failing bearing.", "Close-miking so tightly that mechanical noise overwhelms the musical swirl.", "Confusing rotor noise with amp hum or hiss coming from the electronics."], "scenario_contexts": ["Recording a vintage Leslie and hearing belt or bearing whir between notes.", "Diagnosing a squeal that signals a worn rotor bearing needing service.", "Setting mic distance to keep the swirl but reduce mechanical noise."]}, "19074d3e-ebfa-4d3f-8fd0-95b97aec9710": {"definition": "A soft, irregular, broadband noise made of brief overlapping transients, resembling dry leaves, paper, or fabric in motion. In audio it commonly appears as an artifact, for example clothing rustle picked up by a concealed lavalier microphone, or handling noise on other sources.", "plain_english": "A soft, crinkly, shuffling sound, like dry leaves or paper moving. In recordings it often shows up as clothing brushing against a hidden clip-on mic.", "purpose_function": "Naming rustle helps a technician identify a low-level, random-texture noise so they can trace its source, such as clothing, handling, or wind, and reduce it.", "practical_application": "On a lavalier mic, an engineer prevents clothing rustle by mounting the capsule in a proper clip or mount and taping cables so fabric cannot brush it, then reduces any rustle that remains in editing.", "category": "Noise artifact", "related_terms": ["Rosin noise", "Rotor noise", "Hiss", "Transient", "Sustain"], "common_mistakes": ["Blaming the mic capsule for rustle that is actually clothing contact.", "Mounting a lavalier without a proper mount so fabric brushes the capsule.", "Trying to fix heavy rustle only with EQ instead of remounting the mic."], "scenario_contexts": ["A concealed lavalier picking up shirt rustle when a presenter moves.", "Handling noise as a cable brushes clothing or a bag during a take.", "Leaves or paper rustle captured on a location recording."]}, "dbd60971-4e79-4b0f-8da6-2e366e2c6cfe": {"definition": "A rattling or buzzing artifact produced when a string vibrates against or through an improperly seated, worn, or too-low bridge saddle on a guitar or similar stringed instrument, adding a metallic, granular noise to the note's attack and sustain.", "plain_english": "It is a buzzing rattle from where the string rests on the guitar bridge. The string is not sitting cleanly on that small part, so a fuzzy noise adds to the note.", "purpose_function": "It is not a wanted feature but a diagnostic symptom; hearing it tells a technician the buzz starts at the saddle rather than the frets or nut, so the fix targets the bridge.", "practical_application": "A guitar tech listens for buzz that persists on open and fretted notes and traces it to a loose, cracked, or low saddle, then reseats, shims, or replaces the saddle.", "category": "Mechanical artifact", "related_terms": ["Fret buzz", "Nut buzz", "Rattle", "Sympathetic resonance", "Sustain"], "common_mistakes": ["Confusing saddle buzz with fret buzz, which comes from the fretboard rather than the bridge.", "Assuming the string itself is faulty instead of checking how it seats on the saddle.", "Over-sanding or over-tightening the saddle, which changes action height and intonation."], "scenario_contexts": ["Tracking an acoustic guitar and hearing a metallic buzz on certain notes that the mic picks up.", "Setting up a guitar and isolating whether a buzz starts at the saddle, nut, or frets.", "A worn or loosely fitted saddle rattling under heavy strumming."]}, "18b12d1e-266b-493d-99e1-df1de035990d": {"definition": "A rough, noisy, aperiodic sound produced on a bowed string instrument when bow force exceeds the maximum limit for stable Helmholtz motion, so the string slips irregularly instead of vibrating cleanly, yielding a scratchy crunch instead of a clear pitch.", "plain_english": "A harsh, scratchy sound from a bowed string like a violin. It happens when the player presses the bow too hard, so the string cannot settle into a clean swing and you hear noise instead of a clear note.", "purpose_function": "As a listening cue it tells the player or engineer that bow pressure is too high for the bow speed and contact point, signaling the tone has broken down and needs lighter pressure.", "practical_application": "An engineer recording strings, or a coach, hears the scratchy crunch and asks the player to ease bow weight or shift the contact point so the note locks into a clean pitch.", "category": "Playing artifact", "related_terms": ["Surface sound", "Bow noise", "Wolf tone", "Attack transient", "Sustain"], "common_mistakes": ["Blaming the microphone or strings for noise the bowing technique is creating.", "Thinking more bow pressure always means more tone, when too much destroys the pitch.", "Confusing an intentional gritty attack with an uncontrolled scratch tone."], "scenario_contexts": ["Close-miking a violin and capturing scratchy noise when the player digs in too hard.", "A student pressing the bow too firmly and losing a clear pitch.", "Coaching bow control to move from a scratchy sound to a focused tone."]}, "8be75fe7-810c-4f54-a0e5-9b445dce836b": {"definition": "A buzzing or rattling artifact caused by a loose screw, bolt, or threaded fastener vibrating sympathetically with a sound source, adding an intermittent metallic rattle that appears at specific pitches or sound-pressure levels.", "plain_english": "A rattle caused by a loose screw shaking along with the sound. When a certain note or a loud level hits, the screw vibrates and you hear a small buzzing rattle.", "purpose_function": "Recognizing it points a technician to hardware that has worked loose, so the rattle can be traced and tightened rather than treated as an electronic or acoustic fault.", "practical_application": "A tech chasing a mystery buzz plays sustained tones to find the pitch that excites a loose lug, grille, or panel screw, then tightens or isolates it.", "category": "Mechanical artifact", "related_terms": ["Rattle", "Sympathetic resonance", "Saddle buzz", "Cabinet resonance", "Buzz"], "common_mistakes": ["Assuming a rattling buzz is a blown speaker when a loose screw is the real cause.", "Tightening random screws without first finding which one resonates.", "Ignoring the specific pitch that triggers the rattle, which is the best clue to its source."], "scenario_contexts": ["A loudspeaker cabinet rattling at a certain bass note from a loose grille screw.", "Drum hardware buzzing during a sustained tom hit.", "A rack panel or fixture screw buzzing when the subwoofer kicks in."]}, "a86cc658-d362-42b2-b219-0f141af83265": {"definition": "The sustained, sizzling wash of sound produced by playing hi-hat cymbals loosely closed (semi-open), so the two cymbals are near but not clamped and rattle against each other, giving a longer, brighter, less defined decay than fully closed hats.", "plain_english": "The loose, hissing sound of hi-hat cymbals played not fully shut. The two cymbals sit close but are not squeezed together, so they rattle against each other and ring out longer and brighter.", "purpose_function": "It gives drummers and engineers a controllable middle sound between tight closed hats and a fully open ring, adding energy and sustain to a groove.", "practical_application": "A drummer eases hi-hat foot pressure for a washier feel, and an engineer adjusts mic placement and gating so the extra sustain sits right in the mix.", "category": "Cymbal character", "related_terms": ["Wash", "Sizzle", "Sustain", "Decay", "Bleed"], "common_mistakes": ["Confusing a semi-open wash with a fully open hi-hat, which rings much longer.", "Gating hi-hats too tightly and cutting off the natural wash.", "Assuming the wash is unwanted bleed rather than an intended sound."], "scenario_contexts": ["Recording a groove where the drummer opens the hats slightly for energy in the chorus.", "Mixing and deciding how much hi-hat wash to keep against the other cymbals.", "Setting hi-hat mic height to balance stick attack against the wash."]}, "dd13752f-a602-4de4-8564-0003f0a5bd02": {"definition": "A brass playing technique, common in jazz and big-band lead trumpet, in which the player rapidly alternates between a note and a higher partial by shaking the instrument or lips, producing a wide, fast, tremulous trill-like effect, usually at the top of a phrase.", "plain_english": "A brass trick where a trumpet player quickly wobbles between a note and a higher one. It sounds like a fast, wide shiver on a high note, often at the end of a loud phrase.", "purpose_function": "It adds excitement and emphasis to lead brass lines, giving a bold, showy flourish that projects over a large ensemble.", "practical_application": "An engineer expects extra level and brightness when a lead trumpet shakes, and sets headroom and mic distance so the peak does not overload.", "category": "Brass articulation", "related_terms": ["Lip trill", "Vibrato", "Attack transient", "Overtone", "Sustain"], "common_mistakes": ["Confusing a shake with vibrato, which is a narrower, steadier pitch waver.", "Setting input gain with no headroom for the louder shake peak.", "Thinking a shake is an even trill between neighboring notes rather than a wide, loose wobble."], "scenario_contexts": ["Miking a big-band lead trumpet that shakes at the climax of a chart.", "Setting preamp gain to handle the extra level from a brass shake.", "Identifying a shake versus vibrato when editing a brass take."]}, "d2ee84e1-0fc0-4e5e-a722-f194422892e9": {"definition": "The short, dry percussive sound produced when a drummer strikes the drum's shell (its wooden or metal body) instead of the head, giving a woody or metallic click with fast decay and little tuned sustain.", "plain_english": "The dry, knocking sound made by hitting the side of the drum, not the top skin. It gives a short, woody click instead of the full drum note.", "purpose_function": "It provides a distinct percussive accent and helps a listener or engineer separate the woody shell sound from the tuned head sound when identifying a drum's stroke.", "practical_application": "A drummer strikes the shell for a woody click accent, and an engineer places a mic or edits a sample to capture that dry attack apart from the head's tone.", "category": "Drum attack", "related_terms": ["Rimshot", "Attack transient", "Shell resonance", "Shell tone", "Rim click"], "common_mistakes": ["Confusing a shell hit with a rimshot, which strikes head and rim together.", "Expecting long sustain from a shell hit, which decays quickly.", "Miking only the head and missing the woody shell attack."], "scenario_contexts": ["A drummer adding shell-click accents in a quiet passage.", "Sampling a drum and capturing shell hits as separate articulations.", "Identifying a dry woody click in a recording as a shell hit rather than a head strike."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"762dd64c-5753-4d19-9ed1-91d24c5111c4": {"definition": "The resonant vibration of a drum's shell, driven by the vibrating heads and enclosed air, whose frequency and decay depend on shell material, thickness, diameter, and depth, coloring the drum's tone and sustain.", "plain_english": "The way a drum's body rings along with the skins. The size, wood, and thickness of the shell shape how the drum sounds and how long it rings.", "purpose_function": "It contributes part of a drum's pitch, warmth, and sustain, and knowing it helps a technician predict how shell choice and tuning change the tone.", "practical_application": "A tech chooses shells and tunes heads to control resonance, and an engineer uses damping or EQ to tame or feature it in a mix.", "category": "Drum resonance", "related_terms": ["Shell tone", "Sustain", "Sympathetic resonance", "Overtone", "Fundamental"], "common_mistakes": ["Believing the shell makes most of the sound, when the heads dominate.", "Over-damping a drum and killing useful shell resonance.", "Ignoring how shell depth and diameter shift the resonant frequency."], "scenario_contexts": ["Choosing between maple and birch shells for a warmer or brighter resonance.", "Tuning toms to bring out a controlled shell ring.", "Using EQ to reduce an unwanted resonant frequency from the shell."]}, "277389b4-6c1a-4dbd-9bd9-12600c5bf011": {"definition": "The tonal character a drum shell imparts to its sound, arising from shell resonance and construction (material, number of plies, thickness, and bearing edges), heard as the woody or metallic color layered over the tuned head pitch.", "plain_english": "The particular color a drum's body gives its sound. Different woods and builds make a drum sound warm, bright, or dark on top of the note the skins make.", "purpose_function": "It lets drummers and builders choose shells for a target sound and helps engineers recognize why two similarly tuned drums sound different.", "practical_application": "When a drum sounds too dark or too bright, a tech may swap shells or reshape the bearing edges, while an engineer shapes the shell tone with EQ.", "category": "Drum resonance", "related_terms": ["Shell resonance", "Timbre", "Overtone", "Sustain", "Bearing edge"], "common_mistakes": ["Crediting all tonal differences to heads and ignoring shell construction.", "Assuming thicker shells always sound better, when they simply sound different.", "Confusing shell tone with tuning, which is a separate control over pitch."], "scenario_contexts": ["Comparing maple, birch, and metal snares for their shell tone.", "Explaining why two tuned toms of the same size sound different.", "Choosing EQ to enhance a snare's woody shell tone."]}, "191c1fec-f7f4-4434-a7f3-f09f9762bb98": {"definition": "A bright, sustained, glistening high-frequency character in a sound's sustain or decay; in effects processing, shimmer also names a reverb in which the tail is pitch-shifted upward (commonly an octave) and recirculated to add an ethereal, sparkling sheen.", "plain_english": "A bright, sparkly ring in the high notes as a sound fades. It can be the natural airy sustain of a cymbal, or an effect that adds a glowing, higher-pitched tail to reverb.", "purpose_function": "As a descriptor it labels the airy top-end sustain engineers listen for; as an effect it adds height and atmosphere, filling space with a bright, evolving tail.", "practical_application": "An engineer boosts air-band EQ or adds a shimmer reverb to give vocals, guitars, or synth pads a glistening, spacious top end.", "category": "Decay character", "related_terms": ["Sustain", "Sizzle", "Reverb", "Air band", "Decay"], "common_mistakes": ["Confusing natural high-frequency shimmer with harsh sibilance or hiss.", "Adding so much shimmer reverb that the mix loses clarity.", "Assuming shimmer is only an effect and missing it as a natural decay trait."], "scenario_contexts": ["Adding shimmer reverb to a pad for an atmospheric intro.", "Describing a cymbal's bright, airy sustain as shimmer.", "Using EQ to enhance the shimmer in an acoustic guitar's decay."]}, "ed64219e-4719-4b06-9448-5ae3cfbd58db": {"definition": "A decay stage that is brief, meaning the sound falls from its peak level down to its sustain level (or to silence) very quickly after the initial attack. Short decay produces tight, articulate notes with little ring-out, as heard in damped, muted, or staccato playing.", "plain_english": "Short decay means a sound fades away fast right after it starts. Think of a hand clap or a tightly muted drum: it hits, then it is gone almost at once.", "purpose_function": "The decay portion of a sound's amplitude envelope controls how long a note rings after its attack; a short decay keeps sounds tight and defined and stops them from cluttering a busy mix.", "practical_application": "Engineers shorten decay with damping, gating, or a synth's envelope controls to tighten drums, palm-muted guitars, and plucked notes so each hit stays clean.", "category": "Amplitude Envelope", "related_terms": ["Attack", "Sustain", "Release", "Amplitude envelope", "Damping"], "common_mistakes": ["Confusing decay with release; decay is the fall right after the attack peak, while release is the fade after the note is let go.", "Assuming a short decay always means a short overall note, when a high sustain level can still let the sound ring on.", "Using heavy gating to force a short decay and accidentally chopping off natural tails, leaving clipped, unnatural notes."], "scenario_contexts": ["Programming a tight, punchy synth bass by setting a fast decay on the amplitude envelope.", "Palm-muting an electric guitar so each chord stops quickly for a percussive rhythm part.", "Gating close-miked drums so cymbal bleed and room ring are cut short between hits."]}, "377acd82-a71a-4f0f-8a17-396f6dccba2b": {"definition": "A timbral quality of bright, sustained, finely grained high-frequency energy that gives a sound a shimmering, hissing top end. It is heard in cymbals (notably the rivet-fitted 'sizzle cymbal'), overdriven guitars, and airy vocal material, and it sits in the upper-treble and 'air' bands.", "plain_english": "Sizzle is the bright, fizzy shine at the very top of a sound, like the hiss of a cymbal or a frying pan. It is that crisp, sparkly high end you hear more than you feel.", "purpose_function": "'Sizzle' is a listening descriptor engineers use to name and judge the high-frequency energy that adds air, excitement, and presence to a mix, or that turns harsh when overdone.", "practical_application": "A mix engineer may add sizzle with a high-shelf boost or a saturation/exciter, or tame it when cymbals and vocals get too edgy and fatiguing.", "category": "Timbral Descriptor", "related_terms": ["Air", "Presence", "Sibilance", "Brightness", "Sizzle cymbal", "High-frequency content"], "common_mistakes": ["Confusing musical sizzle with harsh sibilance or distortion, then boosting highs when the real fix is de-essing or cleaning up the source.", "UNSAFE: Chasing more 'sizzle' by monitoring cymbals and highs at very high SPL for long stretches, risking noise-induced hearing loss without hearing protection or level breaks.", "Adding broad high-shelf boosts on every track, so the summed sizzle becomes fatiguing and masks detail."], "scenario_contexts": ["Deciding whether an overhead cymbal mix has enough sizzle without becoming harsh.", "Using a high-shelf EQ or exciter to add air and sizzle to a dull vocal or acoustic guitar.", "Identifying excess sizzle from a cheap condenser mic's peaky top end during tracking."]}, "b0bf05e2-9b62-4390-b292-9f743d01de16": {"definition": "A single, distinct delayed repetition of a sound heard shortly after the original, either as a discrete reflection off a hard parallel surface in a room or as a deliberately created short delay (roughly 40-200 ms) with little or no feedback. Also called slapback or slap echo.", "plain_english": "A slap is one clear echo that bounces back a moment after a sound, like a quick hand-clap answer off a far wall. In the studio it is often added on purpose to vocals to make them sound lively.", "purpose_function": "As a room artifact, slap echo signals a reflection problem a technician must find and treat; as an effect, a short slapback delay adds depth and vintage 'live' character without the smearing of long reverb.", "practical_application": "A technician claps or talks in an empty room to hear slap echo off parallel walls, then adds absorption or angled surfaces; a mix engineer dials a 60-150 ms delay for a rockabilly-style vocal slap.", "category": "Acoustic Artifact", "related_terms": ["Slapback delay", "Flutter echo", "Reflection", "Delay", "Reverberation", "Comb filtering"], "common_mistakes": ["Confusing slap echo (one discrete repeat) with flutter echo (a rapid series of repeats between parallel surfaces).", "Setting slapback delay time too long so it drifts into rhythmic echo and muddies the timing instead of thickening the sound.", "Treating a room's slap echo with bass trapping alone, when the fix is absorption or diffusion on the parallel reflecting surfaces."], "scenario_contexts": ["Diagnosing a distinct echo when clapping between two bare parallel walls in an untreated room.", "Adding a short slapback delay to a lead vocal for a 1950s rockabilly feel.", "Identifying slap echo off a rear wall that is blurring speech intelligibility in a live venue."]}, "6c63e663-1e19-4050-900b-3c3dfa4590e5": {"definition": "The incidental scraping or squeaking sound produced when a finger, or a slide, moves lengthwise along a wound string, as on guitar or bass. It is a broadband friction noise from the fingertip crossing the string's ridged winding, distinct from the fretted musical tone.", "plain_english": "Slide noise is the squeak you hear when a player's fingers slide along guitar strings. It comes from skin dragging over the ridged, wound strings, a bit like rubbing a finger across a comb.", "purpose_function": "Recognizing slide noise as a performance artifact lets an engineer decide when it is natural expressive detail to keep and when it is a distraction to reduce.", "practical_application": "Engineers reduce slide noise by choosing flatwound or coated strings, adjusting mic placement, or using spectral-repair and de-noise tools in post to soften the squeaks.", "category": "Performance Artifact", "related_terms": ["Fret noise", "String squeak", "Fingerboard", "Wound strings", "Spectral repair"], "common_mistakes": ["Trying to EQ out slide noise, which shares frequencies with the guitar's body and rarely works without dulling the tone.", "Assuming all slide noise is a mistake, when tasteful finger squeaks are part of a natural acoustic-guitar performance.", "Blaming the microphone for squeaks that are actually caused by string type and playing technique."], "scenario_contexts": ["Cleaning up finger squeaks on a close-miked acoustic guitar during mixing.", "Choosing coated or flatwound strings to cut slide noise before tracking.", "Deciding to keep light slide noise on a solo fingerstyle piece for realism."]}, "f402af48-b389-438d-8c9f-a14be3e47bcb": {"definition": "An amplitude envelope with a slow, gradual onset, meaning the sound takes a relatively long time to rise from silence to its peak level rather than starting abruptly. This gives a gentle, non-percussive beginning to each note, the opposite of a sharp or hard attack.", "plain_english": "A soft attack means a sound eases in gently instead of starting with a sudden punch. It is like slowly turning up a dimmer switch rather than flipping a light on.", "purpose_function": "The attack portion of the envelope sets how a note begins; a soft attack removes the initial transient's bite, giving pads, strings, and swells a smooth, blended feel.", "practical_application": "A technician creates a soft attack with a synth's attack control, volume swells, or slow fade-ins, and can also round off transients with a slow compressor attack time.", "category": "Amplitude Envelope", "related_terms": ["Attack", "Transient", "Amplitude envelope", "Decay", "Compressor attack time"], "common_mistakes": ["Confusing a soft attack (slow envelope onset) with low volume; a soft attack can still be loud once it reaches its peak.", "Using a very slow compressor attack to soften transients and accidentally letting unwanted initial spikes through.", "Applying a soft attack to percussive parts that need punch, which makes them feel late and lifeless."], "scenario_contexts": ["Programming a synth pad with a long attack so it swells in under a vocal.", "Setting a slow compressor attack to gently round off a bass without killing its punch.", "Automating volume fade-ins to give a string section a soft, breathing entrance."]}, "46a98700-7abf-4bc5-bc9a-5d157f58f73c": {"definition": "The resonant vibration of an instrument's soundboard (the thin top plate of a guitar, piano, violin, or similar), driven by the strings and radiating their energy into the air. Its characteristic resonant modes and coupled body/air resonances shape the instrument's loudness, tone, and sustain.", "plain_english": "Soundboard resonance is the way an instrument's thin wooden top vibrates and amplifies the strings. Without it the strings alone would be almost too quiet to hear, like a rubber band stretched in open air.", "purpose_function": "The soundboard turns a string's tiny vibration into a much louder radiated sound and colors the tone through its own resonances, which is why body size and bracing so strongly affect an acoustic instrument's voice.", "practical_application": "When miking an acoustic guitar or piano, engineers position mics to balance bright string detail against boomy low-mid soundboard resonances, often avoiding the body 'hot spot' near the sound hole.", "category": "Instrument Resonance", "related_terms": ["Resonance", "Helmholtz resonance", "Body resonance", "Sympathetic resonance", "Sustain", "Miking technique"], "common_mistakes": ["Miking straight at an acoustic guitar's sound hole, which captures a boomy soundboard/air resonance instead of a balanced tone.", "Confusing the soundboard's air (Helmholtz) resonance with its wood-plate resonances, though both shape the low end.", "Assuming a bigger body always sounds better, when soundboard resonances can also make an instrument boomy or uneven."], "scenario_contexts": ["Positioning a microphone off-axis from a guitar's sound hole to tame low-end soundboard resonance.", "Hearing a specific note 'bloom' louder on a piano due to a soundboard resonance.", "Diagnosing a boomy, uneven peak on an acoustic instrument during tracking."]}, "fe3ea9af-9372-483b-8364-7bad4151bac0": {"definition": "The crisp, percussive onset produced by spiccato bowing, a string technique in which the bow is bounced lightly off the string so each note sounds short and detached. Each stroke gives a clean, articulate attack followed by a very short decay, with the bow leaving the string between notes.", "plain_english": "A spiccato attack is the sharp, bouncy start of each note when a string player lets the bow hop off the string. Every note gets a quick, crisp tap, like lightly bouncing a ball so it barely touches the ground.", "purpose_function": "Spiccato gives rapid string passages a light, rhythmic, clearly separated articulation, and its sharp attack helps each note cut through and stay distinct at speed.", "practical_application": "When recording or programming strings, engineers pick spiccato articulations or samples for fast detached lines and preserve their sharp transients by avoiding heavy compression or slow attack settings.", "category": "Bowing Articulation", "related_terms": ["Staccato", "Sautille", "Detache", "Pizzicato", "Transient", "Articulation"], "common_mistakes": ["Confusing spiccato (bow bounces off the string) with staccato (short notes usually kept on the string).", "Over-compressing spiccato strings, which flattens the sharp attack that gives the technique its bite.", "Choosing a legato string sample for a fast detached line, losing the crisp spiccato attack the part needs."], "scenario_contexts": ["Selecting a spiccato articulation in a sample library for a fast, bouncy string ostinato.", "Close-miking a string section to capture the crisp attack of spiccato passages.", "Preserving spiccato transients by using light, fast-release compression during mixing."]}, "a357022a-c883-4561-8341-f9b5eeb048ed": {"definition": "The short, bright, quickly decaying accent sound of a splash cymbal, a small, thin cymbal (commonly about 6-12 inches) that speaks almost instantly and dies away fast. The term names both this small cymbal type and its sharp, watery burst of high-frequency sound.", "plain_english": "A splash is the quick, bright burst from a small, thin cymbal that sounds and then vanishes fast. It is a short accent, like a tiny splash of water compared with a big crash.", "purpose_function": "The splash cymbal gives a fast, colorful accent that punctuates a moment without the long wash of a crash, so it adds sparkle while staying out of the way.", "practical_application": "A drummer places a splash near the hi-hat for quick accents, and an engineer captures it with the overhead mics, watching that its sharp transient does not overload the channel.", "category": "Cymbal Sound", "related_terms": ["Crash cymbal", "Ride cymbal", "Sizzle", "Transient", "Overhead miking", "Decay"], "common_mistakes": ["Confusing a splash (short, fast decay) with a crash cymbal (louder, with longer sustain).", "Setting overhead levels for the crash and then clipping on the splash's fast, sharp transient.", "Gating overheads so tightly that the splash's quick decay is cut off unnaturally."], "scenario_contexts": ["Miking a drum kit's overheads to capture bright splash accents cleanly.", "Identifying a splash cymbal's fast decay when editing drum transients.", "Choosing a splash instead of a crash for a quick accent that will not wash over a vocal."]}, "57d20619-ad03-47ae-90a6-7028bc197951": {"definition": "The characteristic mechanical artifacts of a spring reverb, in which coiled springs delay and disperse the signal. It includes the twangy, metallic 'boing' or 'sproing' heard on transients and, notably, the loud crashing sound produced when the unit is bumped or moved and the springs are physically jostled.", "plain_english": "Spring noise is the boingy, metallic sound a spring reverb makes, and the loud crash you hear if you knock the unit. It happens because the sound really does travel down metal springs that rattle when bumped.", "purpose_function": "The springs create reverb cheaply, but their bouncing adds a signature twang and makes the unit sensitive to vibration, so knowing this helps a technician expect and manage the noise.", "practical_application": "Technicians isolate spring reverb tanks from stage vibration and shock, since footsteps or knocks make the springs crash audibly, and they may gate or edit out the boing on transient-heavy material.", "category": "Effect Artifact", "related_terms": ["Spring reverb", "Reverberation", "Plate reverb", "Transient", "Dispersion", "Flutter echo"], "common_mistakes": ["Mounting a spring reverb tank on a vibrating surface or amp, so stage bumps make the springs crash into the mix.", "Confusing the spring's twangy dispersion 'chirp' with a fault, when it is normal spring-reverb behavior.", "Sending sharp transients into a spring reverb and being surprised by the exaggerated boing it adds."], "scenario_contexts": ["Hearing a loud crash from a guitar amp's built-in spring reverb when the cabinet is bumped.", "Identifying the metallic boing of a spring reverb on a surf-guitar recording.", "Isolating a spring reverb unit from floor vibration during a live show."]}, "d623c1e2-23f6-4549-ab9c-cdabcd350e8b": {"definition": "The natural resonant frequency, together with its overtone modes, at which a metal helical spring oscillates when excited; in audio it governs the ringing, dispersive metallic response of a spring-reverb tank and the low-frequency resonance of spring-suspended microphone shock mounts. At these frequencies the spring stores and returns energy efficiently, producing a pronounced, slowly decaying response.", "plain_english": "Every spring has certain notes it likes to shake at. When something hits those notes, the spring rings loudly and takes a while to stop. This is why a spring reverb makes its famous 'boing' sound.", "purpose_function": "It explains why spring-based devices color sound as they do: a spring-reverb tank uses these resonances to build its dense, metallic reverberation, while in a shock mount the spring's resonance is placed below the audio band so it isolates the mic instead of ringing.", "practical_application": "A technician recognizes spring resonance as the twangy, metallic ring of a reverb tank and damps or EQs it, and checks that a mic shock mount's spring resonance sits well below program material so knocks are absorbed rather than passed through.", "category": "Mechanical Resonance", "related_terms": ["Spring vibration", "Spring reverb", "Resonant frequency", "Shock mount", "Decay time", "Reverberation"], "common_mistakes": ["Confusing spring resonance with a smooth digital reverb tail; the spring's dispersive, metallic ring is a mechanical artifact", "Assuming a spring-reverb tank can be mounted anywhere, when its springs pick up floor and cabinet vibration and will 'boing' if bumped", "Thinking more spring tension always means more reverb, rather than shifting the resonant modes"], "scenario_contexts": ["Dialing in a guitar amp's built-in spring reverb and taming the metallic ring", "Diagnosing a 'boing' when a spring-reverb combo amp is bumped during a live set", "Choosing a microphone shock mount whose spring resonance falls below the vocal range"]}, "2716517d-c0f8-44f0-822b-06cdc84b65e5": {"definition": "The physical back-and-forth oscillation of a spring after it is disturbed, in which the coil transmits waves along its length and rings at its resonant modes before damping out. In audio this is the mechanism by which a spring-reverb tank carries and re-radiates a signal, and also the unwanted motion of shock-mount or floor springs that can inject noise.", "plain_english": "A spring vibration is just a spring shaking after you tap it. The shaking travels up and down the coil and slowly dies away. Inside a spring reverb, that traveling shake is what smears the sound out over time.", "purpose_function": "Understanding spring vibration tells a technician how a spring turns a quick input into a spread-out, ringing output, which is useful for spring reverb, and warns when a spring is instead passing stray shakes into the signal.", "practical_application": "On the job you hear spring vibration as the rattling, springy decay of a reverb tank, and you keep tanks and spring mounts away from anything that could bump them during a take.", "category": "Mechanical Artifact", "related_terms": ["Spring resonance", "Spring reverb", "Damping", "Decay", "Mechanical noise", "Shock mount"], "common_mistakes": ["Treating every spring 'boing' as a fault when it is the intended reverb mechanism", "Ignoring that a vibrating tank can be re-excited by nearby subwoofers or footsteps", "Confusing spring vibration, which is mechanical, with electrical hum in the signal"], "scenario_contexts": ["Recording a surf-rock guitar tone that relies on the reverb tank's spring vibration", "Isolating a combo amp so stage thump does not shake its reverb springs", "Troubleshooting a springy noise traced to a knocked reverb pan"]}, "33e4925f-91fb-45e4-8acc-16be71be12bf": {"definition": "Low-frequency mechanical energy from footsteps, stage rumble, HVAC, or handling that travels up a microphone stand into the capsule as structure-borne noise, appearing as thumps and low-frequency rumble in the signal rather than airborne sound. It is controlled with shock mounts, isolation feet, high-pass filtering, and careful stand placement.", "plain_english": "Stand vibration is shaking that travels up a mic stand into the microphone. Footsteps or a bumped stand turn into low thumps in the recording. A shock mount and a low-cut filter help stop it.", "purpose_function": "Recognizing stand vibration matters because a mic picks up not only air but anything shaking its body; naming that path lets a technician block it before it muddies a recording.", "practical_application": "A technician suspects stand vibration when low thumps appear in time with footsteps or bumps, then fits a shock mount, adds isolation, and engages a high-pass filter to remove it.", "category": "Mechanical Artifact", "related_terms": ["Shock mount", "Handling noise", "Low-frequency rumble", "High-pass filter", "Structure-borne noise", "Microphone isolation"], "common_mistakes": ["Blaming stand-vibration rumble on the mic's electronics instead of the mechanical path", "Skipping the shock mount on a sensitive large-diaphragm condenser", "Placing a stand directly on a resonant riser or hollow stage without isolation"], "scenario_contexts": ["Vocal tracking where the singer taps or leans on the stand", "A live stage where subwoofers and footfalls shake mic stands", "Boom-mounted overheads picking up floor rumble in a drum room"]}, "5be4fbf2-9f7e-4444-99e3-ee6b6d450620": {"definition": "The sharp initial transient produced when a drumstick, mallet, or beater strikes a drum, cymbal, or other percussion surface: the brief, high-amplitude onset that precedes the body and decay of the note and that largely defines its perceived punch and articulation.", "plain_english": "Stick attack is the quick 'crack' at the very start of a drum hit. It is the first burst of sound before the drum rings out. This snap is what makes a hit feel punchy.", "purpose_function": "The stick attack carries most of the cues the ear uses to place a drum in time and judge its impact, so preserving or shaping it is central to a tight, punchy drum sound.", "practical_application": "A technician protects the stick attack with fast-transient mics and careful compressor attack settings, or boosts it with a transient shaper when a drum sounds soft and undefined.", "category": "Transient / Attack", "related_terms": ["Transient", "Attack", "Stick definition", "Stick click", "Transient shaper", "Decay"], "common_mistakes": ["Setting a compressor's attack too fast and squashing the stick attack, killing the drum's punch", "Confusing the stick attack, a transient, with the drum's tuning or body tone", "Over-boosting the attack until the drum sounds clicky and unnatural"], "scenario_contexts": ["Compressing a snare while keeping its stick attack intact", "Using a transient designer to add punch to a dull kick", "Choosing overhead mics fast enough to capture cymbal stick attack"]}, "da9cd79a-01a7-475c-92ba-d7ed6410f4ed": {"definition": "The brief, high-frequency click heard at the instant a drumstick contacts a head, rim, cymbal, or another stick: the hard, wood-on-surface component of the attack. It can be a desired articulation, such as a defined kick-beater click or a cross-stick, or an unwanted artifact, such as stray stick noise bleeding into cymbal mics.", "plain_english": "Stick click is the little 'tick' of the wooden stick hitting a surface. Sometimes you want it, like a clear kick-drum click. Other times it is just noise leaking into a mic.", "purpose_function": "Naming the stick click lets a technician decide whether to feature it for attack and definition or reduce it when it clutters cymbals and overheads.", "practical_application": "A technician boosts around the click frequency to help a kick cut through a mix, or uses EQ, mic angle, and gating to tame stick clicks bleeding into overhead and cymbal mics.", "category": "Attack Artifact", "related_terms": ["Stick attack", "Beater click", "Cross-stick", "Bleed", "Stick definition", "Transient"], "common_mistakes": ["Confusing the stick click with the drum's body tone", "Over-gating overhead mics to remove clicks and cutting the cymbal attack as well", "Assuming stick click is always a fault, when a defined beater click helps the mix cut through"], "scenario_contexts": ["Adding beater click to a kick so it cuts through a dense mix", "Reducing stray stick clicks bleeding into overhead mics", "Capturing a clean cross-stick (rim click) on a ballad"]}, "99802dd0-9ab7-4bd0-991e-a692f7790305": {"definition": "The clarity and audibility of the stick's attack within a drum sound: how distinctly the initial transient and its high-frequency detail come through relative to the body and decay. High stick definition makes each hit read as crisp and articulate, while low definition sounds dull or smeared.", "plain_english": "Stick definition is how clearly you can hear the stick hit in a drum sound. When it is high, each hit sounds crisp and clear. When it is low, the hits sound dull and blurry.", "purpose_function": "Stick definition is what lets a listener follow fast drum parts clearly, so engineers manage it to keep drums articulate without making them harsh.", "practical_application": "A technician improves stick definition with presence-range EQ, transient shaping, or closer mic placement, and eases it back when a part sounds too clicky.", "category": "Transient Clarity", "related_terms": ["Stick attack", "Stick click", "Transient", "Presence", "Definition", "Transient shaper"], "common_mistakes": ["Chasing stick definition with harsh high-frequency boosts that make cymbals brittle", "Confusing definition, the clarity of the attack, with overall loudness", "Over-compressing so the attack is lost and definition drops"], "scenario_contexts": ["Restoring articulation to a dull snare with presence EQ", "Balancing stick definition against cymbal harshness on overheads", "Tightening a fast double-kick pattern so each stroke reads clearly"]}, "610b0ba4-5061-4d48-8cbe-a7132b926de0": {"definition": "The natural bounce of a drumstick back off the drumhead or other surface after impact, driven by the head's tension and elasticity returning stored energy to the stick. Drummers exploit this rebound with a relaxed fulcrum grip to play faster, smoother strokes with less effort and to produce multiple-bounce strokes.", "plain_english": "Stick rebound is the way a stick bounces back up after it hits a drum. The tight, springy head pushes the stick back, like a ball bouncing off the floor. Drummers use that bounce to play fast without tiring out.", "purpose_function": "Rebound turns the drumhead's own springiness into free motion for the next stroke, which is why controlling it is central to speed, evenness, and endurance at the kit.", "practical_application": "A drummer relies on stick rebound for buzz rolls, double strokes, and fast single strokes, adjusting grip pressure and head tension to control how much the stick bounces.", "category": "Playing Technique", "related_terms": ["Stick attack", "Drumhead tension", "Double stroke", "Buzz roll", "Rebound stroke", "Grip"], "common_mistakes": ["Gripping the stick too tightly, which kills the rebound and forces muscling every stroke", "Expecting the same rebound from a loose head as from a tightly tuned one", "Relying only on rebound and neglecting controlled strokes for softer dynamics"], "scenario_contexts": ["Practicing double-stroke rolls that depend on even rebound", "Adjusting drumhead tension to get a lively rebound for fast playing", "Playing a soft buzz roll using controlled multiple-bounce rebound"]}, "85894828-fea5-4be8-84ab-577713871d58": {"definition": "The soft, flute-like timbre produced on a bowed string instrument by playing sul tasto, that is, drawing the bow over the fingerboard away from the bridge. Bowing there weakens the upper harmonics and emphasizes the fundamental, giving a veiled, mellow tone; the technique is also called flautando and contrasts with the bright, harmonic-rich sul ponticello.", "plain_english": "Sul tasto tone is a soft, breathy string sound. The player bows over the fingerboard instead of near the bridge. This mellows the sound, a bit like a flute.", "purpose_function": "Sul tasto gives composers and players a gentle, veiled color at the quiet end of the string palette, useful when a normal or bright tone would be too present.", "practical_application": "A player moves the bow over the fingerboard to get a hushed, colorless pad, and an engineer recognizes the tone as intentionally dark rather than a dull mic or muffled recording.", "category": "String Articulation", "related_terms": ["Sul ponticello", "Flautando", "Bow position", "Harmonic content", "Timbre", "Con sordino"], "common_mistakes": ["Confusing a sul tasto tone with a poorly recorded, muffled string sound and 'fixing' it with EQ", "Bowing too near the bridge and losing the intended soft color", "Assuming sul tasto only changes volume, when it mainly changes timbre"], "scenario_contexts": ["Recording a string section asked to play sul tasto for a soft passage", "Identifying an intentionally veiled tone versus a dull microphone", "Contrasting sul tasto and sul ponticello colors in an arrangement"]}, "cd90dd69-e319-42ed-8780-9e1a58842276": {"definition": "A gradual increase in loudness, and often in intensity or brightness, over a note or phrase from soft to louder, a crescendo shaped as a smooth rise that is sometimes followed by a decrease. It can be performed by bowing, breath, or an organ swell box, or created electronically by fading in level with a volume pedal, a guitar volume knob, or a slow envelope or automation.", "plain_english": "A swell is a smooth rise in volume, from quiet to loud. Instead of a sharp start, the sound eases in. Guitarists make one by turning up the volume knob right after they pick a note.", "purpose_function": "A swell removes the hard attack of a note so a sound blooms in gently, which is why it is used for pads, ambient textures, and expressive dynamics.", "practical_application": "A technician creates swells with volume-pedal moves, a slow synth attack, or fade-in automation, and shapes their timing so the sound arrives smoothly under the mix.", "category": "Dynamics / Envelope", "related_terms": ["Crescendo", "Attack", "Volume pedal", "Envelope", "Fade-in", "Dynamics"], "common_mistakes": ["Confusing a swell, a gradual level change, with tremolo, a rapid repeated pulsing", "Making the swell so slow that the note loses its pitch and timing cues", "Forgetting that a fast envelope attack setting cancels an intended slow synth swell"], "scenario_contexts": ["Automating a volume swell on a pad so it blooms into a chorus", "Using a volume pedal for attack-less guitar swells", "Setting a slow synth amplitude-envelope attack to make notes swell in"]}, "890c382c-22f0-4d0d-901b-c1b29673a126": {"definition": "The final, gradually fading portion of a sound after its initial attack and body have ended, most often the decaying reverberation or delay repeats that continue after the source note stops. It is characterized by falling amplitude over time and, in rooms, by a reverberation decay commonly quantified as RT60, the time for the sound to fall 60 dB.", "plain_english": "A tail is the soft, fading part of a sound. It lingers after the main note stops. Think of the echo you hear after you clap in a big empty room.", "purpose_function": "The tail carries the sense of space, size, and sustain in a sound, and engineers listen to it to judge room reverberation, delay settings, and how long a note rings before it fully dies away.", "practical_application": "A technician shapes reverb and delay tails with decay-time, damping, and gating controls, then trims or fades them so they add depth without cluttering the mix or masking the next note.", "category": "Decay characteristic", "related_terms": ["Decay", "Reverberation", "Release", "Delay", "Sustain", "RT60"], "common_mistakes": ["Confusing the reverb tail (the fading space around a sound) with the dry note's own release or sustain.", "Setting decay times so long that overlapping tails smear the mix and mask following notes.", "Hard-cutting or gating a tail too abruptly, leaving an unnatural chopped-off sound instead of a smooth fade."], "scenario_contexts": ["Adjusting a reverb's decay time so a vocal's tail fades smoothly between phrases.", "Using a gate or automated fade to shorten a snare reverb tail in a busy rock mix.", "Judging a hall's reverberation tail (RT60) when tuning a live sound system."]}, "863a02fd-782f-41d0-b198-32a6bf10a55c": {"definition": "A single output point drawn from a specific position along a delay line, producing one discrete delayed copy (echo) of the input signal. Multiple taps at different delay times, each optionally scaled and summed, form a tapped delay line used to create multi-echo, rhythmic, or reverberant effects.", "plain_english": "A tap is one 'listening spot' along a delay that grabs a single echo of the sound. Line up several taps and you get a row of repeats, a bit like bouncing a ball and hearing each bounce.", "purpose_function": "Taps let one delay line yield many timed echoes at once, so designers can build rhythmic multi-tap delays, early-reflection patterns, and reverberation from a single efficient structure.", "practical_application": "On a multi-tap delay plugin or hardware unit, a technician sets each tap's time, level, and pan to place individual echoes in time and space, often synced to the song tempo.", "category": "Delay processing", "related_terms": ["Delay", "Echo", "Feedback", "Early reflections", "Multi-tap delay"], "common_mistakes": ["Confusing a delay tap (one echo output point) with 'tap tempo,' the button used to set delay time by tapping.", "Assuming each tap needs its own separate delay line, when one delay line can feed many taps.", "Forgetting that raising feedback, not adding taps, is what makes echoes repeat and build up over time."], "scenario_contexts": ["Programming a multi-tap delay so guitar echoes fall on musically useful beats.", "Designing early reflections in a reverb by placing several short taps.", "Setting individual tap levels and pans to spread echoes across the stereo field."]}, "7eade947-cee1-491c-b0f1-f6ae6c763827": {"definition": "A subjective descriptor for a low-frequency, dull, short-lived percussive sound with a fast decay and little high-frequency content, such as the weighty body of a struck object like a kick drum, floor tom, or a bumped microphone. It denotes energy concentrated in the low and low-mid range with a soft, damped attack rather than a sharp, bright click.", "plain_english": "A thud is a low, dull thump you feel more than hear, like dropping a heavy book on a table. It has plenty of low end but no bright 'click' on top.", "purpose_function": "Naming a sound a 'thud' quickly tells engineers it lives in the low frequencies with a soft attack, guiding EQ and microphone choices to add or control that weight.", "practical_application": "A technician boosting the thud of a kick drum works in the low bass region for weight, and may cut it to tame a boomy, thuddy tom or a handling-noise bump on a microphone.", "category": "Timbral descriptor", "related_terms": ["Attack", "Transient", "Boom", "Punch", "Low frequency"], "common_mistakes": ["Treating 'thud' as an exact measurement rather than a subjective, low-frequency impression that varies between listeners.", "Boosting low frequencies to add thud without checking on full-range monitors, then overloading small speakers.", "Confusing a musical thud (wanted low-end body) with rumble or handling-noise that should be filtered out."], "scenario_contexts": ["Describing the low-end body of a kick drum during a mix.", "Diagnosing an unwanted thud from microphone handling or foot noise on a stage.", "EQing a floor tom to keep its thud while removing boxy mid frequencies."]}, "473916fa-a90c-4196-8f8a-ff9db4320a97": {"definition": "A bass-guitar technique in which the side of the thumb strikes a string near the end of the fingerboard and bounces off, producing a percussive, sharply transient note with a bright attack and strong fundamental. It is the 'slap' half of slap-and-pop playing, where thumb slapping is combined with finger popping (pulling and releasing) of strings.", "plain_english": "Thumb slap is when a bass player bounces the side of their thumb off a string to make a punchy, drum-like note. It gives that snappy, funky 'slap bass' sound.", "purpose_function": "It adds a percussive, attack-heavy sound to the bass, letting the instrument drive rhythm with a bright snap that cuts through a mix in funk, pop, and fusion styles.", "practical_application": "Players slap over the last frets and combine it with popped strings, while engineers capture the extra transient and string noise with careful gain-staging, compression, and sometimes brighter EQ.", "category": "Playing technique", "related_terms": ["Attack", "Transient", "Slap and pop", "Pop", "Percussive attack"], "common_mistakes": ["Slapping with the flat pad of the thumb instead of bouncing the side off the string, which mutes the tone.", "Hitting too hard and clipping the preamp or interface input from the strong transient peak.", "Confusing the thumb slap (percussive strike) with the popped note (string pulled and released) in slap-and-pop playing."], "scenario_contexts": ["Recording a funk bass line that alternates thumb slaps and pops.", "Setting input gain to handle the loud transient peaks of slap bass without clipping.", "Compressing a slap-bass track to even out the strong attack against quieter fingered notes."]}, "995bb478-ca32-48cc-941d-aafe467c250d": {"definition": "A subjective descriptor for a sharp, hard, percussive transient with a strong, fast attack and pronounced mid/high-frequency snap, such as the aggressive crack of a snare hit, a hard beater on a kick, or a slapped bass string striking the frets. It emphasizes a pronounced attack transient rather than sustained body.", "plain_english": "A thwack is the hard, cracking snap at the very start of a hit, like a ruler smacked flat on a desk. It is all sharp attack and very little ring.", "purpose_function": "Calling a sound a 'thwack' flags a strong attack transient in the upper frequencies, telling engineers to protect or enhance that snap with transient shaping and EQ.", "practical_application": "A technician adds thwack to a snare by boosting a few kilohertz and using a transient shaper to lift the attack, while watching that the sharp peak does not trigger limiting too hard.", "category": "Transient descriptor", "related_terms": ["Attack", "Transient", "Snap", "Punch", "Transient shaper"], "common_mistakes": ["Overusing a transient shaper to add thwack until the sound becomes clicky and unnatural.", "Mistaking a musical thwack (wanted attack) for a distortion click or edit glitch that should be repaired.", "Boosting high-mids for snap without controlling the resulting sharp peaks, causing harsh clipping."], "scenario_contexts": ["Enhancing the attack thwack of a snare in a rock mix.", "Comparing drum samples by how much thwack their attack has.", "Using a transient designer to restore thwack lost to heavy compression."]}, "dfd29b95-bc75-4a03-b284-862d1a618b27": {"definition": "A very brief, high-frequency click, a sharp low-level transient often heard as an unwanted artifact, such as a digital sample-level glitch, a word-clock or edit-point click, a metronome/click-track pulse, or surface noise on vinyl. It occupies a tiny slice of time with high-frequency or broadband content and no sustained tone.", "plain_english": "A tick is a tiny, sharp click, like the tap of a clock's second hand. In recordings it is usually an unwanted little pop you want to find and remove.", "purpose_function": "Identifying a tick tells a technician there is a momentary discontinuity or click in the signal, which points to editing, clocking, or playback problems to fix.", "practical_application": "Engineers locate ticks by ear and on the waveform, then remove them with de-click tools, crossfades at edit points, or by fixing the digital clock or connection causing them.", "category": "Audio artifact", "related_terms": ["Click", "Pop", "Artifact", "Word clock", "Crossfade"], "common_mistakes": ["Confusing a musical click-track tick with an unwanted click artifact in the recording.", "Ignoring a repeating tick that signals a word-clock or sync error rather than a one-off glitch.", "Editing on the waveform without a crossfade, creating a tick at every cut point."], "scenario_contexts": ["Removing mouth or edit clicks (ticks) from a spoken-word recording.", "Tracing a regular tick to a word-clock or digital-sync fault in a studio setup.", "Cleaning ticks and pops from a needle-drop transfer of a vinyl record."]}, "dc197406-4aa2-43fd-ada7-fc95222b6be6": {"definition": "A synonym for timbre: the perceptual attribute of a sound, other than pitch, loudness, and duration, that lets a listener distinguish two sounds presented at the same pitch and loudness, such as a violin versus a flute. It arises mainly from a sound's harmonic (spectral) content and how that content evolves over time, especially during the attack.", "plain_english": "Tone color is what makes two instruments playing the same note still sound different, like a trumpet next to a guitar. It is the 'flavor' or character of a sound, not how high or loud it is.", "purpose_function": "Tone color is how we identify and describe the character of instruments and voices, and engineers shape it with microphone choice, EQ, and processing to make sounds sit and blend in a mix.", "practical_application": "A technician changes tone color by picking microphones, positions, and EQ curves, listening to how the harmonic balance and attack define an instrument's character.", "category": "Timbre", "related_terms": ["Timbre", "Harmonics", "Overtones", "Spectrum", "Attack"], "common_mistakes": ["Thinking tone color and timbre are different things, when they are two names for the same property.", "Assuming tone color depends only on frequency content, ignoring how the attack and time-evolution shape it.", "Confusing tone color (sound character) with pitch or loudness."], "scenario_contexts": ["Choosing a microphone to capture the tone color of an acoustic guitar.", "Using EQ to match the tone color of two vocal takes recorded on different days.", "Describing why two synth patches at the same note sound different."]}, "397562c6-f8e6-494f-8695-91138a27613b": {"definition": "A sharp, percussive click produced by forming suction with the tongue against the roof of the mouth or teeth and releasing it, sounding an ingressive click. In phonetics these are click consonants; in recording they appear as mouth-noise click artifacts on close-miked vocal and voice-over tracks, and are also used deliberately in vocal percussion and beatboxing.", "plain_english": "A tongue click is a little clicking sound. You make it by pressing your tongue to the roof of your mouth and pulling it away fast, like a 'tsk-tsk' noise. On close vocal recordings, these clicks show up as unwanted little pops.", "purpose_function": "Recognizing a tongue click helps a technician tell a natural mouth noise from an electronic glitch, so it can be edited out of speech or kept as a rhythmic element.", "practical_application": "On voice-over and vocal tracks, engineers find tongue clicks between words and remove them with de-click tools or manual edits and fades, and keeping the performer hydrated reduces them at the source.", "category": "Mouth-noise artifact", "related_terms": ["Click", "Tick", "Mouth noise", "De-click", "Artifact"], "common_mistakes": ["Confusing a natural tongue click with a digital click artifact and chasing a gear fault that is not there.", "Removing every tongue click so aggressively that the speech starts to sound unnatural.", "Ignoring the cause, a dry mouth, and only editing clicks out afterward instead of preventing them."], "scenario_contexts": ["Cleaning tongue clicks from a voice-over before final delivery.", "Coaching a singer to stay hydrated to reduce mouth clicks at the microphone.", "Using a tongue click as a percussive sound in a beatbox or a cappella track."]}, "587b8a50-22d5-49a4-aa1c-d10fe106f5e6": {"definition": "A note onset on a wind or brass instrument in which the tongue briefly interrupts the airstream, typically with a 'tu' or 'du' motion, to give the note a clean, defined start. It contrasts with a slurred (un-tongued) attack, where consecutive notes are connected with no tongue articulation.", "plain_english": "A tongued attack is when a wind or brass player uses a little 'tu' of the tongue to start a note crisply, instead of letting notes glide together. It gives each note a clear, clean beginning.", "purpose_function": "Tonguing defines the start of each note, controlling articulation, clarity, and rhythm, and it produces the sharp attack transient that shapes how a wind or brass line is perceived.", "practical_application": "When recording winds and brass, engineers position microphones to capture a clear tongued attack without over-emphasizing breath and tonguing noise, and may use transient control to balance attack against body.", "category": "Articulation", "related_terms": ["Attack", "Articulation", "Transient", "Staccato", "Slur"], "common_mistakes": ["Confusing a tongued attack (tongue-started note) with a slur, where notes connect without tonguing.", "Assuming tonguing stops the air fully, when it only briefly interrupts it to separate notes.", "Close-miking winds so tightly that tonguing and breath noise overpower the note's tone."], "scenario_contexts": ["Miking a trumpet to capture crisp tongued attacks in a horn section.", "Editing a flute part where soft tongued attacks need a little transient lift.", "Distinguishing tongued (articulated) from slurred passages when comping wind takes."]}, "5fe6bfda-a3d6-4aca-8944-cb796273eafd": {"definition": "A transient spike is a very brief, high-amplitude peak at the onset of a sound that rises and falls far faster than the surrounding signal. It appears as a short, sharp jump in level, typical of drum hits, plucks, and vocal consonants, and carries much of a sound's attack information.", "plain_english": "A transient spike is a quick, sharp jump in loudness at the very start of a sound, like the crack of a snare hit. It lasts only a moment but gives a sound its punch.", "purpose_function": "Recognizing transient spikes lets a technician judge a sound's attack and guard against sudden peaks that can clip converters or trip limiters.", "practical_application": "Engineers watch meters and waveforms for transient spikes when setting gain and compressor attack, keeping drums punchy while avoiding overload.", "category": "Attack Artifact", "related_terms": ["Initial transient", "Attack", "Peak", "Clipping", "Transient shaper", "Headroom"], "common_mistakes": ["Confusing a musical transient spike with an unwanted click or digital over.", "UNSAFE: Chasing loudness so transient spikes drive amplifiers and drivers into hard clipping, which can overheat and destroy tweeters.", "Using too fast a compressor attack and flattening the spike, killing the punch.", "Trusting slow meters that miss the very fastest peaks."], "scenario_contexts": ["Setting converter gain so a snare's transient spike does not clip.", "Choosing a limiter to tame transient spikes on a live drum bus.", "Diagnosing intermittent clip lights caused by sharp vocal consonants."]}, "956caf36-105a-4951-a5a7-8bbd8d845ed5": {"definition": "Trashy describes a cymbal or similar metallic sound with a dense, noise-like, inharmonic spectrum, a fast and dry decay, and little clear pitch, giving an aggressive, dirty character like a trash or china cymbal rather than a clean, ringing tone.", "plain_english": "Trashy is a dirty, noisy cymbal sound that ends fast and has no clear note, like a china cymbal or a trash-can lid. It sounds rough and splashy instead of smooth and ringing.", "purpose_function": "The label lets a technician quickly describe a rough, noise-heavy metallic tone so they can decide whether it suits a track or needs taming.", "practical_application": "An engineer calls a cymbal trashy when choosing effect cymbals or setting EQ, and may roll off harsh highs or use it deliberately for gritty, aggressive accents.", "category": "Timbral descriptor", "related_terms": ["Sizzle", "Wash", "China cymbal", "Overtone ring", "Decay", "Timbre"], "common_mistakes": ["Assuming trashy always means bad, when it is often a wanted effect-cymbal sound.", "Confusing a naturally trashy cymbal with a cracked or damaged one.", "Trying to EQ a trashy cymbal into a clean ping, which rarely works."], "scenario_contexts": ["Choosing a trashy china cymbal for aggressive rock accents.", "Taming harsh, trashy overheads with a high-frequency cut.", "Describing a cymbal's dirty, short character to a producer."]}, "ad035832-0914-454b-ba84-fa65159170ca": {"definition": "Tremolo bowing (bowed tremolo) is a string technique in which the player rapidly reiterates a note with quick, short back-and-forth bow strokes, usually near the tip, producing a shimmering, sustained, agitated sound. It is normally unmeasured, the strokes played as fast as possible rather than in strict rhythm.", "plain_english": "Tremolo bowing is moving the bow back and forth very fast on the same note so it shivers and buzzes. Film composers use it to build tension or a sense of drama.", "purpose_function": "It lets strings sustain and intensify a note with a trembling, dramatic texture that a single smooth stroke cannot give.", "practical_application": "When recording or mixing strings, an engineer recognizes tremolo bowing by its dense, sustained shimmer and may adjust mics or reverb so the effect stays clear rather than smeared.", "category": "Bowing technique", "related_terms": ["Sul ponticello", "Measured tremolo", "Fingered tremolo", "Articulation", "Sustain", "Bow noise"], "common_mistakes": ["Confusing bowed tremolo with fingered tremolo, which alternates between two pitches.", "Mistaking the fast bow noise of a tremolo for a recording fault.", "Gating string tracks so hard that the quiet start of a tremolo is cut off."], "scenario_contexts": ["A film cue where violins play tremolo to build suspense.", "Close-miking a section and hearing extra bow noise from tremolo strokes.", "Adding reverb to a tremolo passage for a lush, sustained bed."]}, "93eb5e6e-db70-4310-8de2-00f0cb662635": {"definition": "Twang is a bright, sharp, resonant tone with a fast, ringing attack rich in high harmonics and a quick, metallic decay, characteristic of tightly strung plucked instruments such as the banjo, a Telecaster-style guitar, or a jaw harp. It is heard as a pointed, spring-like pinging quality rather than a warm, rounded sound.", "plain_english": "Twang is the bright, sharp, ringing sound of a plucked string, like a banjo or a country guitar. It has a quick, pingy snap with lots of high, metallic zing.", "purpose_function": "Naming twang helps a technician identify and dial in the bright, cutting plucked-string character that defines styles like country and bluegrass.", "practical_application": "An engineer boosts upper-mid and treble EQ or picks bright strings and pickups to bring out twang, and tames it when it turns harsh.", "category": "Tonal descriptor", "related_terms": ["Attack", "Brightness", "Pluck", "Sustain", "Harmonics", "Bite"], "common_mistakes": ["Confusing twang, a bright plucked tone, with vibrato or pitch bending.", "Over-boosting treble to add twang and making the track thin and harsh.", "Assuming twang is only a guitar term, when banjos and jaw harps twang too."], "scenario_contexts": ["EQing a Telecaster for more twang in a country mix.", "Choosing bright strings and a bridge pickup for a twangy tone.", "Reducing harsh twang on a banjo track with a gentle treble cut."]}, "147ebd4a-b5fb-4737-93e1-666c89b60b56": {"definition": "The regulators are keyed, closed-ended pipes on a full (concert) set of uilleann pipes, mounted with the drones on the common stock, that the piper sounds by pressing their keys, usually with the wrist or heel of the right hand, to add chords and rhythmic harmony beneath the chanter melody. A full set typically carries three: bass, baritone, and tenor.", "plain_english": "Regulators are extra keyed pipes on Irish uilleann pipes that play chords. The piper taps their keys with the wrist to add harmony under the tune, like a one-person backing band.", "purpose_function": "They let a single piper accompany their own melody with chords and rhythm, a feature that makes the uilleann pipes unusually self-contained among bagpipes.", "practical_application": "When miking uilleann pipes, an engineer positions mics to capture the regulators' chordal accents along with the chanter, since the regulators add loud rhythmic stabs.", "category": "Bagpipe component", "related_terms": ["Chanter", "Drone", "Bellows", "Reed", "Bagpipe", "Harmony"], "common_mistakes": ["Confusing regulators with drones; drones sound continuously, regulators only when keyed.", "Assuming every uilleann set has regulators, when practice (half) sets often lack them.", "Miking only the chanter and missing the regulators' chords."], "scenario_contexts": ["Recording a solo piper who uses regulators for chordal accompaniment.", "Balancing chanter and regulator levels in a traditional session mix.", "Identifying rhythmic chord stabs as regulator work, not a second instrument."]}, "847ae384-5d58-4088-98e6-da1d272ad8f9": {"definition": "Valve clatter is the mechanical rattling or knocking noise produced by the moving pistons or rotors of a brass instrument's valves, most audible on larger or worn instruments and easily captured by close microphones. It is unwanted percussive noise unrelated to the instrument's musical tone.", "plain_english": "Valve clatter is the rattly, knocking sound a brass instrument's valves make as they move up and down. Close mics can pick it up like a faint tapping under the notes.", "purpose_function": "Spotting valve clatter helps a technician separate a mechanical noise problem from the musical sound so it can be fixed at the source.", "practical_application": "An engineer hearing valve clatter repositions the mic, often above and behind the player, or asks the player to oil the valves and press more smoothly.", "category": "Mechanical artifact", "related_terms": ["Valve click", "Valve noise", "Key click", "Mechanical noise", "Close miking"], "common_mistakes": ["Blaming valve clatter on the microphone instead of the instrument's action.", "Trying to EQ out clatter, which shares frequencies with the instrument's tone.", "Placing the mic right over the valves, maximizing the clatter."], "scenario_contexts": ["Close-miking a tuba and hearing knocking from the valves.", "Repositioning a trumpet mic to reduce valve clatter.", "Editing out isolated valve clatter in a quiet passage."]}, "7261dad2-bbc3-4504-a613-4365eaf1cc20": {"definition": "Valve click is the short, sharp clicking sound made when a brass instrument's valve seats or returns, often from the piston contacting its casing or from worn felt or cork pads, captured as a brief transient by close microphones. It is a mechanical artifact, not part of the musical tone.", "plain_english": "Valve click is the small, sharp tick you hear when a brass player presses or releases a valve. It is a quick mechanical noise, not a real note.", "purpose_function": "Identifying valve clicks lets a technician tell a harmless mechanical tick apart from an electronic click or an edit glitch.", "practical_application": "An engineer who hears valve clicks moves the mic away from the valve block, or edits out stray clicks in exposed passages during post.", "category": "Mechanical artifact", "related_terms": ["Valve clatter", "Valve noise", "Key click", "Transient", "Close miking"], "common_mistakes": ["Mistaking a mechanical valve click for a digital click or dropout.", "Assuming worn valve felts are fine, when missing felts make clicks louder.", "Miking too close to the valves in a quiet, exposed part."], "scenario_contexts": ["Hearing sharp ticks from a trumpet's valves in a soft passage.", "Deciding whether a click is a valve or an edit point.", "Replacing worn valve felts to quiet the clicking."]}, "3ee7e37e-f53f-4a9c-9ebd-b96f18e86599": {"definition": "Valve noise is the general term for the mechanical sounds, such as clicks, clatter, and rattles, made by the valve mechanism of a brass instrument as the player operates it, distinct from the musical tone and most noticeable with close microphones. In brass close-miking it refers to piston or rotary valve action, not to electronic tube (valve) noise.", "plain_english": "Valve noise is the general name for the clicks and rattles a brass instrument's valves make while being played. It is mechanical sound, not part of the music, and close mics make it easier to hear.", "purpose_function": "The term groups the mechanical noises of valve action so a technician can diagnose and reduce them as one category.", "practical_application": "When valve noise intrudes, an engineer changes mic angle and distance, typically miking from above and behind, or asks for smoother technique and freshly serviced valves.", "category": "Mechanical noise", "related_terms": ["Valve click", "Valve clatter", "Key click", "Mechanical artifact", "Close miking"], "common_mistakes": ["Confusing mechanical brass valve noise with electronic noise from a tube (valve) amplifier.", "Blaming valve noise on the mic rather than the instrument or technique.", "Positioning the mic directly over the valves, worsening the noise."], "scenario_contexts": ["A close-miked euphonium showing audible valve noise between notes.", "Choosing mic placement to minimize valve noise on trumpet.", "Explaining to a player how valve noise reaches the mic."]}, "9b20c6a7-bf04-4b0d-8d66-12785a5a8ba3": {"definition": "Wash is a broad, sustained, undamped blend of overlapping sound with no clear pitch or transient focus, typically the ringing spread of open cymbals or a diffuse reverb tail, heard as a continuous, blurry layer of energy rather than as distinct notes.", "plain_english": "Wash is a wide, blurry cloud of sound that keeps ringing, like crash cymbals or heavy echo smearing together. You hear one smooth haze instead of separate notes.", "purpose_function": "Naming wash helps a technician spot when sustained, undamped sound is filling space and possibly masking detail in a mix.", "practical_application": "An engineer hearing too much wash may dampen cymbals, shorten a reverb tail, or gate tracks to restore clarity.", "category": "Resonance", "related_terms": ["Cymbal wash", "Reverb tail", "Sustain", "Decay", "Masking", "Overtone ring"], "common_mistakes": ["Mistaking a reverb wash for a problem with the source instrument.", "Adding more reverb to fix a thin mix and turning it into a muddy wash.", "Letting cymbal wash build up until it masks the vocals."], "scenario_contexts": ["A drummer rides open cymbals, filling the mix with wash.", "Shortening a reverb tail to cut excess wash on a vocal.", "Gating room mics to control drum wash."]}, "62b5fb2b-4698-4166-8c1e-0fbfb3fa27e6": {"definition": "The bright, shimmering, chiming timbre of a twelve-string guitar, arising because its strings are arranged in six courses of two: the lower four courses pair the main string with one tuned an octave higher, and the upper two courses are paired in unison. Small, unavoidable differences in tuning, phase and decay between each paired string create a natural chorusing (beating) that gives the instrument its characteristic 'jangle.'", "plain_english": "A 12-string guitar pairs each string with a second one tuned the same or an octave up. The two strings are never quite in tune, so they shimmer and ring together. That bright, ringing sound is the jangle. It acts like a built-in chorus effect.", "purpose_function": "The doubled courses and their slight detuning are what set a twelve-string apart from a six-string, adding density and a lush, self-chorusing shimmer to chords and arpeggios. Understanding it explains why a 12-string sounds 'wide' without any effects pedal.", "practical_application": "A technician records or mics a 12-string knowing the paired strings already provide chorus, so added chorus/detune effects are used sparingly, and careful tuning of each course is critical to keep the jangle sweet rather than sour.", "category": "Guitar tone", "related_terms": ["Chorus effect", "Course (paired strings)", "Beating", "Comb filtering", "Rickenbacker 12-string", "Arpeggio"], "common_mistakes": ["Adding a heavy chorus pedal on top of a 12-string, muddying the natural jangle instead of enhancing it.", "Tuning only the main strings and ignoring the octave strings, so the courses beat harshly and sound out of tune.", "Assuming a stereo double-track will sound the same as a real 12-string; the fixed octave pairing is what creates the effect."], "scenario_contexts": ["Tracking a jangly rhythm part on a Rickenbacker or Byrds-style pop record.", "Miking an acoustic 12-string for a folk session where the shimmer must stay clean.", "Tuning a 12-string before a take so each octave course rings in tune."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"50eb0998-dd33-4187-b2b2-8b12d4ef347f": {"definition": "A sustained, self-reinforcing oscillation, typically a low-frequency howl, that occurs when an amplified or miked acoustic guitar's hollow body is re-excited at its main air-cavity (Helmholtz) resonance by sound arriving from loudspeakers or stage monitors, closing an acoustic feedback loop through the sound system.", "plain_english": "When an amplified acoustic guitar sits in front of a speaker, sound from the speaker can shake its hollow body. The body rings back, the speaker makes it louder, and the sound builds into a loud howl. This runaway loop is called feedback.", "purpose_function": "Recognizing acoustic-guitar feedback matters because the guitar's body resonance makes it feed back far more easily than a solid-body electric, so controlling it is essential to reaching usable stage volume without a constant howl.", "practical_application": "A technician fights it by fitting a soundhole cover, notching the offending resonant frequency (often around 90-110 Hz) with EQ, keeping the guitar out of monitor beams, and lowering overall stage level.", "category": "Live sound issue", "related_terms": ["Acoustic feedback", "Helmholtz resonance", "Soundhole cover", "Notch filter", "Stage monitor", "Piezo pickup"], "common_mistakes": ["UNSAFE: Cranking monitors or the PA to overcome feedback, risking loudspeaker/tweeter damage and hearing injury from the sudden howl.", "Rolling off all the low end to stop feedback and leaving the guitar thin, instead of notching the single resonant frequency.", "Pointing the guitar's soundhole straight at a wedge monitor, which excites the body resonance directly."], "scenario_contexts": ["A singer-songwriter's amplified dreadnought howls at low volume on a small stage.", "Soundcheck where a piezo-equipped acoustic feeds back as monitor level is raised.", "A loud band setting where the acoustic guitarist stands close to a floor wedge."]}, "9a6fee10-96ec-4ea1-a4bf-9644d13c3159": {"definition": "The sharp, percussive component of a shamisen note produced when the string is struck with the bachi, a large plectrum whose downward stroke drives the string onto, and strikes, the skin-covered body (kawa). Prominent in tsugaru-jamisen playing, it adds a drum-like 'slap' transient to the pitched tone.", "plain_english": "The shamisen is a Japanese string instrument played with a big pick called a bachi. The player strikes the string and the skin-covered body at the same time. This adds a sharp, drum-like slap to the front of each note.", "purpose_function": "The slap-attack is central to the driving, percussive style of tsugaru-jamisen, giving each note a strong rhythmic punch that carries a melody and a beat at once. It exists because the bachi hits the skin as well as the string.", "practical_application": "When recording shamisen, a technician expects a loud transient 'thwack' from the bachi hitting the skin and sets levels with extra headroom, often close-miking to catch both the string tone and the percussive slap.", "category": "Playing technique", "related_terms": ["Bachi (plectrum)", "Shamisen", "Tsugaru-jamisen", "Transient", "Percussive attack", "Kawa (skin head)"], "common_mistakes": ["Treating the slap 'thwack' as unwanted noise and gating or EQ-ing it out, removing the sound that defines the style.", "Setting record levels too hot and clipping on the sharp bachi transient.", "Confusing the bachi with a small guitar pick; it is a large, fan-shaped plectrum that also strikes the body."], "scenario_contexts": ["Recording a solo tsugaru-jamisen performance with strong percussive attacks.", "Miking a shamisen in a fusion band where the slap must cut through a drum kit.", "Balancing a traditional Japanese ensemble where the shamisen's attack marks the rhythm."]}, "519ef69c-a78a-4983-b155-e68494986d0f": {"definition": "The rapid, rattling strummed sound characteristic of balalaika right-hand technique, in which the index finger (or the whole hand) brushes the strings in rapid up-and-down strokes, producing a continuous, tremolo-like 'brrr' across the strings.", "plain_english": "The balalaika is a Russian instrument with a triangle-shaped body. Players brush the strings fast with one finger, going back and forth. This makes a quick rattling 'brrr' sound, a bit like a drum roll on strings.", "purpose_function": "This rattling strum lets a small, short-sustaining instrument hold long chords and drive a fast dance rhythm, since rapid repeated strokes fill in the sound the way a tremolo does on a mandolin.", "practical_application": "A technician miking a balalaika expects bursts of fast, bright transients from the strum and positions the mic to capture the rattle clearly without the picking hand overloading the input.", "category": "Playing technique", "related_terms": ["Balalaika", "Tremolo", "Strumming", "Rasgueado", "Transient"], "common_mistakes": ["Mistaking the fast rattle for a recording fault or buzz and trying to 'clean' it out.", "Miking too close so the rapid strokes sound clacky and lose the instrument's body tone.", "Assuming a single slow strum can imitate the sustained 'brrr'; it needs continuous rapid strokes."], "scenario_contexts": ["Recording a Russian folk ensemble where the balalaika drives the rhythm with fast strumming.", "Miking a solo balalaika holding a long, rattling chord under a melody.", "Blending a balalaika into a film score cue that needs a driving folk texture."]}, "a44f8704-132e-402b-b6cc-8a4eea1a5deb": {"definition": "A sustained, self-reinforcing oscillation on an amplified or miked banjo in which sound from loudspeakers or monitors re-excites the tensioned drum-like head (membrane) and pot at their resonant frequencies, closing an acoustic feedback loop; the responsive membrane also makes the banjo prone to sympathetic ringing on stage.", "plain_english": "A banjo has a tight, drum-like head. On a loud stage, sound from the speakers can make that head ring on its own. The speaker feeds it back louder until it turns into a howl or ring. This runaway loop is called feedback.", "purpose_function": "Understanding banjo feedback matters because the drum head reacts strongly to stage sound, so a banjo can howl or ring uncontrollably before other instruments do, and controlling it protects both the mix and the gear.", "practical_application": "A technician tames it by notching the resonant frequency with EQ, keeping the banjo head out of monitor and PA beams, muting the head lightly, and lowering stage volume rather than chasing gain.", "category": "Live sound issue", "related_terms": ["Acoustic feedback", "Banjo head", "Notch filter", "Stage monitor", "Sympathetic resonance", "Piezo pickup"], "common_mistakes": ["UNSAFE: Pushing PA or monitor gain to fight the ring, risking loudspeaker damage and hearing harm from a sudden loud howl.", "Blaming the pickup when the untamed drum head is the resonating source.", "Aiming the banjo head straight at a wedge monitor, exciting the membrane directly."], "scenario_contexts": ["A bluegrass band on a small stage where the amplified banjo rings between songs.", "Soundcheck where the banjo howls as monitor level is raised.", "A loud festival set with the banjo standing close to front-of-house speakers."]}, "3b890ddd-e2aa-45b1-835e-2bf9ce7db442": {"definition": "The bright, sharp, bell-like attack of individual notes within a bluegrass banjo roll, a Scruggs-style three-finger pattern of arpeggiated, syncopated eighth notes, produced by picking with metal fingerpicks on a resonator banjo whose short sustain and strong high-frequency content make each plucked note 'ping.'", "plain_english": "In bluegrass, banjo players pick fast, repeating patterns called rolls. Metal finger picks and the bright banjo make each note snap out clearly and quickly fade. That sharp, bell-like note is the 'ping.'", "purpose_function": "The ping is what makes a banjo roll sound crisp and rhythmic rather than blurred; each note stands out because the banjo has little sustain and lots of high end, which is why rolls sound so distinct.", "practical_application": "When recording bluegrass banjo, a technician places the mic to catch the bright ping without harshness and avoids heavy compression that would kill the attack and even out the roll's bounce.", "category": "Playing technique", "related_terms": ["Banjo roll", "Scruggs style", "Fingerpicks", "Resonator banjo", "Transient", "Arpeggio"], "common_mistakes": ["Compressing the banjo hard and squashing the ping, so the roll loses its snap and drive.", "Rolling off all the highs to reduce harshness and dulling the ping that defines the tone.", "Confusing the right-hand roll pattern with the resulting 'ping' attack; the roll is the pattern, the ping is each note's sound."], "scenario_contexts": ["Tracking a fast bluegrass banjo break that must sit crisply over guitar and bass.", "Miking a resonator banjo so each rolled note pings clearly in a mix.", "Mixing a banjo roll where the engineer preserves the attack for rhythmic drive."]}, "8908d725-5f2d-4261-871d-9ee78f612316": {"definition": "The incidental scraping or friction noise made by the steel bar (or slide) as it moves along the strings of a lap-steel, pedal-steel, resonator or slide guitar; a mechanical, unpitched sound distinct from the notes being played, often captured by close mics or magnetic pickups.", "plain_english": "Steel guitar players slide a smooth metal bar along the strings to change notes. The bar can scrape or squeak as it moves. That extra scraping sound, separate from the note, is called bar noise.", "purpose_function": "Some bar noise is a natural, expressive part of steel and slide playing, but too much becomes distracting, so knowing its source lets a player or engineer keep the wanted character while controlling the rest.", "practical_application": "A technician reduces excess bar noise by advising lighter bar pressure and wound-string care, and by using EQ or careful editing to tame the scrape without dulling the slide's natural glide.", "category": "Playing artifact", "related_terms": ["Steel guitar", "Slide guitar", "Tone bar", "String squeak", "Palm muting", "Pickup"], "common_mistakes": ["Treating all bar noise as a fault; a little is part of the authentic slide sound.", "Pressing the bar too hard, which increases scraping and can also pull notes sharp.", "Trying to fix heavy bar noise only with EQ instead of correcting technique at the source."], "scenario_contexts": ["Recording a pedal-steel overdub where excess bar scrape distracts from the melody.", "Miking a bottleneck slide guitar that has expressive but noisy bar moves.", "Editing a lap-steel take to reduce squeaks between slides."]}, "5da7d099-5d51-488c-9ac2-81a4fc3c80d0": {"definition": "Vibrato on a steel guitar produced by rocking or oscillating the hand-held steel bar back and forth along the string's length over a stopped note, cyclically raising and lowering the pitch around the target pitch, rather than by bending or fretting the string.", "plain_english": "On a steel guitar, the player holds a metal bar on the strings instead of pressing frets. Rocking the bar back and forth makes the pitch wobble a little above and below the note. That gentle, singing wobble is bar vibrato.", "purpose_function": "Bar vibrato gives the steel guitar its vocal, crying, sustained quality, adding warmth and expression to long notes much as a singer's vibrato does, and it is a core part of the instrument's identity.", "practical_application": "An engineer recording steel guitar preserves the natural pitch movement of bar vibrato and avoids pitch-correction tools that would fight it, while a player varies its width and speed to shape a phrase.", "category": "Playing technique", "related_terms": ["Steel guitar", "Tone bar", "Vibrato", "Pitch bend", "Portamento", "Sustain"], "common_mistakes": ["Confusing bar vibrato with a whammy-bar wobble on an electric guitar; here the pitch changes by moving the bar on the string.", "Applying automatic pitch correction that flattens the intentional pitch movement.", "Rocking the bar too wide or too fast so the note sounds unstable rather than singing."], "scenario_contexts": ["Recording a pedal-steel ballad part where sustained notes need expressive vibrato.", "Miking a lap-steel solo that relies on bar vibrato for its vocal quality.", "Mixing a country track and choosing not to pitch-correct the steel's vibrato."]}, "0cc54f0b-170d-4afe-a067-d880b48f9dc7": {"definition": "The percussive, metallic 'clank' produced on a bass guitar (or double bass) when the vibrating strings strike the frets or fingerboard, resulting from hard plucking, slapping and popping, or low string action, and adding a sharp attack transient on top of the fundamental note.", "plain_english": "On a bass, the thick strings can smack against the metal frets. This happens with hard picking, slapping, or very low string height. It makes a hard, metallic 'clank' along with the note.", "purpose_function": "A controlled amount of clank adds attack and definition that helps a bass cut through a dense mix, but excess clank buries the pitch, so understanding its cause lets a player or tech dial in the right balance.", "practical_application": "A technician manages clank by adjusting string action and relief on the bass, changing pluck strength or hand position, and using EQ or gentle compression to keep the click without losing the low fundamental.", "category": "Playing artifact", "related_terms": ["Slap bass", "Fret buzz", "String action", "Attack transient", "Neck relief", "Compression"], "common_mistakes": ["Setting the action so low that the strings clank on every note instead of only when intended.", "Trying to remove clank entirely with EQ and leaving the bass dull and lost in the mix.", "Confusing musical slap clank with a genuine fret-buzz fault caused by bad setup."], "scenario_contexts": ["Recording a funk slap-bass line where controlled clank gives the groove its snap.", "Setting up a bass so it stops clanking unintentionally on softer passages.", "Mixing a rock track and shaping the bass attack so it drives without excess click."]}, "d049c27c-1044-434e-96bd-d4d2ad2bc30c": {"definition": "An unwanted turbulent-airflow noise, often called port chuffing, emitted from the vent of a bass-reflex (ported) loudspeaker or instrument cabinet when high-excursion, low-frequency signals drive air through the port fast enough to become turbulent, adding a breathy huffing or whistling sound to the low end.", "plain_english": "It is a huffing or whistling noise from the hole, called a port, in a speaker box. When loud, deep notes push air through that hole too fast, the air turns choppy and you hear a breathy sound.", "purpose_function": "Recognizing it tells a technician the port is moving air too fast, so the cure is a larger or flared port, less level, or a sealed design, rather than blaming the driver.", "practical_application": "A tech hearing a huff on deep bass notes checks the port's air velocity, flares or enlarges the vent, or lowers output so the port stops chuffing.", "category": "Enclosure artifact", "related_terms": ["Bass reflex", "Port tuning", "Cone excursion", "Distortion", "Subwoofer"], "common_mistakes": ["Mistaking port chuffing for a blown or distorting driver.", "Fitting a port that is too small in diameter for the air it must move.", "Ignoring how higher output raises port air velocity and triggers the noise."], "scenario_contexts": ["A ported subwoofer huffing on sustained low notes at high level.", "A bass guitar cabinet whistling at its tuning frequency when pushed hard.", "Choosing a flared port to cut chuffing while designing a cabinet."]}, "883711fd-6684-481a-b1d9-495df9787f64": {"definition": "On the bağlama (Turkish long-necked lute), a fast melodic ornament (trill) rapidly alternating a note with an adjacent one, played within the plectrum-free şelpe fingerstyle technique, in which the right-hand fingers tap, strum, and pluck the strings directly instead of using a pick.", "plain_english": "A fast wobble between two close notes on the bağlama, a Turkish long-necked lute. It is played in the şelpe style, where the fingers tap and pluck the strings instead of using a pick.", "purpose_function": "It adds quick, decorative movement and a percussive, ringing character to a melody, and the şelpe hand gives the player fast fingered ornaments a pick cannot easily make.", "practical_application": "An engineer recording bağlama expects bright finger taps and rapid trills, and uses a close mic with enough headroom to catch the percussive attacks cleanly.", "category": "String articulation", "related_terms": ["Trill", "Ornament", "Hammer-on", "Tremolo", "Fingerstyle"], "common_mistakes": ["Assuming the bağlama is always played with a pick and missing the fingerstyle şelpe attacks.", "Confusing a trill with a slower tremolo repeated on one note.", "Compressing or gating so hard that quiet finger taps disappear."], "scenario_contexts": ["Close-miking a bağlama solo full of fast trills and finger taps.", "Editing a Turkish folk take and recognizing şelpe finger noise as intended.", "Setting levels for the bright, percussive attacks of şelpe playing."]}, "8dc59c5c-503d-421d-89a2-901dd6e62b0a": {"definition": "A high-pitched friction noise produced when a glass or metal slide (bottleneck) is dragged along the wound strings of a guitar, as the slide scrapes across the strings' spiral winding; a form of string squeak specific to slide (bottleneck) playing.", "plain_english": "A squeaky scrape you hear when a slide moves along the guitar strings. The slide rubs over the ridged, wound strings and makes a high, squeaky noise, much like a finger sliding on strings.", "purpose_function": "As a listening cue it marks slide movement between notes; some players keep it for feel, while engineers judge whether it adds character or distracts.", "practical_application": "An engineer recording slide guitar decides whether to keep the squeak for feel or reduce it with a lighter touch, flatwound strings, or gentle EQ.", "category": "Playing artifact", "related_terms": ["String squeak", "Slide guitar", "Fret noise", "Wound string", "Glissando"], "common_mistakes": ["Treating every slide squeak as a fault when it is often part of the style.", "Blaming the pickup or amp for a noise the slide-on-string friction makes.", "Using harsh de-essing that dulls the guitar tone while chasing the squeak."], "scenario_contexts": ["Tracking a blues slide solo and capturing bottleneck squeaks.", "Deciding whether to edit out slide noise between phrases.", "Switching to flatwound strings to reduce slide friction noise."]}, "b7ccf105-5ecc-4ef8-948c-6fe2051b6680": {"definition": "The bright, shimmering high-register character of a strummed charango, a small Andean lute with five double courses tuned in a high, partly re-entrant pattern, whose closely spaced high strings and small body produce a sparkling, jangly wash when strummed.", "plain_english": "The bright, sparkly sound of strumming a charango, a small Andean lute. Its short doubled strings are tuned high, so a strum rings out light and glittery, like tiny bells.", "purpose_function": "This sparkle is the charango's signature voice, adding shimmer and rhythmic drive high above guitars and bass in Andean music.", "practical_application": "An engineer miking a charango captures its bright top end, then in the mix carves space so the sparkle sits above the guitar without clashing or sounding harsh.", "category": "Tonal character", "related_terms": ["Course (strings)", "Re-entrant tuning", "Strum", "Timbre", "Air band"], "common_mistakes": ["Boosting high EQ until the sparkle turns harsh and brittle.", "Treating the charango like a guitar and missing its high, doubled-string tuning.", "Letting the sparkle mask the vocals or guitars instead of blending it in."], "scenario_contexts": ["Recording an Andean group and placing the charango's sparkle above the guitar.", "Mixing a bright strummed charango so it cuts through without harshness.", "Choosing mic position to balance body warmth against string sparkle."]}, "03223c6b-6158-436f-8d84-4d80a6142b90": {"definition": "The bright, high-pitched plucked accent of the sitar's chikari strings, a pair of thin drone/rhythm strings tuned high (often to the tonic an octave or more up) and struck with the little finger of the plucking hand to punctuate rhythm, especially in the fast jhala section.", "plain_english": "A bright, high ping from the sitar's thin drone strings. The player flicks them with the little finger to mark the beat, adding a ringing sparkle over the main tune.", "purpose_function": "The chikari ping provides rhythmic drive and a constant high drone, marking the pulse and energizing fast passages on the sitar.", "practical_application": "An engineer recording sitar expects sharp high-frequency pings between melody notes and leaves headroom and picks mic placement so these transients stay clean and are not clipped.", "category": "String articulation", "related_terms": ["Drone string", "Sympathetic strings", "Jhala", "Transient", "Sitar"], "common_mistakes": ["Confusing the chikari drone strings with the sitar's sympathetic (tarab) strings.", "Setting gain with no headroom for the sharp ping transients.", "Gating too tightly and clipping off the ringing drone."], "scenario_contexts": ["Miking a sitar and capturing crisp chikari pings in a jhala section.", "Balancing the high drone against the melody strings in a mix.", "Identifying the rhythmic ping as chikari rather than a sympathetic-string ring."]}, "eb4e7cf6-7824-4944-880c-8cc00d8ef742": {"definition": "A sustained tone on the cimbalom, a large Hungarian hammered dulcimer, produced by a rapid tremolo that quickly alternates the two beaters on a string or course to overcome the instrument's natural decay and hold a note or shimmering swell.", "plain_english": "A long, shimmering note on the cimbalom, a large hammered dulcimer. The player taps a string very fast with two beaters so the sound keeps ringing instead of fading away.", "purpose_function": "Because struck strings die away quickly, the roll lets the player sustain notes and shape crescendos, giving the cimbalom a singing, tremolando voice.", "practical_application": "An engineer recording a cimbalom roll captures a dense, sustained tremolo and rides the build in level so the swell neither overloads nor loses its shimmer.", "category": "Playing technique", "related_terms": ["Tremolo", "Sustain", "Hammered dulcimer", "Decay", "Crescendo"], "common_mistakes": ["Expecting a single struck note to sustain like a bowed string.", "Compressing a roll so hard that its natural swell flattens out.", "Confusing the fast roll with a slow, measured tremolo."], "scenario_contexts": ["Recording a cimbalom holding a long rolled note in a folk piece.", "Capturing a rolled crescendo without clipping the peak.", "Identifying a sustained cimbalom tone as a two-beater roll."]}, "1ad40209-19d2-4836-8030-f6c58dbbaafc": {"definition": "The strong, percussive downstroke accent of clawhammer (frailing) banjo, a plectrum-free style in which the back of a fingernail strikes down across the strings while the thumb sounds the fifth (drone) string, producing the driving 'bum-ditty' rhythm; the thump is that firm downbeat strike.", "plain_english": "The hard, driving downbeat of clawhammer banjo, also called frailing. The player brushes down with the back of a fingernail and plucks the short drone string with the thumb, giving a punchy thump.", "purpose_function": "The thump supplies the strong rhythmic pulse and percussive drive of old-time banjo, letting one player sound both a melody and a steady beat.", "practical_application": "An engineer recording clawhammer banjo captures a punchy, percussive attack and sets compression and mic position so the driving downstroke stays tight without swamping the melody.", "category": "Playing technique", "related_terms": ["Drone string", "Downstroke", "Frailing", "Attack transient", "Banjo"], "common_mistakes": ["Confusing clawhammer's downstroke frailing with three-finger bluegrass picking.", "Compressing so hard that the percussive thump loses its punch.", "Missing the thumb's fifth-string drone that drives the rhythm."], "scenario_contexts": ["Recording an old-time banjo player frailing a tune.", "Setting mic and compression for a punchy clawhammer downbeat.", "Telling clawhammer's rhythmic thump apart from bluegrass roll picking."]}, "b4cad57d-9dec-4682-88ba-af5f6026f9d5": {"definition": "The intentional use of acoustic feedback, a self-sustaining loop in which sound from the amplifier's loudspeaker vibrates the electric guitar's strings and the pickup re-amplifies that motion, to sustain or swell a note or harmonic, shaped by the player through guitar position, volume, and pickup choice.", "plain_english": "This is guitar feedback used on purpose. Loud sound from the amp shakes the strings, the pickup sends it back to the amp, and the note keeps ringing. The player aims the guitar to hold and shape it.", "purpose_function": "It lets a guitarist sustain notes far longer than a plucked string naturally allows and produce singing, howling swells for expressive lead playing.", "practical_application": "A guitarist stands near the amp and adjusts volume, angle, and distance to coax a sustained feedback note, while a live engineer manages stage level so only the wanted feedback sounds.", "category": "Playing technique", "related_terms": ["Acoustic feedback", "Sustain", "Larsen effect", "Gain", "Resonance"], "common_mistakes": ["UNSAFE: Cranking stage or monitor level to force feedback, risking hearing damage and a runaway howl through the PA; keep exposure within safe limits and control it at the guitar rig instead.", "Confusing wanted musical feedback with an uncontrolled PA feedback squeal.", "Expecting the same feedback note at every stage volume and guitar position."], "scenario_contexts": ["A lead guitarist holding a sustained feedback note at the end of a solo.", "Setting up an amp and guitar to get feedback at a manageable stage volume.", "A live engineer keeping controlled guitar feedback from triggering PA feedback."]}, "2588a01d-fe72-4cf0-9e3c-75d57988abfe": {"definition": "The core sounding technique of the đàn bầu (Vietnamese single-string zither), in which the player plucks the string while lightly touching it at a harmonic node so only a flageolet (harmonic) tone sounds, giving a pure, flute-like note whose pitch is then bent with the flexible rod that anchors the string.", "plain_english": "The way the đàn bầu, a Vietnamese one-string instrument, is played. The player plucks the string while lightly touching a special spot, so only a soft, pure tone rings out, like a whistle.", "purpose_function": "Playing only harmonics gives the đàn bầu its pure, vocal, flute-like voice, and the bending rod lets one string produce a full, sliding melody.", "practical_application": "An engineer recording đàn bầu captures a quiet, pure harmonic tone with wide pitch bends, using a close pickup or mic and careful gain for its low output and soft attacks.", "category": "String articulation", "related_terms": ["Harmonic", "Flageolet", "Node", "Pitch bend", "Monochord"], "common_mistakes": ["Expecting a normal plucked-string tone rather than a pure harmonic.", "Setting gain too low for the instrument's soft, quiet output.", "Missing that pitch is bent by the flexible rod, not by fretting."], "scenario_contexts": ["Recording a đàn bầu melody full of sliding harmonic notes.", "Setting gain and mic placement for its soft, pure harmonics.", "Identifying the flute-like tone as a plucked harmonic, not a bowed note."]}, "c598f20f-597e-44b7-8fe7-31d34645a53a": {"definition": "On the Vietnamese dan bau, a single-string monochord, the technique of flexing the instrument's whippy rod (can dan), to which the string is anchored, to raise or lower the pitch of a plucked harmonic and add vibrato, glissando, or expressive pitch bends.", "plain_english": "The dan bau is a Vietnamese one-string instrument. A bendy rod holds the string. The player pushes or pulls this rod to slide the note up or down, a bit like a guitar whammy bar.", "purpose_function": "It lets a single string produce a wide, smooth range of pitches and expressive inflections, giving the dan bau its speech-like, sliding voice from just plucked harmonics.", "practical_application": "A player sounds a harmonic on the open string, then works the flexible rod with the picking hand to bend into the target pitch, add vibrato, or connect notes with slides.", "category": "Playing technique", "related_terms": ["Portamento", "Vibrato", "Harmonic", "Glissando", "Pitch bend"], "common_mistakes": ["Thinking the dan bau is fretted or stopped like a guitar, when its pitch comes mainly from harmonics plus rod bending.", "Over-flexing the rod so notes overshoot the intended pitch.", "Confusing the rod bend, which changes pitch, with a guitar tremolo effect that changes volume."], "scenario_contexts": ["Performing traditional Vietnamese melodies that imitate the sliding contours of the spoken language.", "Recording dan bau for a film score and capturing its expressive pitch bends.", "Amplifying a modern pickup-equipped dan bau in a live ensemble."]}, "493cf423-89ec-464b-ab6d-bad151ffbeda": {"definition": "A right-hand technique on the domra, a round-bodied Russian plucked lute, in which the plectrum rapidly alternates down-and-up strokes on a string to sustain an otherwise quickly decaying plucked tone into a continuous, singing line.", "plain_english": "The domra is a round Russian string instrument played with a pick. Its plucked notes fade fast. So the player flicks the pick up and down very quickly to hold a note out and make it sing.", "purpose_function": "It overcomes the short natural decay of a plucked string, letting the domra play smooth, sustained melodies and long held notes much like a bowed instrument.", "practical_application": "A domra player uses steady tremolo for lyrical passages and long notes, switching to single strokes for faster, detached figures.", "category": "Playing technique", "related_terms": ["Tremolo", "Plectrum", "Sustain", "Balalaika", "Mandolin"], "common_mistakes": ["Playing tremolo unevenly, so the note pulses instead of sounding smooth.", "Gripping the plectrum too tightly, which tires the hand and roughens the tremolo.", "Confusing this continuous tremolo with a measured, notated tremolo rhythm."], "scenario_contexts": ["Playing a slow, singing melody in a Russian folk orchestra.", "Sustaining a long held note that a single pluck could not carry.", "Blending domra with balalaika in an ensemble arrangement."]}, "78f51ff2-a611-492f-a43d-a8a1500e9cd9": {"definition": "On the hurdy-gurdy, the continuous, organ-like sustain produced when the hand-cranked rosined wheel acts as a rotating bow, keeping the drone (bourdon) strings, and the melody strings, in steady vibration for as long as the wheel turns.", "plain_english": "A hurdy-gurdy has a spinning wheel turned by a crank. The wheel rubs the strings like a never-ending bow. This keeps the drone strings humming steadily, so the sound never stops while you crank.", "purpose_function": "The turning wheel replaces a bow, so the instrument can hold unbroken drones and melody notes indefinitely, giving the hurdy-gurdy its steady, bagpipe-like backdrop.", "practical_application": "A player keeps the crank turning at an even speed to sustain the drones, adjusting cotton and rosin on the wheel to control tone and volume.", "category": "Playing technique", "related_terms": ["Drone", "Bourdon", "Rosin", "Sustain", "Sympathetic resonance"], "common_mistakes": ["Cranking unevenly, which makes the drone wobble in pitch and volume.", "Neglecting to rosin or cotton the wheel, causing a weak or scratchy tone.", "Assuming the drone strings are plucked rather than bowed by the wheel."], "scenario_contexts": ["Providing a steady drone under a dance tune in European folk music.", "Setting up a hurdy-gurdy by adjusting wheel rosin for even sustain.", "Recording the instrument's continuous drone as a bed for other parts."]}, "b9fd143e-83e9-49d5-9635-2c728e095aec": {"definition": "Unwanted electrical noise, harmonically richer and edgier than smooth power-line hum, induced in an electric instrument's pickups and high-impedance wiring by capacitive (electrostatic) coupling to nearby alternating-current fields such as light dimmers, fluorescent ballasts, and displays; it typically drops when the player touches the grounded strings.", "plain_english": "This is a harsh electrical buzz in an electric guitar. Nearby power wiring and lights leak their electric field into the pickups. Touching the metal strings often makes it fade, because your body helps send the noise to ground.", "purpose_function": "Recognizing it as electrostatic (capacitive) noise rather than magnetic hum tells a technician to fix it with shielding and proper grounding instead of just repositioning the instrument.", "practical_application": "A tech reduces it by shielding the guitar's control and pickup cavities with grounded conductive foil, confirming the bridge-to-string ground, and moving away from dimmers or fluorescent fixtures.", "category": "Electrical noise", "related_terms": ["Hum", "Shielding", "Grounding", "Single-coil pickup", "Electromagnetic interference"], "common_mistakes": ["Confusing electrostatic buzz with magnetic hum, which shielding alone will not fix.", "UNSAFE: Lifting the mains earth/ground pin to chase the buzz, which defeats safety grounding and can leave a chassis live and lethal.", "Assuming humbucking pickups remove all buzz, when capacitively coupled noise still needs shielding and grounding."], "scenario_contexts": ["A single-coil guitar buzzing on a stage lit by dimmer packs.", "Recording near a computer monitor or fluorescent light and hearing edgy buzz.", "Shielding a guitar's cavities to cure buzz that touching the strings reduces."]}, "707a845d-c61a-4d6d-86a3-44a466bb5572": {"definition": "A programmatic sound effect on the erhu, the Chinese two-string bowed fiddle, in which fast, oscillating finger slides combined with firm bow pressure imitate the neighing or whinnying of a horse; it is most famous from the closing passage of the solo piece 'Horse Racing' (Sai ma).", "plain_english": "The erhu is a Chinese two-string fiddle. By sliding the fingers fast up and down while bowing hard, the player can make it sound like a horse neighing. This trick is famous in the piece 'Horse Racing.'", "purpose_function": "It showcases the erhu's strong power to imitate voices and animal sounds, adding drama and a vivid picture to descriptive, programmatic pieces.", "practical_application": "A player produces it with quick back-and-forth finger slides and firm bowing near the end of 'Horse Racing' to mimic a whinnying horse.", "category": "Playing technique", "related_terms": ["Portamento", "Glissando", "Vibrato", "Bowing", "Tremolo"], "common_mistakes": ["Sliding too slowly, so the effect sounds like a plain glissando instead of a whinny.", "Using too little bow pressure, which weakens the braying, vocal quality.", "Treating it as fixed notes rather than a free, imitative gesture."], "scenario_contexts": ["Performing the finale of 'Horse Racing' in a recital.", "Scoring an erhu part that needs an animal or vocal imitation.", "Teaching students expressive glissando control through the whinny effect."]}, "3e6dd299-f638-4966-b07c-0082c030a136": {"definition": "The smooth, continuous slide in pitch between two notes on the fretless erhu, produced by moving a stopping finger along the string while bowing; it is a central expressive device that gives erhu melody its vocal, speech-like inflection.", "plain_english": "The erhu has no frets, so the finger can slide along the string. This makes the note glide smoothly from one pitch to the next. It gives the erhu its crying, voice-like sound.", "purpose_function": "Portamento lets the erhu bend and connect notes like a singing voice, carrying much of the emotion and regional style of the music.", "practical_application": "A player controls the speed and width of the slide with the left hand to shape phrases, imitate vocal ornaments, or match a regional style.", "category": "Playing technique", "related_terms": ["Glissando", "Vibrato", "Fingering", "Bowing", "Huqin"], "common_mistakes": ["Sliding on every note, which makes playing sound sloppy rather than expressive.", "Rushing the slide so it loses its smooth, vocal shape.", "Confusing portamento, a connecting slide, with vibrato, a small pitch wobble."], "scenario_contexts": ["Shaping a lyrical erhu melody to sound like a human voice.", "Matching the slides typical of a particular regional Chinese style.", "Connecting two widely spaced notes smoothly in a slow piece."]}, "47ea0a2e-b383-46a9-8e7b-09c0cdc0e83b": {"definition": "The shimmering, sustained resonance heard on the esraj and dilruba, North Indian bowed instruments, when their numerous under-strings (tarab), tuned to the notes of the raga, vibrate sympathetically in response to the bowed melody strings without being touched.", "plain_english": "The esraj and dilruba are Indian bowed instruments. Under the main strings sit many thin extra strings. When you bow a note, the matching extra strings hum on their own. This adds a soft, ringing halo around the sound.", "purpose_function": "The sympathetic strings enrich and sustain the tone, surrounding each bowed note with a resonant halo tuned to the raga, which reinforces the mode and adds depth.", "practical_application": "A player tunes the sympathetic strings to the current raga so they ring correctly, and uses mic placement or damping to balance that resonance in performance or recording.", "category": "Acoustic resonance", "related_terms": ["Sympathetic resonance", "Tarab", "Drone", "Sarangi", "Sustain"], "common_mistakes": ["Leaving the sympathetic strings out of tune, so their ringing clashes with the raga.", "Assuming the extra strings are bowed or plucked directly, when they sound on their own.", "Ignoring how strongly the sympathetic ring bleeds into a close microphone."], "scenario_contexts": ["Tuning the tarab strings to a raga before a Hindustani performance.", "Close-miking a dilruba and managing the wash of sympathetic resonance.", "Comparing the fuller ring of a dilruba with the lighter esraj."]}, "06da211b-7b1f-4727-b15c-a870d072d42a": {"definition": "On the five-string banjo, the sustained, unchanging note sounded by the short fifth (thumb) string, which runs only from a peg at the fifth fret to the bridge and is tuned to a high pitch (commonly g'); repeatedly struck by the thumb, it provides a constant drone above the melody.", "plain_english": "A five-string banjo has one short string that starts partway up the neck. It is tuned to a high note and is usually left open. The player's thumb keeps hitting it, so the same note rings again and again like a drone.", "purpose_function": "The fifth string adds a steady high drone that drives the rhythm and gives clawhammer and bluegrass banjo their characteristic rolling, ringing sound.", "practical_application": "A player sounds the open fifth string with the thumb on offbeats in rolls and frailing patterns, usually leaving it unfretted as a fixed drone.", "category": "Playing technique", "related_terms": ["Drone", "Open string", "Clawhammer", "Roll", "Capo"], "common_mistakes": ["Trying to fret the fifth string like the others, when it usually stays open as a drone.", "Changing key without spiking or capoing the fifth string, so the drone clashes.", "Overpowering the melody by striking the drone string too hard."], "scenario_contexts": ["Playing a bluegrass roll where the thumb keeps sounding the drone string.", "Frailing an old-time tune with a steady fifth-string drone.", "Using fifth-string spikes or a capo to change the drone's pitch for a new key."]}, "2d339430-2d1d-4d7f-860b-cef7e6be80d6": {"definition": "A percussive string technique in which the player pulls a string away from the fingerboard and releases it, or strikes it down, so it snaps back against the fingerboard and frets to produce a sharp click alongside the note; on the upright (double) bass it is the basis of rockabilly slap bass, and on electric bass it forms part of slap-and-pop playing.", "plain_english": "The player pulls a string and lets it snap back onto the fingerboard. This makes a sharp clicking sound along with the note. It adds a drum-like beat to the bass line, as heard in rockabilly.", "purpose_function": "It adds a built-in percussive click to each note, letting a bassist supply both the bass line and a drum-like rhythmic drive at once.", "practical_application": "An upright player slaps the strings against the fingerboard between notes for a rockabilly groove; an electric player combines thumb slaps and finger pops for funk.", "category": "Playing technique", "related_terms": ["Slap bass", "Pizzicato", "Pop", "Percussive attack", "Double bass"], "common_mistakes": ["Slapping so hard that the strings and fingerboard wear or the instrument is damaged.", "Letting the click drown out the pitch, so the bass line loses its note.", "Confusing upright slap with electric thumb-slap, which use different hand motions."], "scenario_contexts": ["Driving a rockabilly tune with slap on an amplified upright bass.", "Adding funk rhythm with slap-and-pop on electric bass.", "Miking or using a pickup on an upright to capture the slap click cleanly."]}, "66e3e14d-ba22-4e75-ad9f-041d2808d3df": {"definition": "A buzzing or rattling tone produced when a vibrating string on a fretted instrument makes unwanted contact with one or more frets instead of ringing cleanly. It typically results from low string action, too little or too much neck relief, or uneven and high frets.", "plain_english": "Fret buzz is the buzzy rattle you hear when a guitar string slaps against the metal frets instead of ringing out. It usually means the strings sit too low, or the neck or frets need a small setup fix.", "purpose_function": "It is a fault symptom rather than a feature; recognizing it tells a technician that the instrument's setup (action, neck relief, or fret height) needs adjustment before recording or performance.", "practical_application": "During a setup, a tech plays each note up the neck to find buzzing frets, then adjusts the truss rod, raises the saddle or bridge height, or levels and crowns high frets until the buzz clears.", "category": "Setup Defect", "related_terms": ["String action", "Neck relief", "Truss rod", "Fret leveling", "Fret noise"], "common_mistakes": ["Confusing fret buzz with an amp or pickup problem instead of a setup issue", "Cranking the truss rod hard to force the buzz away, which can bow or crack the neck", "Lowering action as far as it will go for comfort, then getting buzz across the whole neck"], "scenario_contexts": ["Setting up a new electric guitar so it plays cleanly across the whole neck", "Diagnosing a rattly note that shows up on a recorded DI guitar track", "Chasing buzz that appears after seasonal humidity moves the neck"]}, "522dd0cc-2932-453a-9261-a444290cd4ff": {"definition": "The incidental clicks, squeaks, and scrapes made by the fretting hand moving on the strings and frets of a guitar or bass, especially as fingers slide or shift position on wound strings. In sampling it is treated as a distinct articulation and appears in the General MIDI Level 1 sound set as program 121, 'Guitar Fret Noise.'", "plain_english": "Fret noise is the little squeak or scrape you hear when a player's fingers slide along the strings to change chords or notes. It is a normal part of guitar sound, and engineers can leave it in or clean it up.", "purpose_function": "It adds realism and human feel to guitar and bass parts, which is why sample libraries include it as a separate layer; identifying it lets an engineer decide whether to keep or reduce it.", "practical_application": "When editing a recorded acoustic guitar, an engineer may automate short volume dips or use de-noise tools to soften distracting finger squeaks between chords while keeping a natural feel.", "category": "Performance Noise", "related_terms": ["Fret buzz", "String squeak", "Fretless fingerboard noise", "Articulation", "De-noise"], "common_mistakes": ["Trying to remove all fret noise, which makes the guitar sound fake and lifeless", "Confusing fret noise (finger movement) with fret buzz (a setup fault)", "Boosting high frequencies heavily, which exaggerates the squeaks"], "scenario_contexts": ["Comping an acoustic guitar take where loud finger squeaks distract between phrases", "Programming a sampled guitar and adding fret-noise samples for realism", "Close-miking a wound-string bass that captures finger slides"]}, "1bdabc66-0508-4f78-9812-ee4f7add2c6a": {"definition": "The movement of the fretting hand from one fret position to another on a fretted string instrument, together with the connected sound of that shift, ranging from a smooth slide (glissando) to an audible finger scrape on wound strings. In sampled instruments it is commonly reproduced as a transition or legato sample linking two notes.", "plain_english": "A fret transition is when a guitarist's hand moves from one fret to another to reach a new note. The move can sound smooth like a slide, or add a small scrape as the fingers travel along the strings.", "purpose_function": "It links notes musically and shapes phrasing; capturing or modeling it convincingly is what makes sampled guitars and basses sound like a real player rather than a set of separate notes.", "practical_application": "A sound designer building a virtual guitar records slide and legato samples so that moving between notes triggers a natural transition instead of an abrupt note change.", "category": "Playing Technique", "related_terms": ["Legato", "Glissando", "Position shift", "Fret noise", "Articulation"], "common_mistakes": ["Treating every transition as a clean slide and ignoring the finger noise real players make", "Using one transition sample for all speeds, which sounds robotic", "Confusing a musical slide with unwanted fret buzz"], "scenario_contexts": ["Editing a solo where slide transitions need to feel smooth and in time", "Designing a sampled guitar patch that adds slide samples between held notes", "Notating a passage that calls for an audible position shift"]}, "5ae3a98f-003e-4ad4-8223-617ab8f0def4": {"definition": "The friction, scrape, and singing sounds produced on a fretless instrument (such as fretless bass, the violin family, or the oud) when a finger presses the string directly against the smooth fingerboard and slides between pitches, with no fret to break the contact. It includes the sustained gliding tone characteristic of fretless playing.", "plain_english": "On a fretless instrument there are no metal frets, so the finger presses the string straight onto the smooth board. When the player slides, you hear a smooth gliding or singing sound, and sometimes a soft scrape along the wood.", "purpose_function": "This noise is part of the expressive, vocal-like character players want from fretless instruments; knowing it is normal helps an engineer mic and mix it rather than treat it as a fault.", "practical_application": "Recording a fretless bass, an engineer sets mic placement and EQ to capture the singing slide tone while keeping harsh board scrapes under control.", "category": "Performance Noise", "related_terms": ["Fretless oud slide", "Fret noise", "Glissando", "Fingerboard", "String squeak"], "common_mistakes": ["Trying to remove the slide or gliding sound, which is the whole point of a fretless instrument", "Confusing normal fingerboard slide with a buzz or a defect", "Pressing too lightly, which gives weak, unclear notes instead of clean pitch"], "scenario_contexts": ["Recording a fretless bass solo that relies on smooth slides between notes", "Mixing a fretless part where board scrapes are too loud on close mics", "Sampling a fretless instrument and adding slide layers for realism"]}, "700628a2-3ad7-4149-82c1-ac7ec63aceb3": {"definition": "A glissando or portamento performed on the oud, whose fretless fingerboard lets a finger slide continuously between pitches, including the small microtonal intervals of Arabic and Turkish maqam. The absence of frets makes smooth, vocal-like slides a core expressive device of the instrument.", "plain_english": "The oud has no frets, so a player can slide a finger smoothly along the string to bend from one note to the next. This gliding move is a key part of the oud's singing, expressive sound in Middle Eastern music.", "purpose_function": "Sliding lets the oud reach the in-between (microtonal) notes of maqam scales and add vocal-like ornament, something fretted instruments cannot easily do.", "practical_application": "An engineer recording an oud keeps mic placement and EQ that preserve the smooth slides and finger detail without exaggerating string scrape.", "category": "Playing Technique", "related_terms": ["Oud", "Glissando", "Maqam", "Fretless fingerboard noise", "Microtonality"], "common_mistakes": ["Assuming the oud is fretted like a lute or guitar", "Editing out slides that carry the maqam's microtonal notes", "Pitch-correcting or quantizing an oud line and destroying its slides"], "scenario_contexts": ["Recording an oud solo in a world-music session", "Mixing a maqam piece where slides define the melody's character", "Sampling an oud and needing slide articulations for authenticity"]}, "cfcdcb22-e02d-48dd-909e-dfdd36b98163": {"definition": "The resonant ringing of the gadulka's sympathetic strings, a set of undamped strings mounted beneath the bowed melody strings of this Bulgarian pear-shaped bowed lute; they vibrate in sympathy when the melody strings sound, producing a shimmering halo around the played note.", "plain_english": "The gadulka is a Bulgarian bowed fiddle with extra strings that no one touches. When the player bows the main strings, these spare strings ring on their own. They add a soft, shimmering echo around the melody.", "purpose_function": "Sympathetic strings enrich and sustain the instrument's tone without being played directly, giving the gadulka its characteristic ringing, reverberant sound.", "practical_application": "When miking a gadulka, an engineer places the mic to capture both the bowed melody and the sympathetic ring, and avoids over-damping the instrument's body.", "category": "Resonance", "related_terms": ["Sympathetic strings", "Gadulka", "Resonance", "Drone", "Bowed string"], "common_mistakes": ["Thinking the extra strings are fingered and played like the melody strings", "Muting or damping the sympathetic strings and losing the instrument's signature ring", "Confusing the sympathetic ring with reverb added later in the mix"], "scenario_contexts": ["Recording a Bulgarian folk ensemble featuring gadulka", "Mixing a track where the sympathetic ring needs space to bloom", "Comparing gadulka to other sympathetic-string instruments such as sarangi or viola d'amore"]}, "981eb2f0-80d0-4bb5-9de1-aa9fcff805f2": {"definition": "Fan yin are the harmonic (flageolet) tones of the guqin, produced when a left-hand finger lightly touches a string at a nodal point marked by the inlaid hui studs while the right hand plucks, yielding clear, bell-like overtones. They form one of the three main tone categories of the guqin, alongside open-string (san yin) and stopped (an yin) tones.", "plain_english": "Floating harmonics are soft, bell-like notes on the Chinese guqin zither. The player rests a fingertip very lightly on the string, plucks, and lifts, so only a pure, ringing tone sounds. The notes seem to float above the music.", "purpose_function": "Harmonics give the guqin a pure, ethereal timbre used for special passages, and because they sound only at exact points on the string they also serve as position and tuning references.", "practical_application": "Recording solo guqin, an engineer uses a quiet room and a sensitive close mic to capture the delicate, low-level floating harmonics cleanly.", "category": "Playing Technique", "related_terms": ["Harmonic (flageolet)", "Nodal point", "Guqin", "Guqin slide squeak (zou yin)", "Overtone"], "common_mistakes": ["Pressing the string down instead of touching it lightly, which kills the harmonic", "Touching between the marked points, so no clear overtone sounds", "Setting record levels for loud notes and missing the very quiet harmonics"], "scenario_contexts": ["Recording a traditional guqin piece with harmonic passages", "Setting gain for a quiet solo instrument with wide dynamic range", "Studying string harmonics and their nodal positions"]}, "9a3de45d-2443-46d4-b5e5-03857ae4a5c1": {"definition": "The sliding-hand tone of the guqin (zou yin), the sustained gliding sound made when a left-hand finger presses a string after plucking and slides along it to new pitches, often with an audible friction squeak against the string. It is central to the guqin's expressive, speech-like melodic style rather than an unwanted noise.", "plain_english": "On the guqin, after plucking a string the player often slides a finger along it to move between notes. This makes a smooth gliding tone, and sometimes a light squeak as the finger rubs the string. It is a wanted, expressive part of the music.", "purpose_function": "Sliding tones connect notes and imitate the rise and fall of the human voice, giving the guqin its distinctive singing, expressive melodic lines.", "practical_application": "When recording guqin, an engineer decides how much of the natural slide friction to keep, capturing the expressive glides while avoiding overly harsh finger squeaks.", "category": "Playing Technique", "related_terms": ["Portamento", "Glissando", "Guqin floating harmonics (fan yin)", "Guqin", "Vibrato"], "common_mistakes": ["Treating the slide squeak as a mistake and editing it all out", "Confusing the expressive slide with a fault such as fret buzz", "Over-compressing the track, which pushes quiet slide sounds forward harshly"], "scenario_contexts": ["Recording a guqin performance rich in sliding tones", "Editing finger friction on a close-miked solo instrument", "Analyzing guqin melodic ornaments and slides"]}, "b9a8c15b-04df-4539-a714-a378c86e1e94": {"definition": "The rough, buzzing sustained tone of the gusle, a Balkan bowed instrument with one (rarely two) horsehair string bowed against a skin-bellied wooden body; its many-stranded string and sideways finger-stopping produce a raspy, penetrating drone that accompanies epic singing.", "plain_english": "The gusle is a Balkan folk instrument with a single thick horsehair string played with a bow. It makes a rough, buzzing, droning sound that backs a singer telling long epic stories. The scratchy tone is just what the instrument is meant to have.", "purpose_function": "The raspy drone provides a steady, speech-supporting backdrop for a solo epic singer, its rough timbre helping the voice cut through and carry the story.", "practical_application": "Recording a gusle, an engineer chooses a mic and placement that capture its raw, raspy character without harsh distortion, keeping voice and instrument balanced.", "category": "Timbre", "related_terms": ["Drone", "Bowed string", "Timbre", "Sympathetic strings", "Gadulka sympathetic ring"], "common_mistakes": ["Trying to make the gusle sound smooth and clean, removing its natural rasp", "Treating the buzzy tone as distortion that needs fixing", "Overpowering the singer, when the gusle should support the voice"], "scenario_contexts": ["Recording a Balkan guslar performing epic poetry", "Mixing voice and gusle so the story stays clear", "Documenting traditional single-string bowed instruments"]}, "e26bb1d8-7a01-4b13-8a91-d57dbd232366": {"definition": "A glissando or portamento made by sliding the stopping finger along a gut string so the sounding pitch moves continuously between two notes. On gut-strung instruments such as the classical guitar, lute, viol or oud, the softer, more textured string surface gives the slide an audible finger-on-string friction and a warm, gradual change of pitch.", "plain_english": "Moving a finger along a gut string while it sounds, so the note glides smoothly up or down. It is like a trombone slide, where moving the slide smoothly changes the pitch with no break between notes.", "purpose_function": "It links two pitches with a smooth, vocal-like slur and adds expression; the gut string's soft texture also gives a gentle sliding noise that is part of the instrument's natural character.", "practical_application": "When recording nylon or gut-strung instruments, a technician expects these slides and their finger noise, and chooses mic placement and any noise processing so the slide stays musical rather than being cut away or exaggerated.", "category": "Playing technique", "related_terms": ["Glissando", "Portamento", "Finger noise", "Legato", "Gut string", "Fingerboard"], "common_mistakes": ["Confusing a gut-string slide, which is a continuous pitch change, with a hammer-on or fretted legato that moves in discrete steps.", "Using heavy noise reduction that strips out the sliding finger sound and leaves the slide lifeless.", "Assuming every string slide sounds alike; gut and nylon strings give a softer, less squeaky slide than wound steel strings."], "scenario_contexts": ["Close-miking a classical guitarist whose left hand slides between positions on the treble strings.", "Recording a lute or viol part where expressive slides connect the notes of a phrase.", "Editing a solo passage where a slide's finger noise must be balanced against the note itself."]}, "cda6e391-346c-45b7-9f97-75648ac3b355": {"definition": "A rapid glissando swept across the open strings of the guzheng (Chinese zither), sounding the successive pitches of its pentatonic tuning in a cascading run. Played by drawing the fingers or nails up or down across the strings, it is a signature ornamental gesture of the instrument.", "plain_english": "A quick sweep of the fingers across the guzheng's strings, so the notes flow past like water. It sounds a bit like running your thumb down a row of piano keys, but on plucked strings.", "purpose_function": "It supplies flowing ornamental runs and transitions that colour a melody; because the guzheng is tuned to a pentatonic scale, every swept note fits the mode, so the sweep always sounds pleasant.", "practical_application": "When miking or mixing a guzheng, a technician captures the wide left-to-right spread of a sweep and watches for sharp peaks and nail noise as the fingers cross many strings quickly.", "category": "Playing technique", "related_terms": ["Glissando", "Pentatonic scale", "Zither", "Plucking", "Tremolo", "Transient"], "common_mistakes": ["Assuming the sweep is chromatic; the guzheng's open strings are pentatonic, so the run skips the missing scale degrees.", "Panning a single spot mic so a sweep collapses to one point instead of showing the instrument's natural left-to-right motion.", "Setting compression too fast and squashing the bright attack of each swept string."], "scenario_contexts": ["Recording a solo guzheng where sweeps open or close musical phrases.", "Balancing a guzheng in a fusion mix so its glissando cuts through without harsh nail noise.", "Stereo-miking the instrument to preserve the movement of a full-range sweep."]}, "e1771763-26d8-4d7f-be0e-532bf887d113": {"definition": "The action of striking the courses of a hammered dulcimer with lightweight hand-held hammers (beaters) to set the strings vibrating. The hammer's mass and hardness and the point of contact along the string shape the loudness, attack and tone of each note.", "plain_english": "Hitting the strings of a hammered dulcimer with small handheld hammers to make them ring. It works like tapping a tuned string with a little mallet, where a harder tap gives a brighter, louder note.", "purpose_function": "Striking is how the instrument makes its sound; the bounce of the light hammers lets a player repeat notes fast, while hammer hardness and strike point set the brightness and attack of the tone.", "practical_application": "A technician recording a hammered dulcimer expects sharp percussive peaks and wide dynamics, and sets gain and mic distance so loud strikes do not clip while soft passages stay audible.", "category": "Playing technique", "related_terms": ["Course", "Transient", "Attack", "Struck string", "Beater", "Sustain"], "common_mistakes": ["Setting input gain for quiet notes and then clipping on hard strikes, since dulcimer strikes have a very high peak level.", "Over-compressing the attack and losing the bright percussive character of the strike.", "Placing a mic so close to one course that nearby courses ringing sympathetically are missed."], "scenario_contexts": ["Close-miking a hammered dulcimer in a folk session with strong percussive strikes.", "Recording rapid tremolo passages built from fast, repeated hammer strikes.", "Setting a limiter to catch unexpected loud strikes during a live performance."]}, "1387970e-7716-414f-8d7a-51856021bcfa": {"definition": "Acoustic feedback that occurs when an amplified harp's pickup or microphone signal is reproduced by a loudspeaker and re-excites the harp's soundboard and strings, forming a self-sustaining howl or ring. The harp's large resonant body and many freely vibrating strings make it especially prone to feedback on stage.", "plain_english": "A howling or ringing sound that happens when a plugged-in harp's own amplified sound feeds back into it and builds up. It is the same runaway loop you hear when a microphone gets too close to its speaker.", "purpose_function": "Feedback is an unwanted loop, not a goal; understanding it matters because the harp's open strings and big soundbox pick up amplified sound easily, so controlling it keeps the amplified harp usable at stage volume.", "practical_application": "A technician fights harp feedback by managing gain before feedback, using directional mics or contact pickups, placing the harp away from and behind the speakers, and notching the problem frequencies with EQ.", "category": "Amplification", "related_terms": ["Acoustic feedback", "Gain before feedback", "Pickup", "Notch filter", "Monitor wedge", "Ringing out"], "common_mistakes": ["UNSAFE: Letting feedback build into a sudden loud howl, which can damage speakers and hearing; pull the gain down or mute at the first sign of ringing.", "Raising the harp channel gain to hear more instead of moving the harp out of the monitor's direct path.", "Aiming a floor wedge straight at the harp's soundboard, which invites feedback."], "scenario_contexts": ["Amplifying a lever or pedal harp in a loud band where the soundboard starts to ring.", "Ringing out the monitors before a set that features an amplified harp.", "Choosing between a contact pickup and a mic to reduce feedback on a small stage."]}, "6ab545a8-8b6b-4d35-9b7a-563b5d3ff912": {"definition": "An electric-guitar pickup that uses two coils wired in series with opposite magnetic polarity and reversed winding sense, so that externally induced hum cancels while the string signal from both coils adds in phase. The result is a quieter, higher-output and warmer-sounding pickup than a single coil.", "plain_english": "A guitar pickup made of two coils that cancel out the buzzing hum a single coil picks up. The coils are wired so the noise cancels but the guitar sound adds together, giving a fuller, quieter tone.", "purpose_function": "It exists to remove the mains-frequency hum that plagues single-coil pickups; pairing two coils that see hum in opposite phase cancels the shared noise while doubling the wanted signal, raising output and thickening the tone.", "practical_application": "A technician treats a humbucker-equipped guitar as a hotter, quieter source, sets input gain for its higher output, and expects less 50/60 Hz hum than from single coils near lighting or transformers.", "category": "Guitar pickup", "related_terms": ["Single-coil pickup", "Hum", "Series wiring", "Coil split", "Pickup", "Ground loop"], "common_mistakes": ["Thinking a humbucker removes all noise; it cancels shared magnetic hum but not radio interference or ground-loop buzz.", "Assuming humbucker and single-coil outputs match, then clipping the input when switching to the hotter humbucker.", "Splitting a humbucker to single-coil mode and forgetting that its hum-cancelling is then lost."], "scenario_contexts": ["DI-ing or miking a humbucker-equipped electric guitar under stage lighting that would hum through single coils.", "Setting preamp gain when a player switches between single-coil and humbucker guitars.", "Troubleshooting guitar hum and confirming whether the pickup is a true humbucker."]}}$j$::jsonb)) d
WHERE g.id = d.id;
UPDATE glossary g SET
 definition = CASE WHEN d.p ? 'definition' THEN d.p->>'definition' ELSE g.definition END,
 plain_english = CASE WHEN d.p ? 'plain_english' THEN d.p->>'plain_english' ELSE g.plain_english END,
 purpose_function = CASE WHEN d.p ? 'purpose_function' THEN d.p->>'purpose_function' ELSE g.purpose_function END,
 practical_application = CASE WHEN d.p ? 'practical_application' THEN d.p->>'practical_application' ELSE g.practical_application END,
 category = CASE WHEN d.p ? 'category' THEN d.p->>'category' ELSE g.category END,
 related_terms = CASE WHEN d.p ? 'related_terms' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'related_terms') x) ELSE g.related_terms END,
 common_mistakes = CASE WHEN d.p ? 'common_mistakes' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'common_mistakes') x) ELSE g.common_mistakes END,
 scenario_contexts = CASE WHEN d.p ? 'scenario_contexts' THEN (SELECT array_agg(x) FROM jsonb_array_elements_text(d.p->'scenario_contexts') x) ELSE g.scenario_contexts END
FROM (SELECT key::uuid AS id, value AS p FROM jsonb_each($j${"2d5d3ae9-1182-4b45-9598-e4879812a062": {"definition": "The tone produced when bowing one of the inner strings of a multi-string bowed instrument (for example the D or A string of a violin), which lie between the outer strings and demand a precise bow-arm height to sound cleanly without brushing the neighbouring strings. This inner-string tone tends to be more covered and mellow than that of the freely bowed outer strings.", "plain_english": "The sound made when a bow plays one of the middle strings of an instrument like a violin. These strings sit between the outer two, so the arm must be held at just the right height to sound only one string cleanly.", "purpose_function": "Naming the inner-string tone matters because these strings need a careful bow-arm level; getting it right gives a smooth, even tone and avoids accidentally sounding the strings on either side.", "practical_application": "When recording strings, a technician may notice the inner strings sound slightly darker or quieter and adjusts mic placement or balance so passages on the middle strings match the brighter outer strings.", "category": "Bowing technique", "related_terms": ["Bowing technique", "String crossing", "Double stop", "Sul tasto", "Bow contact point", "Timbre"], "common_mistakes": ["Blaming the instrument for an uneven tone when the real cause is the bow arm sitting at the wrong height for an inner string.", "Expecting inner strings to record as brightly as the top string and not balancing them in the mix.", "Confusing inner-string tone with sul tasto or sul ponticello, which are about where the bow contacts the string, not which string is played."], "scenario_contexts": ["Recording a violin solo where a melody moves onto the inner D and A strings.", "Balancing a string section so middle-string passages sit evenly with outer-string ones.", "Coaching mic placement for a violist playing mostly on the inner strings."]}, "c6d6cd4d-d1bd-40ac-9014-2cd5861e542e": {"definition": "The bright, buzzing, overtone-rich timbre created by the jawari (javari) — the broad, gently curved bridge of Indian string instruments such as the sitar, tanpura and veena. As a string vibrates it grazes the curved bridge surface, and this repeated glancing contact adds and sustains high harmonics, producing the characteristic humming buzz.", "plain_english": "The rich, buzzing ring of a sitar or tanpura. It happens when the strings graze a wide, curved bridge. That gentle brushing adds shimmering overtones, a bit like how a buzzing reed sounds fuller than a clean one.", "purpose_function": "The jawari bridge exists to give these instruments their signature sustained, overtone-heavy sound; the grazing contact keeps high harmonics alive far longer than a normal sharp-edged bridge would.", "practical_application": "A technician recording a sitar or tanpura captures this bright, harmonic-rich buzz with careful mic choice and placement, avoiding harshness while keeping the sustaining overtones that define the sound.", "category": "Instrument timbre", "related_terms": ["Jivari drone bloom", "Bridge", "Sympathetic strings", "Overtones", "Sustain", "Sitar"], "common_mistakes": ["Mistaking the intended jawari buzz for an unwanted rattle or fret buzz and trying to EQ it out.", "Close-miking so tightly that the overtones sound harsh instead of rich and sustained.", "Assuming any curved-bridge buzz is a defect; on these instruments the buzz is the desired tone and is finely shaped by a craftsman."], "scenario_contexts": ["Recording a sitar where the jawari gives every note a long, shimmering tail.", "Miking a tanpura drone whose buzzing overtones underpin a raga performance.", "Deciding EQ on an Indian-classical track so the jawari overtones stay musical."]}, "5f7800de-9a4d-48e6-af80-650455a3fda2": {"definition": "The swelling, harmonically blooming sustain of a tanpura's drone produced by its jivari (jawari) bridge and the cotton threads (juari) laid under the strings. As each plucked string grazes the curved bridge, overtones build and evolve during the note, so the drone seems to bloom and shimmer rather than simply decay.", "plain_english": "The way a tanpura's droning notes seem to swell and shimmer instead of just fading. The strings brush a curved bridge and a small thread, which makes overtones grow during the note, so the drone blooms like a slowly opening chord.", "purpose_function": "This blooming drone provides the harmonic backdrop for Indian classical music; the jivari bridge and threads are tuned so the overtones rise and sustain, giving singers and soloists a rich, living reference pitch.", "practical_application": "A technician records the tanpura with enough sustain and stereo space that the blooming overtones fill the background, and sets levels so the drone supports rather than masks the lead.", "category": "Instrument timbre", "related_terms": ["Jawari/javari buzz", "Tanpura", "Drone", "Overtones", "Sympathetic resonance", "Sustain"], "common_mistakes": ["Gating or heavily compressing the tanpura, which kills the slow bloom and the evolving overtones.", "Treating the blooming overtones as tuning drift instead of the intended sound of the jivari.", "Recording the drone too quietly or too loudly so it either disappears or masks the soloist."], "scenario_contexts": ["Tracking a tanpura drone under a vocal raga so its bloom fills the harmonic space.", "Choosing reverb and level so the tanpura blooms without swamping the mix.", "Miking a live tanpura so the evolving overtones reach the audience."]}, "54c0b2ec-0909-44a9-9629-2f80803043b5": {"definition": "The bright, penetrating, slightly nasal timbre characteristic of the kamancheh, a Persian bowed spike fiddle whose sound is radiated by a thin skin (membrane) stretched over a small round wooden or gourd body. The membrane and compact resonator emphasize the upper harmonics, giving a reedy, voice-like nasal quality.", "plain_english": "The bright, slightly buzzy, voice-like sound of the kamancheh, a Persian bowed fiddle. Its small skin-covered body makes a thin, nasal tone, a bit like a singer humming through the nose.", "purpose_function": "The skin-headed body and small resonator shape this nasal, upper-harmonic-rich tone, which lets the kamancheh sing expressively and cut through an ensemble in Persian classical music.", "practical_application": "A technician miking a kamancheh positions the mic to capture the skin's bright nasal tone without harshness, and may tame upper-midrange peaks with gentle EQ.", "category": "Instrument timbre", "related_terms": ["Spike fiddle", "Membrane", "Bowing technique", "Timbre", "Overtones", "Resonator"], "common_mistakes": ["Mistaking the natural nasal tone for a bad mic or harsh EQ and dulling it until the instrument loses character.", "Placing a bright condenser too close to the skin head, which exaggerates the nasal upper mids.", "Assuming it should sound like a violin; the skin-covered body gives a thinner, more nasal voice."], "scenario_contexts": ["Recording a kamancheh solo in a Persian classical ensemble.", "Balancing the kamancheh's nasal tone against softer plucked instruments in a mix.", "Choosing mic distance to capture the skin head's bright timbre naturally."]}, "9e5931e7-4dcc-4f55-aca6-8353775ada5a": {"definition": "The characteristic reedy, nasal, penetrating tone produced by bowing the kemençe, a family of small pear- or bottle-shaped bowed lutes played upright on the knee, with the strings stopped by the fingernails or fingertips rather than pressed to a fingerboard. Its bright, sharp timbre, often likened to a double-reed instrument, arises from the short body, high string tension and the bow's stick-slip excitation, and is central to Black Sea (Pontic lyra) and Ottoman classical kemençe music.", "plain_english": "The sharp, nasal, oboe-like sound a kemence makes when you play it with a bow. This small upright fiddle from Turkey and the Black Sea has a thin, cutting voice, so it stands out clearly even in a loud band.", "purpose_function": "The reedy, penetrating tone lets the kemençe carry a melody over drums, voices and dancing crowds in Black Sea and Ottoman music, which is why players and builders prize its bright, cutting voice.", "practical_application": "When recording or amplifying a kemençe a technician expects a strong upper-midrange edge and audible bow noise, so they choose mic placement and gentle EQ that keep the reedy character without letting it turn harsh.", "category": "Instrument timbre", "related_terms": ["Arco sound", "Bowing", "Stick-slip motion", "Timbre", "Nasal tone", "Spot mic"], "common_mistakes": ["Assuming the kemençe is fretted or stopped like a violin; players stop the strings with their fingernails, not by pressing them onto a fingerboard.", "EQ-ing away all of the upper-midrange 'reed' to make it sound smooth, which strips the instrument of its identity.", "Miking too close and exaggerating harsh bow scratch instead of capturing the body and reedy ring."], "scenario_contexts": ["Recording a Pontic lyra (Black Sea kemençe) for a folk-fusion track.", "Amplifying a kemençe on a live horon-dance stage where it must cut through the mix.", "Blending an Ottoman classical kemençe with other instruments in an ensemble session."]}, "cad01d39-0b51-4e15-8e66-4e90eaa19cee": {"definition": "A brief, percussive click transient heard at the very start (and often the end) of a note on an electromechanical or electronic organ, most famously the Hammond tonewheel organ. It occurs because the tone is always present at the key contacts, so making or breaking a contact chops the waveform and produces a sharp attack (and release) spike; it is regarded as a defining part of the vintage organ sound and is deliberately modeled in clonewheel instruments.", "plain_english": "The short, snappy click you hear when an organ key goes down or up. It comes from the electrical contacts under the key turning the sound on and off. This click is a big part of what makes a Hammond organ sound like a Hammond.", "purpose_function": "Originally an unavoidable side effect of the key contacts, key click became a valued musical feature that adds attack and definition to each note, so modern organs let players dial in the amount to imitate vintage instruments.", "practical_application": "A player or engineer sets the attack and release key-click level on a clonewheel or reissue organ to taste, adding more for a percussive, aggressive feel or less for a smoother, pad-like sound.", "category": "Keyboard artifact", "related_terms": ["Drawbar", "Percussion (organ)", "Tonewheel", "Attack transient", "Clonewheel organ", "Key release"], "common_mistakes": ["Treating all key click as a fault to be removed; on a Hammond it is a wanted part of the tone.", "Confusing electrical key click with mechanical key-action noise, which comes from the physical keys rather than the contacts.", "Cranking click so high that it masks the note attack and sounds unnaturally spiky."], "scenario_contexts": ["Dialing in vintage key click on a clonewheel organ for a soul or gospel track.", "Recording a real Hammond and preserving its natural attack and release clicks.", "Reducing excessive modeled key click that sounds harsh in a dense mix."]}, "c79160ff-b544-460f-b737-7359be28415e": {"definition": "The unwanted mechanical sound made by the keys and their action as they are pressed and released, distinct from the instrument's intended musical tone. On acoustic and digital pianos and organs it includes the impact of keys moving, bottoming out and returning to rest, and it can be captured by microphones or transmitted structurally into pickups.", "plain_english": "The clicky, clunky sound the keys make as you press and release them, apart from the notes. Every keyboard makes some of this. It is like the soft clatter you hear on a quiet digital piano, even through headphones.", "purpose_function": "Key noise is a normal by-product of any physical key mechanism; recognizing it matters because it can intrude on quiet recordings and must be managed so it does not distract from the music.", "practical_application": "When close-miking a soft passage a technician positions mics and sets levels to keep key noise low, and on digital pianos may isolate the instrument from resonant surfaces that amplify the clatter.", "category": "Mechanical noise", "related_terms": ["Key-action noise", "Key thump", "Key return", "Key click", "Acoustic spill", "Close miking"], "common_mistakes": ["Assuming key noise means the instrument is broken; a certain amount is normal mechanical operation.", "Gating hard to remove key noise and cutting off the quiet start or tail of real notes.", "Blaming the microphone for key noise that is actually structure-borne through the stand or floor."], "scenario_contexts": ["Recording a soft solo piano passage where key clatter becomes audible between notes.", "Tracking a digital piano late at night and noticing mechanical key sound through headphones.", "Miking an organ manual and picking up the keys as well as the tone."]}, "cd7e96f3-78e9-41a3-a11c-5e8bd2533ce3": {"definition": "The act of letting go of a depressed key, which ends the note's actuation. On a MIDI instrument it sends a Note Off message; on a synthesizer it triggers the release stage of the amplitude envelope; and on acoustic or sampled instruments it lets the damper fall and may produce a distinct key-off or release sound.", "plain_english": "The moment you lift your finger off a key to end a note. On a synth this starts the note fading away, and on a piano it drops the damper back onto the string to stop the sound.", "purpose_function": "Key release tells the instrument when a note should stop, letting the player control note length and phrasing; the speed of the following envelope release then shapes how quickly the sound dies away.", "practical_application": "A technician sets envelope release time so notes end smoothly, and when using sampled pianos enables release samples so the natural key-off sound is heard when keys are lifted.", "category": "Note articulation", "related_terms": ["Key return", "ADSR envelope", "Note Off", "Damper", "Release sample", "Sustain"], "common_mistakes": ["Confusing key release (letting go of the key) with the envelope's release time (how fast the sound fades).", "Setting a very long envelope release and causing notes to overlap and turn muddy.", "Forgetting that a held sustain pedal keeps notes sounding even after the keys are released."], "scenario_contexts": ["Programming a synth pad and lengthening the release so chords bloom after keys are lifted.", "Using release samples in a virtual piano for realistic note endings.", "Editing MIDI note-off timing to tighten a staccato keyboard part."]}, "58a6a5b8-7948-42a4-b031-72042a7de1fe": {"definition": "The mechanical travel of a key back to its rest (up) position after it is released, driven by a spring, gravity or a counterweight, together with the soft impact and noise produced as the key settles. On weighted and hammer-action keyboards it also involves the action parts falling back, and its speed limits how quickly a note can be repeated.", "plain_english": "The way a key springs back up after you let it go, and the little soft thud it makes settling into place. If a key returns slowly, you cannot play fast repeated notes on it.", "purpose_function": "Reliable key return resets the key for the next note and gives the player a consistent feel; the return also generates a small mechanical sound that engineers may need to manage on quiet recordings.", "practical_application": "A technician checks that keys return evenly on a piano or controller so repeated notes trigger reliably, and keeps mic levels in mind because the soft key-return noise can appear in intimate recordings.", "category": "Mechanical noise", "related_terms": ["Key-action noise", "Key noise", "Key thump", "Key release", "Weighted action", "Repetition"], "common_mistakes": ["Confusing key return (the key rising back up) with key release (the act of letting go of the key).", "Ignoring sluggish key return, which prevents fast note repetition and feels uneven.", "Gating out quiet key-return noise so aggressively that soft note tails are also lost."], "scenario_contexts": ["Servicing a controller whose sticky keys do not return fully to rest.", "Recording a soft passage where the key-return thud becomes audible.", "Testing action feel by checking even, springy key return across the keyboard."]}, "dd1dcf1f-c579-48f4-a833-a4bcb587169e": {"definition": "A low-frequency thud produced when a key is pressed hard and bottoms out on the key bed, or when the action falls back on release, transmitting mechanical energy into the instrument's body. It is common on digital pianos and weighted controllers and can be picked up by microphones or radiated as a dull knock, especially on resonant stands or surfaces.", "plain_english": "The dull, low thump you feel and hear when a key hits the bottom of its travel. It is like tapping a table; the energy spreads into the keyboard's body and can be picked up as a soft knock.", "purpose_function": "Key thump is an unwanted by-product of the key hitting its end stop; understanding it helps a technician stop that low-frequency knock from muddying quiet recordings or resonating through the stage.", "practical_application": "A technician reduces key thump by placing the keyboard on an isolating stand or pad, and may use a high-pass filter to remove the low-frequency knock without touching the musical range.", "category": "Mechanical noise", "related_terms": ["Key-action noise", "Key noise", "Key return", "High-pass filter", "Structure-borne noise", "Isolation"], "common_mistakes": ["Confusing mechanical key thump with a low-frequency electrical thump or pop from the audio signal.", "Trying to EQ out key thump with a broad low cut that also thins the instrument's real bass notes.", "Ignoring structure-borne thump traveling through a shared stand or riser into other microphones."], "scenario_contexts": ["Recording a weighted digital piano where heavy playing produces a low key thump.", "High-passing a keyboard DI to remove low-frequency knock in a live mix.", "Isolating a controller on foam to stop thump traveling into a resonant desk."]}, "939f8c80-fe42-4753-b89f-1e8172f5bdba": {"definition": "The mechanical noise generated specifically by a keyboard instrument's action, the hammers, jacks, wippens, dampers, springs and key bushings, as these parts move when notes are played. It is inherent to the physical mechanism; felt and cloth cushions are used to quiet it, but some remains and can be captured by close microphones.", "plain_english": "The clicky, knocky sound made by the moving parts inside a keyboard's action, like the hammers and levers, not the strings or speakers. Even good pianos make a little of it, which is why the parts are padded with felt.", "purpose_function": "Key-action noise is an unavoidable result of a mechanical action doing its job; knowing its causes lets a technician minimize it through maintenance and mic choices so it does not intrude on the recording.", "practical_application": "A technician keeps action parts regulated and felts in good condition, and on quiet takes moves mics slightly away from the action or angles them to reduce the mechanical clatter reaching the recording.", "category": "Mechanical noise", "related_terms": ["Key noise", "Key thump", "Key return", "Damper", "Piano action", "Close miking"], "common_mistakes": ["Assuming audible action noise means a defect; some is normal even on a well-regulated instrument.", "Letting worn or dried-out felt bushings go unserviced, so the action rattles more than it should.", "Placing mics right over the action on a quiet passage and exaggerating the mechanical clatter."], "scenario_contexts": ["Close-miking a grand piano for a delicate solo and hearing hammer and damper noise.", "Regulating a piano action to reduce excess mechanical clatter before a session.", "Choosing mic distance on an upright to balance tone against action noise."]}, "b833b3f5-32f1-405e-b0d2-ec3e6530a700": {"definition": "A hum or buzz, usually at the mains frequency (50 or 60 Hz) and its harmonics, caused when a keyboard or synthesizer and the mixer or amplifier it feeds are connected to ground through more than one path, forming a closed loop. Small voltage differences between the grounds drive current through the audio cable shield, which is heard as hum in the signal.", "plain_english": "A steady hum or buzz that appears when a keyboard and a mixer are grounded through two different paths at once, making a loop. Stray current flows through the cable shield and you hear it as an annoying hum.", "purpose_function": "This term names a specific, common cause of unwanted hum so technicians can tell it apart from other noise and cure the wiring at its source rather than masking the symptom.", "practical_application": "A technician cures keyboard ground-loop hum with balanced connections, a DI box with a ground-lift switch, or an isolation transformer, and keeps signal cables away from power cables, never by disconnecting the mains safety ground.", "category": "Electrical noise", "related_terms": ["Ground loop", "DI box", "Ground lift", "Balanced connection", "Isolation transformer", "Hum"], "common_mistakes": ["UNSAFE: Lifting or defeating the mains earth/safety ground (for example with a cheater plug or by cutting the ground pin) to stop the hum; this removes shock protection and can be lethal.", "Using a DI box's signal ground-lift switch and expecting it to fix every loop, when the wiring path itself may still need changing.", "Chasing the hum with EQ or noise gates instead of finding and breaking the ground loop at its source."], "scenario_contexts": ["A stage keyboard buzzes when plugged into the main mixer on a different power circuit.", "A studio synth hums only when connected to both an audio interface and a separately grounded amp.", "Adding a DI box with a ground lift to silence hum between a keyboard and the front-of-house console."]}, "487882de-9d7c-4ac1-bfc1-bff0351806a4": {"definition": "The bright, ringing, bell-like tone produced by plucking the kokle (Latvian) or kantele (Finnish), related Baltic and Finnic box zithers of the psaltery family in which open strings are stretched over a flat soundboard and plucked with the fingers, fingernails or a plectrum. Plucking sets the strings into free vibration so they sustain and shimmer, while the player's other hand can damp the strings that should not ring.", "plain_english": "The clear, ringing sound you get by plucking the open strings of a kantele or kokle, box zithers from Finland and Latvia. It sounds bright and bell-like, a bit like a small harp, and the notes ring on until they are damped.", "purpose_function": "Plucking excites the free strings so they ring and sustain, giving these zithers their delicate, shimmering voice; damping with the free hand lets the player control which strings ring and keep the harmony clean.", "practical_application": "When recording a kantele or kokle a technician mics the soundboard to capture the bright attack and long ring, and watches for finger and string noise from the plucking hand on quiet passages.", "category": "Instrument timbre", "related_terms": ["Pizzicato", "Plucked string", "Sustain", "Damping", "Soundboard", "Spot mic"], "common_mistakes": ["Confusing the kantele/kokle with a hammered dulcimer; these zithers are plucked, not struck with beaters.", "Miking too far away and losing the bright pluck attack that defines the sound.", "Forgetting that undamped strings keep ringing, so overlapping notes can blur the harmony."], "scenario_contexts": ["Recording a solo kantele for a Finnish folk album.", "Amplifying a kokle in an ensemble and controlling string ring with careful damping.", "Capturing the bright plucked attack of a Baltic psaltery for a film score."]}, "2df30a3e-3fbe-4f16-9331-c797f2114eeb": {"definition": "The buzzing, rattling timbre characteristic of the kora, a 21-string West African harp-lute, traditionally produced by a metal plate fitted with loose jingle rings (the nyenyemo) attached near the bridge, whose sympathetic vibration adds a sustained buzz to each plucked note. Loose leather or metal tuning rings (konso) on the neck can add further rattle. The buzz is a deliberate aesthetic element, though many modern players remove the device for clarity when amplified.", "plain_english": "The soft buzzing, rattly sound a kora makes. The kora is a big West African harp with 21 strings. A small metal plate with loose rings sits near the bridge. The rings shake and buzz as the strings sound. Players like this fuzzy tail, but some take the rings off when they plug in.", "purpose_function": "The buzz enriches and sustains each plucked note and adds a percussive shimmer prized in West African music, which is why the rattle device is built onto the instrument.", "practical_application": "When recording or amplifying a kora a technician expects this buzzy, rattly overtone and sets mic placement and EQ to keep it musical, or works with a player who may remove the rattle plate for a cleaner amplified sound.", "category": "Instrument timbre", "related_terms": ["Sympathetic resonance", "Timbre", "Bridge buzz", "Overtone", "Close miking", "String rattle"], "common_mistakes": ["Assuming the buzz is a fault or a bad string setup; on a traditional kora the rattle is intentional.", "Trying to EQ out all of the buzz, which strips the instrument of its natural character.", "Confusing the bridge rattle device (nyenyemo) with loose tuning rings, which cause a different, unwanted clatter."], "scenario_contexts": ["Recording a traditional kora where the buzzing rattle plate is still fitted.", "Amplifying a kora on stage and deciding whether to keep or remove the rattle for clarity.", "Troubleshooting whether a rattle comes from the buzz device or from loose tuning rings."]}, "b13ec23c-6afd-479e-9da3-7f01179891ba": {"definition": "The smooth, continuous glide in pitch produced on a lap steel (Hawaiian) guitar by sliding a solid metal or glass bar — the 'steel' — along the strings instead of pressing them onto frets. Because the bar never stops the strings at a fixed fret, the player moves smoothly between and beyond pitches, giving the instrument its singing, vocal-like portamento.", "plain_english": "The sliding, singing sound of a lap steel guitar. Instead of pressing the strings down on frets, the player rests a smooth metal bar on top of the strings and slides it up and down. This lets the notes glide into each other, a bit like a voice sliding between pitches.", "purpose_function": "Sliding the bar lets the player connect notes with a smooth glide and add expressive vibrato, which is the core voice of Hawaiian, country and blues steel-guitar styles.", "practical_application": "A technician recording or amplifying lap steel expects long sustained notes and glides, plus some bar and string noise, and sets levels and EQ so the sustain and slide stay clear without harsh scrape.", "category": "Playing technique", "related_terms": ["Slide guitar", "Glissando", "Portamento", "Vibrato", "Sustain", "Pickup"], "common_mistakes": ["Confusing lap-steel technique with fretting; the bar rests on the strings and never presses them to the fretboard.", "Pressing the bar down hard enough to touch the frets, which causes buzzing and choked notes.", "Forgetting that pitch depends on exact bar position, so slightly wrong placement plays out of tune."], "scenario_contexts": ["Recording a lap or Hawaiian steel glide in a country session.", "Amplifying a Hawaiian steel guitar on stage.", "Capturing bluesy slide lines with long sustained glides."]}, "0869c4f1-f6fb-4289-a96a-c62974e1a748": {"definition": "A pipa (Chinese lute) right-hand technique, also called lun, in which the fingers of the right hand strike the string outward in rapid succession — typically index, middle, ring and little finger, then thumb — turning a short plucked note into a continuous, sustained tremolo. It is the pipa's principal means of sustaining a melody, since a single pluck decays quickly.", "plain_english": "A fast finger-rolling trick on the pipa, a pear-shaped Chinese lute. The player flicks each finger of the right hand across the string one after another, over and over. A single pluck fades fast, so this rolling motion keeps the note going in a steady shimmer.", "purpose_function": "Rolling the fingers in sequence sustains a plucked string that would otherwise decay at once, letting the pipa hold long, singing melody notes and swells.", "practical_application": "When recording pipa a technician expects these dense tremolo passages and chooses mic placement and gentle compression that keep every finger-stroke even without exaggerating nail noise.", "category": "Playing technique", "related_terms": ["Pipa", "Tremolo", "Sustain", "Plucked string", "Attack transient", "Fingerpicking"], "common_mistakes": ["Thinking lunzhi is a single finger's tremolo; it is a roll of several fingers in sequence.", "Assuming it works like mandolin pick tremolo; the pipa uses individual fingers, not a plectrum.", "Over-compressing the roll so the natural swell and decay of the tremolo are flattened."], "scenario_contexts": ["Recording a solo pipa piece with long sustained tremolo lines.", "Balancing a pipa's tremolo against an ensemble in a fusion track.", "Editing pipa where finger-roll strokes need even level."]}, "f7e068ba-7549-4fc6-85a7-6a7929e12050": {"definition": "Acoustic feedback that occurs when an amplified mandolin's pickup or microphone picks up its own amplified sound and drives the hollow body and strings into sustained self-oscillation, usually heard as a howl or ring at a resonant frequency. It is most common with acoustic-electric or close-miked mandolins on loud stages.", "plain_english": "The howling or ringing sound that happens when an amplified mandolin feeds its own sound back into its pickup or mic. The speaker sound shakes the small hollow body and strings, and the loop builds into a squeal. It is like when a singer's mic gets too close to the speaker.", "purpose_function": "Understanding mandolin feedback matters because the small resonant body feeds back easily on stage, so controlling it keeps the instrument loud enough without breaking into a howl.", "practical_application": "To stop feedback a technician lowers gain, moves the mandolin or monitors, notches the ringing frequency with EQ, or fits a soundhole cover, watching the resonant note that first starts to howl.", "category": "Live-sound artifact", "related_terms": ["Acoustic feedback", "Gain before feedback", "Notch filter", "Monitor wedge", "Soundhole cover", "Resonant frequency"], "common_mistakes": ["UNSAFE: Chasing more volume by pushing gain past the feedback point, which can send a sudden loud squeal through the PA and risk hearing damage.", "Blaming the pickup when the real cause is monitor level or the mandolin facing the speakers.", "Notching so many frequencies to kill feedback that the mandolin's natural tone is lost."], "scenario_contexts": ["An acoustic-electric mandolin howling on a loud bluegrass stage.", "Setting gain before feedback for a close-miked mandolin.", "Using a soundhole cover to tame feedback during an amplified set."]}, "0199fd8d-2326-4ffb-8e26-98dff5900517": {"definition": "A mandolin performance technique in which the player rapidly alternates down-and-up plectrum strokes across a pair (course) of strings to sustain a note or chord, compensating for the quick decay of the plucked double strings. It produces the mandolin's characteristic shimmering, sustained tone on longer notes.", "plain_english": "The fast, shimmery picking that lets a mandolin hold a long note. A plucked mandolin string fades quickly, so the player flicks the pick down and up very fast on the same string pair. This rapid picking blurs into one long, trembling sound.", "purpose_function": "Rapid alternate picking sustains notes that would otherwise die away fast, giving the mandolin a smooth, singing line on melodies and long chords.", "practical_application": "When recording mandolin tremolo a technician expects a dense stream of pick attacks and sets mic position and light compression so the tremolo sounds even and smooth rather than choppy or spiky.", "category": "Playing technique", "related_terms": ["Tremolo", "Course (strings)", "Plectrum", "Sustain", "Alternate picking", "Pick attack"], "common_mistakes": ["Confusing pick tremolo with pitch vibrato; mandolin tremolo is rapid re-picking, not a pitch wobble.", "Setting compression so hard that the individual pick strokes turn into an unnatural wall of sound.", "Miking so close that each pick attack clicks harshly instead of blending into a smooth tremolo."], "scenario_contexts": ["Recording a sustained mandolin melody built on tremolo.", "Mixing tremolo-picked mandolin in a bluegrass or classical piece.", "Capturing even tremolo across a mandolin's string courses."]}, "1076671d-8a08-497d-b365-300160af774a": {"definition": "In Hindustani (North Indian) classical music, meend is a smooth, continuous glide in pitch that connects notes, a portamento central to raga phrasing. On the sitar it is produced by pulling (deflecting) a string laterally across the curved fret so that a single stopped position can bend up through several notes, letting one gesture traverse multiple pitches without re-plucking.", "plain_english": "A smooth pitch slide used in Indian classical music. On a sitar the player pulls the string sideways across a fret, and the pitch rises smoothly through several notes. It is like sliding your finger along a stretched rubber band so the sound climbs with no gaps, all from one pluck.", "purpose_function": "Meend links notes with an unbroken glide that carries the feeling and identity of a raga, which is why smooth bending is a core expressive skill on sitar and in vocal-style playing.", "practical_application": "When recording sitar a technician expects long bent glides after a single pluck and sets levels and any compression so the quiet tail of the bend stays audible instead of dropping out.", "category": "Playing technique", "related_terms": ["Raga", "String bend", "Portamento", "Glissando", "Sitar", "Sustain"], "common_mistakes": ["Thinking meend is a quick guitar-style bend; it is a smooth, controlled glide that can pass through several notes.", "Gating or compressing so hard that the fading tail of the glide is cut off.", "Assuming each note in the glide is re-plucked; meend flows from one pluck across the bend."], "scenario_contexts": ["Recording a sitar alap full of long meend glides.", "Preserving the quiet tail of a bend during mixing.", "Capturing vocal-style glides in an Indian classical session."]}, "6c9246d5-f456-4a11-bff2-23de51eab722": {"definition": "The broad, expressive vibrato characteristic of the morin khuur, the Mongolian two-string horse-head fiddle, whose strings are stopped from the side by the fingernails or finger pads rather than pressed onto a fingerboard. This side-stopping allows a wide, vocal pitch oscillation used to imitate the human voice and horse sounds in Mongolian long-song and folk styles.", "plain_english": "The wide, wailing pitch wobble of the morin khuur, Mongolia's two-string horse-head fiddle. The player does not press the strings onto a fingerboard; the fingers touch the strings from the side. This lets the pitch swing widely, so the fiddle can cry and sing almost like a human voice.", "purpose_function": "The wide vibrato gives the morin khuur its deeply vocal, expressive voice, letting it imitate singing and horse calls, which is central to Mongolian long-song and storytelling music.", "practical_application": "When recording or amplifying a morin khuur a technician expects broad pitch swings and a rich low-mid tone, and chooses mic placement that captures the expressive vibrato and body resonance without boom.", "category": "Playing technique", "related_terms": ["Vibrato", "Bowing", "Stopped string", "Portamento", "Timbre", "Spot mic"], "common_mistakes": ["Assuming the strings are pressed to a fingerboard like a violin; the morin khuur is stopped from the side by the fingers.", "Using tuning or editing software that 'corrects' the wide vibrato and destroys the instrument's expressive character.", "Miking so close that bow noise masks the smooth width of the vibrato."], "scenario_contexts": ["Recording a morin khuur accompanying Mongolian long-song.", "Amplifying the horse-head fiddle in a folk-fusion band.", "Capturing the wide, vocal vibrato in a solo performance."]}, "ef15f2c1-0876-4b3e-b4a8-3e6d5647d8d8": {"definition": "The bright, sharply defined onset of a plucked note produced when the string is released by the player's fingernail rather than the flesh of the fingertip, as on classical guitar, harp or lute. Contact with the harder nail releases the string cleanly and excites more high-frequency partials, giving a crisper, louder, more articulate attack.", "plain_english": "The bright, crisp start of a note when you pluck a string with your fingernail. The hard nail lets go of the string quickly and cleanly, so the note begins with a sharp, clear edge. It sounds brighter and more cutting than plucking with the soft pad of your finger.", "purpose_function": "Using the nail gives a louder, brighter, more precise attack and lets the player shape tone and projection, which is why classical guitarists and harpists carefully shape their nails.", "practical_application": "When recording a nail-plucked instrument a technician expects strong high-frequency attack transients and chooses mic placement and gentle EQ or compression that keep the bright pluck clear without turning it clicky or harsh.", "category": "Playing technique", "related_terms": ["Plucked string", "Attack transient", "Nail-vs-flesh attack", "Timbre", "Fingerstyle", "Transient"], "common_mistakes": ["Assuming nail attack is just louder; it also shifts the tone brighter by adding high partials.", "Miking too close so the nail attack becomes a harsh click instead of a crisp pluck.", "Compressing the attack so hard that the clear onset of each note is squashed."], "scenario_contexts": ["Recording classical guitar played with the nails.", "Capturing the bright pluck of a concert harp.", "Comparing nail and flesh tone during a session."]}, "2a92f385-3c2d-4377-ba7e-147a42a14ed3": {"definition": "The tonal contrast between plucking a string with the fingernail versus the bare flesh of the fingertip, a core tone-shaping choice on classical guitar, harp and related instruments. Nail contact yields a brighter, louder, more articulate attack rich in high partials, while flesh produces a warmer, rounder, darker tone with a softer onset; many players use a combined nail-and-flesh contact to blend the two.", "plain_english": "The difference in sound between plucking a string with your nail and with the soft skin of your fingertip. The nail gives a bright, sharp, loud note. The flesh gives a warm, soft, rounder note. Players pick one or blend both to control how bright or mellow each note sounds.", "purpose_function": "Choosing nail, flesh, or a blend lets a player control brightness, volume and attack note by note, which is a main way string players shape tone and expression.", "practical_application": "A technician recording fingerstyle guitar or harp hears whether a player uses nail or flesh and adjusts mic choice, placement and EQ so a bright nail tone does not get harsh or a warm flesh tone does not get dull.", "category": "Playing technique", "related_terms": ["Nail-pluck attack", "Plucked string", "Timbre", "Attack transient", "Fingerstyle", "Tone production"], "common_mistakes": ["Thinking the choice only changes volume; it mainly changes brightness and attack shape.", "Assuming flesh tone is always better or worse; each suits different music and passages.", "Reaching for EQ to fix a tone that the player is actually creating with nail-versus-flesh technique."], "scenario_contexts": ["A classical guitarist switching between nail and flesh for contrast.", "A harpist choosing flesh for a warmer passage.", "Deciding mic and EQ to suit a bright nail or warm flesh tone."]}, "4e80a56c-5959-422a-be07-e67cfa34deef": {"definition": "On the ngoni, a small West African (Mande) plucked lute with a hide-covered wooden body and gut or nylon strings, a plucked note that sounds with a short, tight, quickly decaying tone having little sustain or ringing resonance, giving a dry, percussive character.", "plain_english": "The ngoni is a small West African lute with a skin-covered body. A dry pluck is a plucked note that stops ringing fast. It sounds short and snappy, not long and echoey.", "purpose_function": "The dry, fast-decaying pluck gives the ngoni its crisp rhythmic drive, letting fast melodic runs stay clear and articulate without notes blurring into one another.", "practical_application": "An engineer captures the ngoni close with a small-diaphragm condenser to preserve its tight transient, avoiding excess room sound that would smear the naturally dry, percussive notes.", "category": "Playing technique", "related_terms": ["Plucked lute", "Attack (transient)", "Sustain", "Damping", "Kora"], "common_mistakes": ["Confusing the ngoni with the kora; the kora is a large 21-string harp-lute with long sustain, while the ngoni is small with a short, dry decay", "Drenching the ngoni in reverb, which masks its tight, percussive attack", "Treating a dry pluck as a technical fault, when it is the instrument's natural short-sustain voice"], "scenario_contexts": ["Miking a ngoni for a Mande griot recording where rhythmic clarity matters", "Blending ngoni with kora and balafon in a West African ensemble mix", "Choosing close mic placement to preserve the ngoni's dry, articulate transient"]}, "7cfadfe3-00fb-453b-b151-5b374922a34d": {"definition": "On the nyckelharpa, a bowed Swedish keyed fiddle fitted with a set of undertuned sympathetic strings, the bright, ringing, halo-like resonance produced when those sympathetic strings vibrate in sympathy with the bowed melody notes, adding a shimmering, reverb-like sheen to the tone.", "plain_english": "A nyckelharpa is a Swedish fiddle played with a bow and rows of keys. Under the main strings sit extra strings that no one bows. They ring on their own when you play, adding a bright, shimmery glow like a soft echo.", "purpose_function": "The sympathetic-string shimmer enriches the nyckelharpa's tone with a natural, sustained resonance, giving it a characteristic bright, ringing sustain even on short bow strokes.", "practical_application": "An engineer recording nyckelharpa avoids over-close mic placement and heavy upper-mid EQ cuts so the delicate sympathetic shimmer stays audible, often adding a little room capture to let it bloom.", "category": "Sympathetic resonance", "related_terms": ["Sympathetic resonance", "Sympathetic strings", "Sustain", "Bowed string", "Resonance"], "common_mistakes": ["Confusing the sympathetic strings, which are never bowed, with the melody strings the bow and keys play", "Cutting high-mid frequencies so hard in the mix that the shimmer disappears", "Damping the body or using too many close mics, which chokes the ringing resonance"], "scenario_contexts": ["Recording a solo nyckelharpa where the sympathetic shimmer is central to the sound", "Placing a room mic to capture the halo of resonance around the direct tone", "Blending nyckelharpa into a Nordic folk mix without masking its ringing overtones"]}, "cc55168e-acae-4f81-a67b-69f62e10ef99": {"definition": "The incidental squeaks, scrapes, and thumps produced when a player's fingers slide along or release the strings of a nylon-string (classical) guitar, most audible on the metal-wound bass strings where the fingertips drag across the winding while shifting position.", "plain_english": "On a classical guitar, the low strings are wrapped in thin metal. When a player slides their fingers along them to change notes, the fingers catch the ridges and squeak. That squeak is finger noise.", "purpose_function": "Finger noise is a natural by-product of moving the fingers on the strings; in a recording it can lend intimate realism, but at high levels it distracts from the notes and must be managed.", "practical_application": "When recording classical guitar, an engineer manages finger squeak through mic choice and placement, gentle high-frequency EQ, or careful editing, and may advise the player on smoother shifts or coated strings.", "category": "Performance noise", "related_terms": ["String squeak", "Wound string", "Fret buzz", "Close miking", "De-essing"], "common_mistakes": ["Trying to erase every squeak, which strips natural realism and sounds artificial", "Blaming the guitar, when smoother left-hand position shifts reduce the noise more than gear changes", "Assuming the plain treble nylon strings squeak, when the noise comes mostly from the metal-wound bass strings"], "scenario_contexts": ["Editing squeaks out of a solo classical guitar take before mastering", "Choosing a mic position that reduces finger noise on a close-miked nylon guitar", "Advising a guitarist on coated strings or cleaner shifts to cut down squeak"]}, "486753da-1842-45ca-8438-9e0ec20367bc": {"definition": "The full, freely sustaining tone produced when a string is played open, sounded along its entire length without being stopped by a finger or fret, allowing it to vibrate and ring longer and more resonantly than a fretted note and to resonate sympathetically with related pitches.", "plain_english": "An open string is one you play without pressing it down. With nothing stopping it, the whole string is free to vibrate. So it rings out longer and louder than a note you hold down with a finger.", "purpose_function": "Open-string ring gives players sustained, resonant tones and lets a note keep sounding while the hand moves elsewhere; it also adds sympathetic resonance that enriches an instrument's overall sound.", "practical_application": "Guitarists and engineers use open-string ring for drones, arpeggios, and sustain, but watch for unwanted ringing bleeding into later notes, muting strings by hand when a cleaner, drier passage is needed.", "category": "String resonance", "related_terms": ["Open string", "Sustain", "Sympathetic resonance", "Damping", "Palm muting"], "common_mistakes": ["Letting open strings ring into a passage where they clash with the harmony, muddying the chord", "Forgetting to mute a ringing open string before it bleeds into the next section", "Assuming a fretted note rings as long as an open string, when open strings usually sustain longer"], "scenario_contexts": ["Using open strings as a drone under a fingerpicked guitar part", "Muting ringing open strings to keep a tight, dry rhythm part clean", "Tuning a mix so sympathetic open-string resonance supports rather than clutters the track"]}, "5dfeaf3f-5b8d-46c3-8999-1b282fcf725e": {"definition": "On the Japanese koto and related zithers, a left-hand technique in which the player presses down on a string on the far side of its movable bridge, increasing tension to raise the pitch, typically by a semitone or whole tone, allowing pitch bends and ornaments beyond the tuning fixed by the bridge positions.", "plain_english": "A koto has movable bridges that set each string pitch. With oshide, the player presses the string down on one side of its bridge. That tightens the string, so the note bends up higher, like bending a guitar string.", "purpose_function": "Oshide lets the koto reach pitches and expressive bends the fixed bridge tuning cannot provide, adding vibrato, ornaments, and note-to-note pitch slides central to the instrument's musical style.", "practical_application": "A player uses oshide to raise a plucked note or add an ornament; a recording engineer captures it with enough dynamic range and low-noise gain to preserve the subtle pitch rise and the string's changing tension.", "category": "Playing technique", "related_terms": ["Pitch bend", "Vibrato", "Koto", "Portamento", "Ornament"], "common_mistakes": ["Pressing so hard the pitch overshoots the intended semitone or whole tone", "Confusing oshide, pressing left of the bridge to raise pitch, with moving the bridge itself to retune", "Pressing on the wrong side of the bridge, which slackens rather than tightens the string"], "scenario_contexts": ["Performing a koto ornament that bends a plucked note up a semitone", "Recording traditional koto where oshide pitch slides must stay clearly audible", "Notating oshide press-bends in a transcription of Japanese zither music"]}, "ac62d938-b709-44fe-b8cb-cd2074b7de29": {"definition": "On the pedal steel guitar, the smooth pitch changes produced two ways: sliding the handheld steel bar along the strings for continuous glides (portamento), and pressing foot pedals or knee levers that mechanically alter the tension of chosen strings through the changer to bend individual notes up or down while other notes sustain.", "plain_english": "A pedal steel is played flat, sliding a metal bar over the strings. Moving the bar slides the pitch up or down smoothly. Foot pedals and knee levers can also bend single strings while the rest hold, giving that crying, gliding country sound.", "purpose_function": "Bends and glides give the pedal steel its vocal, weeping character and let a player bend some notes within a chord while others stay put, creating the smooth voice-leading that defines the instrument.", "practical_application": "A player combines bar glides with pedal and knee-lever bends for expressive lines; an engineer records the instrument with a clean, full-range signal so the sustained, gliding pitches and their overtones come through without distortion.", "category": "Playing technique", "related_terms": ["Portamento", "Pitch bend", "Glissando", "Slide guitar", "Sustain"], "common_mistakes": ["Confusing bar glides, made by moving the steel, with pedal or knee-lever bends, made by mechanical string-tension changes", "Assuming all strings bend together, when pedals and levers bend only the strings they are set to", "Sliding the bar carelessly so glides land off-pitch instead of on the target note"], "scenario_contexts": ["Recording a country ballad where pedal-steel glides answer the vocal line", "Setting up a pedal steel's copedent so specific strings bend on each pedal", "Blending a pedal steel's sustained bends into a mix without masking the lead vocal"]}, "0446c5bd-a36f-4a82-8b13-c619549792ad": {"definition": "On the pipa, a Chinese four-string fretted lute plucked with the fingernails, a sharp, percussive plucking attack in which a string is struck or pulled and released hard so it produces a bright, biting snap, sometimes rebounding against the frets, adding crisp accent and attack.", "plain_english": "The pipa is a Chinese lute plucked with the fingernails. A snap is a hard, sharp pluck. The string is hit or pulled and let go so it cracks out a bright, punchy sound, a bit like a slapped bass note.", "purpose_function": "The snap gives the pipa strong rhythmic accents and a percussive edge, cutting through an ensemble and marking beats or dramatic moments with a sharp, attacking transient.", "practical_application": "An engineer recording pipa leaves enough headroom for the snap's fast, loud transient so it stays punchy and undistorted, and may use gentle compression to keep snaps even without dulling their attack.", "category": "Playing technique", "related_terms": ["Attack (transient)", "Plectrum", "Pizzicato", "Sao", "Transient"], "common_mistakes": ["Setting record levels too hot so the snap's sharp transient clips and distorts", "Over-compressing until the snap loses its percussive attack", "Confusing the percussive snap with the smooth sweeping strum (sao)"], "scenario_contexts": ["Capturing a pipa solo where sharp snaps punctuate the melody", "Leaving headroom on the pipa channel for loud snapped accents", "Balancing snapped accents against sustained tremolo passages in a mix"]}, "acd1b1c7-d33e-4d91-8dec-21c2283d1a1e": {"definition": "On the pipa, the technique called sao, a rapid outward strum in which the fingers sweep across all four strings almost at once, sounding them together in a strong, broad, slightly percussive rush of sound; its reverse-direction counterpart is fu.", "plain_english": "On the pipa, sao means quickly brushing your fingers across all four strings at once. It is like a fast strum on a guitar. All the strings sound together in one broad, sweeping burst.", "purpose_function": "Sao lets the pipa sound full chords and strong accents in a single sweep, adding power, fullness, and rhythmic drive that a single plucked string cannot provide.", "practical_application": "A recording engineer captures sao sweeps with even coverage of all four strings and enough headroom for their combined loud transient, positioning the mic so the sweep sounds balanced rather than favoring one string.", "category": "Playing technique", "related_terms": ["Strum", "Chord", "Transient", "Pipa snap", "Tremolo"], "common_mistakes": ["Confusing sao, a sweeping strum across all strings, with plucking one string at a time", "Micing so close to one string that the sweep sounds uneven across the four strings", "Reversing sao and fu, when sao sweeps outward and fu sweeps back in the opposite direction"], "scenario_contexts": ["Recording a dramatic pipa passage built on strong sao sweeps", "Placing a mic to capture all four strings evenly during strummed sweeps", "Balancing loud sao chords against quieter single-note lines in a mix"]}, "908018f6-df94-49be-a866-6501cb5fa935": {"definition": "The buzzing, rattling, or percussive timbre produced when an object such as a screw, bolt, coin, or piece of rubber is placed on or between a struck or plucked string, as on a prepared piano or prepared guitar, so the object vibrates loosely against the string and alters its normal pitched tone.", "plain_english": "If you rest a small object like a screw on a piano or guitar string, the string rattles against it when played. Instead of a clear note, you get a buzzy, clattery sound. Composers like John Cage did this on purpose.", "purpose_function": "Preparing a string with an added object turns a pitched instrument into a source of new percussive and noise-like colors, letting composers draw gong-like, buzzing, or drum-like sounds from a piano or guitar.", "practical_application": "A player fixes objects to chosen strings following a preparation table, and an engineer mics the instrument closely to capture the delicate rattles and buzzes, watching levels so sudden loud rattles do not overload the input.", "category": "Extended technique", "related_terms": ["Prepared piano", "Muting", "Fret buzz", "Timbre", "Percussive"], "common_mistakes": ["Placing objects so loosely they fall off, or so tightly they fully mute the string instead of rattling", "UNSAFE: forcing hard objects between piano strings or against the soundboard, which can damage the strings, bridge, or finish", "Assuming any object gives the same sound, when material, size, and position each change the rattle"], "scenario_contexts": ["Recording a prepared-piano piece where each note has a different rattle", "Following a composer's preparation chart to place objects on specific strings", "Close-miking a prepared guitar to capture subtle string rattles"]}, "a0a554bc-3f45-4498-b698-f0be73a24d35": {"definition": "The high, thin, nasal sustained tone characteristic of the rebab, a bowed spike fiddle of the Middle East, North Africa, and Southeast Asia; the sound arises from a small resonating body and bowed strings rich in upper harmonics, giving a penetrating, reedy voice often likened to a whine.", "plain_english": "A whine is the thin, high, nose-like sound of the rebab, a small bowed fiddle. Because its body is tiny and the bow keeps the string going, the tone stays bright and cuts right through the music.", "purpose_function": "Names the rebab's signature timbre so engineers and players can recognize, capture, and control the instrument's bright, penetrating character within a mix.", "practical_application": "A technician close-mics the rebab and may tame harsh upper mids with EQ so the whine stays present and expressive without becoming piercing in a folk or world-music recording.", "category": "Timbre", "related_terms": ["Sarangi wash", "Sympathetic strings", "Bowing", "Harmonic content", "EQ (equalization)"], "common_mistakes": ["Cranking high-frequency EQ to add brightness, which makes the whine harsh and fatiguing", "Confusing the rebab's natural nasal tone with a fault in the mic or signal chain", "Gating too aggressively and cutting the sustained bowed tail"], "scenario_contexts": ["Miking a rebab for a world-music or film-score session", "Blending a rebab against a string section in a fusion arrangement", "Taming harsh upper mids on a solo rebab line during mixing"]}, "56286b3d-85fc-4ff7-b206-127af71d7313": {"definition": "The bright, metallic, sustaining resonance produced by the spun-metal cone of a resonator (Dobro-style) guitar; driven by the bridge like a mechanical loudspeaker, the cone radiates the string energy with a characteristic ringing, bell-like sustain and strong upper-mid content.", "plain_english": "The ring is the bright, bell-like sustain that comes from the metal cone inside a resonator guitar. The cone works like a small speaker, so the notes ring out longer and sound more metallic than on a normal acoustic.", "purpose_function": "Describes the core tonal signature of resonator guitars so engineers can capture and preserve the ringing, sustaining character that defines blues, bluegrass, and country resonator tones.", "practical_application": "A technician positions a mic between the cone and the body ports, a few feet back, to capture the ring and body warmth without exaggerating pick and slide noise.", "category": "Timbre", "related_terms": ["Resonator feedback", "Resonator rattle", "Sustain", "Slide technique", "Microphone placement"], "common_mistakes": ["Miking directly on the cone, which captures pick noise instead of the full ring", "Over-compressing and squashing the natural ringing sustain", "Assuming all resonators sound alike regardless of single-cone (biscuit or spider) or tricone design"], "scenario_contexts": ["Recording a Dobro for a bluegrass or country track", "Capturing bottleneck slide blues on a single-cone resonator", "Balancing resonator ring against a vocal in a mix"]}, "068cbb30-7e7e-461f-a05c-7fc0b04692ca": {"definition": "Acoustic feedback that occurs when an amplified resonator guitar's cone, designed to pick up and radiate string energy, is re-excited by sound arriving from monitors or the PA, producing a sustained howl or ring at the loop's resonant frequency.", "plain_english": "Feedback is the loud howl that starts when a resonator guitar's cone picks up sound from the speakers and feeds it back around in a loop. Because the cone is built to grab and boost vibration, it feeds back more easily than a solid guitar.", "purpose_function": "Warns that the resonator's amplifying cone makes it especially prone to feedback on stage, so technicians plan gain structure, monitor levels, and EQ to keep it under control.", "practical_application": "A technician lowers monitor level, notches the ringing frequency with EQ, or blocks the body ports to stop a resonator from howling during a loud live set.", "category": "Live Sound", "related_terms": ["Resonator cone ring", "Acoustic feedback", "Monitor wedge", "Notch filter", "Gain before feedback"], "common_mistakes": ["UNSAFE: Pushing overall system or monitor gain to hear the resonator, which can trigger a sudden loud feedback howl that risks hearing damage and blown drivers", "Blaming the PA rather than the resonator's cone for stage feedback", "Notching so many frequencies that the guitar tone is hollowed out"], "scenario_contexts": ["A resonator player steps toward a monitor and the instrument begins to howl", "Setting gain structure for an amplified resonator at soundcheck", "Ringing out monitors to raise the feedback threshold for a resonator player"]}, "5ec28c74-467e-460a-aa9c-2d45b9738054": {"definition": "An unwanted buzzing or rattling noise from a resonator guitar caused by a loose or improperly seated cone, spider, coverplate, tailpiece, or hardware vibrating against the body or against itself when the strings are played.", "plain_english": "A rattle is a buzzing noise from a resonator guitar. It happens when a loose part, like the metal cone or cover plate, shakes against the body. It usually means a part needs tightening, not that the guitar is broken.", "purpose_function": "Flags a mechanical noise fault so a technician can locate and fix the loose component before it spoils a recording or performance.", "practical_application": "A technician isolates the buzz by muting strings and tapping parts, then reseats the cone or snugs the coverplate hardware to silence the rattle.", "category": "Instrument Noise", "related_terms": ["Resonator cone ring", "Resonator feedback", "Buzz", "Setup and maintenance", "Fret buzz"], "common_mistakes": ["Assuming the rattle is a bad string or amp fault when it is actually loose resonator hardware", "Overtightening coverplate screws and distorting the cone seat", "Ignoring a faint rattle that a close mic will clearly capture on a quiet recording"], "scenario_contexts": ["Tracking a Dobro and hearing a buzz on certain notes", "Pre-gig inspection of a resonator for loose hardware", "Diagnosing a rattle that only appears at high playing volume"]}, "68e8614a-2972-40d8-86fc-439a686e3268": {"definition": "A rapid, even alternation of down-and-up plectrum (risha) strokes on the oud or buzuq that sustains a pitch or fills a phrase, producing the continuous, shimmering tremolo texture common in Arabic and Turkish string music.", "plain_english": "Risha tremolo is fast back-and-forth picking on an oud, using the thin pick called a risha. The quick strokes blur into one long, shimmering note, the way a mandolin player holds a note.", "purpose_function": "Names the technique that lets a plucked oud sustain a tone or ornament a melody, since a single pluck decays quickly.", "practical_application": "An engineer captures the fine stroke detail of risha tremolo with a close condenser mic and avoids heavy transient limiting that would flatten the shimmer.", "category": "Articulation", "related_terms": ["Risha/mizrab attack", "Tremolo", "Plectrum", "Sustain", "Transient"], "common_mistakes": ["Confusing tremolo (fast repeated notes) with vibrato (a pitch wobble)", "Heavy transient shaping that smears the individual strokes into mush", "Miking too far away and losing the crisp stroke detail"], "scenario_contexts": ["Recording an oud taqsim that uses tremolo on sustained notes", "Blending an oud tremolo bed under a vocal line", "Editing a tremolo passage where stroke evenness matters"]}, "73227c0e-0026-451f-99ec-0b8066bd2b98": {"definition": "The sharp initial transient produced when a plectrum strikes the string on plucked lutes of the Middle East and South Asia — the risha (oud, buzuq), the wire mizrab worn on the finger (sitar), or the hand-held java plectrum (sarod) — giving each note its percussive onset and defining the music's rhythmic articulation.", "plain_english": "The attack is the sharp pluck sound at the very start of a note when a pick hits the string. On an oud the pick is a risha; on a sitar it is a wire finger pick called a mizrab, while a sarod is played with a hand-held pick called a java. This crisp start gives the music its rhythmic bite.", "purpose_function": "Describes the onset transient that carries the rhythm and clarity of plucked-lute lines, which engineers must preserve for definition in a mix.", "practical_application": "A technician sets preamp and converter headroom so the sharp mizrab or risha attack is not clipped, and uses gentle compression to even out onsets without dulling them.", "category": "Articulation", "related_terms": ["Risha tremolo", "Attack (envelope)", "Transient", "Plectrum", "Sarod glissando"], "common_mistakes": ["Using fast, hard compression that dulls the plectrum attack", "Setting record levels too hot and clipping the sharp transient", "Confusing the metal mizrab's bright attack with digital distortion"], "scenario_contexts": ["Recording a sitar where each mizrab stroke must stay crisp", "Tracking an oud rhythm part that drives the groove", "Setting gain staging to protect sharp plucked transients from clipping"]}, "16b4e6e7-e311-43e8-85ae-47649e2f63ff": {"definition": "The bright, sustained, glistening decay of the santoor (santur), a hammered dulcimer whose many courses of metal strings, struck with light mallets, ring and reinforce one another to create a shimmering wash of overtones.", "plain_english": "Shimmer is the bright, sparkling sound that lingers after a santoor is struck. It has many metal strings hit with small hammers, and they all ring together, like sunlight on water, leaving a glowing tail.", "purpose_function": "Names the santoor's signature sustained, overtone-rich decay so engineers can capture and preserve its glistening character.", "practical_application": "An engineer uses a stereo pair placed over the instrument to capture the full shimmer and reverberant tail without close-miking artifacts.", "category": "Timbre", "related_terms": ["Sarangi wash", "Sympathetic strings", "Sustain", "Overtones", "Stereo miking"], "common_mistakes": ["Adding bright reverb that clashes with the natural overtone shimmer", "Close-miking one region and missing the full field of ringing strings", "Over-compressing and killing the long ringing decay"], "scenario_contexts": ["Recording a santoor solo in Persian or Indian classical music", "Placing a santoor's shimmer in a film or ambient mix", "Choosing reverb that complements rather than masks the natural decay"]}, "98997b78-2ec0-449e-a58c-3d3781adc213": {"definition": "The soft, continuous, blended texture of the sarangi, a bowed short-necked Indian fiddle whose numerous sympathetic strings resonate with the bowed melody strings to surround each note with a haze of sustained overtones.", "plain_english": "The wash is the soft, cloudy blanket of sound around a sarangi's melody. The sarangi has many extra strings that ring on their own when you bow, filling the space with a smooth glow behind the tune.", "purpose_function": "Describes the sympathetic-string resonance that gives the sarangi its vocal, enveloping sound, which engineers aim to capture rather than suppress.", "practical_application": "A technician mics the sarangi to include the sympathetic strings' resonance, avoiding tight close-miking that would thin out the wash.", "category": "Timbre", "related_terms": ["Santoor shimmer", "Sympathetic strings", "Bowing", "Resonance", "Reverb"], "common_mistakes": ["Aggressive noise gating that chops off the sustained resonant tail", "Close-miking only the melody strings and losing the sympathetic wash", "Mistaking the natural sympathetic resonance for added reverb"], "scenario_contexts": ["Recording a sarangi accompaniment in Hindustani classical music", "Capturing the vocal-like sustain of a sarangi solo", "Preserving sympathetic resonance while controlling bow noise"]}, "3e81d6b9-0ab1-4917-8f0d-d0d39f299890": {"definition": "A smooth, continuous slide in pitch on the sarod, a fretless plucked lute with a polished metal fingerboard that lets the fingernail glide along the string, producing the seamless pitch transitions (meend) central to Hindustani music.", "plain_english": "A glissando is a smooth slide from one pitch to another. The sarod has no frets and a shiny metal board, so a player can slide a fingernail along the string and let the note glide, with no steps in between.", "purpose_function": "Names the continuous pitch-slide technique that the sarod's fretless metal fingerboard makes possible and that defines its expressive, vocal phrasing.", "practical_application": "An engineer captures the glissando with enough high-frequency detail to keep the sliding fingernail-on-metal character, avoiding heavy filtering that would dull it.", "category": "Articulation", "related_terms": ["Risha/mizrab attack", "Glissando", "Portamento", "Fretless", "Sympathetic strings"], "common_mistakes": ["Confusing a glissando (a smooth slide) with discrete stepped notes", "Rolling off the highs and losing the fingernail-slide detail", "Using pitch correction that fights the continuous slide"], "scenario_contexts": ["Recording a sarod alap full of sliding meend phrases", "Editing a sarod line without quantizing the pitch slides", "Blending a sarod glissando into a fusion arrangement"]}}$j$::jsonb)) d
WHERE g.id = d.id;
COMMIT;
